const e=[{id:1,icon:"Snowflake",accent:"#2563eb",title:"سەلامەتی لە زستاندا",subtitle:"پاراستنی خۆت لە سەرما و مەترسییەکانی زستان",summary:"زستان وەرزێکی جوانە، بەڵام مەترسیی خۆشی هەیە: سەرما، بەفر، سەهۆڵ، خلیسکان و گازی ژەهراویی سۆبەکان. پێویستە بزانین چۆن خۆمان و خێزانەکەمان بپارێزین.",blocks:[{heading:"گەرمکردنەوەی ماڵ بە سەلامەتی",body:`سۆبەی گاز، نەوت و کارەبا بە دروستی و بەپێی ڕێنماییەکانی کۆمپانیای بەرهەمهێنەر بەکاربهێنە.
• ڕێگایەکی هەوا لە ژوورەکەدا کراوە بهێڵەوە، چونکە سۆبەی گاز و نەوت گازی ژەهراویی مۆنۆکسیدی کاربۆن (CO) دروست دەکەن.
• لە کاتی خەوتندا سۆبە بە داگیرساوی مەهێڵەوە.`},{heading:"پاراستن لە سەرما",body:"جلی گەرم چین لەسەر چین لەبەر بکە. سەر، دەست و پێیەکانت باش دابپۆشە. ئەگەر هەوا زۆر سارد بوو، ماوەیەکی درێژ لە دەرەوە مەمێنەوە."},{heading:"لێخوڕینی سەلامەت لەسەر بەفر و سەهۆڵ",body:"لەسەر بەفر و سەهۆڵ بە هێواشی لێبخوڕە. دووریی نێوان ئۆتۆمبێلەکەت و ئۆتۆمبێلی پێشەوە زیاد بکە. تایەی زستانە یان زنجیر بەکاربهێنە."},{heading:"ڕێگرتن لە بەستنی بۆرییەکان",body:"بۆرییەکانی ئاو بەهۆی سەرماوە دەبەستن و دەتەقن. بۆرییەکانی دەرەوە بپێچە و عازل بکە. لە شەوە زۆر ساردەکاندا، بهێڵە ئاو کەمێک و بە هێواشی بڕوات."}],tips:["زەنگی ئاگاداریی گازی CO (مۆنۆکسیدی کاربۆن) لە ماڵەوە دابنێ.","پێش خەوتن سۆبەی گاز بکوژێنەرەوە.","جلی چین لەسەر چین لەبەر بکە — لە یەک جلی ئەستوور باشترن.","جانتایەکی فریاکەوتنی سەرەتایی و بەتانییەک لە ئۆتۆمبێلەکەتدا هەبێت.","کاتێک دەچیتە دەرەوە، مۆبایلەکەت پڕ شەحن بێت."],warnings:["سۆبە لە نزیک پەردە و جل دامەنێ.","منداڵان لە سۆبە دوور بخەرەوە.","مەهێڵە بەفرێکی زۆر لەسەر بانی خانووەکە کۆببێتەوە.","یەک پلاکی کارەبا بە چەندین سۆبەی کارەبا بار مەکە."],activity:{prompt:"لە ماڵەوەیت و سۆبەی گاز داگیرساوە. یەکێک لە ئەندامانی خێزان سەری دێشێت و هەست بە سەرگێژبوون دەکات. چی دەکەیت؟",options:[{text:"یەکسەر هەمووان دەبەمە دەرەوە بۆ هەوای پاک (سۆبەکە لە ڕێگادا تەنها دەکوژێنمەوە ئەگەر خێرا و سەلامەت بوو)، پەیوەندی بە ١٢٢ دەکەم تەنانەت ئەگەر هەستیان بە باشتربوون کرد، و کەس ناگەڕێتەوە ژوورەوە تا ژوورەکە هەوای بۆ نەکرێت و سۆبەکە نەپشکنرێت",correct:!0,feedback:"سەرئێشە و سەرگێژبوون لە نزیک سۆبەی گاز دەکرێت نیشانەی ژەهراویبوون بە CO بن، بۆیە هەوای پاک و پەیوەندیکردن بە ١٢٢ یەکەم کارن."},{text:"دەرمانێکی سەرئێشەی پێدەدەم و سۆبەکە بە داگیرساوی دەهێڵمەوە",correct:!1,feedback:"حەب یارمەتی نادات ئەگەر سۆبەکە گازی CO دروست بکات؛ هەمووان ببە دەرەوە بۆ هەوای پاک و پەیوەندی بە ١٢٢ بکە."},{text:"تەنها سۆبەکە دەکوژێنمەوە و لە ژوورەکەدا دەمێنینەوە",correct:!1,feedback:"کوژاندنەوەی سۆبەکە بەس نییە: گازە ژەهراوییەکە لە ژوورەکەدا دەمێنێتەوە، بۆیە دەبێت هەمووان بچنە دەرەوە بۆ هەوای پاک."},{text:"هیچ ناکەم و چاوەڕێ دەکەم",correct:!1,feedback:"چاوەڕێکردن مەترسیدارە: گازەکە هەر کۆ دەبێتەوە، بۆیە هەمووان ببە دەرەوە بۆ هەوای پاک و پەیوەندی بە ١٢٢ بکە."}]},quiz:[{question:"بۆچی پێویستە ڕێگایەکی هەوا لە ژوورەکەدا کراوە بێت کاتێک سۆبەی گاز داگیرساوە؟",options:[{text:"بۆ ئەوەی بۆنی ژوورەکە خۆش بێت",correct:!1},{text:"بۆ ڕێگرتن لە کۆبوونەوەی گازی ژەهراویی مۆنۆکسیدی کاربۆن (CO)",correct:!0},{text:"بۆ ئەوەی ژوورەکە سارد نەبێت",correct:!1},{text:"بۆ ئەوەی دەنگ دەرنەچێت",correct:!1}],explanation:"سۆبەی گاز و نەوت گازی ژەهراویی مۆنۆکسیدی کاربۆن (CO) دروست دەکەن. ڕێگایەکی هەوای کراوە ڕێگری لە کۆبوونەوەی لە ژوورەکەدا دەکات."},{question:"کام جل بۆ پاراستن لە سەرما باشترە؟",options:[{text:"یەک جلی ئەستوور",correct:!1},{text:"جلی چین لەسەر چین",correct:!0},{text:"جلی تەنک",correct:!1},{text:"هیچ جیاوازییەک نییە",correct:!1}],explanation:"جلی گەرمی چین لەسەر چین باشتر لە یەک جلی ئەستوور دەپارێزن. سەر و دەست و پێیەکانیشت باش دابپۆشە."},{question:"چۆن ڕێگری لە بەستنی بۆرییەکانی ئاو دەکەین؟",options:[{text:"بۆرییەکان دەپێچین و لە شەوە زۆر ساردەکاندا دەهێڵین ئاو کەمێک و بە هێواشی بڕوات",correct:!0},{text:"هیچ ناکەین",correct:!1},{text:"لە ژێر بۆرییەکاندا ئاگر دەکەینەوە",correct:!1},{text:"بۆرییەکان دەشکێنین",correct:!1}],explanation:"بۆرییەکانی ئاو بە سەرما دەبەستن و دەتەقن. بۆرییەکانی دەرەوە بپێچە و ئیزۆلە بکە، و لە شەوە زۆر ساردەکاندا بهێڵە ئاو کەمێک و بە هێواشی بڕوات."}]},{id:2,icon:"Sun",accent:"#ea580c",title:"سەلامەتی لە هاویندا",subtitle:"پاراستنی خۆت لە گەرما و ئاگری دارستانەکان",summary:"هاوین وەرزێکی گەرمە و مەترسیی تایبەتی تێدایە، وەک گەرمالێدان، سووتانی کشتوکاڵ و دەغڵودان، ئاگری دارستانەکان، خنکان لە ئاودا و کەمیی ئاو. وەرە با فێر ببین چۆن خۆمان بپارێزین.",blocks:[{heading:"پاراستن لە گەرمالێدان (Heatstroke)",body:"بە درێژایی ڕۆژ ئاو بخۆرەوە، پێش ئەوەی تینووت بێت. لە گەرمترین کاتەکانی ڕۆژدا لەبەر خۆر مەمێنەوە. جلی ڕەنگ کاڵ و سووک لەبەر بکە و کڵاو بەکاربهێنە."},{heading:"ماندووبوون بە گەرما یان گەرمالێدان؟",body:`• ماندووبوون بە گەرما (Heat exhaustion): ئارەقکردنەوەی زۆر، پێستی سارد و زەرد و شێدار، لاوازی، سەرگێژخواردن، سەرئێشە، دڵتێکهەڵاتن و تینوێتی. کەسەکە بگوازەرەوە بۆ شوێنێکی فێنک، جلەکانی شل بکەرەوە، بە ئاو ساردی بکەرەوە و ئەگەر بە تەواوی بەئاگا بوو قومە ئاوی بدەرێ. داوای یارمەتیی پزیشکی بکە ئەگەر ڕشایەوە، ئەگەر نیشانەکان خراپتر بوون یان لە کاتژمێرێک زیاتر بەردەوام بوون، یان ئەگەر شێوا (ئەمە گەرمالێدانە).
• گەرمالێدان (Heatstroke): لەشی زۆر گەرم لەگەڵ شێواوی، ڕەفتاری نائاسایی، قسەکردنی قورس، گرژبوون یان کەوتن؛ پێست دەکرێت گەرم و وشک بێت یان هێشتا ئارەقەی هەبێت. ئەمە باری نائاساییە: پەیوەندی بە ١٢٢ بکە، کەسەکە بگوازەرەوە بۆ شوێنێکی فێنک، جلە زیادەکانی دابکەنە و یەکسەر ساردی بکەرەوە، پێش ئەوەی بگوازرێتەوە بۆ نەخۆشخانە. باشترین ڕێگا: لەشی تا مل بخە ناو ئاوی ساردەوە بۆ ماوەی ١٥ خولەک یان تا هۆشی دیسان ڕوون دەبێتەوە، کامیان زووتر بێت؛ ئەگەر نەکرا، دووشی سارد، خاولی یان چەرچەفی تەڕی سارد و کیسەی سەهۆڵ بەکاربهێنە و باوەشێنی بۆ بکە. هیچ خواردنەوەیەک مەدە بە کەسێکی شێواو.`},{heading:"ڕێگرتن لە ئاگری دارستانەکان",body:"لە دارستان و ناو گیای وشکدا ئاگر مەکەرەوە. جگەرە فڕێ مەدە. بوتڵی شووشە لە دەرەوە بەجێ مەهێڵە، چونکە دەتوانن وەک هاوێنە تیشکی خۆر کۆبکەنەوە و ئاگر بکەنەوە."},{heading:"سەلامەتی لە دەریاچە و ڕووبارەکاندا",body:"بە تەنها مەچۆ مەلەکردن. تەنها لە شوێنی سەلامەت و لەژێر چاودێریدا مەلە بکە. چاکەتی ڕزگاربوون (Life jacket) لەبەر بکە. چاوت لە منداڵان هەڵمەگرە."},{heading:"پاراستنی خۆراک و ئاو",body:"لە هاویندا خۆراک زوو خراپ دەبێت. خۆراک لە سەلاجەدا بپارێزە. ئاوی پاک بخۆرەوە. میوە و سەوزە باش بشۆ."}],tips:["بە درێژایی ڕۆژ ئاو بخۆرەوە — زۆربەی جار ٢ لیتر یان زیاتر.","لە نیوەڕۆ و دوای نیوەڕۆدا، کە گەرما لە بەرزترین ئاستدایە، لەبەر خۆر مەمێنەوە.","کرێمی پاراستن لە خۆر (SPF 30+) بەکاربهێنە.","میوەی ئاودار بخۆ (وەک شووتی و کاڵەک).","منداڵان و ئاژەڵان بە تەنها لە ئۆتۆمبێلی گەرمدا بەجێ مەهێڵە."],warnings:["گەرمالێدان دەتوانێت بکوژێت — ئاوی زۆر بخۆرەوە و لە سێبەردا بە.","ئاگر لە دارستاندا بە خێرایی بڵاو دەبێتەوە.","خنکان لە ئاودا — منداڵان بێ چاودێری بەجێ مەهێڵە.","خۆراکی خراپبوو دەبێتە هۆی ژەهراویبوون."],activity:{prompt:"لە دەرەوەیت و هەست بە سەرگێژبوون و لاوازی دەکەیت. لەشت زۆر گەرم بووە. چی دەکەیت؟",options:[{text:"دەچمە سێبەرێک، ئاو دەخۆمەوە، لەشم بە ئاوی فێنک سارد دەکەمەوە و پەیوەندی بە ١٢٢ دەکەم",correct:!0,feedback:"سەرگێژبوون، لاوازی و لەشی زۆر گەرم نیشانەی مەترسیی گەرمان: بچۆ بۆ سێبەر، لەشت سارد بکەرەوە و پەیوەندی بە ١٢٢ بکە."},{text:"بەردەوام دەبم لە کارەکەم",correct:!1,feedback:"بەردەوامبوون لە کارەکەت لەشت زیاتر گەرم دەکات؛ بوەستە، بچۆ بۆ شوێنێکی فێنک، لەشت سارد بکەرەوە و پەیوەندی بە ١٢٢ بکە."},{text:"لەبەر خۆر دەمێنمەوە و تەنها ئاوی سەهۆڵاوی دەخۆمەوە",correct:!1,feedback:"مانەوە لەبەر خۆر لەشت زیاتر گەرم دەکات؛ بچۆ بۆ سێبەر و لەشت بە ئاو سارد بکەرەوە."},{text:"لەبەر خۆر ڕادەکشێم و دەخەوم",correct:!1,feedback:"ڕاکشان لەبەر خۆر لەشت گەرمتر دەکات؛ بچۆ بۆ شوێنێکی فێنک، لەشت سارد بکەرەوە و پەیوەندی بە ١٢٢ بکە."}]},quiz:[{question:"بۆچی نابێت بوتڵی شووشەی ئاو لە دەرەوە لەبەر خۆر بەجێ بهێڵین؟",options:[{text:"چونکە ئاوەکە گەرم دەبێت",correct:!1},{text:"چونکە وەک هاوێنە دەتوانن ئاگر بکەنەوە",correct:!0},{text:"چونکە شووشەکە دەشکێت",correct:!1},{text:"هیچ جیاوازییەک نییە",correct:!1}],explanation:"بوتڵی شووشە دەتوانێت وەک هاوێنە کار بکات: تیشکی خۆر کۆدەکاتەوە و دەتوانێت ئاگر بکاتەوە. بوتڵی شووشە لە دەرەوە بەجێ مەهێڵە."},{question:"لە هاویندا، پێویستە چەند ئاو بخۆینەوە؟",options:[{text:"نیو لیتر بەسە",correct:!1},{text:"١ لیتر بەسە",correct:!1},{text:"بە درێژایی ڕۆژ، ٢ لیتر یان زیاتر",correct:!0},{text:"تەنها کاتێک تینوومان دەبێت",correct:!1}],explanation:"بە درێژایی ڕۆژ ئاو بخۆرەوە، زۆربەی جار ٢ لیتر یان زیاتر، و پێش ئەوەی تینووت بێت. ئەمە یارمەتیت دەدات لە گەرمالێدان بپارێزرێیت."},{question:"لە هاویندا، لە کام کاتی ڕۆژدا گەرما و مەترسی زیاترن؟",options:[{text:"بەیانیی زوو",correct:!1},{text:"نیوەڕۆ و دوای نیوەڕۆ",correct:!0},{text:"ئێوارە",correct:!1},{text:"شەو",correct:!1}],explanation:"لە نیوەڕۆ و دوای نیوەڕۆدا گەرما لە بەرزترین ئاستیدایە، بۆیە لەو کاتانەدا لەبەر خۆر مەمێنەوە."}]},{id:3,icon:"Home",accent:"#059669",title:"سەلامەتی لە ماڵەوە",subtitle:"پاراستنی خێزان لە مەترسییەکانی ناو ماڵ",summary:"پێویستە ماڵ شوێنێکی سەلامەت بێت بۆ خێزان، بەڵام مەترسیی زۆر لە ماڵدا هەن، وەک ئاگر، کارەبا، گاز، کەوتن و ژەهراویبوون. وەرە با فێر ببین چۆن ماڵێکی سەلامەت دروست بکەین.",blocks:[{heading:"سەلامەتیی ئاگر و ئاگرکوژێنەرەوە",body:`زەنگی دووکەڵ دابنێ و هەموو مانگێک تاقی بکەرەوە. ئاگرکوژێنەرەوەیەک لە نزیک چێشتخانە دابنێ. جۆرەکانی ئاگرکوژێنەرەوە (پۆلەکانی NFPA):
• ئاو: بۆ دار، کاغەز و قوماش (پۆلی A).
• CO₂: بۆ ئامێرە کارەباییەکان (پۆلی C).
• تۆزی ABC: بۆ پۆلەکانی A، B و C، بەڵام نە بۆ ڕۆنی چێشتخانە و نە بۆ کانزاکان.
• کەف (Foam): بۆ شلە گڕگرەکان (پۆلی B).
• هەرگیز ئاو مەکە سەر ڕۆنی ئاگرگرتوو!

ئاگرکوژێنەرەوە تەنها بەکاربهێنە ئەگەر هەموو ئەمانە ڕاست بن: ئاگرەکە بچووک و تازە دەستی پێکردبێت، ئاگرکوژێنەرەوەکە گونجاو بێت، ڕێگای دەرچوون لە پشتتەوە بێت، ئاگادارکردنەوە درابێت و پەیوەندی بە ١١٥ەوە کرابێت، تۆ ڕاهێنراو بیت، و هیچ دووکەڵ یان گەرمایەک ڕێگات نەگرێت. ئەگەر ئاگرەکە یەکسەر نەکوژایەوە، دەرچۆ و دەرگاکە دابخە. ڕێگای PASS: سنجاقی سەلامەتی ڕابکێشە (Pull)، سەری لوولەکە بەرەو بنی ئاگرەکە بگرە (Aim)، دەسکەکە بە هێز بگوشە (Squeeze) و لوولەکە بۆ چەپ و ڕاست بجووڵێنە (Sweep). ڕێگای دەرچوونی تەنگانە لە ماڵەوە دیاری بکە.`},{heading:"سەلامەتیی کارەبا و مۆلیدە",body:`پلاک و وایەرەکانی کارەبا بە ساغی ڕابگرە. وایەری بڕاو یان خراپبوو چاک بکە یان بیگۆڕە. بە دەستی تەڕ دەست لە ئامێرە کارەباییەکان مەدە. ئامێری زۆر بە یەک پلاکی زیادەوە مەبەستەوە.

مۆلیدە (Generator): مۆلیدە تەنها لە دەرەوە بەکاربهێنە، لانیکەم ٦ مەتر (٢٠ پێ) دوور لە پەنجەرە، دەرگا و کونی هەوا — هەرگیز لە ناو ماڵ، گەراج، نهۆمی ژێرزەوی، دووکان یان کۆگادا نا، تەنانەت ئەگەر دەرگا و پەنجەرەکان کراوە بن. ئاگادارکەرەوەی CO ی پاتریدار لە ماڵەوە دابنێ. هەرگیز مۆلیدە بە پلاکی دیوار یان بە وایەرەکانی کارەبای ماڵەوە مەبەستەوە: دەتوانێت دراوسێکان و کارمەندانی کارەبا بە کارەبا بکوژێت. تەنها کارەباچییەکی شارەزا دەتوانێت بیبەستێتەوە، لە ڕێگەی سویچی گواستنەوە (Transfer Switch).`},{heading:"سەلامەتیی گاز",body:"بۆری و سلیندەرەکانی گاز بە ڕێکی بپشکنە. ئەگەر بۆنی گاز هات: هیچ سویچێکی کارەبا مەکەرەوە و مەکوژێنەرەوە، ئاگر مەکەرەوە و لە ناو ماڵ تەلەفۆن بەکارمەهێنە، و مۆلیدە یان ئۆتۆمبێل لە نزیکەوە هەڵمەکە. ئەگەر توانیت، لە ڕێگای دەرچوونتدا پەنجەرە و دەرگاکان بکەرەوە. سەمامەی گاز تەنها دابخە ئەگەر نزیک بوو و گەیشتن پێی سەلامەت بوو، بەبێ ئەوەی بچیتە ئەو شوێنەی گازی تێدا کۆبووەتەوە؛ ئەگەر نا، لێی نزیک مەبەوە. لە ماڵ دەربچۆ، خەڵکی تر ئاگادار بکەرەوە و لە دەرەوەی ماڵ پەیوەندی بە ١١٥ بکە."},{heading:"ڕێگرتن لە کەوتن",body:"دەسگرە بۆ پلیکانەکان دابنێ. شت لەسەر زەوی و پلیکانەکان بەجێ مەهێڵە. ڕووناکیی پلیکانەکان باش بێت. ئاوی ڕژاو لەسەر زەوی یەکسەر پاک بکەرەوە."}],tips:["هەموو مانگێک زەنگی دووکەڵ تاقی بکەرەوە.","ئامێری زۆر بە پلاکی زیادەوە مەبەستەوە.","دەرمان و مادە کیمیاییەکان لە شوێنێکی داخراو و دوور لە منداڵان دابنێ.","ڕێگای دەرچوونی تەنگانە هەمیشە کراوە بێت.","ژمارەکانی تەنگانە (١١٥، ١٢٢، ١٠٤) لە شوێنێکی دیار بنووسە."],warnings:["منداڵان بە تەنها لە چێشتخانەدا بەجێ مەهێڵە.","شتی شووشەیی و تیژ لە شوێنێکی بەرز و دوور لە منداڵان دابنێ.","پەنجەرە و باڵکۆنەکان بۆ منداڵان سەلامەت بکە.","یاریکردن بە ئاگر و کارەبا دەتوانێت بکوژێت."],activity:{prompt:"بۆنی گاز لە چێشتخانەوە دێت. چی دەکەیت؟",options:[{text:"لە ڕێگای دەرچوونمدا پەنجەرەکان دەکەمەوە، سەمامەی گاز تەنها دادەخەم ئەگەر گەیشتن پێی سەلامەت بێت، لە ماڵ دەردەچم و لە دەرەوە پەیوەندی بە ١١٥ دەکەم",correct:!0,feedback:"هیچ سویچ و ئاگرێک بەکارناهێنیت، لە ڕێگادا پەنجەرەکان دەکەیتەوە، سەمامەکە تەنها ئەگەر سەلامەت بێت دادەخەیت و لە دەرەوە پەیوەندی بە ١١٥ دەکەیت."},{text:"چرا هەڵدەکەم بۆ ئەوەی شوێنی دزەکردنی گازەکە ببینم",correct:!1,feedback:"هەڵکردنی چرا دەتوانێت گازەکە دابگیرسێنێت؛ دەست لە هیچ سویچێک مەدە و لە ماڵ دەربچۆ."},{text:"لە ناو ماڵەوە لایتی مۆبایلەکەم هەڵدەکەم",correct:!1,feedback:"بەکارهێنانی مۆبایل لە ناو ماڵ دەتوانێت گازەکە دابگیرسێنێت؛ سەرەتا دەربچۆ و لە دەرەوە پەیوەندی بە ١١٥ بکە."},{text:"چاوەڕێ دەکەم تا بۆنی گازەکە نامێنێت",correct:!1,feedback:"کاتێک چاوەڕێ دەکەیت گازەکە هەر کۆ دەبێتەوە؛ دەربچۆ، خەڵکی تر ئاگادار بکەرەوە و لە دەرەوە پەیوەندی بە ١١٥ بکە."}]},quiz:[{question:"پێویستە چەند جار زەنگی دووکەڵ تاقی بکەینەوە؟",options:[{text:"هەر ٥ ساڵ جارێک",correct:!1},{text:"هەموو مانگێک",correct:!0},{text:"هەرگیز",correct:!1},{text:"تەنها لە کاتی کڕیندا",correct:!1}],explanation:"هەموو مانگێک زەنگی دووکەڵ تاقی بکەرەوە، بۆ ئەوەی دڵنیا بیت کە کاتێک ئاگر دەست پێدەکات ئاگادارت دەکاتەوە."},{question:"کاتێک بۆنی گاز لە ماڵەوە دێت، چی دەکەین؟",options:[{text:"چراکانی کارەبا هەڵدەکەین",correct:!1},{text:"لە ڕێگای دەرچووندا پەنجەرەکان دەکەینەوە، سەمامەی گاز تەنها دادەخەین ئەگەر گەیشتن پێی سەلامەت بێت، و دەردەچین",correct:!0},{text:"جگەرەیەک دادەگیرسێنین",correct:!1},{text:"چاوەڕێ دەکەین تا بۆنەکە نامێنێت",correct:!1}],explanation:"هەر سویچێک یان ئاگرێک دەتوانێت گازەکە دابگیرسێنێت. لە ڕێگای دەرچووندا پەنجەرەکان بکەرەوە، سەمامەی گاز تەنها دابخە ئەگەر نزیک بوو و گەیشتن پێی سەلامەت بوو، و لە دەرەوە پەیوەندی بە ١١٥ بکە."},{question:"بۆچی نابێت بە دەستی تەڕ دەست لە کارەبا بدەین؟",options:[{text:"چونکە دەست پیس دەبێت",correct:!1},{text:"چونکە ئاو کارەبا دەگوازێتەوە و دەبێتە هۆی شۆکی کارەبا",correct:!0},{text:"چونکە کارەبا دەبڕێت",correct:!1},{text:"هیچ جیاوازییەک نییە",correct:!1}],explanation:"ئاو کارەبا دەگوازێتەوە، بۆیە دەستدان لە ئامێرە کارەباییەکان بە دەستی تەڕ دەتوانێت تووشی شۆکی کارەبات بکات."}]},{id:4,icon:"HeartPulse",accent:"#dc2626",title:"بنەماکانی فریاکەوتنی سەرەتایی",subtitle:"کارە سەرەتاییەکان بۆ ڕزگارکردنی ژیان تا گەیشتنی ئەمبولانس",summary:"فریاکەوتنی سەرەتایی دەتوانێت ژیان ڕزگار بکات. ئەگەر کەسێک بریندار بوو، دڵی وەستا یان نەیتوانی هەناسە بدات، تۆ دەتوانیت یارمەتیی بدەیت تا ئەمبولانس دەگات. یەکەم کار: پەیوەندی بە ١٢٢ بکە.",blocks:[{heading:"پەستانی سنگ (CPR) بۆ گەورەساڵان",body:`کاتێک دڵی کەسێک دەوەستێت (بێهۆش دەبێت و هەناسە نادات یان بە دروستی هەناسە نادات):
١. دڵنیا بە کە شوێنەکە بۆ تۆ سەلامەتە.
٢. شانەکانی بجووڵێنە و بە دەنگی بەرز بپرسە: «باشیت؟»
٣. ئەگەر وەڵامی نەدایەوە، پەیوەندی بە ١٢٢ بکە و کەسێک بنێرە بۆ هێنانی ئامێری شۆکی دڵ (AED).
٤. ٣٠ پەستان لە ناوەڕاستی سنگ بدە: قووڵی ٥-٦ سم، خێرایی ١٠٠-١٢٠ پەستان لە خولەکێکدا.
٥. ئەگەر فێر بوویت، ٢ هەناسە بدە (سەری بەرەو دواوە بەرە، چەناگەی بەرز بکەرەوە و لووتی بگرە). ئەگەر فێر نەبوویت یان نەتەوێت هەناسە بدەیت، تەنها پەستانی سنگ بدە (Hands-Only CPR)، بەبێ وەستان.
٦. ٣٠:٢ (یان تەنها پەستان) دووبارە بکەرەوە تا تیمی ئەمبولانس دەگات.

• AED: ئەگەر هەبوو، یەکسەر بیکەرەوە و بەپێی دەنگی ئامێرەکە کار بکە.`},{heading:"خوێنبەربوون — وەستاندنی خوێن",body:`• پەستانی ڕاستەوخۆ: پەڕۆیەکی پاک بخە سەر برینەکە و بە هێز پەستان بدە. دەستت هەڵمەگرە تا خوێنەکە دەوەستێت.
• ئەگەر پەڕۆکە بە خوێن تەڕ بوو، لای مەبە؛ پەڕۆیەکی تر بخە سەری و بەردەوام پەستان بدە.
• تۆرنیکێت (Tourniquet): بۆ خوێنبەربوونێکی زۆر توند لە دەست یان قاچەکان، ٥-٧ سم لە سەرووی برینەکەوە (نە لەسەر ئەژنۆ یان ئانیشک) بیبەستە و توندی بکە تا خوێنەکە دەوەستێت. کاتی بەستنەکەی بنووسە و هەرگیز شلی مەکەرەوە.
• ئەگەر شتێک لە برینەکەدا چەقیبوو، دەری مەهێنە! لە دەوروبەریدا پەستان بدە و پەیوەندی بە ١٢٢ بکە.`},{heading:"سووتان — فریاکەوتنی سەرەتایی",body:`• سووتانی سووک: یەکسەر ئاوی فێنکی ڕەوان بۆ ماوەی ٢٠ خولەک بکە سەر شوێنی سووتانەکە (نە سەهۆڵ و نە ئاوی زۆر سارد).
• بڵقەکانی سووتان مەتەقێنە و کەرە، ڕۆن یان هەویری ددانی لێ مەدە.
• دوای ساردکردنەوە، بە پەڕۆیەکی پاک یان نایلۆنی خۆراک بە سووکی دایپۆشە.
• سووتانی توند یان گەورە: پەیوەندی بە ١٢٢ بکە. ئەگەر جل بە پێستەوە نووسابوو، ڕای مەکێشە. لەشی بە گەرمی ڕابگرە.`},{heading:"خنکان بە شتێک (Choking)",body:`نیشانەکان: کەسەکە ناتوانێت قسە بکات، بکۆکێت یان هەناسە بدات و دەستەکانی بە گەرووی خۆیەوە دەگرێت.
• گەورەساڵ و منداڵ (لە یەک ساڵ و سەرووتر): ٥ لێدان بە بنی لەپی دەست لە نێوان هەردوو شانیدا بدە. پاشان ٥ پەستانی سک (Heimlich): لە پشتیەوە بوەستە، مشتت کەمێک لە سەرووی ناوکەوە و زۆر لە خوار ئێسکی سنگەوە دابنێ و بە خێرایی بەرەو ناوەوە و بەرەو سەرەوە پەستان بدە. ٥+٥ دووبارە بکەرەوە.
• ساوا (کەمتر لە یەک ساڵ): ساواکە لەسەر باسکت دابنێ، ڕووی بەرەو خوارەوە و سەری نزمتر لە سنگی، و ٥ لێدان لە پشتی بدە. پاشان لەسەر پشت وەریبگێڕە و بە بنی لەپی یەک دەست ٥ پەستان لە ناوەڕاستی سنگی بدە. هەرگیز پەستانی سک بۆ ساوا مەکە.
• ئەگەر بێهۆش بوو، پەیوەندی بە ١٢٢ بکە و دەست بە CPR بکە.`}],tips:["هەمیشە یەکەم کار پەیوەندی بە ١٢٢ بکە.","ئەگەر هەبوو، دەستکێش بەکاربهێنە.","جانتای فریاکەوتنی سەرەتایی لە ماڵەوە و لە ئۆتۆمبێلدا هەبێت.","خولێکی فریاکەوتنی سەرەتایی ببینە.","کات گرنگە — زوو دەست بە یارمەتیدان بکە."],warnings:["پێش هەموو شتێک، سەلامەتیی خۆت بپشکنە.","ئەگەر کەسێک لە شوێنێکی بەرزەوە کەوتبێت، مەیجووڵێنە (لەوانەیە ملی یان پشتی بریندار بێت)، مەگەر شوێنەکە مەترسیدار بێت یان پێویستی بە CPR هەبێت.","هیچ شتێک مەخە ناو دەمی کەسی بێهۆشەوە.","بە دەستی پیس دەست لە برین مەدە."],activity:{prompt:"کەسێک لە ماڵەوە بە شتێک خنکاوە و ناتوانێت قسە بکات یان هەناسە بدات. چی دەکەیت؟",options:[{text:"٥ لێدان لە پشتی دەدەم، پاشان ٥ پەستانی سک (Heimlich) دەدەم و دووبارەی دەکەمەوە",correct:!0,feedback:"کەسێک کە ناتوانێت قسە بکات یان هەناسە بدات بە تەواوی خنکاوە؛ ٥ لێدان لە پشت و پاشان ٥ پەستانی سک، بە دووبارەکردنەوە، دەتوانن شتەکە دەربهێنن."},{text:"ئاوی پێدەدەم بیخواتەوە",correct:!1,feedback:"خواردنەوەی ئاو چارەسەری خنکان نییە: ٥ لێدان لە پشت بدە، پاشان ٥ پەستانی سک، و دووبارەی بکەرەوە."},{text:"پەنجەکانم بە قووڵی دەخەمە ناو دەمییەوە",correct:!1,feedback:"وانەکە ئەمە فێر ناکات: ٥ لێدان لە پشت بدە، پاشان ٥ پەستانی سک، و دووبارەی بکەرەوە."},{text:"چاوەڕێ دەکەم تا باشتر دەبێت",correct:!1,feedback:"کەسێک کە ناتوانێت هەناسە بدات ناتوانێت چاوەڕێ بکات: یەکسەر دەست بە لێدانی پشت و پەستانی سک بکە."}]},quiz:[{question:"لە کاتی CPR بۆ گەورەساڵان، ڕێژەی پەستان بۆ هەناسە چەندە؟",options:[{text:"١٠ پەستان و ١ هەناسە",correct:!1},{text:"٣٠ پەستان و ٢ هەناسە",correct:!0},{text:"١٥ پەستان و ٢ هەناسە",correct:!1},{text:"٥٠ پەستان و ٥ هەناسە",correct:!1}],explanation:"CPR بۆ گەورەساڵان ٣٠ پەستانی سنگە، پاشان ٢ هەناسە ئەگەر فێر بوویت. ئەگەر فێر نەبوویت، تەنها پەستان بدە (Hands-Only CPR)، بەبێ وەستان."},{question:"بۆ سووتانی سووک چی دەکەین؟",options:[{text:"سەهۆڵی لەسەر دادەنێین",correct:!1},{text:"کەرەی لێدەدەین",correct:!1},{text:"ئاوی فێنکی ڕەوان بۆ ماوەی ٢٠ خولەک",correct:!0},{text:"نەوتی لێدەدەین",correct:!1}],explanation:"سووتانی سووک بۆ ماوەی ٢٠ خولەک بە ئاوی فێنکی ڕەوان سارد بکەرەوە. سەهۆڵ، کەرە، ڕۆن یان هیچ ماددەیەکی تری لێ مەدە."},{question:"ژمارەی ئەمبولانس چەندە؟",options:[{text:"١١٥",correct:!1},{text:"١٢٢",correct:!0},{text:"١٠٤",correct:!1},{text:"٩١١",correct:!1}],explanation:"لە هەرێمی کوردستان، ١٢٢ ژمارەی ئەمبولانسە؛ ١١٥ بەرگریی شارستانییە و ١٠٤ پۆلیسە."}]},{id:5,icon:"Backpack",accent:"#9333ea",title:"جانتای تەنگانە",subtitle:"ئامادەکردنی جانتایەک بۆ کاتی تەنگانە",summary:"جانتای تەنگانە ئەو جانتایەیە کە پێداویستییەکانی کاتی تەنگانەی تێدایە، وەک بوومەلەرزە، لافاو یان هەر ڕووداوێکی تر. پێویستە هەموو ماڵێک جانتایەکی وای هەبێت.",blocks:[{heading:"ئاو و خۆراک",body:`• ئاو: نزیکەی ٤ لیتر بۆ هەر کەسێک لە ڕۆژێکدا، بۆ لانیکەم ٣ ڕۆژ (بۆ خواردنەوە و پاکوخاوێنی).
• خۆراکی قوتوو یان خۆراکی وشک کە پێویستی بە لێنان نەبێت.
• بیسکیت، خورما و شیرینی.`},{heading:"کەرەستەی پزیشکی",body:"باندێج، پەڕۆی پاکی برینپێچ، شریتی پزیشکی، دەستکێش، مقەست، مووچنە، و دەرمانی تایبەتی ئەندامانی خێزان (ئەگەر هەبێت)."},{heading:"کەرەستە گرنگەکان",body:"چرای دەستی و پاتری، ڕادیۆیەکی بچووک، پاوەر بانک بۆ شەحنکردنی مۆبایل، جلی زیادە، بەتانی و فیکەیەک بۆ داوای یارمەتی."},{heading:"بەڵگەنامە و پارە",body:"کۆپیی ناسنامە و پاسپۆرت، بڕێک پارەی نەختینە، لیستی ژمارە گرنگەکان و کلیلی زیادە."}],tips:["جانتایەکی سووک هەڵبژێرە کە بە ئاسانی هەڵبگیرێت.","هەر ٦ مانگ جارێک ناوەڕۆکی جانتاکە بپشکنە و ئەو ئاو و خۆراکەی ماوەیان بەسەرچووە بیانگۆڕە.","جانتاکە لە شوێنێکی نزیک دەرگا دابنێ کە بە ئاسانی پێی بگەیت.","شتی تایبەت بۆ هەر ئەندامێکی خێزان (منداڵ، بەساڵاچوو، نەخۆش) تێیدا دابنێ.","ئاژەڵە ماڵییەکانیش لەبیر مەکە."],warnings:["دڵنیا بە کە ئاو و خۆراک بەشی هەموو ئەندامانی خێزان دەکات.","دەرمانەکانت لەبیر مەکە.","مۆبایل و شەحنکەرێکی تێدا بێت.","پارەی نەختینە گرنگە، چونکە لەوانەیە کارتی بانک کار نەکات."],activity:{prompt:"دوای بوومەلەرزەیەک، پێویستە بە خێرایی ماڵەکە چۆڵ بکەن. جانتای تەنگانە لە ماڵەوە ئامادەیە. چی دەکەیت؟",options:[{text:"جانتاکە هەڵدەگرم و دەچمە خاڵی کۆبوونەوە",correct:!0,feedback:"بردنی جانتا ئامادەکە بۆ خاڵی کۆبوونەوە ئاو و خۆراک و دەرمانت دەداتێ بەبێ ئەوەی کات بەفیڕۆ بچێت."},{text:"ماوەیەک دەگەڕێم بۆ ئەوەی شتی تر کۆبکەمەوە",correct:!1,feedback:"گەڕان بەدوای شتی تردا کات بەفیڕۆ دەدات لە ماڵێکدا کە لەوانەیە زیانلێکەوتوو بێت؛ جانتا ئامادەکە هەڵبگرە و دەربچۆ."},{text:"جانتاکە بەجێ دەهێڵم و بە تەنها ڕادەکەم",correct:!1,feedback:"بەجێهێشتنی جانتاکە واتە ئەو ئاو و خۆراک و دەرمانانەی ئامادەت کردبوون لەدەست دەدەیت؛ جانتاکە ئامادەیە، بۆیە لەگەڵ خۆتی ببە."},{text:"لە ماڵەوە دەمێنمەوە و چاوەڕێ دەکەم",correct:!1,feedback:"دەبێت ماڵەکە چۆڵ بکەن: مانەوە لە ماڵێکدا کە لەوانەیە زیانلێکەوتوو بێت مەترسیدارە، بۆیە جانتاکە هەڵبگرە و بچۆ بۆ خاڵی کۆبوونەوە."}]},quiz:[{question:"بۆ هەر کەسێک، پێویستە چەند ئاو لە جانتای تەنگانەدا هەبێت؟",options:[{text:"١ لیتر بەسە",correct:!1},{text:"نزیکەی ٤ لیتر لە ڕۆژێکدا، بۆ لانیکەم ٣ ڕۆژ",correct:!0},{text:"نیو لیتر",correct:!1},{text:"هیچ جیاوازییەک نییە",correct:!1}],explanation:"بۆ هەر کەسێک نزیکەی ٤ لیتر ئاو لە ڕۆژێکدا ئامادە بکە، بۆ لانیکەم ٣ ڕۆژ، بۆ خواردنەوە و پاکوخاوێنی."},{question:"پێویستە چەند جار ناوەڕۆکی جانتاکە بپشکنین؟",options:[{text:"هەر ١٠ ساڵ جارێک",correct:!1},{text:"هەر ٦ مانگ جارێک",correct:!0},{text:"تەنها لە کاتی کڕیندا",correct:!1},{text:"هەرگیز پێویستی بە پشکنین نییە",correct:!1}],explanation:"هەر ٦ مانگ جارێک جانتاکە بپشکنە و ئەو ئاو و خۆراکەی ماوەیان بەسەرچووە بیانگۆڕە."},{question:"کام لەم شتانە لە جانتای تەنگانەدا پێویست نییە؟",options:[{text:"ئاو",correct:!1},{text:"چرای دەستی",correct:!1},{text:"تەلەفزیۆن",correct:!0},{text:"دەرمان",correct:!1}],explanation:"تەلەفزیۆن پێویست نییە. جانتاکە ئەو شتانەی تێدایە کە لە تەنگانەدا پێویستن: ئاو، خۆراک، دەرمان، چرای دەستی و ڕادیۆیەکی بچووک."}]},{id:6,icon:"PhoneCall",accent:"#16a34a",title:"ژمارەکانی تەنگانە",subtitle:"زانینی ژمارەکان و چۆنیەتیی پەیوەندیکردن",summary:"زانینی ژمارەکانی تەنگانە دەتوانێت ژیان ڕزگار بکات. پێویستە هەموو کەسێک ئەم ژمارانە لەبەر بکات و بزانێت کەی و چۆن پەیوەندی بکات.",blocks:[{heading:"ژمارە سەرەکییەکان لە هەرێمی کوردستان",body:`• ١١٥: بەرگریی شارستانی (ئاگر، ڕزگارکردن، ڕووخانی بینا، لافاو، دزەکردنی گاز و مادە مەترسیدارەکان).
• ١٢٢: ئەمبولانس (تەنگانە پزیشکییەکان).
• ١٠٤: پۆلیس.`},{heading:"چۆنیەتیی پەیوەندیکردن",body:"ئارام بە و بە ڕوونی قسە بکە. پێش هەموو شتێک شوێنی دروست بڵێ: گەڕەک، شەقام، نیشانەیەکی دیاری نزیک و نهۆم. پاشان بڵێ چی ڕوویداوە، چەند کەس بریندار بوون یان گیریان خواردووە، و هەر مەترسییەک (بڵاوبوونەوەی ئاگر، گاز، کارەبا، مادەی کیمیایی). ناوی خۆت و ژمارەی تەلەفۆنەکەت بڵێ. وەڵامی پرسیارەکان بدەوە، ڕێنماییەکانیان جێبەجێ بکە و تەلەفۆنەکە دامەخە تا ئەوان پێت نەڵێن."},{heading:"کەی پەیوەندی بە کام ژمارەوە بکەین",body:`• ئاگر، دووکەڵ، تەقینەوە، ڕووخان، لافاو یان کەسێکی گیرخواردوو: ١١٥.
• برینداربوون، نەخۆشییەکی قورس یان کەسێکی بێهۆش: ١٢٢.
• دزی، هەڕەشە و ڕووداوە ئەمنییەکان: ١٠٤.
• ئەگەر ئاگر یان ڕووداو و بریندار پێکەوە هەبوون: ١١٥ و ١٢٢.`},{heading:"ناونیشانی دروست",body:"ناوی گەڕەک و شەقام، نیشانە دیارەکانی نزیک (مزگەوت، قوتابخانە، دوکان)، ژمارەی خانوو و ڕەنگەکەی بڵێ."}],tips:["ژمارەکان لە مۆبایلەکەتدا تۆمار بکە.","لیستی ژمارەکان لە شوێنێکی دیاری ماڵەوە دابنێ.","ژمارەکان فێری منداڵان بکە.","ناونیشانی ماڵەوە فێری منداڵان بکە.","ناونیشانی ماڵەکەت بە دروستی لەبەر بکە."],warnings:["هەرگیز پەیوەندیی درۆ یان گاڵتەجاڕی مەکە — ئەوانە یارمەتی لە کەسانی پێویست دوور دەخەنەوە.","هێڵی تەنگانە بێ هۆ سەرقاڵ مەکە — ژیانی خەڵکی تر لە مەترسیدایە.","ئارام بە و بە ڕوونی قسە بکە.","ناونیشانی دروست زۆر گرنگە."],activity:{prompt:"بینیت ئۆتۆمبێلێک لەسەر شەقام لە کەسێکی دا و بریندار بوو. چی دەکەیت؟",options:[{text:"پەیوەندی بە ١٢٢ دەکەم، ناونیشانەکە دەڵێم و باری بریندارەکە ڕادەگەیەنم",correct:!0,feedback:"کەسی بریندار پێویستی بە ئەمبولانسە: پەیوەندیکردن بە ١٢٢ لەگەڵ ناونیشانی دروست و باری بریندارەکە یارمەتی بە خێرایی دەگەیەنێت."},{text:"بە ڕێگای خۆمدا دەڕۆم",correct:!1,feedback:"ڕۆیشتن بە ڕێگای خۆتدا کەسی بریندار بێ یارمەتی بەجێ دەهێڵێت؛ پەیوەندی بە ١٢٢ بکە و ناونیشانی دروست بڵێ."},{text:"ڤیدیۆ دەگرم",correct:!1,feedback:"ڤیدیۆگرتن یارمەتی بریندارەکە نادات و ڕێزی لێ ناگرێت؛ سەرەتا پەیوەندی بە ١٢٢ بکە و ناونیشانی دروست بڵێ."},{text:"تەنها سەیر دەکەم",correct:!1,feedback:"تەنها سەیرکردن یارمەتی نادات و کات بەفیڕۆ دەدات؛ یەکسەر پەیوەندی بە ١٢٢ بکە و ناونیشانی دروست بڵێ."}]},quiz:[{question:"ژمارەی بەرگریی شارستانی (ئاگر و ڕزگارکردن) چەندە؟",options:[{text:"١٢٢",correct:!1},{text:"١٠٤",correct:!1},{text:"١١٥",correct:!0},{text:"٩١١",correct:!1}],explanation:"١١٥ بەرگریی شارستانییە: ئاگر، ڕزگارکردن، ڕووخانی بینا، لافاو، دزەکردنی گاز و مادە مەترسیدارەکان. ١٢٢ ئەمبولانسە و ١٠٤ پۆلیسە."},{question:"کاتێک پەیوەندی دەکەیت، پێویستە کام زانیارییانە بدەیت؟",options:[{text:"تەنها ناوی خۆت",correct:!1},{text:"پێش هەموو شتێک شوێنی دروست، پاشان چی ڕوویداوە، چەند کەس بریندار بوون یان گیریان خواردووە، هەر مەترسییەک، و ناو و ژمارەی تەلەفۆنەکەت",correct:!0},{text:"تەنها ناونیشان",correct:!1},{text:"هیچ زانیارییەک پێویست نییە",correct:!1}],explanation:"پێش هەموو شتێک شوێنی دروست بڵێ بۆ ئەوەی یارمەتی بگاتە لات؛ پاشان چی ڕوویداوە، چەند کەس بریندار بوون یان گیریان خواردووە، هەر مەترسییەک، و ناو و ژمارەی تەلەفۆنەکەت."},{question:"ژمارەی ئەمبولانس چەندە؟",options:[{text:"١١٥",correct:!1},{text:"١٢٢",correct:!0},{text:"١٠٤",correct:!1},{text:"١٠٠",correct:!1}],explanation:"١٢٢ ژمارەی ئەمبولانسە، بۆ برینداربوون، نەخۆشیی قورس و کەسی بێهۆش. ١١٥ بەرگریی شارستانییە و ١٠٤ پۆلیسە."}]},{id:7,icon:"FireExtinguisher",accent:"#dc2626",title:"ئاگرکوژێنەرەوە — ڕاهێنانێکی تەواو",subtitle:"ناسینی جۆرەکانی ئاگرکوژێنەرەوە، پۆلەکانی ئاگر و ڕێگای PASS",summary:"ئاگرکوژێنەرەوە (Fire Extinguisher) ئامێرێکی سەرەکییە بۆ کوژاندنەوەی ئاگرە بچووکەکان لە سەرەتایاندا. پێویستە هەموو کەسێکی گەورە لە ماڵەوە و لە شوێنی کار بزانێت چۆن بە خێرایی و بە دروستی بەکاری بهێنێت، چونکە ئاگرکوژێنەرەوە دەستییەکان تەنها چەند چرکەیەک کار دەکەن. ئەگەر ئاگرەکە گەورە بوو، ئاگرکوژێنەرەوەکە بەجێ بهێڵە، دەرچۆ و پەیوەندی بە ١١٥ بکە.",blocks:[{heading:"پۆلەکانی ئاگر (بەپێی NFPA)",body:`• پۆلی A: کەرەستە ڕەقە ئاساییەکان (دار، کاغەز، قوماش).
• پۆلی B: شلە و گازە گڕگرەکان (بەنزین، نەوت، گاز). ئاو شلەی سووتاو بڵاو دەکاتەوە.
• پۆلی C: ئامێرە کارەباییەکان کە کارەبایان تێدایە. ئاو و کەف بەکارمەهێنە.
• پۆلی D: کانزا گڕگرەکان (وەک مەگنیسیۆم). ئاو کاردانەوەیەکی توند و تەقینەوە دروست دەکات.
• پۆلی K: ڕۆن و چەوریی چێشتخانە. ئاو ڕۆنی گەرم بە ئاگرێکی گەورەوە بڵاو دەکاتەوە.`},{heading:"جۆرەکانی ئاگرکوژێنەرەوە",body:`پۆلەکان بە پیتەکانی NFPA نووسراون:
• ئاو: تەنها بۆ پۆلی A.
• CO₂: بۆ پۆلی B و ئامێرە کارەباییەکان کە کارەبایان تێدایە (B و C بەپێی NFPA؛ بەپێی EN 2، C گازە و CO₂ بۆ ئاگری گاز نییە). مەودای کورتە و بۆ ئاگری قووڵی دار و کاغەز نییە. تەنها دەسکەکە بگرە و دەست لە سەری لوولەکە مەدە — زۆر سارد دەبێت و پێست دەسووتێنێت. لە ژوورێکی بچووکدا دوای بەکارهێنان دەرچۆ و هەوا بگۆڕە، چونکە CO₂ ئۆکسجین دەردەکات.
• تۆزی ABC: بۆ A، B و C. نە بۆ پۆلی D و نە بۆ پۆلی K.
• کەف: بۆ A و B. بۆ ئامێرە کارەباییەکان بەکاری مەهێنە.
• گازی پاک (Clean Agent): بۆ ئامێرە هەستیارەکان وەک کۆمپیوتەر؛ پۆلەکانی بەپێی مۆدێل جیاوازن، بۆیە لەیبڵەکە بخوێنەرەوە.
• کیمیایی شل (Wet Chemical): بۆ ڕۆنی چێشتخانە (پۆلی K).
• پۆلی D: تەنها ئاگرکوژێنەرەوە یان ماددەیەک کە ناوی ئەو کانزایەی دەسووتێت لەسەر لەیبڵەکەی هاتبێت.`},{heading:"ڕێگای PASS",body:`پێش بەکارهێنانی ئاگرکوژێنەرەوە (دەبێت هەموو وەڵامەکان «بەڵێ» بن):
• ئاگرەکە بچووکە و تازە دەستی پێکردووە، وەک ئاگرێک لە سەتڵی زبڵ یان تاوەیەکدا.
• ئاگرکوژێنەرەوەکە گونجاوە بۆ ئەم جۆرە ئاگرە.
• ڕێگای دەرچوون لە پشتتەوەیە و ئاگرەکە لە نێوان تۆ و دەرچوونەکەدا نییە.
• ئاگادارکردنەوە دراوە: ئەوانی تر ئاگادار کراونەتەوە و پەیوەندی بە ١١٥ەوە کراوە.
• تۆ بۆ بەکارهێنانی ئاگرکوژێنەرەوە ڕاهێنراویت.
• هیچ دووکەڵ یان گەرمایەک ڕێگای دەرچوونت ناگرێت.
• ئەگەر ئاگرەکە یەکسەر نەکوژایەوە، بوەستە، دەرچۆ و دەرگاکە لە دوای خۆتەوە دابخە.

١. P = Pull (ڕابکێشە): سنجاقی سەلامەتی ڕابکێشە.
٢. A = Aim (ئاڕاستە بکە): سەری لوولەکە بەرەو بنی ئاگرەکە بگرە، نەک بەرەو سەری ئاگرەکە.
٣. S = Squeeze (بگوشە): دەسکی ئاگرکوژێنەرەوەکە بە هێز بگوشە.
٤. S = Sweep (بجووڵێنە): لوولەکە بۆ چەپ و ڕاست بجووڵێنە تا ئاگرەکە دەکوژێتەوە.

PASS ڕێگای گشتییە بۆ زۆربەی ئاگرکوژێنەرەوە دەستییەکان. ئاگرکوژێنەرەوەکانی Class D، کیمیایی شل (Wet Chemical)، گازی پاک (Clean Agent) و ئەوانەی لەسەر تایەن: بەپێی لەیبڵ و ڕێنماییەکانی کۆمپانیای دروستکەر بەکاریان بهێنە.`},{heading:"پشکنینی ئاگرکوژێنەرەوە",body:`پشکنینی چاوی هەموو مانگێک، لەلایەن کەسی بەرپرسەوە:
• ئاگرکوژێنەرەوەکە لە شوێنی خۆیدایە، دیارە و بە ئاسانی دەگاتێ.
• سنجاقی سەلامەتی و مۆرەکەی لە شوێنی خۆیاندا بن.
• لەیبڵەکە دەخوێنرێتەوە و ڕووی لە دەرەوەیە.
• لوولەکە نە شکاو و نە کونبوو بێت، و سەری لوولەکە نەگیرابێت.
• لەشی ئاگرکوژێنەرەوەکە نە ژەنگاوی، نە شکاو بێت و نە دزە بکات.
• ئەگەر پەستانپێوی هەبێت، دەرزییەکەی لە ناوچەی سەوزدا بێت. ئاگرکوژێنەرەوەی CO₂ پەستانپێوی نییە: هەڵیبگرە بۆ ئەوەی هەست بکەیت پڕە.

خزمەتگوزاریی کەسێکی پسپۆڕ:
• پشکنین و چاککردنەوە (Maintenance): ساڵی جارێک.
• پڕکردنەوە (Recharge): دوای هەر بەکارهێنانێک، تەنانەت ئەگەر کورتیش بێت.
• چاککردنەوەی ٦ ساڵە: ئاگرکوژێنەرەوەکانی تۆزی وشکی پەستانی هەڵگیراو (stored-pressure) کە پێویستیان بە تاقیکردنەوەی پەستانی ١٢ ساڵە هەیە، هەر ٦ ساڵ جارێک بەتاڵ دەکرێنەوە و ناوەوەیان دەپشکنرێت.
• تاقیکردنەوەی پەستانی لەشەکەی (Hydrostatic test): هەر ٥ ساڵ بۆ ئاگرکوژێنەرەوەکانی ئاو، کەف (AFFF)، CO₂ و تۆزی وشکی ستێنلێس ستیل (stainless steel)؛ هەر ١٢ ساڵ بۆ ئاگرکوژێنەرەوەکانی تۆزی وشکی پەستانی هەڵگیراو کە لەشیان لە پۆڵای ئاسایی (mild steel)، بڕنجی لەحیمکراو (brazed brass) یان ئەلەمنیۆمە.

کاتی تاقیکردنەوە کاتی گۆڕین نییە. ئاگرکوژێنەرەوە لە کار دەخرێت ئەگەر لە پشکنین یان تاقیکردنەوەدا سەرنەکەوت، خراپ بوو، کۆن بوو یان کۆمپانیای دروستکەر گەڕاندییەوە (recall)، لەیبڵەکەی نەخوێنرایەوە، یان ئاگرکوژێنەرەوەیەکی پڕنەکراوە بوو و ماوەی کارکردنی سەر لەیبڵەکەی بەسەرچوو. ڕێساکانی دهۆک هێشتا پشتڕاست نەکراونەتەوە.`},{heading:"مەترسییە تایبەتەکان لە ماڵەوە و لە کۆمەڵگادا",body:`• چێشتخانە: ڕۆنی چێشتخانە (پۆلی K) — ئاگرکوژێنەرەوەی Wet Chemical یان سەرقاپێکی گەورە بەکاربهێنە.
• کارەبا: پلاک و وایەر — پۆلی C.
• سۆبەی گاز و سلیندەر: گاز — پۆلی B؛ گرنگترین شت ڕاگرتنی گازەکەیە: کەسێکی شارەزا سەمامەی گاز دادەخات تەنها ئەگەر گەیشتن پێی سەلامەت بێت. ئەگەر گازەکە بە سەلامەتی ڕانەگیرێت، ئاگری گازەکە مەکوژێنەرەوە: هەمووان دەربهێنە و پەیوەندی بە ١١٥ بکە.
• بەنزین و نەوت: دوور لە ماڵ و لە شوێنێکی هەوادار هەڵیانبگرە.
• ئاگرکوژێنەرەوەی ABC بۆ زۆربەی ئاگرەکانی ماڵ باشە، بەڵام نە بۆ ڕۆنی چێشتخانە (K) و نە بۆ کانزاکان (D).`},{heading:"ڕەنگەکانی ئاگرکوژێنەرەوە (BS EN 3 و BS 7863)",body:`ڕەنگ پۆلی ئاگر نییە. بەپێی ستانداردی ئەورووپیی BS EN 3، لەشی ئاگرکوژێنەرەوە سوورە؛ لە بەریتانیا پارچەیەکی ڕەنگکراو (BS 7863) ماددەکە نیشان دەدات:
• کرێمی = کەف.
• شین = تۆزی وشک.
• ڕەش = CO₂.
• زەرد = Wet Chemical.
• ئاو هیچ پارچەیەکی نییە.

وڵاتانی تر ڕەنگی تر بەکاردەهێنن و ڕەنگەکانی دهۆک هێشتا پشتڕاست نەکراونەتەوە، بۆیە هەمیشە لەیبڵ و نیشانەکانی پۆل بخوێنەرەوە.`},{heading:"پۆلی F (ڕۆنی چێشتخانە) — هەمان پۆلی K",body:`پۆلەکانی ئاگر لێرەدا بە پیتەکانی NFPA 10 نووسراون وەک سەرچاوەی پرۆژە؛ سیستەمی فەرمیی دهۆک هێشتا پشتڕاست نەکراوەتەوە. هاوتاکانی EN 2: NFPA A = EN A؛ NFPA B (شلە) = EN B؛ NFPA B (گاز) = EN C؛ NFPA C (ئامێری کارەبایی کە کارەبای تێدایە) هیچ پۆلێکی EN ی نییە؛ NFPA D = EN D؛ NFPA K = EN F. بۆیە پۆلی F (EN 2) و پۆلی K (NFPA) یەک پۆلن: ئاگری ڕۆن و چەوریی چێشتخانە.
• ڕۆنی زۆر گەرم دەتوانێت لە خۆیەوە ئاگر بگرێت.
• ئاگرکوژێنەرەوەی Wet Chemical گونجاوە: چینێکی وەک سابوون لەسەر ڕۆنەکە دروست دەکات کە ئۆکسجین دەبڕێت و ڕۆنەکە سارد دەکاتەوە.
• ڕێستوران و چێشتخانە گەورەکان پێویستیان بە ئاگرکوژێنەرەوەی پۆلی F/K هەیە.`}],tips:["لانیکەم یەک ئاگرکوژێنەرەوەی ABC لە هەموو ماڵێکدا هەبێت.","ئاگرکوژێنەرەوەکە لە نزیک دەرگای چێشتخانە دابنێ، نەک لە ناو چێشتخانە لە نزیک تەباخەکە.","هەموو ئەندامە گەورەکانی خێزان فێری بەکارهێنانی ئاگرکوژێنەرەوە بکە.","هەموو مانگێک ئاگرکوژێنەرەوەکە بپشکنە؛ ئەگەر پەستانپێوی هەبێت، دەبێت دەرزییەکەی لە ناوچەی سەوزدا بێت (ئاگرکوژێنەرەوەی CO₂ پەستانپێوی نییە: هەڵیبگرە بۆ ئەوەی هەست بکەیت پڕە).","سنجاقی سەلامەتی ڕامەکێشە تا پێویست نەبێت.","لەو دوورییەوە دەست پێبکە کە لەسەر لەیبڵی ئاگرکوژێنەرەوەکە یان لە ڕێنماییەکانی کۆمپانیای دروستکەردا هاتووە، ڕێگای دەرچوون لە پشتتەوە بێت، و تەنها کاتێک ئاگرەکە بچووک دەبێتەوە نزیکتر ببەوە.","پشتت بەرەو دەرگای دەرچوون بێت — بۆ ئەوەی ڕێگای ڕاکردن هەمیشە کراوە بێت.","ساڵی جارێک ئاگرکوژێنەرەوەکە بدە بە کەسێکی پسپۆڕ بۆ ئەوەی چاکی بکاتەوە (Service).","ئاگرکوژێنەرەوەی دەستی تەنها چەند چرکەیەک کار دەکات — پێش دەستپێکردن ئامادە بە."],warnings:["هەرگیز ئاو مەکە سەر ڕۆنی ئاگرگرتوو — ئاگرێکی گەورە بە خێرایی بڵاو دەبێتەوە!","هەرگیز ئاو لەسەر ئامێرە کارەباییەکان بەکارمەهێنە — شۆکی کارەبا!","ئاگرکوژێنەرەوە بەکارمەهێنە ئەگەر ئاگرەکە لە سەتڵێکی زبڵ گەورەتر بوو، بڵاو دەبێتەوە یان دووکەڵ زیاد دەبێت: دەرچۆ و پەیوەندی بە ١١٥ بکە!","هەمیشە سەری لوولەکە بەرەو بنی ئاگرەکە بگرە — نەک بەرەو سەری!","ئاگرکوژێنەرەوەی CO₂: دەست لە سەری لوولەکە مەدە! نزیکەی ٧٨ پلە لە ژێر سفرەوە سارد دەبێت و پێست دەسووتێنێت.","تۆزی ABC لە ژوورێکی داخراودا بینین کەم دەکاتەوە و هەناسەدان قورس دەکات — دوای بەکارهێنان دەرچۆ و دەرگا و پەنجەرەکان بکەرەوە."],activity:{prompt:"لە چێشتخانەی ماڵەوە، ڕۆنی ناو تاوەکە لەسەر تەباخەکە ئاگری گرت! چی دەکەیت؟",options:[{text:"ئاوی دەکەمە سەر",correct:!1,feedback:"ئاو لە ناو ڕۆنی گەرمدا دەبێتە هەڵم و ڕۆنی سووتاو بە ئاگرێکی گەورەوە بڵاو دەکاتەوە؛ هەرگیز ئاوی مەکە سەر."},{text:"ئەگەر سەلامەت بوو تەباخەکە دەکوژێنمەوە و سەرقاپێکی گەورە دەخەمە سەری بۆ ئەوەی ئۆکسجین ببڕم، یان ئاگرکوژێنەرەوەی Wet Chemical بەکاردەهێنم",correct:!0,feedback:"کوژاندنەوەی تەباخەکە و دانانی سەرقاپ لەسەر تاوەکە ئۆکسجین دەبڕێت؛ ئاگرکوژێنەرەوەی Wet Chemical بۆ ڕۆنی چێشتخانە دروستکراوە."},{text:"تاوەکە هەڵدەگرم و دەیبەمە دەرەوە",correct:!1,feedback:"تاوەی ئاگرگرتوو هەڵمەگرە؛ ئەگەر سەلامەت بوو تەباخەکە بکوژێنەرەوە و سەرقاپێکی گەورەی بخەرە سەر."},{text:"بە پارچە جلێک لێی دەدەم بۆ ئەوەی بکوژێتەوە",correct:!1,feedback:"وانەکە ئەمە فێر ناکات: سەرقاپێکی گەورە بخەرە سەر تاوەکە یان ئاگرکوژێنەرەوەی Wet Chemical بەکاربهێنە."}]},quiz:[{question:"بە پیتەکانی NFPA، ئاگرکوژێنەرەوەی CO₂ بۆ کام پۆلەکانی ئاگر گونجاوە؟",options:[{text:"A و D",correct:!1},{text:"B و C",correct:!0},{text:"A و K",correct:!1},{text:"D و K",correct:!1}],explanation:"بە پیتەکانی NFPA، ئاگرکوژێنەرەوەی CO₂ بۆ پۆلی B (شلە گڕگرەکان) و پۆلی C (ئامێرە کارەباییەکان کە کارەبایان تێدایە)یە؛ بۆ ئاگری قووڵی دار و کاغەز، کانزاکان (D) یان ڕۆنی چێشتخانە (K) نییە."},{question:"لە ڕێگای PASS، پێویستە سەری لوولەکە بەرەو کوێ بێت؟",options:[{text:"سەری ئاگرەکە",correct:!1},{text:"بنی ئاگرەکە",correct:!0},{text:"دەوروبەری ئاگرەکە",correct:!1},{text:"بنمیچی ژوورەکە",correct:!1}],explanation:"لە PASS دا، سەری لوولەکە بەرەو بنی ئاگرەکە بگرە، نەک بەرەو سەری ئاگرەکە، و بۆ چەپ و ڕاست بجووڵێنە تا ئاگرەکە دەکوژێتەوە."},{question:"بۆچی ئاو ناکرێتە سەر ئاگری ڕۆن (پۆلی K)؟",options:[{text:"چونکە هیچ کاریگەرییەکی نییە",correct:!1},{text:"چونکە ئاو بە خێرایی دەبێتە هەڵم و ڕۆنی گەرم بە ئاگرێکی گەورەوە بڵاو دەکاتەوە",correct:!0},{text:"چونکە ڕۆن ئاو هەڵدەمژێت",correct:!1},{text:"چونکە ئاو خۆی دەسووتێت",correct:!1}],explanation:"ئاو لە ناو ڕۆنی گەرمدا بە خێرایی دەبێتە هەڵم و ڕۆنی سووتاو بە ئاگرێکی گەورەوە بڵاو دەکاتەوە. لە جیاتی ئاو، سەرقاپێکی گەورە یان ئاگرکوژێنەرەوەی Wet Chemical بەکاربهێنە."},{question:"کام ئاگرکوژێنەرەوە بۆ زۆربەی ئاگرەکانی ماڵ (پۆلەکانی A، B و C) گونجاوە؟",options:[{text:"ئاگرکوژێنەرەوەی ئاو",correct:!1},{text:"ئاگرکوژێنەرەوەی CO₂",correct:!1},{text:"ئاگرکوژێنەرەوەی تۆزی ABC",correct:!0},{text:"ئاگرکوژێنەرەوەی کەف",correct:!1}],explanation:"تۆزی ABC پۆلەکانی A، B و C دەگرێتەوە، بۆیە بۆ زۆربەی ئاگرەکانی ماڵ گونجاوە. بۆ ڕۆنی چێشتخانە (K) و کانزاکان (D) نییە."},{question:"بەپێی کۆدی ڕەنگەکانی بەریتانیا (BS EN 3 لەگەڵ BS 7863)، ڕەنگی پارچە ڕەنگکراوەکەی سەر ئاگرکوژێنەرەوەی Wet Chemical (بۆ ڕۆنی چێشتخانە) چییە؟",options:[{text:"سوور",correct:!1},{text:"ڕەش",correct:!1},{text:"زەرد",correct:!0},{text:"شین",correct:!1}],explanation:"بەپێی کۆدی بەریتانیا، پارچەی زەرد Wet Chemical نیشان دەدات. ڕەنگ هەرگیز پۆلی ئاگر نییە و ڕەنگەکانی دهۆک هێشتا پشتڕاست نەکراونەتەوە، بۆیە هەمیشە لەیبڵەکە بخوێنەرەوە."},{question:"بەپێی NFPA 10، پێویستە کەسێکی پسپۆڕ چەند جار چاککردنەوە (Maintenance) بۆ ئاگرکوژێنەرەوە بکات؟",options:[{text:"هەموو هەفتەیەک",correct:!1},{text:"ساڵی جارێک، لەگەڵ پشکنینێکی چاوی لە هەموو مانگێکدا",correct:!0},{text:"هەر ٢٠ ساڵ جارێک",correct:!1},{text:"پێویستی بە پشکنین نییە",correct:!1}],explanation:"کەسی بەرپرس هەموو مانگێک پشکنینی چاوی دەکات؛ کەسێکی پسپۆڕ ساڵی جارێک پشکنین و چاککردنەوە دەکات و دوای هەر بەکارهێنانێک ئاگرکوژێنەرەوەکە پڕ دەکاتەوە."}]},{id:8,icon:"Heart",accent:"#db2777",title:"فریاکەوتنی سەرەتایی و پەستانی سنگ (CPR)",subtitle:"ڕاهێنانێکی تەواو لەسەر فریاکەوتنی سەرەتایی و زیندووکردنەوەی دڵ",summary:"فریاکەوتنی سەرەتایی (First Aid) ئەو یارمەتییە سەرەتاییەیە کە پێش گەیشتنی تیمی پزیشکی پێشکەشی کەسی بریندار یان نەخۆش دەکرێت. پێویستە هەموو کەسێک لە کۆمەڵگادا بزانێت چۆن CPR بکات، خوێنبەربوون بوەستێنێت و بریندار بپارێزێت تا ئەمبولانس دەگات. ئەم وانەیە دەتوانێت ژیانی تۆ و خێزانەکەت بپارێزێت.",blocks:[{heading:"پەستانی سنگ (CPR) — زیندووکردنەوەی دڵ و سییەکان",body:`١. سەلامەتیی شوێنەکە بپشکنە.
٢. شانەکانی بریندارەکە بجووڵێنە و بپرسە: «باشیت؟»
٣. ئەگەر وەڵامی نەدایەوە و بە دروستی هەناسەی نەدا، پەیوەندی بە ١٢٢ بکە و داوای ئامێری شۆکی دڵ (AED) بکە.
٤. ٣٠ پەستان لە ناوەڕاستی سنگ بدە: ١٠٠-١٢٠ پەستان لە خولەکێکدا، قووڵی ٥-٦ سم بۆ هەموو گەورەساڵان.
٥. ئەگەر فێر بوویت و دەتەوێت، ٢ هەناسە بدە، هەر یەکەیان بە درێژایی یەک چرکە. ئەگەر فێر نەبوویت یان نەتەوێت هەناسە بدەیت، تەنها پەستانی سنگ بدە (Hands-Only CPR)، بەبێ وەستان.
٦. ٣٠:٢ (یان تەنها پەستان) بەردەوام بکە تا تیمی ئەمبولانس دەگات.
٧. ئەگەر AED هەبوو، یەکسەر بەکاری بهێنە.`},{heading:"وەستاندنی خوێنبەربوون",body:`• پەستانی ڕاستەوخۆ: پەڕۆیەکی پاک بخە سەر برینەکە و بە هێز پەستان بدە.
• ئەگەر پەڕۆکە بە خوێن تەڕ بوو، لای مەبە؛ پەڕۆیەکی تر بخە سەری و بەردەوام پەستان بدە.
• تۆرنیکێت (Tourniquet): بۆ خوێنبەربوونی زۆر توندی دەست و قاچەکان، ٥-٧ سم لە سەرووی برینەکەوە بیبەستە، کاتی بەستنەکەی بنووسە و هەرگیز شلی مەکەرەوە.
• ئەو شتەی لە برینەکەدا چەقیوە دەری مەهێنە!`},{heading:"چارەسەرکردنی سووتان",body:`• سووتان بە گەرمی: ئاوی فێنکی ڕەوان بۆ ماوەی ٢٠ خولەک.
• سووتان بە مادەی کیمیایی: بە ئاوی زۆر بیشۆ، لانیکەم بۆ ماوەی ٢٠ خولەک.
• سووتان بە کارەبا: یەکەم کار کارەبا ببڕە! پاشان پەیوەندی بە ١٢٢ بکە.
• بڵقەکانی سووتان مەتەقێنە و کەرە، ڕۆن یان هەویری ددان بەکارمەهێنە.`},{heading:"شکان و کەوتن",body:`• ئەندامی بریندار مەجووڵێنە — بە دارێک یان تەختەیەک جێگیری بکە (Splint).
• ئەو کەسەی لە شوێنێکی بەرزەوە کەوتووە مەیجووڵێنە: لەوانەیە ملی یان پشتی بریندار بێت. بە جێگیری ڕایبگرە و پەیوەندی بە ١٢٢ بکە. تەنها ئەگەر شوێنەکە مەترسیدار بێت (ئاگر، هاتوچۆ، ڕووخان، گاز، بەرزبوونەوەی ئاو) بیجووڵێنە، و سەر، مل و پشتی لەسەر یەک هێڵ ڕابگرە. ئەگەر پێویستی بە CPR هەبێت، لەسەر پشت لەسەر ڕووێکی ڕەق پاڵی بخە. لەسەر لا (دۆخی چاکبوونەوە) دایمەنێ.
• سەهۆڵ لە پەڕۆیەکدا بپێچە و بیخە سەر شوێنە ئاوساوەکە.`},{heading:"شۆکی کارەبا",body:`• یەکسەر کارەبا ببڕە! تا کارەبا نەبڕدرێت، دەست لە بریندارەکە مەدە.
• ئەگەر نەتتوانی کارەبا ببڕیت (تەنها بۆ کارەبای ماڵ)، بە دارێکی وشک وایەرەکە لە بریندارەکە دوور بخەرەوە.
• پەیوەندی بە ١٢٢ بکە؛ پێویستە هەر کەسێک کارەبا لێیدابێت لەلایەن پزیشکەوە بپشکنرێت.`},{heading:"خنکان بە شتێک — ڕێگای Heimlich",body:`ئەگەر کەسێک نەتوانێت قسە بکات، بکۆکێت یان هەناسە بدات و دەستەکانی بە گەرووی خۆیەوە بگرێت، ئەوا بە شتێک خنکاوە.
• ٥ لێدان بە بنی لەپی دەست لە نێوان هەردوو شانیدا بدە.
• ٥ پەستانی سک (Heimlich): لە پشتیەوە بوەستە، مشتت کەمێک لە سەرووی ناوکەوە و زۆر لە خوار ئێسکی سنگەوە دابنێ، بە دەستەکەی ترت بیگرە و بە خێرایی بەرەو ناوەوە و بەرەو سەرەوە پەستان بدە.
• ٥+٥ بەردەوام بکە تا شتەکە دەردەچێت یان کەسەکە بێهۆش دەبێت؛ ئەگەر بێهۆش بوو، پەیوەندی بە ١٢٢ بکە و دەست بە CPR بکە.
• ساوا (کەمتر لە یەک ساڵ): ٥ لێدان لە پشت (سەری نزمتر لە سنگی) و ٥ پەستان لە سنگ. هەرگیز پەستانی سک بۆ ساوا مەکە.`},{heading:"دۆخی چاکبوونەوە (Recovery Position)",body:`ئەگەر کەسێک بێهۆش بوو بەڵام بە دروستی هەناسە دەدات، و گومانی برینداربوونی مل یان پشت نەبوو، بیخە دۆخی چاکبوونەوە:
١. ئەو دەستەی کە لە تۆوە نزیکە بە گۆشەیەکی ڕاست بەرەو سەری دابنێ.
٢. دەستە دوورەکەی بهێنە سەر سنگی و پشتی دەستەکەی لە ژێر ڕوومەتیدا دابنێ.
٣. ئەژنۆی قاچە دوورەکەی بەرز بکەرەوە.
٤. بە گرتنی ئەژنۆ و شانی، بەرەو لای خۆت لەسەر لایەک وەریبگێڕە.
٥. سەری کەمێک بەرەو دواوە بەرە بۆ ئەوەی ڕێگای هەوا کراوە بمێنێتەوە.

• پەیوەندی بە ١٢٢ بکە و چاودێریی هەناسەدانی بکە تا ئەمبولانس دەگات.`}],tips:["هەموو ماڵێک جانتایەکی فریاکەوتنی سەرەتایی هەبێت.","لیستی ژمارەکانی تەنگانە لە شوێنێکی دیار بێت.","هەموو خێزانەکەت فێری CPR و ڕێگای Heimlich بکە.","پەڕۆی پاک، تۆرنیکێت و مقەست لە جانتاکەدا بن.","١٢٢ هەمیشە ئامادەیە — مەترسە و پەیوەندی بکە.","مێشک بێ ئۆکسجین بە خێرایی زیان دەبینێت — بە خێرایی دەست بە CPR بکە.","بۆ هەموو گەورەساڵان، بەساڵاچووانیشەوە، قووڵیی پەستان ٥-٦ سانتیمەترە — کەمی مەکەرەوە.","بۆ ئافرەتی دووگیان یان کەسی زۆر قەڵەو، لە کاتی خنکان بە شتێک، پەستان لە ناوەڕاستی سنگ بدە نەک لەسەر سک."],warnings:["ئەگەر کارەبا نەبڕدرابێت، دەست لە بریندارەکە مەدە!","ئەو شتەی لە برینەکەدا چەقیوە دەری مەهێنە!","بڵقەکانی سووتان مەتەقێنە!","ئەو کەسەی لە شوێنێکی بەرزەوە کەوتووە مەیجووڵێنە، مەگەر شوێنەکە مەترسیدار بێت یان پێویستی بە CPR هەبێت!","بۆ ساوای کەمتر لە یەک ساڵ، پەستانی سک (Heimlich) بەکارمەهێنە!","CPR بەردەوام بکە تا تیمی ئەمبولانس دەگات — مەوەستە."],activity:{prompt:"ئاگر لە دەستی هاوڕێیەکت گیرا و سووتانێکی گەورەی هەیە. چی دەکەیت؟",options:[{text:"کەرە یان ڕۆنی لێدەدەم",correct:!1,feedback:"هەرگیز کەرە یان ڕۆن لە سووتان مەدە؛ بۆ ماوەی ٢٠ خولەک بە ئاوی فێنکی ڕەوان ساردی بکەرەوە و پەیوەندی بە ١٢٢ بکە."},{text:"ئاوی فێنکی ڕەوان بۆ ماوەی ٢٠ خولەک دەکەمە سەر سووتانەکە و پەیوەندی بە ١٢٢ دەکەم",correct:!0,feedback:"ئاوی فێنکی ڕەوان بۆ ماوەی ٢٠ خولەک سووتانەکە سارد دەکاتەوە، و سووتانی گەورە پێویستی بە ئەمبولانس (١٢٢) هەیە."},{text:"بڵقەکانی سووتانەکە دەتەقێنم",correct:!1,feedback:"هەرگیز بڵقەکانی سووتان مەتەقێنە؛ بۆ ماوەی ٢٠ خولەک بە ئاوی فێنکی ڕەوان سووتانەکە سارد بکەرەوە و پەیوەندی بە ١٢٢ بکە."},{text:"هیچ ناکەم",correct:!1,feedback:"سووتانی گەورە پێویستی بە یارمەتیی خێرا هەیە: بۆ ماوەی ٢٠ خولەک بە ئاوی فێنکی ڕەوان ساردی بکەرەوە و پەیوەندی بە ١٢٢ بکە."}]},quiz:[{question:"لە کاتی CPR، پێویستە لە خولەکێکدا چەند پەستان لە سنگ بدرێت؟",options:[{text:"٥٠-٧٠",correct:!1},{text:"٨٠-٩٠",correct:!1},{text:"١٠٠-١٢٠",correct:!0},{text:"١٥٠ و زیاتر",correct:!1}],explanation:"لە ناوەڕاستی سنگدا بە هێز و خێرا پەستان بدە: ١٠٠-١٢٠ پەستان لە خولەکێکدا، قووڵی ٥-٦ سم بۆ هەموو گەورەساڵان."},{question:"ئەگەر شتێکی تیژ لە برینەکەدا چەقیبوو، چی دەکەیت؟",options:[{text:"دەری دەهێنم",correct:!1},{text:"لە شوێنی خۆی دەیهێڵمەوە و پەیوەندی بە ١٢٢ دەکەم",correct:!0},{text:"بەجێی دەهێڵم و بە ڕێگای خۆمدا دەڕۆم",correct:!1},{text:"بە ئاو دەیشۆم و دەری دەهێنم",correct:!1}],explanation:"ئەو شتەی لە برینەکەدا چەقیوە دەرمەهێنە: لە شوێنی خۆی بیهێڵەوە، لە دەوری پەستان بدە و پەیوەندی بە ١٢٢ بکە."},{question:"ئەگەر کارەبا لە کەسێکی دا، یەکەم کار چییە؟",options:[{text:"دەستی دەگرم",correct:!1},{text:"یەکسەر CPR دەکەم",correct:!1},{text:"کارەبا دەبڕم",correct:!0},{text:"ئاوی دەکەمە سەر",correct:!1}],explanation:"سەرەتا کارەبا ببڕە: تا کارەبا نەبڕدرێت، دەستدان لە بریندارەکە دەتوانێت تووشی شۆکت بکات. پاشان پەیوەندی بە ١٢٢ بکە."},{question:"نیشانەی سەرەکیی خنکانی تەواو بە شتێک چییە؟",options:[{text:"دەنگێکی بەرز لە گەرووەوە",correct:!1},{text:"نەتوانینی قسەکردن، کۆکین و هەناسەدان، و دەست بە گەرووەوە گرتن",correct:!0},{text:"کۆکەیەکی سووک",correct:!1},{text:"سەرئێشە",correct:!1}],explanation:"لە خنکانی تەواودا، کەسەکە ناتوانێت قسە بکات، بکۆکێت یان هەناسە بدات و دەست بە گەرووییەوە دەگرێت. ٥ لێدان لە پشت بدە، پاشان ٥ پەستانی سک."},{question:"دۆخی چاکبوونەوە (Recovery Position) بۆ کام کەس بەکاردێت؟",options:[{text:"کەسی بێهۆش کە هێشتا بە دروستی هەناسە دەدات",correct:!0},{text:"کەسی بێهۆش کە هەناسە نادات",correct:!1},{text:"کەسی بەهۆش کە برینێکی سووکی هەیە",correct:!1},{text:"کەسێکی تەندروست کە هیچ کێشەیەکی نییە",correct:!1}],explanation:"دۆخی چاکبوونەوە بۆ کەسی بێهۆشە کە بە دروستی هەناسە دەدات و گومانی برینداربوونی مل یان پشتی نییە. کەسێک کە هەناسە نادات پێویستی بە CPR هەیە."}]},{id:9,icon:"CarFront",accent:"#2563eb",title:"سەلامەتیی هاتوچۆ",subtitle:"پاراستنی خۆت و خێزانەکەت لەسەر ڕێگاکان",summary:"ڕووداوەکانی هاتوچۆ یەکێکن لە گەورەترین هۆکارەکانی مردن و برینداربوون. فێربوونی یاساکانی هاتوچۆ و پەیڕەوکردنیان دەتوانێت ژیانت بپارێزێت. ئەم وانەیە باسی سەلامەتیی پیادەڕەوان، شۆفێران و منداڵان دەکات.",blocks:[{heading:"سەلامەتیی پیادەڕەوان",body:"هەمیشە بەسەر شۆستەدا بڕۆ. پێش پەڕینەوە لە شەقام، سەیری هەردوو لا بکە و لە شوێنی پەڕینەوەی پیادەڕەوانەوە بپەڕەوە. لە کاتی پەڕینەوەدا سەیری مۆبایل مەکە. بە شەو جلی ڕەنگ کاڵ یان جلی نیشانەی ڕووناکیدانەوەدار (Reflective) لەبەر بکە."},{heading:"سەلامەتیی لێخوڕین",body:"هەمیشە پشتێنی سەلامەتی ببەستە. لە کاتی لێخوڕیندا مۆبایل بەکارمەهێنە. خێراییەکی گونجاو و بەپێی یاسا ڕابگرە. لە زستاندا تایەی گونجاو بەکاربهێنە."},{heading:"منداڵان لە ئۆتۆمبێلدا",body:"منداڵان هەمیشە لەسەر کورسیی تایبەتی منداڵ (Car seat) دابنێ کە بۆ تەمەن و کێشیان گونجاو بێت. منداڵانی ١٢ ساڵ و کەمتر لەسەر کورسییەکانی دواوە دابنیشن. هەرگیز منداڵان بە تەنها لە ئۆتۆمبێلدا بەجێ مەهێڵە."},{heading:"ماتۆڕ و پاسکیل",body:"هەمیشە کڵاوی پاراستن (Helmet) لەسەر بکە. بە شەو ڕووناکی و نیشانەی ڕووناکیدانەوە پێویستن. دەستکێش و پێڵاوی گونجاو لەبەر بکە."}],tips:["هەمیشە پشتێنی سەلامەتی ببەستە.","لە کاتی لێخوڕیندا مۆبایل بەکارمەهێنە.","منداڵان لەسەر کورسییەکانی دواوە دابنیشن.","کڵاوی پاراستن بۆ ماتۆڕ و پاسکیل."],warnings:["مۆبایل + لێخوڕین = مەترسیی مردن.","خێرایی + بەفر یان سەهۆڵ = ڕووداو."],activity:{prompt:"ئۆتۆمبێل لێدەخوڕیت و مۆبایلەکەت زەنگ لێدەدات. نامەیەکی گرنگ هاتووە. چی دەکەیت؟",options:[{text:"بەردەوام لێدەخوڕم و نامەکە دەخوێنمەوە",correct:!1,feedback:"مۆبایل + لێخوڕین = مەترسیی مردن؛ سەرەتا لە شوێنێکی سەلامەت بوەستە، پاشان نامەکە بخوێنەرەوە."},{text:"لە شوێنێکی سەلامەت لە لێواری ڕێگاکە ڕادەوەستم و پاشان وەڵام دەدەمەوە",correct:!0,feedback:"وەستان لە شوێنێکی سەلامەت لە پێشدا واتە دەتوانیت وەڵام بدەیتەوە بەبێ ئەوەی کەس لەسەر ڕێگا بخەیتە مەترسییەوە."},{text:"بە یەک دەست مۆبایلەکە بەکاردەهێنم",correct:!1,feedback:"بەکارهێنانی مۆبایل بە یەک دەستیش هەر بەکارهێنانە لە کاتی لێخوڕیندا؛ سەرەتا لە شوێنێکی سەلامەت بوەستە."},{text:"لە کاتی لێخوڕیندا بە خێرایی وەڵامەکە دەنووسم",correct:!1,feedback:"نووسین لە کاتی لێخوڕیندا یەکێکە لە مەترسیدارترین کارەکان؛ لە شوێنێکی سەلامەت بوەستە، پاشان وەڵام بدەرەوە."}]},quiz:[{question:"منداڵانی تەمەنی چەند ساڵ و کەمتر پێویستە لەسەر کورسییەکانی دواوەی ئۆتۆمبێل دابنیشن؟",options:[{text:"١٢ ساڵ",correct:!0},{text:"٦ ساڵ",correct:!1},{text:"١٨ ساڵ",correct:!1},{text:"هیچ جیاوازییەک نییە",correct:!1}],explanation:"منداڵانی تەمەن ١٢ ساڵ و کەمتر پێویستە لەسەر کورسییەکانی دواوە دابنیشن، لەسەر کورسیی تایبەتی منداڵ کە بۆ تەمەن و کێشیان گونجاو بێت."},{question:"کام لەم کارانە لە کاتی لێخوڕیندا یەکێکە لە مەترسیدارترین کارەکان؟",options:[{text:"بەکارهێنانی مۆبایل",correct:!0},{text:"بەستنی پشتێنی سەلامەتی",correct:!1},{text:"لێخوڕین بە خێرایی یاسایی",correct:!1},{text:"وەستان لەبەر چرای سووری هاتوچۆ",correct:!1}],explanation:"لە کاتی لێخوڕیندا مۆبایل بەکارمەهێنە: مۆبایل + لێخوڕین = مەترسیی مردن. بەستنی پشتێنی سەلامەتی و خێرایی یاسایی یارمەتیی پاراستنت دەدەن."},{question:"ئایا دەکرێت منداڵان بە تەنها لە ئۆتۆمبێلێکی وەستاودا بەجێ بهێڵرێن؟",options:[{text:"نەخێر، تەنانەت بۆ ماوەیەکی کورتیش نا",correct:!0},{text:"بەڵێ، ئەگەر پەنجەرەکان کەمێک کرابنەوە",correct:!1},{text:"بەڵێ، بۆ چەند خولەکێک",correct:!1},{text:"بەڵێ، ئەگەر ئۆتۆمبێلەکە لە سێبەردا وەستابێت",correct:!1}],explanation:"هەرگیز منداڵان بە تەنها لە ئۆتۆمبێلدا بەجێ مەهێڵە، تەنانەت بۆ ماوەیەکی کورتیش. هەمیشە لەسەر کورسیی تایبەتی منداڵ دایانبنێ کە بۆ تەمەن و کێشیان گونجاو بێت."}]},{id:10,icon:"LifeBuoy",accent:"#0891b2",title:"سەلامەتیی ئاو و ڕێگرتن لە خنکان",subtitle:"پاراستنی خۆت و منداڵان لە نزیک ئاو",summary:"بەپێی ڕێکخراوی تەندروستیی جیهانی (WHO)، خنکان لە ئاودا یەکێکە لە هۆکارە سەرەکییەکانی مردنی منداڵان و گەنجان لە جیهاندا. لە هەرێمی کوردستان، دەریاچە، بەنداو و ڕووبارەکان لە هاویندا زۆر مەترسیدارن. فێربوونی سەلامەتیی ئاو بۆ هەموو خێزانێک پێویستە.",blocks:[{heading:"منداڵان و ئاو",body:"هەرگیز منداڵان بە تەنها لە نزیک ئاو بەجێ مەهێڵە — منداڵی بچووک دەتوانێت لە ئاوێکی زۆر کەمدا (چەند سانتیمەترێک، وەک سەتڵێک یان تەشتێک) بخنکێت. لە نزیک حەوز و ئاوەکان، هەمیشە چاوت لەسەریان بێت."},{heading:"مەلەکردن بە سەلامەتی",body:"تەنها لە شوێنی فەرمی و لەژێر چاودێریدا مەلە بکە. هەمیشە کەسێکی تر لەگەڵت بێت. پێش چوونە ناو ئاو، قووڵییەکەی بزانە. لە دەریاچە و ڕووبارەکاندا چاکەتی ڕزگاربوون (Life jacket) لەبەر بکە."},{heading:"ڕزگارکردن",body:`ئەگەر کەسێک لە ئاودا دەخنکێت:
١. خۆت مەچۆ ناو ئاوەکە!
٢. شتێکی بۆ درێژ بکە یان فڕێی بدە (گوریس، دار، تۆپی ڕزگارکردن).
٣. پەیوەندی بە ١١٥ و ١٢٢ بکە.
٤. دوای ئەوەی لە ئاو هاتە دەرەوە، هەناسەی بپشکنە. ئەگەر بە دروستی هەناسەی نەدا و فێر بوویت، دەست بە CPR لەگەڵ هەناسەدان بکە: لە خنکاندا یەکەمجار هەناسە دەوەستێت، بۆیە هەناسەدان لە هەموو شتێک گرنگترە. ئەگەر فێر نەبوویت یان ناتوانیت هەناسە بدەیت، تەنها پەستانی سنگ بدە تا یارمەتی دەگات.
٥. هەر کەسێک لە ئاو دەرهێنرابێت، پێویستە پزیشک بیپشکنێت، تەنانەت ئەگەر باشیش دیار بێت، چونکە دواتر کێشەی سییەکان زۆر ڕوودەدەن.`}],tips:["منداڵان بە تەنها لە نزیک ئاو بەجێ مەهێڵە.","لە دەریاچە و ڕووبارەکاندا چاکەتی ڕزگاربوون (Life jacket) لەبەر بکە.","بۆ ڕزگارکردن مەچۆ ناو ئاوەکە — شتێکی بۆ فڕێ بدە.","CPR فێر بە."],warnings:["چەند سانتیمەترێک ئاو بەسە بۆ خنکاندنی منداڵێکی بچووک.","ئاوی ڕووبار و بەنداوەکانی هەرێم دەتوانێت زۆر بەهێز و سارد بێت، تەنانەت ئەگەر لە سەرەوە ئارام دیار بێت."],activity:{prompt:"تۆ و خێزانەکەت لە نزیک دەریاچەیەکن. منداڵێکی بچووکت دەیەوێت بچێتە ناو ئاوەکە. چی دەکەیت؟",options:[{text:"دەهێڵم بچێت — ئاساییە",correct:!1,feedback:"منداڵی بچووک دەتوانێت لە ئاوێکی زۆر کەمیشدا بخنکێت؛ هەرگیز مەهێڵە بە تەنها بچێتە ناو ئاو."},{text:"چاکەتی ڕزگاربوونی لەبەر دەکەم، لەگەڵی دەچم و لە نزیکەوە چاودێری دەکەم",correct:!0,feedback:"چاکەتی ڕزگاربوون و کەسێکی گەورە لە نزیکەوە کە هەموو کات چاودێری دەکات، منداڵی بچووک لە نزیک ئاو سەلامەتتر دەکەن."},{text:"پێی دەڵێم لە لێوارەکە بمێنێتەوە و لێی دوور دەکەومەوە",correct:!1,feedback:"هەرگیز منداڵان بە تەنها لە نزیک ئاو بەجێ مەهێڵە، تەنانەت لە لێوارەکەش؛ لە نزیکیان بمێنەوە و چاوت لەسەریان بێت."},{text:"لە دوورەوە سەیری دەکەم",correct:!1,feedback:"سەیرکردن لە دوورەوە بەس نییە: لە نزیک ئاو، لە نزیکیان بمێنەوە و هەمیشە چاوت لەسەریان بێت."}]},quiz:[{question:"ئەگەر کەسێک لە ئاودا دەخنکێت، یەکەم کار چییە؟",options:[{text:"دەچمە ناو ئاوەکە بۆ ئەوەی ڕزگاری بکەم",correct:!1},{text:"شتێکی بۆ فڕێ دەدەم (گوریس یان دار) و پەیوەندی بە ١١٥ و ١٢٢ دەکەم",correct:!0},{text:"تەنها هاوار دەکەم",correct:!1},{text:"هیچ ناکەم",correct:!1}],explanation:"خۆت مەچۆ ناو ئاوەکە. شتێکی بۆ درێژ بکە یان فڕێی بدە، وەک گوریس، دار یان تۆپی ڕزگارکردن، و پەیوەندی بە ١١٥ و ١٢٢ بکە."},{question:"چەند ئاو بەسە بۆ خنکاندنی منداڵێکی بچووک؟",options:[{text:"چەند سانتیمەترێک، وەک لە سەتڵێکدا",correct:!0},{text:"تەنها ئاوێک کە لە باڵای منداڵەکە قووڵتر بێت",correct:!1},{text:"تەنها دەریاچە و بەنداوە قووڵەکان",correct:!1},{text:"لانیکەم ئاوێک تا کەمەری منداڵەکە",correct:!1}],explanation:"چەند سانتیمەترێک ئاو بەسە بۆ خنکاندنی منداڵێکی بچووک، وەک لە سەتڵێک یان تەشتێکدا. هەرگیز منداڵان بە تەنها لە نزیک ئاو بەجێ مەهێڵە."},{question:"کەسێک لە ئاو دەرهێنراوە و بە دروستی هەناسە نادات. تۆ فێری CPR بوویت. چی دەکەیت؟",options:[{text:"دەست بە CPR لەگەڵ هەناسەدان دەکەم",correct:!0},{text:"تەنها پەستانی سنگ دەدەم",correct:!1},{text:"چاوەڕێ دەکەم تا خۆی هەناسە بدات",correct:!1},{text:"وەری دەگێڕم تا ئاوەکە لێی بێتە دەرەوە",correct:!1}],explanation:"ئەگەر بە دروستی هەناسەی نەدا و فێر بوویت، دەست بە CPR لەگەڵ هەناسەدان بکە: لە خنکاندا یەکەمجار هەناسە دەوەستێت، بۆیە هەناسەدان لە هەموو شتێک گرنگترە. ئەگەر فێر نەبوویت یان ناتوانیت هەناسە بدەیت، تەنها پەستانی سنگ بدە تا یارمەتی دەگات."}]},{id:11,icon:"Activity",accent:"#d97706",title:"بوومەلەرزە لە ماڵەوە و لە کۆمەڵگادا",subtitle:"ئامادەبوون و وەڵامدانەوە",summary:"بوومەلەرزە بێ ئاگادارکردنەوە دێت. ئامادەبوونی خێزانەکان و زانینی ڕێگای دروست لە کاتی بوومەلەرزەدا ژیان دەپارێزێت. ناوچەکەمان لە مەترسیی بوومەلەرزە دوور نییە، بۆیە پێویستە هەموو خێزانێک ئامادە بێت.",blocks:[{heading:"لە کاتی بوومەلەرزەدا",body:`١. خۆت نزم بکەرەوە، خۆت دابپۆشە و بیگرە (Drop, Cover, Hold On): بچۆ ژێر مێزێکی بەهێز و قاچی مێزەکە بگرە.
٢. لە پەنجەرە، شووشە و شتی قورس دوور بە.
٣. ڕامەکە بۆ دەرەوە، لە ژێر چوارچێوەی دەرگادا مەوەستە و ئاسانسۆر بەکارمەهێنە.
٤. ئەگەر لە دەرەوە بوویت: لە بینا، دار و تەلی کارەبا دوور بکەوەرەوە.`},{heading:"جانتای تەنگانە",body:"پێویستە هەموو خێزانێک جانتایەکی تەنگانە ئامادە بکات: ئاو (نزیکەی ٤ لیتر بۆ هەر کەسێک لە ڕۆژێکدا، بۆ لانیکەم ٣ ڕۆژ)، خۆراکێک کە خراپ نابێت، دەرمان، ڕادیۆی پاتریدار، چرای دەستی، بەتانی و بەڵگەنامە گرنگەکان."},{heading:"دوای بوومەلەرزە",body:"ئەگەر بۆنی گاز هات یان گوێت لە دەنگی دزەکردنی گاز بوو: دەست لە هیچ سویچێک مەدە و ئاگر مەکەرەوە، لە ڕێگای دەرچوونتدا پەنجەرەکان بکەرەوە، سەمامەی گاز تەنها دابخە ئەگەر نزیک بوو و توانیت پێی بگەیت بەبێ ئەوەی بچیتە ئەو شوێنەی گازی تێدا کۆبووەتەوە و بەبێ هیچ پریشکێک، دەرچۆ و لە دەرەوە پەیوەندی بە ١١٥ بکە. مەچۆ ناو بینا زیانلێکەوتووەکان. چاوەڕێی لەرزەکانی دوای بوومەلەرزە (Aftershock) بە. ئەگەر کەسێک لە ژێر بیناکاندا مابێتەوە یان بریندار هەبوو، پەیوەندی بە ١١٥ و ١٢٢ بکە."}],tips:["خۆت نزم بکەرەوە، خۆت دابپۆشە و بیگرە.","جانتای تەنگانە هەمیشە ئامادە ڕابگرە.","گاز تەنها ببڕە ئەگەر بۆنی هات یان دەنگی دزەکردنی بیسترا، و بتوانیت بگەیتە سەمامەکە بەبێ ئەوەی بچیتە ناو گازەکە و بەبێ هیچ پریشکێک.","لە بینا زیانلێکەوتووەکاندا مەمێنەوە."],warnings:["لە کاتی لەرزینەکەدا ڕامەکە!","مەچۆ ناو بینا زیانلێکەوتووەکان!"],activity:{prompt:"بوومەلەرزەیەکی بەهێز ڕوودەدات. لە ماڵەوەیت و منداڵەکان دەترسن. چی دەکەیت؟",options:[{text:"لەگەڵ منداڵەکان دەچینە ژێر مێزێکی بەهێز، سەرمان دادەپۆشین و قاچی مێزەکە دەگرین",correct:!0,feedback:"خۆنزمکردنەوە، داپۆشین و گرتن لە ژێر مێزێکی بەهێز تۆ و منداڵەکان لەو شتانەی دەکەونە خوارەوە دەپارێزێت تا لەرزینەکە دەوەستێت."},{text:"بەرەو دەرەوە ڕادەکەین",correct:!1,feedback:"لە کاتی لەرزینەکەدا ڕامەکە؛ خۆت نزم بکەرەوە، خۆت دابپۆشە و لە ژێر مێزێکی بەهێز بیگرە."},{text:"لەبەر پەنجەرە دەوەستین",correct:!1,feedback:"پەنجەرە و شووشە دەتوانن لە کاتی لەرزیندا بشکێن؛ لێیان دوور بە و لە ژێر مێزێکی بەهێز خۆت دابپۆشە."},{text:"بە ئاسانسۆر دادەبەزین",correct:!1,feedback:"هەرگیز لە کاتی بوومەلەرزەدا ئاسانسۆر بەکارمەهێنە؛ خۆت نزم بکەرەوە، خۆت دابپۆشە و لە ژێر مێزێکی بەهێز بیگرە."}]},quiz:[{question:"لە کاتی بوومەلەرزەدا لە ماڵەوە، یەکەم کار چییە؟",options:[{text:"بچۆ ژێر مێزێکی بەهێز و سەرت دابپۆشە",correct:!0},{text:"بەرەو دەرەوە ڕابکە",correct:!1},{text:"لەبەر پەنجەرە بوەستە",correct:!1},{text:"ئاسانسۆر بەکاربهێنە",correct:!1}],explanation:"لە کاتی لەرزینەکەدا، خۆت نزم بکەرەوە، خۆت دابپۆشە و بیگرە لە ژێر مێزێکی بەهێز. بەرەو دەرەوە ڕامەکە، لە نزیک پەنجەرە مەوەستە و ئاسانسۆر بەکارمەهێنە."},{question:"تۆ لە دەرەوەیت کاتێک بوومەلەرزە دەست پێدەکات. چی دەکەیت؟",options:[{text:"لە بینا، دار و تەلی کارەبا دوور دەکەومەوە",correct:!0},{text:"ڕادەکەمە ناو نزیکترین بینا و دەچمە ژێر مێزێک",correct:!1},{text:"لە نزیک دیوارێکی بەرز دەوەستم بۆ خۆپاراستن",correct:!1},{text:"لە ژێر دارێکی گەورە دەمێنمەوە تا لەرزینەکە دەوەستێت",correct:!1}],explanation:"ئەگەر لە کاتی بوومەلەرزەدا لە دەرەوە بوویت، لە بینا، دار و تەلی کارەبا دوور بکەوەرەوە. لە کاتی لەرزینەکەدا ڕامەکە."},{question:"دوای بوومەلەرزە، ئایا دەتوانیت بچیتە ناو بینایەکی زیانلێکەوتوو؟",options:[{text:"نەخێر، مەچۆ ناو بینا زیانلێکەوتووەکان",correct:!0},{text:"بەڵێ، بۆ هێنانی بەڵگەنامە و دەرمانە گرنگەکان",correct:!1},{text:"بەڵێ، یەکسەر دوای ئەوەی لەرزینەکە کۆتایی دێت",correct:!1},{text:"بەڵێ، ئەگەر ماڵی خۆت بێت",correct:!1}],explanation:"مەچۆ ناو بینا زیانلێکەوتووەکان و چاوەڕێی لەرزەکانی دوای بوومەلەرزە (Aftershock) بە. ئەگەر کەسێک لە ژێر بیناکاندا مابێتەوە یان بریندار هەبوو، پەیوەندی بە ١١٥ و ١٢٢ بکە."}]},{id:12,icon:"Siren",accent:"#dc2626",title:"کاری بەرگریی شارستانی",subtitle:"ئەرکەکانی تیمەکانی ١١٥ و چۆن دەتوانیت یارمەتییان بدەیت",summary:"بەرگریی شارستانی دەزگایەکی حکوومیی گرنگە کە ژیانی هاووڵاتیان و موڵکی تایبەت و گشتی دەپارێزێت. لە هەرێمی کوردستان، ١١٥ ژمارەی بەرگریی شارستانییە بۆ ئاگر، ڕزگارکردن و کارەساتەکان، و تیمەکانی شەو و ڕۆژ ئامادەن. پێویستە هاووڵاتیان بزانن چۆن پەیوەندی بە ١١٥ بکەن و چۆن یارمەتیی تیمەکان بدەن، نەک ڕێگرییان لێ بکەن.",blocks:[{heading:"ئەرکە سەرەکییەکانی بەرگریی شارستانی",body:`• کوژاندنەوەی ئاگر: لە ماڵ، فەرمانگە، کارگە، کێڵگە و دارستانەکان.
• ڕزگارکردن: لە ئۆتۆمبێلی ڕووداو، لە ژێر داڕماوەکان و لە ئاو.
• لافاو و کارەسات: گواستنەوەی خەڵک، دەرکێشانی ئاو و یارمەتیدانی زیانلێکەوتووان.
• مادە مەترسیدارەکان (HazMat): دزەکردنی گاز و مادە کیمیاییەکان.
• فێرکردن و هۆشیاری: وانە لە قوتابخانە و فەرمانگەکان.
• پشکنینی سەلامەتی: لە بازاڕ، ڕێستوران، هۆڵ و بینا بەرزەکان.`},{heading:"پێکهاتەی فەرمی",body:`• لە هەرێمی کوردستان، بەرگریی شارستانی سەر بە وەزارەتی ناوخۆیە.
• لە هەر پارێزگایەک بەڕێوەبەرایەتییەکی بەرگریی شارستانی هەیە، وەک بەڕێوەبەرایەتیی بەرگریی شارستانیی دهۆک، و بنکەکانی لە شار و قەزاکاندا هەن.
• بەشەکانی کار: کوژاندنەوەی ئاگر، ڕزگارکردن، فریاکەوتنی سەرەتایی، فێرکردن و بەشە تەکنیکییەکان.
• لە کاتی کارەساتە گەورەکاندا، بەرگریی شارستانی لەگەڵ ئەمبولانس (١٢٢)، پۆلیس (١٠٤) و دەزگاکانی تر پێکەوە کار دەکات.`},{heading:"کەرەستە و ئۆتۆمبێلەکانیان",body:`• ئۆتۆمبێلی ئاگرکوژێنەوە: ئاو، لوولە و پەمپ هەڵدەگرن.
• ئۆتۆمبێلی پەیژە: دەگەنە نهۆمە بەرزەکان.
• ئامێرەکانی ڕزگارکردن: ئامێری هایدرۆلیکی بۆ بڕینی ئاسنی ئۆتۆمبێل و دەرهێنانی کەسانی گیرخواردوو (Jaws of Life).
• ئامێری هەناسەدان (BA — Breathing Apparatus): هەوای پاک لە ناو دووکەڵدا دەدات بە ئاگرکوژ.
• جلی تایبەت بۆ پاراستن لە گەرما.
• ڕادیۆ بۆ پەیوەندی لە نێوان تیمەکاندا.`},{heading:"چۆن پەیوەندی بە ١١٥ بکەیت",body:`١. ژمارە ١١٥ لێبدە.
٢. ئارام بە و بە ڕوونی قسە بکە.
٣. بڵێ: ناونیشانی دروست (گەڕەک، شەقام و نیشانەیەکی دیاری نزیک)، چی ڕوویداوە (ئاگر؟ ڕووداو؟ کەسێک گیری خواردووە؟)، چەند کەس بریندار بوون یان گیریان خواردووە، هەر مەترسییەکی تایبەت (گاز، مادەی کیمیایی، کارەبا)، و ناو و ژمارەی تەلەفۆنەکەت بۆ ئەوەی بتوانن دیسان پەیوەندیت پێوە بکەن.
٤. تەلەفۆنەکە دامەخە تا ئەوان پێت نەڵێن.
٥. ئەگەر سەلامەت بوو، ڕێگا بۆ ئۆتۆمبێلەکانی ئاگرکوژێنەوە کراوە بهێڵەوە.
٦. کەسێک بنێرە سەر شەقام بۆ ئەوەی ڕێگاکە نیشانی تیمەکە بدات.`},{heading:"چۆن کۆمەڵگا یارمەتیی ١١٥ دەدات",body:`• لەسەر ڕێگا: کاتێک گوێت لە دەنگی سایرەن دەبێت، بە ئارامی بەرەو لای ڕاست بڕۆ و ڕابوەستە بۆ ئەوەی ڕێگا کراوە بێت.
• پەیوەندیی درۆ مەکە: هەر پەیوەندییەکی درۆ تیمێک لە تەنگانەیەکی ڕاستەقینە دوور دەخاتەوە.
• ڕێگای گەیشتن کراوە بهێڵەوە: ئۆتۆمبێل لەبەر دەرگاکان و لە کۆڵانە تەسکەکاندا ڕامەگرە.
• شایەتی: ئەگەر ڕووداوەکەت بینی، بمێنەوە و زانیارییەکانت بدە بە تیمەکە.
• لە نزیک تیمەکە قەرەباڵغی دروست مەکە و وێنە مەگرە، بۆ ئەوەی ڕێگایان لێ نەگریت.
• ئەگەر تیمەکە داوای یارمەتیی کرد، یارمەتی بدە.
• ئەگەر بینیت پێویست بە ١١٥ هەیە، دوا مەکەوە — پەیوەندی بکە.
• ئارام بە و ترس و شڵەژان بڵاو مەکەرەوە.`},{heading:"کارکردن و خۆبەخشی لە بەرگریی شارستانیدا",body:`• داواکاریی دامەزراندن لە ڕێگەی ڕاگەیاندنە فەرمییەکانی بەرگریی شارستانییەوە پێشکەش دەکرێت.
• مەرجەکانی تەمەن، خوێندن، تەندروستیی جەستەیی و تاقیکردنەوەکان لەلایەن بەڕێوەبەرایەتییەوە دیاری دەکرێن — بۆ زانیاریی نوێ پەیوەندی بە بەڕێوەبەرایەتیی بەرگریی شارستانیی دهۆکەوە بکە.
• فەرمانبەرە نوێیەکان ڕاهێنانێکی بنەڕەتی لە بوارەکانی کوژاندنەوەی ئاگر، ڕزگارکردن و فریاکەوتنی سەرەتاییدا دەبینن.
• هاووڵاتیان دەتوانن بەشداری لە وانە و ڕاهێنانەکانی هۆشیاریدا بکەن و لە کاتی تەنگانەدا لە گەڕەکەکەی خۆیان ببنە یارمەتیدەر.`}],tips:["١١٥ لەبەر بکە — هەموو ئەندامانی خێزانیش.","ناونیشانی ماڵەکەت بە دروستی بزانە (گەڕەک، شەقام، ژمارەی خانوو).","کاتێک گوێت لە دەنگی سایرەن دەبێت، بەرەو لای ڕاست بڕۆ و ڕابوەستە، نەک لە ناوەڕاستی ڕێگادا.","١١٥ تەنها بۆ تەنگانە بەکاربهێنە، بۆ ئەوەی هێڵەکەی بۆ کەسانی پێویست کراوە بێت.","ئەگەر گومانی ئاگر یان مەترسییەکت هەبوو، پەیوەندی بکە — باشترە تیمەکە بێت و کێشە نەبێت.","ژمارەی خانوو و ناوی گەڕەک لەسەر دەرگاکە دیار بکە بۆ ئەوەی تیمەکە بە ئاسانی بگاتە لات.","پلانی دەرچوون لە ماڵەوە بنووسە و لەگەڵ خێزانەکەت تاقی بکەرەوە."],warnings:["پەیوەندیی درۆ بە ١١٥ مەکە — کاتی تیمەکان بەفیڕۆ دەدەن و ژیان دەخەنە مەترسییەوە.","لە نزیک ئۆتۆمبێلەکانی ١١٥ قەرەباڵغی دروست مەکە و وێنە مەگرە — ڕێگا لە کارەکەیان دەگریت.","ڤیدیۆی قوربانییان مەگرە و بڵاوی مەکەرەوە — ڕێزیان بگرە.","کاتێک گوێت لە سایرەن دەبێت، بە دوای ئۆتۆمبێلەکانی تەنگانەدا لێمەخوڕە و ڕێگایان بۆ کراوە بهێڵەوە."],activity:{prompt:"لەبەر ماڵەکەت ڕووداوێکی ئۆتۆمبێل ڕوویدا. ٢ کەس لە ناو ئۆتۆمبێلەکەدا گیریان خواردووە و کەسی تر لەوێ نییە. چی دەکەیت؟",options:[{text:"یەکسەر پەیوەندی بە ١١٥ و ١٢٢ دەکەم و ناونیشانی دروست دەڵێم. ئەگەر ئاگر نەبێت، بریندارە گیرخواردووەکان دەرناهێنم بۆ ئەوەی مل و پشتیان زیان نەبینێت. لە شوێنێکی سەلامەت دەمێنمەوە و ڕێنماییەکانی ١١٥ پەیڕەو دەکەم.",correct:!0,feedback:"پەیوەندیکردن بە ١١٥ و ١٢٢ ڕزگارکردن و یارمەتیی پزیشکی دەگەیەنێت، و نەجووڵاندنی بریندارە گیرخواردووەکان مل و پشتیان دەپارێزێت."},{text:"بە خێرایی هەوڵ دەدەم بریندارە گیرخواردووەکان دەربهێنم",correct:!1,feedback:"دەرهێنانی بریندارە گیرخواردووەکان دەتوانێت زیان بە مل و پشتیان بگەیەنێت؛ ئەگەر ئاگر نەبوو، پەیوەندی بە ١١٥ و ١٢٢ بکە و ڕێنماییەکانیان پەیڕەو بکە."},{text:"ڤیدیۆ دەگرم و لە تۆڕە کۆمەڵایەتییەکاندا بڵاوی دەکەمەوە",correct:!1,feedback:"گرتن و بڵاوکردنەوەی ڤیدیۆی قوربانییان یارمەتی نادات و ڕێزیان لێ ناگرێت؛ سەرەتا پەیوەندی بە ١١٥ و ١٢٢ بکە."},{text:"دەڕۆم بۆ ئەوەی کەسێکی تر بۆ یارمەتی بدۆزمەوە و پەیوەندی ناکەم",correct:!1,feedback:"دوامەخە: تەنها تۆ لەوێیت، بۆیە خۆت یەکسەر پەیوەندی بە ١١٥ و ١٢٢ بکە."}]},quiz:[{question:"لە هەرێمی کوردستان، ژمارەی تەنگانەی بەرگریی شارستانی چەندە؟",options:[{text:"٩٩١",correct:!1},{text:"١٠٧",correct:!1},{text:"١١٥",correct:!0},{text:"١٢٢",correct:!1}],explanation:"لە هەرێمی کوردستان، ١١٥ ژمارەی بەرگریی شارستانییە بۆ ئاگر، ڕزگارکردن و کارەساتەکان. ١٢٢ ئەمبولانسە."},{question:"کاتێک ئۆتۆمبێلێکی ئاگرکوژێنەوە بە سایرەنەوە دەبینیت، چی دەکەیت؟",options:[{text:"بە ئارامی بەرەو لای ڕاست دەڕۆم و ڕادەوەستم بۆ ئەوەی ڕێگا کراوە بێت",correct:!0},{text:"بە خێرایی بە دوایدا لێدەخوڕم",correct:!1},{text:"ڕێگای لێ دەگرم",correct:!1},{text:"ڤیدیۆ دەگرم",correct:!1}],explanation:"بە ئارامی چوون بۆ لای ڕاست و وەستان ڕێگا بۆ ئۆتۆمبێلی ئاگرکوژێنەوە کراوە دەهێڵێتەوە. هەرگیز بە دوایدا لێمەخوڕە، ڕێگای لێ مەگرە و بۆ ڤیدیۆگرتن مەوەستە."},{question:"کاتێک پەیوەندی بە ١١٥ دەکەیت، گرنگترین شت کە پێویستە یەکەم جار بیڵێیت چییە؟",options:[{text:"تەنها ناوی خۆت",correct:!1},{text:"ناونیشان و چی ڕوویداوە",correct:!0},{text:"دەڵێم «بە خێرایی وەرن» و تەلەفۆنەکە دادەخەم",correct:!1},{text:"دەپرسم کەی دەگەن",correct:!1}],explanation:"تیمەکە دەبێت بزانێت بۆ کوێ بچێت و چی ڕوویداوە. پاشان ژمارەی بریندارەکان، هەر مەترسییەک و ناو و ژمارەکەت بڵێ، و تەلەفۆنەکە دامەخە تا پێت نەڵێن."},{question:"ئامێری BA (Breathing Apparatus) چی دەکات؟",options:[{text:"ئاگرکوژێنەرەوەیە",correct:!1},{text:"ئامێری هەناسەدانە، هەوای پاک لە ناو دووکەڵدا دەدات بە ئاگرکوژ",correct:!0},{text:"ڕادیۆیە",correct:!1},{text:"سایرەنە",correct:!1}],explanation:"ئامێری هەناسەدان (BA) هەوای پاک لە ناو دووکەڵدا دەدات بە ئاگرکوژ بۆ ئەوەی هەناسە بدات."},{question:"ئەگەر ئاگر و کەسی بریندار پێکەوە هەبوون، پەیوەندی بە کام ژمارەوە دەکەیت؟",options:[{text:"تەنها ١٠٤",correct:!1},{text:"تەنها ١٢٢",correct:!1},{text:"١١٥ و ١٢٢",correct:!0},{text:"پەیوەندی ناکەم و چاوەڕێ دەکەم",correct:!1}],explanation:"ئاگر پێویستی بە بەرگریی شارستانی (١١٥) هەیە و برینداران پێویستیان بە ئەمبولانس (١٢٢) هەیە، بۆیە پەیوەندی بە هەردووکیان بکە."}]},{id:13,icon:"FlameKindling",accent:"#ea580c",title:"جۆرەکانی ئاگر",subtitle:"هەموو ئاگرێک وەک یەک نییە — هەر جۆرێک ڕێگایەکی تایبەتی دەوێت",summary:"بەپێی سیستەمی ئەمریکی (NFPA 10)، پێنج پۆلی ئاگر هەن: A، B، C، D و K. پۆلەکانی ئاگر لێرەدا بە پیتەکانی NFPA 10 نووسراون وەک سەرچاوەی پرۆژە؛ سیستەمی فەرمیی دهۆک هێشتا پشتڕاست نەکراوەتەوە. هاوتاکانی EN 2: NFPA A = EN A؛ NFPA B (شلە) = EN B؛ NFPA B (گاز) = EN C؛ NFPA C (ئامێری کارەبایی کە کارەبای تێدایە) هیچ پۆلێکی EN ی نییە؛ NFPA D = EN D؛ NFPA K = EN F. لە هەر پۆلێکدا مادەیەکی جیاواز دەسووتێت و ئاگرکوژێنەرەوەیەکی گونجاوی دەوێت. هەڵبژاردنی ئاگرکوژێنەرەوەی هەڵە دەتوانێت ئاگرەکە گەورەتر بکات. ئەم وانەیە فێرت دەکات چۆن جۆری ئاگر بناسیتەوە و چی بەکاربهێنیت.",blocks:[{heading:"پۆلی A — کەرەستە ڕەقەکان (دار، کاغەز، قوماش)",body:`لە ماڵدا زۆر باوە: کاغەز، کارتۆن، پەردە، قوماش، پلاستیک و کەلوپەلی داری. ئاگرکوژێنەرەوە: ئاو یان تۆزی ABC. بنی ئاگرەکە بکە ئامانج، لەو دوورییەوە دەست پێبکە کە لەسەر لەیبڵی ئاگرکوژێنەرەوەکە هاتووە، و ڕێگای دەرچوون لە پشتتەوە بێت.
• ئەگەر ئاگر لە جلەکانت گیرا: بوەستە، خۆت بدە بە زەویدا و خۆت بگلێنەوە (Stop, Drop, Roll).`},{heading:"پۆلی B — شلە و گازە گڕگرەکان (بەنزین، نەوت، ئەلکهول)",body:`ئەم شلانە بە خێرایی ئاگر دەگرن و هەڵمەکانیان دەتوانن لە دوورەوە ئاگر بگرن. ئاو بەکارمەهێنە: ئاو شلەی سووتاو بڵاو دەکاتەوە و ئاگرەکە گەورەتر دەکات. ئاگرکوژێنەرەوە بۆ شلەکان: کەف (Foam)، CO₂ یان تۆزی ABC. کەفەکە بە هێواشی بەسەر ڕووی شلەکەدا بڵاو بکەرەوە بۆ ئەوەی دایپۆشێت.
• ئەلکهول، ئەسیتۆن و شلە جەمسەرییەکانی تر (polar solvents): CO₂، تۆزی ABC یان کەفی بەرگەگری ئەلکهول (AR foam)؛ کەفی ئاسایی لەسەریان تێکدەچێت.
• ئاگری گاز (گازی LPG یان گازی سروشتی): گرنگترین شت ڕاگرتنی گازەکەیە. کەسێکی شارەزا سەمامەی گاز دادەخات تەنها ئەگەر گەیشتن پێی سەلامەت بێت. ئەگەر گازەکە بە سەلامەتی ڕانەگیرێت، ئاگری گازەکە مەکوژێنەرەوە: گازی نەسووتاو کۆ دەبێتەوە و دەتوانێت بتەقێتەوە. ئەگەر سەلامەت نەبوو، هەمووان دەربهێنە، ئاگادار بکەرەوە و پەیوەندی بە ١١٥ بکە. کەف هەڵبژاردەی گشتی نییە بۆ ئاگری گاز. بەپێی EN 2، ئاگری گاز پۆلی C یە.
• BLEVE: ئەگەر ئاگر سلیندەرێکی گاز یان تانکێکی گەرم کرد، دەتوانێت بە تەقینەوەیەکی گەورە بتەقێتەوە — لێی دوور بکەوەرەوە و پەیوەندی بە ١١٥ بکە.`},{heading:"پۆلی C — ئامێرە کارەباییەکان (بەپێی NFPA)",body:`کۆمپیوتەر، تەلەفزیۆن، سەلاجە، پلاک و وایەرەکانی کارەبا.
• هەرگیز ئاو بەکارمەهێنە! شۆکی کارەبا دەتوانێت بکوژێت.
• یەکەم کار کارەبا ببڕە (فیشەکە دەربهێنە یان کارەبای سەرەکیی ماڵ ببڕە)، پاشان CO₂، گازی پاک (Clean Agent) یان تۆزی ABC بەکاربهێنە.
• تۆزی ABC ئامێرە ئەلیکترۆنییەکان تێکدەدات؛ بۆ ئامێرە هەستیارەکان CO₂ باشترە.
• لە سیستەمی ئەورووپیدا (EN 2)، ئاگری کارەبا پۆلێکی جیا نییە.`},{heading:"پۆلی D — کانزا گڕگرەکان (مەگنیسیۆم، تیتانیۆم، سۆدیۆم، لیتیۆمی کانزایی)",body:`ئەم کانزایانە بە گەرمییەکی زۆر بەرز دەسووتێن.
• ئاو و CO₂ لەسەر کانزا سووتاوەکان بەکارمەهێنە — کاردانەوەیەکی توند و ئاگرێکی گەورەتر دروست دەکەن.
• تەنها ئاگرکوژێنەرەوە یان ماددەیەک بەکاربهێنە کە ناوی ئەو کانزایە لەسەر لەیبڵەکەی هاتبێت؛ ماددەکە لە کانزایەکەوە بۆ یەکێکی تر جیاوازە (بۆ نموونە، لیتیۆم پێویستی بە ماددەیەکی تایبەت بە لیتیۆم هەیە). هەرگیز ئاو، تۆزی ئاسایی یان کەف بەکار مەهێنە. لمی وشک تەنها ئەگەر پلانی ئاگری شوێنەکە یان SDS ی کانزاکە ناوی هێنابێت و تەواو وشک بێت. پەیوەندی بە ١١٥ بکە.
• پاترییەکانی لیتیۆم-ئایۆن (Li-ion) کە لە مۆبایل، لاپتۆپ، پاوەر بانک و پاسکیلی کارەباییدا هەن، لیتیۆمی کانزاییان تێدا نییە و سەر بە پۆلی D نین: ئەگەر ئاگریان گرت، بە ئاوی زۆر ساردیان بکەرەوە و پەیوەندی بە ١١٥ بکە. پۆلی D تەنها بۆ پاترییەکانی لیتیۆمی کانزایی (Lithium-metal) بەکاردێت.`},{heading:"پۆلی K (NFPA) / F (EN 2) — ڕۆنی چێشتخانە",body:`ئاگری ڕۆنی گەرم لە تاوە یان مەنجەڵدا لەسەر تەباخ.
• هەرگیز ئاو بەکارمەهێنە! ئاو لە ناو ڕۆنی گەرمدا بە خێرایی دەبێتە هەڵم و ڕۆنی سووتاو بە تەقینەوەیەک بڵاو دەکاتەوە.
• تۆزی ABC بۆ ئەم پۆلە گونجاو نییە.
• ئاگرکوژێنەرەوەی کیمیایی شل (Wet Chemical) بەکاربهێنە، یان تەباخەکە بکوژێنەرەوە و سەرقاپێکی گەورە یان بەتانیی ئاگر (Fire blanket) بخە سەری بۆ ئەوەی ئۆکسجین ببڕێت.
• تاوەکە هەڵمەگرە و مەیبە دەرەوە.`},{heading:"قۆناغەکانی گەشەکردنی ئاگر",body:`١. سەرەتا (Incipient): ئاگرەکە بچووکە و دووکەڵ کەمە. تەنها لەم قۆناغەدا بەکارهێنانی ئاگرکوژێنەرەوە سەلامەتە.
٢. گەشەکردن (Growth): گەرما زیاد دەبێت و ئاگرەکە بڵاو دەبێتەوە.
٣. ئاگری تەواو (Fully Developed): هەموو ژوورەکە لە ناو ئاگردایە.
٤. کەمبوونەوە (Decay): ئاگرەکە کەم دەبێتەوە، بەڵام ئەگەر لەناکاو هەوا بچێتە ناو ژوورەکە، مەترسیی تەقینەوەی ئاگر (Backdraft) هەیە.

• Flashover: کاتێک گەرمیی چینی دووکەڵی گەرم لە ژێر بنمیچی ژوورەکە دەگاتە نزیکەی ٥٠٠-٦٠٠ پلەی سەدی، هەموو شتەکانی ژوورەکە پێکەوە ئاگر دەگرن.`}],tips:["پێش کڕین، ئەو پۆلانەی ئاگر بخوێنەرەوە کە لەسەر لەیبڵی ئاگرکوژێنەرەوەکە نووسراون.","لە ماڵەوە لانیکەم یەک ئاگرکوژێنەرەوەی ABC هەبێت، و بۆ چێشتخانە ئاگرکوژێنەرەوەی Wet Chemical یان بەتانیی ئاگر.","بەپێی NFPA 10، لە شوێنەکانی کار دووریی گەیشتن بە ئاگرکوژێنەرەوەی پۆلی A لە ٢٣ مەتر زیاتر نابێت.","بەپێی NFPA، چێشتلێنان یەکەم هۆکاری ئاگرکەوتنەوەی ماڵانە — لە کاتی چێشتلێناندا چێشتخانە بەجێ مەهێڵە.","ئاگری ئامێرە کارەباییەکان: هەرگیز ئاو بەکارمەهێنە — یەکەم کار کارەبا ببڕە.","پاتریی لیتیۆم-ئایۆن: ئەگەر گەرم بوو، ئاوسا یان دووکەڵی لێ هات، دوور لە شتی گڕگر دایبنێ، لێی دوور بکەوەرەوە و پەیوەندی بە ١١٥ بکە.","ڕۆنی چێشتخانە: تەباخەکە بکوژێنەرەوە و سەرقاپێکی گەورە بخە سەری — ئەمە یەکەم ڕێگایە بۆ کوژاندنەوەی ئەو ئاگرە."],warnings:["ئاو لەسەر ڕۆنی ئاگرگرتوو = تەقینەوەی هەڵم و ئاگرێکی گەورە.","ئاو لەسەر ئامێرە کارەباییەکان = شۆکی کوشندە.","تۆزی ABC لەسەر کۆمپیوتەر = زیان بە ئامێرەکە دەگات.","پاتریی لیتیۆم-ئایۆنی ئاگرگرتوو بە ئاوی زۆر سارد بکەرەوە و پەیوەندی بە ١١٥ بکە — ئاگرەکە دەتوانێت دیسان هەڵبگیرسێتەوە.","ئاگری گەورەتر لە سەتڵی زبڵ = یەکسەر دەرچۆ، نەک ئاگرکوژێنەرەوە."],activity:{prompt:"لە چێشتخانەدایت. ڕۆنی ناو تاوەکە ئاگری گرت و تەباخەکە هێشتا داگیرساوە. خێزانەکەت لە ژووری نووستندان. چی دەکەیت؟",options:[{text:"تەباخەکە دەکوژێنمەوە، سەرقاپێکی گەورە دەخەمە سەر تاوەکە، خێزانەکەم ئاگادار دەکەمەوە و ئەگەر ئاگرەکە نەکوژایەوە دەردەچین و پەیوەندی بە ١١٥ دەکەین",correct:!0,feedback:"کوژاندنەوەی تەباخەکە و سەرقاپەکە گەرما و ئۆکسجین دەبڕن، و ئاگادارکردنەوەی خێزانەکەت ڕێگە دەدات هەمووان دەربچن ئەگەر پێویست بوو."},{text:"ئاوی دەکەمە سەر بۆ ئەوەی سارد ببێتەوە",correct:!1,feedback:"ئاو لەسەر ڕۆنی ئاگرگرتوو تەقینەوەی هەڵم و ئاگرێکی گەورە دروست دەکات؛ هەرگیز ئاوی مەکە سەر."},{text:"تاوەکە هەڵدەگرم و دەیبەمە دەرەوە",correct:!1,feedback:"تاوەکە هەڵمەگرە و مەیبە دەرەوە؛ تەباخەکە بکوژێنەرەوە و سەرقاپێکی گەورەی بخەرە سەر."},{text:"بە تەنها ڕادەکەم و خێزانەکەم ئاگادار ناکەمەوە",correct:!1,feedback:"خێزانەکەشت لە مەترسیدایە؛ ئاگاداریان بکەرەوە، و ئەگەر ئاگرەکە نەکوژایەوە، پێکەوە دەربچن و پەیوەندی بە ١١٥ بکەن."}]},quiz:[{question:"ئاگر لە کۆمپیوتەرێک لە ژوورەکەت گیرا. کام ڕێگا دروستە؟",options:[{text:"ئاو",correct:!1},{text:"یەکەم کارەبا دەبڕم، پاشان CO₂، گازی پاک (Clean Agent) یان ABC",correct:!0},{text:"کەف (AFFF Foam)",correct:!1},{text:"کیمیایی شل (Wet Chemical)",correct:!1}],explanation:"کۆمپیوتەر ئامێرێکی کارەباییە: سەرەتا کارەبا ببڕە، پاشان CO₂، گازی پاک (Clean Agent) یان تۆزی ABC بەکاربهێنە. ئاو دەتوانێت شۆکێکی کارەبایی کوشندە دروست بکات."},{question:"ڕۆنی تاوە لەسەر تەباخی گاز ئاگری گرت. یەکەم کار چییە؟",options:[{text:"ئاوی دەکەمە سەر",correct:!1},{text:"سەمامەی گاز دادەخەم و سەرقاپێکی گەورە دەخەمە سەری",correct:!0},{text:"تۆزی ABC دەکەمە سەر",correct:!1},{text:"بە پارچە قوماشێک لێی دەدەم",correct:!1}],explanation:"داخستنی گاز گەرما ڕادەگرێت و سەرقاپێکی گەورە ئۆکسجین دەبڕێت. ئاو تەقینەوەی هەڵم دروست دەکات و تۆزی ABC بۆ ڕۆنی چێشتخانە گونجاو نییە."},{question:"پاتریی لیتیۆم-ئایۆنی مۆبایلێک ئاگری گرت. چی دەکەیت؟",options:[{text:"بە بەتانییەک دایدەپۆشم و لە ژوورەکەدا جێی دەهێڵم",correct:!1},{text:"تەنها تۆزی ABC دەکەمە سەر و دەڕۆم",correct:!1},{text:"ئەگەر سەلامەت بوو، دووری دەخەمەوە لە شتی گڕگر، بە ئاوی زۆر ساردی دەکەمەوە و پەیوەندی بە ١١٥ دەکەم",correct:!0},{text:"تەنها CO₂ لێدەدەم و بەجێی دەهێڵم",correct:!1}],explanation:"ئەگەر سەلامەت بوو، پاترییەکە لە شتی گڕگر دوور بخەرەوە، بە ئاوی زۆر ساردی بکەرەوە و پەیوەندی بە ١١٥ بکە. تۆزی ABC و CO₂ ئەم ئاگرە بە تەواوی ناوەستێنن."},{question:"Flashover ڕوودەدات کاتێک گەرمیی چینی دووکەڵی گەرم لە ژێر بنمیچدا دەگاتە نزیکەی چ پلەیەک؟",options:[{text:"٢٠٠ پلەی سەدی",correct:!1},{text:"٣٠٠ پلەی سەدی",correct:!1},{text:"٥٠٠-٦٠٠ پلەی سەدی",correct:!0},{text:"١٠٠٠ پلەی سەدی",correct:!1}],explanation:"Flashover ڕوودەدات کاتێک گەرمیی چینی دووکەڵی گەرم لە ژێر بنمیچدا دەگاتە نزیکەی ٥٠٠-٦٠٠ پلەی سەدی: هەموو شتەکانی ژوورەکە پێکەوە ئاگر دەگرن."},{question:"بەپێی NFPA، کام کار یەکەم هۆکاری ئاگرکەوتنەوەی ماڵانە؟",options:[{text:"خوێندنەوەی کتێب",correct:!1},{text:"شوشتنی جل بە دەست",correct:!1},{text:"چێشتلێنان (چێشتخانە)",correct:!0},{text:"خەوتن",correct:!1}],explanation:"بەپێی NFPA، چێشتلێنان یەکەم هۆکاری ئاگرکەوتنەوەی ماڵانە، بۆیە لە کاتی چێشتلێناندا چێشتخانە بەجێ مەهێڵە."}]},{id:14,icon:"FireExtinguisher",accent:"#0891b2",title:"چۆن ئاگرکوژێنەرەوە بەکاربهێنیت",subtitle:"جۆرەکانی ئاگرکوژێنەرەوە، ڕێگای PASS، و کەی پێویستە ئاگرکوژێنەرەوەکە بەجێ بهێڵیت و دەرچیت",summary:"ئاگرکوژێنەرەوە لە ماڵ، فەرمانگە و شوێنە گشتییەکاندا هەن، بەڵام زۆر کەس نازانن چۆن بەکاریان بهێنن. ئاگرکوژێنەرەوەی دەستی تەنها چەند چرکەیەک کار دەکات، بۆیە پێویستە پێش ئاگرکەوتنەوە ئامادە بیت. ئەم وانەیە ڕێگای PASS، هەڵبژاردنی ئاگرکوژێنەرەوەی گونجاو و لە هەمووی گرنگتر — کەی نابێت ئاگرکوژێنەرەوە بەکاربهێنیت و دەبێت دەرچیت — فێرت دەکات.",blocks:[{heading:"جۆرە سەرەکییەکانی ئاگرکوژێنەرەوە",body:`پۆلەکان بە پیتەکانی NFPA:
• ئاو: تەنها پۆلی A.
• کەف (Foam): A و B.
• CO₂: پۆلی B و ئامێرە کارەباییەکان کە کارەبایان تێدایە (B و C بەپێی NFPA؛ بەپێی EN 2، C گازە و CO₂ بۆ ئاگری گاز نییە). مەودای کورتە؛ بۆ ئاگری قووڵی دار و کاغەز نییە؛ لە ژوورێکی بچووکدا دوای بەکارهێنان دەرچۆ و هەوا بگۆڕە.
• تۆزی ABC: A، B و C — باوترینیان؛ نە بۆ D و نە بۆ K.
• کیمیایی شل (Wet Chemical): K، ڕۆنی چێشتخانە.
• گازی پاک (Clean Agent): بۆ ئامێرە ئەلیکترۆنییە هەستیارەکان؛ پۆلەکانی بەپێی مۆدێل جیاوازن، بۆیە لەیبڵەکە بخوێنەرەوە.

ڕەنگ پۆلی ئاگر نییە. بەپێی BS EN 3، لەشی ئاگرکوژێنەرەوە سوورە؛ لە بەریتانیا پارچەیەکی ڕەنگکراو (BS 7863) ماددەکە نیشان دەدات: کرێمی = کەف، شین = تۆزی وشک، ڕەش = CO₂، زەرد = Wet Chemical؛ ئاو هیچ پارچەیەکی نییە. وڵاتانی تر ڕەنگی تر بەکاردەهێنن و ڕەنگەکانی دهۆک هێشتا پشتڕاست نەکراونەتەوە، بۆیە هەمیشە لەیبڵ و نیشانەکانی پۆل بخوێنەرەوە.

پۆلەکانی ئاگر لێرەدا بە پیتەکانی NFPA 10 نووسراون وەک سەرچاوەی پرۆژە؛ سیستەمی فەرمیی دهۆک هێشتا پشتڕاست نەکراوەتەوە. هاوتاکانی EN 2: NFPA A = EN A؛ NFPA B (شلە) = EN B؛ NFPA B (گاز) = EN C؛ NFPA C (ئامێری کارەبایی کە کارەبای تێدایە) هیچ پۆلێکی EN ی نییە؛ NFPA D = EN D؛ NFPA K = EN F.

بۆ ماڵ: ئاگرکوژێنەرەوەی ABC، و Wet Chemical یان بەتانیی ئاگر بۆ چێشتخانە.`},{heading:"PASS — هەنگاو بە هەنگاو",body:`پێش دەستپێکردن، دەبێت هەموو وەڵامەکان «بەڵێ» بن: ئاگرەکە بچووک و تازە دەستی پێکردبێت، ئاگرکوژێنەرەوەکە گونجاو بێت، ڕێگای دەرچوون لە پشتتەوە بێت، ئاگادارکردنەوە درابێت و پەیوەندی بە ١١٥ەوە کرابێت، تۆ ڕاهێنراو بیت، و هیچ دووکەڵ یان گەرمایەک ڕێگات نەگرێت.

١. P = Pull (ڕابکێشە): سنجاقی سەلامەتی ڕابکێشە.
٢. A = Aim (ئاڕاستە بکە): سەری لوولەکە بەرەو بنی ئاگرەکە بگرە، نەک بەرەو سەری. لەو دوورییەوە دەست پێبکە کە لەسەر لەیبڵی ئاگرکوژێنەرەوەکە هاتووە، و تەنها کاتێک ئاگرەکە بچووک دەبێتەوە نزیکتر ببەوە.
٣. S = Squeeze (بگوشە): دەسکەکە بە هێز و بە بەردەوامی بگوشە.
٤. S = Sweep (بجووڵێنە): بۆ چەپ و ڕاست و بە هێواشی بیجووڵێنە تا ئاگرەکە دەکوژێتەوە.

• ئەگەر ئاگرەکە یەکسەر نەکوژایەوە، دەرچۆ و دەرگاکە دابخە.
• ئاگرکوژێنەرەوە بچووکەکان بە خێرایی بەتاڵ دەبن، زۆر جار لە چەند چرکەیەکدا؛ کاتی دروستی بەتاڵبوون لەسەر لەیبڵەکە نووسراوە.
• PASS ڕێگای گشتییە بۆ زۆربەی ئاگرکوژێنەرەوە دەستییەکان. ئاگرکوژێنەرەوەکانی Class D، کیمیایی شل (Wet Chemical)، گازی پاک (Clean Agent) و ئەوانەی لەسەر تایەن: بەپێی لەیبڵ و ڕێنماییەکانی کۆمپانیای دروستکەر بەکاریان بهێنە.`},{heading:"شوێنی وەستان — سەلامەتی پێش هەموو شتێک",body:`پشتت هەمیشە بەرەو دەرگا (ڕێگای دەرچوون) بێت. لەو دوورییەوە دەست پێبکە کە لەسەر لەیبڵی ئاگرکوژێنەرەوەکە یان لە ڕێنماییەکانی کۆمپانیای دروستکەردا هاتووە، و تەنها کاتێک ئاگرەکە بچووک دەبێتەوە نزیکتر ببەوە. ئەگەر گەرما زۆر بوو، بگەڕێوە دواوە. هەرگیز مەهێڵە ئاگرەکە بکەوێتە نێوان تۆ و دەرگاکەوە.
• دووکەڵ و گەرما دەتوانن بە خێرایی بکوژن — ئەگەر ژوورەکە پڕ بوو لە دووکەڵ، یەکسەر دەرچۆ.`},{heading:"کەی نابێت ئاگرکوژێنەرەوە بەکاربهێنیت",body:`• ئاگرەکە لە سەتڵێکی زبڵ گەورەترە یان بە خێرایی بڵاو دەبێتەوە.
• ژوورەکە پڕ دەبێت لە دووکەڵ.
• نازانیت چ مادەیەک دەسووتێت.
• ڕێگای دەرچوون لە پشتتەوە نییە.
• هێشتا کەس پەیوەندیی بە ١١٥ نەکردووە (یەکەم جار پەیوەندی بکە).
• ئاگرەکە لە سلیندەرێکی گاز یان تانکێکی شلە نزیک دەبێتەوە.
• شلە گڕگرەکان بەسەر ڕووبەرێکی گەورەدا بڵاو بوونەتەوە.

لە هەموو ئەم بارانەدا: یەکەم جار دەرچۆ، پاشان پەیوەندی بە ١١٥ بکە.`},{heading:"پشکنینی ئاگرکوژێنەرەوە لە ماڵەوە",body:`هەموو مانگێک (پشکنینی چاوی، لەلایەن کەسی بەرپرسەوە):
١. ئاگرکوژێنەرەوەکە لە شوێنی خۆیدایە و دیارە، و ڕێگای گەیشتن پێی کراوەیە.
٢. سنجاقی سەلامەتی و مۆرەکەی ساغ بن.
٣. لەشی ئاگرکوژێنەرەوەکە پاک، بێ ژەنگ، بێ شکان و بێ دزە بێت؛ لوولە و سەری لوولەکە کراوە بن.
٤. لەیبڵی ڕێنماییەکان بە ئاسانی بخوێنرێتەوە و ڕووی لە دەرەوە بێت.
٥. ئەگەر پەستانپێوی هەبێت، دەرزییەکەی لە ناوچەی سەوزدا بێت. ئاگرکوژێنەرەوەی CO₂ پەستانپێوی نییە: هەڵیبگرە بۆ ئەوەی هەست بکەیت پڕە.

خزمەتگوزاریی کەسێکی پسپۆڕ:
• پشکنین و چاککردنەوە (Maintenance): ساڵی جارێک، و تۆمارکردنی لەسەر کارتی ئاگرکوژێنەرەوەکە.
• پڕکردنەوە (Recharge): دوای هەر بەکارهێنانێک، تەنانەت ئەگەر کورتیش بێت.
• چاککردنەوەی ٦ ساڵە: ئاگرکوژێنەرەوەکانی تۆزی وشکی پەستانی هەڵگیراو (stored-pressure) کە پێویستیان بە تاقیکردنەوەی پەستانی ١٢ ساڵە هەیە، هەر ٦ ساڵ جارێک بەتاڵ دەکرێنەوە و ناوەوەیان دەپشکنرێت.
• تاقیکردنەوەی پەستانی لەشەکەی (Hydrostatic test): هەر ٥ ساڵ بۆ ئاگرکوژێنەرەوەکانی ئاو، کەف (AFFF)، CO₂ و تۆزی وشکی ستێنلێس ستیل (stainless steel)؛ هەر ١٢ ساڵ بۆ ئاگرکوژێنەرەوەکانی تۆزی وشکی پەستانی هەڵگیراو کە لەشیان لە پۆڵای ئاسایی (mild steel)، بڕنجی لەحیمکراو (brazed brass) یان ئەلەمنیۆمە.

کاتی تاقیکردنەوە کاتی گۆڕین نییە. ئاگرکوژێنەرەوە لە کار دەخرێت ئەگەر لە پشکنین یان تاقیکردنەوەدا سەرنەکەوت، خراپ بوو، کۆن بوو یان کۆمپانیای دروستکەر گەڕاندییەوە (recall)، لەیبڵەکەی نەخوێنرایەوە، یان ئاگرکوژێنەرەوەیەکی پڕنەکراوە بوو و ماوەی کارکردنی سەر لەیبڵەکەی بەسەرچوو. ڕێساکانی دهۆک هێشتا پشتڕاست نەکراونەتەوە.`},{heading:"ئاگرکوژێنەرەوە لە کوێ دابنێین؟",body:`• لە ماڵەوە (لانیکەم یەک دانە): لە نزیک دەرگای چێشتخانە، و ئەگەر هەبوو لە هەر نهۆمێک.
• لە شوێنەکانی کار (NFPA 10): دووریی گەیشتن بە ئاگرکوژێنەرەوە بۆ پۆلی A لە ٢٣ مەتر زیاتر نابێت، و بۆ پۆلی B ٩ یان ١٥ مەتر (بەپێی قەبارەی ئاگرکوژێنەرەوەکە).
• نیشانەی ئاگرکوژێنەرەوە (Sign) پێویستە لە دوورەوە دیار بێت.
• ئاگرکوژێنەرەوەکە بە دیوارەوە هەڵبواسە، لە بەرزییەک کە بە ئاسانی پێی بگەیت (سەرەکەی لە نزیکەی ١٫٥ مەتر بەرزتر نەبێت)، نە لەسەر زەوی و نە لە ناو دۆڵابی داخراودا.`}],tips:["بۆ کڕین: ئاگرکوژێنەرەوەی ABC کە بتوانیت هەڵیبگریت و بەکاری بهێنیت (کێشەکەی لەسەر لەیبڵەکەیە) بۆ ماڵ، و ئاگرکوژێنەرەوەی Wet Chemical یان بەتانیی ئاگر بۆ چێشتخانە.","پێش کڕین، پۆلەکانی ئاگر و نیشانەی ستاندارد (وەک EN 3) لەسەر لەیبڵەکە بپشکنە.","PASS لە ڕاهێنانێکدا بە ئاگرکوژێنەرەوەیەکی ڕاهێنان تاقی بکەرەوە.","لەسەر لەیبڵەکە بخوێنەرەوە کە ئاگرکوژێنەرەوەکەت چەند چرکە کار دەکات — زۆربەی ئاگرکوژێنەرەوە بچووکەکان بە خێرایی بەتاڵ دەبن.","بەشداری لە ڕاهێنانەکانی بەرگریی شارستانیدا بکە کاتێک لە گەڕەک یان شوێنی کار ئەنجام دەدرێن.","لەو دوورییەوە دەست پێبکە کە لەسەر لەیبڵی ئاگرکوژێنەرەوەکە هاتووە، ڕێگای دەرچوون لە پشتتەوە بێت، و تەنها کاتێک ئاگرەکە بچووک دەبێتەوە نزیکتر ببەوە.","پشتت هەمیشە بەرەو دەرگا بێت."],warnings:["ئاگرکوژێنەرەوەی بچووک تەنها چەند چرکەیەک کار دەکات — ئامادە بە.","سەری لوولەی ئاگرکوژێنەرەوەی CO₂ زۆر سارد دەبێت — دەستی لێ مەدە.","تۆزی ABC لەسەر کۆمپیوتەر دەتوانێت زیان بە ئامێرەکە بگەیەنێت.","ئاگر لە سەتڵێکی زبڵ گەورەترە = دەرچۆ، نەک ئاگرکوژێنەرەوە.","پاتریی لیتیۆم-ئایۆن: تۆزی ABC و CO₂ ئاگرەکە بە تەواوی ناوەستێنن — بە ئاوی زۆر ساردی بکەرەوە و پەیوەندی بە ١١٥ بکە."],activity:{prompt:"لە ماڵەوەیت. لە ژووری نووستندا، شەحنکەری مۆبایل لەسەر پلاکی کارەبا ئاگری گرت. ئاگرەکە بچووکە و ٢ ئاگرکوژێنەرەوە لەبەردەستتدان: ABC (٢ کیلۆ) و Wet Chemical. چی دەکەیت؟",options:[{text:"یەکەم کارەبا دەبڕم (ئەگەر سەلامەت بوو فیشەکە دەردەهێنم، یان کارەبای سەرەکی دەبڕم). خێزانەکەم ئاگادار دەکەمەوە و پەیوەندی بە ١١٥ دەکەم. پاشان، بە پشتم بەرەو دەرگا، ئاگرکوژێنەرەوەی ABC هەڵدەگرم و PASS بەکاردەهێنم، لەو دوورییەوە کە لەسەر لەیبڵەکەی هاتووە؛ ئەگەر ئاگرەکە یەکسەر نەکوژایەوە، دەردەچم و دەرگاکە دادەخەم.",correct:!0,feedback:"کارەبا بڕاوە، خێزان ئاگادارە، پەیوەندی بە ١١٥ کراوە، دەرچوون لە پشتتە و ئاگرکوژێنەرەوەکە گونجاوە: پێش PASS هەموو وەڵامەکان «بەڵێ»ن."},{text:"ئاگرکوژێنەرەوەی Wet Chemical بەکاردەهێنم",correct:!1,feedback:"Wet Chemical بۆ ڕۆنی چێشتخانەیە (پۆلی K)؛ بۆ ئەم ئاگرە کارەباییە، کارەبا ببڕە، پاشان ئاگرکوژێنەرەوەی ABC بەکاربهێنە."},{text:"ئاوی دەکەمە سەر",correct:!1,feedback:"هەرگیز ئاو لەسەر ئامێرە کارەباییەکان بەکارمەهێنە: دەتوانێت شۆکێکی کارەبایی کوشندە دروست بکات."},{text:"ڕادەکەم و کەس ئاگادار ناکەمەوە",correct:!1,feedback:"دەرچوون بەبێ ئاگادارکردنەوەی کەس خێزانەکەت دەخاتە مەترسییەوە؛ ئاگاداریان بکەرەوە و پەیوەندی بە ١١٥ بکە، تەنانەت ئەگەر ئاگرەکەش نەکوژێنیتەوە."}]},quiz:[{question:"لە ڕێگای PASS، پیتی P مانای چییە؟",options:[{text:"Push (پاڵ بنێ)",correct:!1},{text:"Pull (سنجاقی سەلامەتی ڕابکێشە)",correct:!0},{text:"Point (نیشان بدە)",correct:!1},{text:"Press (دایبگرە)",correct:!1}],explanation:"P واتە Pull: سنجاقی سەلامەتی ڕابکێشە. پاشان بەرەو بنی ئاگرەکە ئاڕاستەی بکە (Aim)، دەسکەکە بگوشە (Squeeze) و بۆ چەپ و ڕاست بیجووڵێنە (Sweep)."},{question:"ئاگرکوژێنەرەوەیەکی بچووکی تۆزی ABC (٢ کیلۆ) نزیکەی چەند کات کار دەکات؟",options:[{text:"٣-٥ خولەک",correct:!1},{text:"تەنها چەند چرکەیەک؛ کاتی دروست لەسەر لەیبڵەکەی نووسراوە",correct:!0},{text:"١ خولەک",correct:!1},{text:"بێ سنوور",correct:!1}],explanation:"ئاگرکوژێنەرەوەی بچووک لە چەند چرکەیەکدا بەتاڵ دەبێت، بۆیە پێش دەستپێکردن ئامادە بە. کاتی دروستی بەتاڵبوون لەسەر لەیبڵەکەی نووسراوە."},{question:"چۆن دەزانیت لە چ دوورییەکەوە لە ئاگرەکە دەست پێبکەیت؟",options:[{text:"هەمیشە لە نیو مەترەوە دەست پێبکە",correct:!1},{text:"لە لەیبڵی ئاگرکوژێنەرەوەکەوە: لەو دوورییەوە دەست پێبکە کە لەوێ هاتووە، ڕێگای دەرچوون لە پشتتەوە بێت، و تەنها کاتێک ئاگرەکە بچووک دەبێتەوە نزیکتر ببەوە",correct:!0},{text:"هەمیشە لە ٧-١٠ مەترەوە دەست پێبکە",correct:!1},{text:"هیچ جیاوازییەک نییە",correct:!1}],explanation:"هیچ دوورییەکی جێگیر نییە: لەو دوورییەوە دەست پێبکە کە لەسەر لەیبڵی ئاگرکوژێنەرەوەکە هاتووە، ڕێگای دەرچوون لە پشتتەوە بێت و تەنها کاتێک ئاگرەکە بچووک دەبێتەوە نزیکتر ببەوە."},{question:"کەی پێویستە ئاگرکوژێنەرەوە بەکارنەهێنیت و دەرچیت؟",options:[{text:"هەرگیز — هەمیشە بەکاری بهێنە",correct:!1},{text:"کاتێک ئاگرەکە لە سەتڵێکی زبڵ گەورەتر بێت یان ژوورەکە پڕ ببێت لە دووکەڵ",correct:!0},{text:"تەنها لە چێشتخانە",correct:!1},{text:"تەنها لە ژووری نووستن",correct:!1}],explanation:"ئەگەر ئاگرەکە لە سەتڵێکی زبڵ گەورەتر بوو، بڵاو بووەوە یان ژوورەکە پڕ بوو لە دووکەڵ، ئاگرکوژێنەرەوە بەکارمەهێنە: دەربچۆ و پەیوەندی بە ١١٥ بکە."},{question:"بۆ ئاگری ڕۆنی چێشتخانە، کام ئاگرکوژێنەرەوە گونجاوە؟",options:[{text:"ئاو",correct:!1},{text:"تۆزی ABC",correct:!1},{text:"Wet Chemical (پۆلی K/F)",correct:!0},{text:"CO₂",correct:!1}],explanation:"ئاگری ڕۆنی چێشتخانە پۆلی K (NFPA) یان F (EN 2)یە. ئاگرکوژێنەرەوەی Wet Chemical چینێک دروست دەکات کە ئۆکسجین دەبڕێت و ڕۆنەکە سارد دەکاتەوە؛ هەرگیز ئاو بەکارمەهێنە."}]},{id:15,icon:"HeartHandshake",accent:"#e11d48",title:"فریاکەوتنی سەرەتایی بۆ هاووڵاتیان",subtitle:"پشکنینی سەرەتایی، CPR، AED، خوێنبەربوون، سووتان و خنکان",summary:"ژیانی مرۆڤێک دەتوانێت بە دەستی هاووڵاتییەکی ئاسایی ڕزگار بێت، ئەگەر بزانێت چی بکات. دوای وەستانی دڵ، هەر خولەکێک بێ CPR و بێ AED دەرفەتی مانەوە لە ژیاندا کەم دەکاتەوە. بەپێی ڕێنماییەکانی AHA 2025، ئەم وانەیە پشکنینی سەرەتایی (DRABC)، پەستانی سنگ (CPR)، ئامێری شۆکی دڵ (AED)، ڕێگای Heimlich، وەستاندنی خوێنبەربوون، سووتان و هەندێک تەنگانەی تر ڕوون دەکاتەوە. پێویستە هەموو هاووڵاتییەک ئەم زانیارییانە فێر بێت.",blocks:[{heading:"DRABC — پشکنینی سەرەتایی",body:`• D = Danger (مەترسی): ئایا مەترسی هەیە؟ کارەبا، ئاگر یان هاتوچۆ؟ پێش هەموو شتێک سەلامەتیی خۆت بپارێزە.
• R = Response (وەڵام): شانەکانی بجووڵێنە و بە دەنگی بەرز بپرسە: «باشیت؟» ئەگەر وەڵامی نەدایەوە، پەیوەندی بە ١٢٢ بکە و داوای AED بکە.
• A = Airway (ڕێگای هەوا): سەری بەرەو دواوە بەرە و چەناگەی بەرز بکەرەوە.
• B = Breathing (هەناسە): لە ١٠ چرکە زیاتر نەبێت، سەیر بکە ئایا سنگی دەجووڵێت و هەناسەدانی ئاساییە یان نا.
• C = CPR: ئەگەر بە دروستی هەناسەی نەدا، یەکسەر دەست بە پەستانی سنگ بکە. پێویست ناکات هاووڵاتی لێدانی دڵ (Pulse) بپشکنێت.`},{heading:"CPR — ٣٠:٢ یان تەنها بە دەست (Hands-Only)",body:`• شوێن: ناوەڕاستی سنگ، دەستێک لەسەر ئەوی تر، باسکەکانت ڕاست بن.
• گەورەساڵ (بەساڵاچووانیشەوە): قووڵی ٥-٦ سم، خێرایی ١٠٠-١٢٠ پەستان لە خولەکێکدا.
• ٣٠ پەستان + ٢ هەناسە ئەگەر فێر بوویت؛ ئەگەر نا، تەنها پەستان بدە (Hands-Only). بۆ منداڵان، ساواکان و ئەو کەسانەی لە ئاودا خنکاون، هەناسە بە تایبەتی گرنگە: ئەگەر فێر بوویت و دەتوانیت، CPR لەگەڵ هەناسە بکە؛ ئەگەر ناتوانیت، تەنها پەستان باشترە لە هیچ نەکردن.
• مەوەستە تا AED دەگات، تیمی ئەمبولانس کارەکە وەردەگرێت، یان تۆ ناتوانیت بەردەوام بیت.
• منداڵ (لە یەک ساڵییەوە تا تەمەنی پێگەیشتن): بە یەک یان هەردوو دەست، قووڵی نزیکەی ٥ سم (یەک لەسەر سێی قووڵیی سنگ).
• ساوا (کەمتر لە یەک ساڵ): بە هەردوو پەنجە گەورە، لە کاتێکدا دەستەکانت دەوری سنگی دەگرن، یان بە بنی لەپی یەک دەست؛ قووڵی نزیکەی ٤ سم. ڕێگای دوو پەنجە ئیتر فێر ناکرێت (AHA 2025).
• بۆ منداڵ و ساوا، ئەگەر دوو کەس پێکەوە CPR بکەن: ١٥:٢.`},{heading:"AED — ئامێری شۆکی دڵ (Defibrillator)",body:`AED لە شوێنە گشتییەکان وەک فەرمانگە، نەخۆشخانە و بازاڕە گەورەکان هەیە. هەر کەسێک دەتوانێت بەکاری بهێنێت، چونکە ئامێرەکە بە دەنگ ڕێنمایی دەدات. بەکارهێنانی زووی دەرفەتی ڕزگاربوون زۆر زیاد دەکات.
١. ئامێرەکە بکەرەوە.
٢. ٢ پادەکە لەسەر سنگی ڕووت دابنێ، وەک وێنەکەی سەر پادەکان.
٣. گوێ لە دەنگی ئامێرەکە بگرە.
٤. هاوار بکە: «کەس دەستی لێ نەدات!»
٥. ئەگەر ئامێرەکە وتی، دوگمەی شۆک دابگرە.
٦. یەکسەر بۆ ماوەی ٢ خولەک CPR بەردەوام بکە و بەپێی ئامێرەکە کار بکە.

• لە کاتی شۆکدا، کەس دەست لە بریندارەکە نەدات!`},{heading:"Heimlich — خنکان بە شتێک",body:`نیشانەکان: کەسەکە ناتوانێت قسە بکات، بکۆکێت یان هەناسە بدات، و دەستەکانی بە گەرووی خۆیەوە دەگرێت.
١. ٥ لێدان بە بنی لەپی دەست لە نێوان هەردوو شانیدا بدە (Back blows).
٢. پاشان ٥ پەستانی سک (Heimlich): مشتت کەمێک لە سەرووی ناوکەوە و زۆر لە خوار ئێسکی سنگەوە دابنێ، و بە خێرایی بەرەو ناوەوە و بەرەو سەرەوە پەستان بدە.
٣. ٥+٥ دووبارە بکەرەوە تا شتەکە دەردەچێت؛ ئەگەر بێهۆش بوو، پەیوەندی بە ١٢٢ بکە و دەست بە CPR بکە.

• ساوا (کەمتر لە یەک ساڵ): ٥ لێدان لە پشت (سەری نزمتر لە سنگی) + ٥ پەستان لە سنگ. هەرگیز پەستانی سک مەکە.
• ئافرەتی دووگیان یان کەسی زۆر قەڵەو: پەستان لە ناوەڕاستی سنگ بدە، نەک لەسەر سک.`},{heading:"خوێنبەربوون — Stop the Bleed",body:`١. پەستانی ڕاستەوخۆ: پەڕۆیەکی پاک بخە سەر برینەکە و بە هێز و بە بەردەوامی پەستان بدە. ئەگەر پەڕۆکە بە خوێن تەڕ بوو، لای مەبە؛ پەڕۆیەکی تر بخە سەری.
٢. پڕکردنەوەی برین (Wound packing): ئەگەر برینەکە قووڵ بوو، پەڕۆی پاکی برینپێچ (Gauze) بخە ناو برینەکە تا پڕ دەبێت و پاشان بە هێز پەستان بدە.
٣. تۆرنیکێت (Tourniquet): بۆ خوێنبەربوونێک کە ژیان دەخاتە مەترسییەوە لە دەست یان قاچەکان، ٥-٧ سم لە سەرووی برینەکەوە (نە لەسەر ئەژنۆ یان ئانیشک) بیبەستە و توندی بکە تا خوێنەکە دەوەستێت. کاتی بەستنەکەی بنووسە، و هەرگیز شلی مەکەرەوە و لای مەبە — تەنها تیمی پزیشکی لای دەبات.

• شتی تیژ لە برینەکە دەرمەهێنە!
• برینی چاو: پەستان لەسەر چاو مەدە.
• برینی سەر: ئەگەر گومانی شکانی ئێسکی سەر هەبوو، بە سووکی پەستان بدە.
• پەیوەندی بە ١٢٢ بکە.`},{heading:"سووتان و تەنگانەکانی تر",body:`• سووتان: ٢٠ خولەک ئاوی فێنکی ڕەوان (نە ئاوی گەرم و نە سەهۆڵ).
• لەهۆشچوون (Fainting): لەسەر پشت پاڵی بخە و قاچەکانی کەمێک بەرز بکەرەوە.
• نەخۆشی شەکرە (Diabetic): ئەگەر بەهۆش بوو و دەتوانێت قووت بدات، شتێکی شیرینی پێبدە.
• ترس (Panic attack): ئارام بە و یارمەتیی بدە بۆ ئەوەی بە هێواشی هەناسە بدات.
• برینی سەر یان مل: مەیجووڵێنە؛ بە جێگیری ڕایبگرە و پەیوەندی بە ١٢٢ بکە. تەنها ئەگەر شوێنەکە مەترسیدار بێت یان پێویستی بە CPR هەبێت بیجووڵێنە، و سەر، مل و پشتی لەسەر یەک هێڵ ڕابگرە. لەسەر لا (دۆخی چاکبوونەوە) دایمەنێ.
• شکان (Fracture): ئەندامەکە مەجووڵێنە، جێگیری بکە و سەهۆڵی پێچراو بخە سەر شوێنە ئاوساوەکە.
• شۆکی کارەبا: یەکەم کار کارەبا ببڕە.
• پێوەدانی مار (Snake bite): لە مارەکە دوور بکەوەرەوە و کەسەکە هێمن و بێجووڵە بهێڵەرەوە. باسک یان قاچە پێوەدراوەکە مەجووڵێنە و بە دار جێگیری بکە، و ئەنگوستیلە، کاتژمێر و جلی تەنگ لابەرە پێش ئەوەی بئاوسێت. پەیوەندی بە ١٢٢ بکە و بە خێرایی بیگەیەنە نەخۆشخانە. برینەکە مەبڕە و مەیمژە، پەت یان تۆرنیکێتی توند مەبەستە، سەهۆڵی لەسەر دامەنێ و چارەسەری میللی یان گیایی بەکارمەهێنە.
• ژەهراویبوون: پەیوەندی بە ١٢٢ بکە و قوتووی مادە ژەهراوییەکە یان لەیبڵەکەی بپارێزە بۆ ئەوەی نیشانی پزیشکەکانی بدەیت. هەوڵ مەدە بیڕشێنیتەوە، و شیر، ڕۆن، ئاوی خوێ یان هیچ چارەسەرێکی ماڵەوەی تری مەدەرێ؛ هیچ خواردن و خواردنەوەیەکی مەدەرێ مەگەر پزیشک پێت بڵێت. ئەگەر نەوت، بەنزین یان ڕۆنی چرا قووت درابێت، ڕشانەوە زۆر مەترسیدارە چونکە مادەکە دەتوانێت بچێتە ناو سییەکانەوە. ئەگەر ژەهرەکە بەر پێست یان چاو کەوتبێت، بە ئاوی ڕەوانی زۆر بیشۆ و جلە پیسبووەکانی دابکەنە. ئەگەر کەسەکە خەواڵوو یان بێهۆش بوو بەڵام هەناسەی ئاسایی دەدات، لەسەر لا دایبنێ.`}],tips:["١٢٢ بۆ ئەمبولانس و ١١٥ بۆ ئاگر و ڕزگارکردن — لەبەریان بکە.","خولێکی CPR و فریاکەوتنی سەرەتایی ببینە و هەر چەند ساڵ جارێک نوێی بکەرەوە.","بزانە لە نزیک ماڵ و شوێنی کارەکەت ئامێرەکانی AED لە کوێن.","دوای وەستانی دڵ، هەر خولەکێک گرنگە — بە خێرایی دەست بە CPR بکە.","گۆرانیی «Stayin' Alive» ڕیتمی ١٠٠-١٢٠ پەستان لە خولەکێکدا بیرت دەخاتەوە.","جانتای فریاکەوتنی سەرەتایی لە ماڵەوە، لە ئۆتۆمبێلدا و لە شوێنی کار هەبێت.","لە جانتای فریاکەوتنی سەرەتاییدا: پەڕۆی پاک، دەستکێش، تۆرنیکێت، مقەست و لیستی ژمارەکانی تەنگانە."],warnings:["هەرگیز دەست لە کەسێک مەدە کە کارەبا لێیداوە تا کارەبا نەبڕدرێت.","ئەگەر گومانی برینداربوونی پشت یان مل هەبوو، کەسی کەوتوو مەجووڵێنە، مەگەر شوێنەکە مەترسیدار بێت یان پێویستی بە CPR هەبێت.","تۆرنیکێت: کاتی بەستنەکەی بنووسە، و هەرگیز شلی مەکەرەوە و لای مەبە.","ئاوی گەرم، سەهۆڵ، کەرە یان هەویری ددان مەکە سەر سووتان.","پادەکانی AED نابێت بەسەر یەکدا بن؛ بۆ منداڵانی خوار ٨ ساڵ، ئەگەر هەبوو، پادی منداڵان بەکاربهێنە."],activity:{prompt:"لەسەر شەقام، بینیت کەسێکی تەمەن ٥٥ ساڵ کەوت. وەڵام ناداتەوە و هەناسە نادات. AED لەبەر دەرگای فەرمانگەیەکی نزیک هەیە و کەسێکی تر لەوێیە. چی دەکەیت؟",options:[{text:"دڵنیا دەبمەوە کە شوێنەکە سەلامەتە و وەڵامدانەوەکەی دەپشکنم. پەیوەندی بە ١٢٢ دەکەم و کەسەکەی تر دەنێرم بۆ هێنانی AED. یەکسەر دەست بە CPR (٣٠:٢) دەکەم و کاتێک AED گەیشت بەکاری دەهێنم.",correct:!0,feedback:"پەیوەندیکردن بە ١٢٢، ناردنی کەسێک بۆ AED و دەستپێکردنی یەکسەری CPR گرنگن، چونکە هەر خولەکێکی بێ CPR دەرفەتی ڕزگاربوون کەم دەکاتەوە."},{text:"تەنها کەسێک دەنێرم بۆ هێنانی AED و بێ CPR چاوەڕێ دەکەم",correct:!1,feedback:"چاوەڕێکردن بەبێ CPR خولەکە گرنگەکان بەفیڕۆ دەدات؛ یەکسەر دەست بە پەستان بکە کاتێک کەسەکەی تر AED دەهێنێت."},{text:"ئاوی پێدەدەم",correct:!1,feedback:"هیچ شتێک مەخە ناو دەمی کەسی بێهۆش؛ پەیوەندی بە ١٢٢ بکە و دەست بە CPR بکە."},{text:"لە دوورەوە ڤیدیۆ دەگرم",correct:!1,feedback:"ڤیدیۆگرتن یارمەتی نادات؛ ئەم کەسە ئێستا پێویستی بە CPR و AED هەیە، بۆیە پەیوەندی بە ١٢٢ بکە و دەست بە پەستان بکە."}]},quiz:[{question:"لە کاتی CPR، قووڵیی پەستان بۆ گەورەساڵان چەندە؟",options:[{text:"٢ سم",correct:!1},{text:"٥-٦ سم",correct:!0},{text:"١٠ سم",correct:!1},{text:"هیچ جیاوازییەک نییە",correct:!1}],explanation:"بۆ هەموو گەورەساڵان، بەساڵاچووانیشەوە، ٥-٦ سم قووڵ پەستان بدە، بە خێرایی ١٠٠-١٢٠ پەستان لە خولەکێکدا. قووڵییەکە کەم مەکەرەوە."},{question:"کێ دەتوانێت ئامێری AED بەکاربهێنێت؟",options:[{text:"تەنها پزیشک",correct:!1},{text:"هەر کەسێک — ئامێرەکە بە دەنگ ڕێنمایی دەدات",correct:!0},{text:"تەنها ئاگرکوژ",correct:!1},{text:"هیچ کەس لە دەرەوەی نەخۆشخانە",correct:!1}],explanation:"هەر کەسێک دەتوانێت AED بەکاربهێنێت: ئامێرەکە بە دەنگ ڕێنمایی دەدات، و بەکارهێنانی زووی دەرفەتی ڕزگاربوون زۆر زیاد دەکات."},{question:"CPR بۆ ساوا (کەمتر لە یەک ساڵ) چۆن دەکرێت؟",options:[{text:"بە هەردوو دەست، وەک گەورەساڵان",correct:!1},{text:"بە هەردوو پەنجە گەورە (دەستەکان دەوری سنگ دەگرن) یان بە بنی لەپی یەک دەست، قووڵی نزیکەی ٤ سم",correct:!0},{text:"بە دوو پەنجە، ٢ سم",correct:!1},{text:"CPR بۆ ساوا ناکرێت",correct:!1}],explanation:"بۆ ساوا، هەردوو پەنجە گەورە بە دەستەکانەوە کە دەوری سنگ دەگرن، یان بنی لەپی یەک دەست بەکاربهێنە، قووڵی نزیکەی ٤ سم. ڕێگای دوو پەنجە ئیتر فێر ناکرێت (AHA 2025)."},{question:"دوای بەستنی تۆرنیکێت، پێویستە چی بکەیت؟",options:[{text:"دوای ١٠ خولەک شلی دەکەمەوە",correct:!1},{text:"کاتی بەستنەکەی دەنووسم و هەرگیز شلی ناکەمەوە تا تیمی پزیشکی دەگات",correct:!0},{text:"هەر نیو کاتژمێر جارێک دەیکەمەوە و دیسان دەیبەستمەوە",correct:!1},{text:"کاتێک خوێنەکە وەستا یەکسەر لای دەبەم",correct:!1}],explanation:"کاتی بەستنی تۆرنیکێتەکە بنووسە و هەرگیز شلی مەکەرەوە و لای مەبە؛ تەنها تیمی پزیشکی لای دەبات."},{question:"ساوایەکی کەمتر لە یەک ساڵ بە شتێک خنکاوە و هێشتا بەهۆشە. چی دەکەیت؟",options:[{text:"یەکسەر پەستانی سک (Heimlich)",correct:!1},{text:"٥ لێدان لە پشت + ٥ پەستان لە سنگ",correct:!0},{text:"یەکسەر CPR",correct:!1},{text:"بە تەنها جێی دەهێڵم",correct:!1}],explanation:"بۆ ساوایەکی بەهۆش کە بە شتێک خنکاوە: ٥ لێدان لە پشت (سەری نزمتر لە سنگی)، پاشان ٥ پەستان لە سنگ. هەرگیز پەستانی سک بۆ ساوا مەکە."}]},{id:16,icon:"DoorOpen",accent:"#dc2626",title:"خۆپاراستن لە ئاگری ماڵ",subtitle:"ئاگادارکەرەوەی دووکەڵ، پلانی دەرچوونی خێزان و چی بکەیت ئەگەر گیرت خوارد",summary:"ئاگری ماڵ دەتوانێت زۆر بە خێرایی بڵاو ببێتەوە: دوای لێدانی ئاگادارکەرەوەی دووکەڵ، لەوانەیە تەنها دوو خولەکت هەبێت بۆ ئەوەی بە سەلامەتی دەرچیت. ئاگادارکەرەوەی دووکەڵی کارا، پلانێکی دەرچوون کە هەموو خێزان ڕاهێنانی لەسەر کردبێت و چەند یاسایەکی سادە ژیان ڕزگار دەکەن: دەرچۆ، لە دەرەوە بمێنەوە، دەرگاکان لە دوای خۆتەوە دابخە و لە دەرەوە پەیوەندی بە ١١٥ بکە.",blocks:[{heading:"ئاگادارکەرەوەی دووکەڵ: ئاگادارکردنەوەی زوو",body:`ئاگادارکەرەوەی دووکەڵ دەتوانێت کاتێک دووکەڵ هەیە لە خەو بەئاگات بهێنێت، تەنانەت لە نیوەی شەویشدا.
• ئاگادارکەرەوەی دووکەڵ لە هەموو ژوورێکی نووستن، لە دەرەوەی شوێنەکانی نووستن و لە هەموو نهۆمێکی ماڵدا دابمەزرێنە، لە سەقف یان لە بەرزایی دیوار، بەپێی ڕێنمایی کۆمپانیای بەرهەمهێنەر.
• لە سۆبەی چێشتلێنان و دەرگای حەمام دووریان بخەرەوە، بۆ ئەوەی دووکەڵی چێشتلێنان و هەڵمی ئاو لێیان نەدات.
• هەموو ئاگادارکەرەوەیەک مانگی جارێک بە دوگمەی تاقیکردنەوە تاقی بکەرەوە.
• ئەو باترییانەی دەگۆڕدرێن لانیکەم ساڵی جارێک بگۆڕە، و یەکسەر ئەگەر ئاگادارکەرەوەکە بە دووبارە دەنگێکی کورتی دا (نیشانەی لاوازی باتری).
• هەموو ئاگادارکەرەوەکە بگۆڕە کاتێک ١٠ ساڵ بەسەر دروستکردنیدا تێدەپەڕێت، یان زووتر ئەگەر ڕێنمایی کۆمپانیای بەرهەمهێنەر وا بڵێت.
• هەرگیز باترییەکە دەرمەهێنە و ئاگادارکەرەوەکە مەکوژێنەرەوە لەبەر ئەوەی چێشتلێنان لێی دەدات.`},{heading:"پلانی دەرچوونی خێزان",body:`پلانەکە پێکەوە دابنێن و لەگەڵ هەموو ئەوانەی لە ماڵەکەدا دەژین ڕاهێنانی لەسەر بکەن.
١. نەخشەیەکی سادەی ماڵەکە بکێشە کە هەموو دەرگا و پەنجەرەکان نیشان بدات.
٢. ئەگەر دەکرێت، بۆ هەموو ژوورێک دوو ڕێگای دەرچوون دیاری بکە: دەرگا و ڕێگایەکی دووەم، وەک پەنجەرەیەک کە دەکرێتەوە.
٣. ڕاڕەو، پلیکانە و دەرچەکان بەتاڵ ڕابگرە. ئەو دەرگا و شیشی پەنجەرانەی لەسەر ڕێگای دەرچوونن دەبێت لە ناوەوە بە خێرایی بکرێنەوە؛ ئەگەر کلیلیان هەیە، لە شوێنێکی دیاریکراو لە نزیک دەرگاکە دایبنێ.
٤. خاڵی کۆبوونەوە لە دەرەوە هەڵبژێرە، لە پێشی ماڵەکە و لە دوورییەکی سەلامەتدا، وەک دارێک یان ستوونێکی کارەبا، بۆ ئەوەی لەوێ هەمووان بژمێردرێن.
٥. دیاری بکە کێ یارمەتی منداڵان، بەساڵاچووان و کەسانی خاوەن پێداویستی تایبەت دەدات بۆ دەرچوون.
٦. لانیکەم ساڵی دوو جار ڕاهێنان بە پلانەکە بکەن، بە شەو و بە ڕۆژ.`},{heading:"کاتێک ئاگادارکەرەوەکە لێدەدات: دەرچۆ و لە دەرەوە بمێنەوە",body:`• بە دەنگی بەرز بڵێ «ئاگر!» بۆ ئەوەی هەمووان ئاگادار بن، و یەکسەر لە نزیکترین ڕێگای سەلامەتەوە دەرچۆ. بۆ کۆکردنەوەی کەلوپەل مەوەستە.
• ئەگەر دووکەڵ هەبوو، خۆت نزم بکەرەوە و لە ژێر دووکەڵەکەوە بەرەو ڕێگای دەرچوون بڕۆ: هەوای پاکتر لە نزیک زەوییە.
• پێش ئەوەی دەرگایەکی داخراو بکەیتەوە، بە پشتی دەستت دەرگاکە و دەسکەکەی تاقی بکەرەوە. ئەگەر گەرم بوو، یان دووکەڵ لە دەورییەوە دەهات، داخراوی بهێڵەوە و ڕێگای دووەم بەکاربهێنە.
• کاتێک دەردەچیت دەرگاکان لە دوای خۆتەوە دابخە: دەرگای داخراو بڵاوبوونەوەی دووکەڵ، گەرما و ئاگر خاو دەکاتەوە.
• پلیکانە بەکاربهێنە، هەرگیز ئاسانسۆر بەکارمەهێنە.
• بڕۆ بۆ خاڵی کۆبوونەوە و لە دەرەوە پەیوەندی بە ١١٥ بکە. سەرەتا ناونیشانی ماڵەکە و نیشانەیەکی دیاری نزیک بڵێ.
• هەرگیز بۆ کەس، ئاژەڵ یان کەلوپەل مەگەڕێوە ژوورەوە. ئەگەر کەسێک ون بوو، یەکسەر بە ئاگرکوژێنەرەوەکان بڵێ لەوانەیە لە کوێ بێت.`},{heading:"ئەگەر گیرت خوارد: دەرگا دابخە، کونەکان بگرە، پەیوەندی بکە و ئاماژە بدە",body:`ئەگەر دووکەڵ یان ئاگر هەردوو ڕێگای دەرچوونی گرت:
١. لە ژوورێکدا بمێنەوە کە پەنجەرەی هەیە و ئەو دەرگایەی لە نێوان تۆ و ئاگرەکەدایە دابخە.
٢. خاولی، بەتانی یان جل لە دەوری دەرگاکە و لەسەر کونەکانی هەوا دابنێ، بۆ ئەوەی دووکەڵ نەیەتە ژوورەوە.
٣. پەیوەندی بە ١١٥ بکە و بە وردی بڵێ لە کوێیت: ناونیشان، نهۆم و ژوور. تەلەفۆنەکە دامەخە تا پێت نەڵێن.
٤. لە بەر پەنجەرە بە پارچە قوماشێکی ڕەنگ کاڵ یان بە چرایەکی دەستی ئاماژە بکە، بۆ ئەوەی ئاگرکوژێنەرەوەکان بتبینن. ئەگەر پەنجەرەکەت بۆ هەوا کردەوە و دووکەڵ هات، دووبارە دایبخەرەوە.
٥. نزم بمێنەوە و چاوەڕێی ئاگرکوژێنەرەوەکان بکە. لە نهۆمی سەرەوە خۆت فڕێ مەدە.`},{heading:"ئاگرگرتنی جل و سووتان",body:`• ئەگەر جلەکانت ئاگریان گرت: بوەستە، خۆت بدە بە زەویدا، بە دەستەکانت دەموچاوت دابپۆشە و خۆت بگلێنەوە تا گڕەکە دەکوژێتەوە. ڕامەکە.
• ئەگەر کەسێک نەتوانێت خۆی بدات بە زەویدا و خۆی بگلێنێتەوە، بە بەتانییەکی قورس یان چاکەتێک گڕەکە بکوژێنەرەوە.
• یەکسەر سووتانەکە بۆ ماوەی ٢٠ خولەک لە ژێر ئاوی فێنکی ڕەواندا سارد بکەرەوە. سەهۆڵ، کەرە، مەعجوونی ددان یان کرێم لەسەری مەدە، و بڵقەکان مەتەقێنە.
• ئەڵقە، کاتژمێر و ئەو جلانەی نزیکی سووتانەکەن لابە، بەڵام ئەو شتەی بە پێستەوە نووساوە لامەبە. پاشان نایلۆنی خۆراکی پاک یان پارچە قوماشێکی پاک بە شلی بخە سەری.
• پەیوەندی بە ١٢٢ بکە ئەگەر سووتانەکە گەورە یان قووڵ بوو، لەسەر دەموچاو، دەست، پێ یان کۆئەندامی زاوزێ بوو، بە کارەبا یان ماددەیەکی کیمیایی بوو، یان کەسەکە بە زەحمەت هەناسەی دەدا.`}],tips:["بە شەو دەرگای ژوورەکانی نووستن و چێشتخانە دابخە: دەرگای داخراو بڵاوبوونەوەی دووکەڵ و ئاگر خاو دەکاتەوە.","چرایەکی دەستی و تەلەفۆنەکەت لە نزیک جێگای نووستنت دابنێ.","دڵنیا بە کە ژمارەی ماڵەکەت یان نیشانەیەکی دیار بە شەو و بە ڕۆژ لە شەقامەوە دەبینرێت.","١١٥، ١٢٢ و ناونیشانی تەواوی ماڵەکەت لەگەڵ نیشانەیەکی دیار لە شوێنێک بنووسە کە هەمووان بیبینن.","پلانی دەرچوون و خاڵی کۆبوونەوە فێری منداڵان بکە: ئەوان دەردەچن، گەورەیەک ئاگادار دەکەنەوە و هەرگیز هەوڵی کوژاندنەوەی ئاگر نادەن."],warnings:["هەرگیز مەگەڕێوە ناو بینایەکی ئاگرگرتوو، تەنانەت بۆ ئەندامێکی خێزانیش: بە ئاگرکوژێنەرەوەکان بڵێ ئەو کەسە لە کوێیە.","بە ڕاوەستاوی بە ناو دووکەڵدا مەڕۆ، و هەرگیز دەرگایەکی گەرم مەکەرەوە.","لە کاتی ئاگردا هەرگیز ئاسانسۆر بەکارمەهێنە."],activity:{prompt:"بە شەو ئاگادارکەرەوەی دووکەڵ لە خەو هەڵتدەستێنێت. بە پشتی دەستت دەست لە دەرگای ژووری نووستن دەدەیت و گەرمە. ژوورەکەت لە نهۆمی سێیەمە و پەنجەرەی هەیە. چی دەکەیت؟",options:[{text:"دەرگاکە بە خێرایی دەکەمەوە و بە ناو ڕاڕەوەکەدا بەرەو پلیکانەکان ڕادەکەم.",correct:!1,feedback:"دەرگای گەرم واتە ئاگر یان دووکەڵێکی زۆر گەرم لە پشتییەتی؛ کردنەوەی دەتوانێت بیانهێنێتە ناو ژوورەکەت. داخراوی بهێڵەوە و ڕێگای دووەم بەکاربهێنە یان لە بەر پەنجەرە چاوەڕێ بکە."},{text:"دەرگاکە داخراو دەهێڵمەوە، کونەکانی دەوری بە خاولی یان جل دەگرم، بە ناونیشان، نهۆم و ژوورەوە پەیوەندی بە ١١٥ دەکەم و لە بەر پەنجەرە بە قوماشێکی ڕەنگ کاڵ ئاماژە دەدەم.",correct:!0,feedback:"دەرگای داخراو و گیراو لە دووکەڵ و ئاگر دەتپارێزێت، و ١١٥ پێویستی بە شوێنی وردی تۆیە بۆ ئەوەی بە خێرایی بگاتە لات."},{text:"یەکسەر خۆم لە پەنجەرەکەوە فڕێ دەدەم، پێش ئەوەی دووکەڵ بگاتە ژوورەکە.",correct:!1,feedback:"خۆفڕێدان لە نهۆمی سێیەمەوە دەتوانێت بتکوژێت یان بە سەختی بریندارت بکات. دەرگاکە دابخە، پەیوەندی بە ١١٥ بکە و لە بەر پەنجەرە ئاماژە بدە: ئاگرکوژێنەرەوەکان دەتوانن لەوێ بگەنە لات."},{text:"خۆم لە ژێر قەرەوێڵەکە دەشارمەوە و بە بێدەنگی چاوەڕێ دەکەم تا دووکەڵەکە تێدەپەڕێت.",correct:!1,feedback:"دووکەڵ خۆی تێناپەڕێت، و دەبێت ئاگرکوژێنەرەوەکان بتوانن بتدۆزنەوە. لە بەر پەنجەرە بمێنەوە، ئاماژە بدە و بە ١١٥ بڵێ لە کوێیت."}]},quiz:[{question:"ئاگادارکەرەوەی دووکەڵ دەبێت لە کوێی ماڵ دابمەزرێت؟",options:[{text:"تەنها لە چێشتخانە، ڕاستەوخۆ لە سەرووی سۆبەی چێشتلێنان",correct:!1},{text:"لە هەموو ژوورێکی نووستن، لە دەرەوەی شوێنەکانی نووستن و لە هەموو نهۆمێک",correct:!0},{text:"تەنها لە ژووری دانیشتن، لە نزیک دەرگای سەرەکی، لە شوێنێک کە هەمووان دەنگی دەبیستن",correct:!1},{text:"لە ناو کەنتۆرێکدا، بۆ ئەوەی تۆز و منداڵ نەگەنە پێی",correct:!1}],explanation:"شوێنی ئاگادارکەرەوەی دووکەڵ لە هەموو ژوورێکی نووستن، لە دەرەوەی شوێنەکانی نووستن و لە هەموو نهۆمێکە. ڕاستەوخۆ لە سەرووی سۆبە، دووکەڵی چێشتلێنان لێیان دەدات و خەڵک دەیانەوێت بیانکوژێننەوە."},{question:"هەر ئاگادارکەرەوەیەکی دووکەڵ چەند جار دەبێت بە دوگمەی تاقیکردنەوە تاقی بکرێتەوە؟",options:[{text:"هەر پێنج ساڵ جارێک",correct:!1},{text:"مانگی جارێک",correct:!0},{text:"تەنها کاتێک باترییەکە دەگۆڕدرێت",correct:!1},{text:"هەرگیز: تاقیکردنەوە ئاگادارکەرەوەکە تێکدەدات",correct:!1}],explanation:"هەموو ئاگادارکەرەوەیەک مانگی جارێک تاقی بکەرەوە. باترییە گۆڕاوەکان لانیکەم ساڵی جارێک بگۆڕە، و هەموو ئاگادارکەرەوەکە دوای ١٠ ساڵ یان بەپێی ڕێنمایی کۆمپانیای بەرهەمهێنەر بگۆڕە."},{question:"لە ماڵە ئاگرگرتووەکە دەرچوویت، بەڵام ئەندامێکی خێزان هێشتا ونە. چی دەکەیت؟",options:[{text:"لە دەرەوە دەمێنمەوە، پەیوەندی بە ١١٥ دەکەم و بە ئاگرکوژێنەرەوەکان دەڵێم ئەو کەسە لەوانەیە لە کوێ بێت",correct:!0},{text:"بە خێرایی دەگەڕێمەوە ژوورەوە بۆ گەڕان بەدوایدا پێش گەیشتنی ئاگرکوژێنەرەوەکان بۆ ماڵەکە",correct:!1},{text:"بە بێدەنگی لە خاڵی کۆبوونەوە چاوەڕێ دەکەم تا ئاگرەکە دەکوژێتەوە",correct:!1},{text:"منداڵێک دەنێرمە ژوورەوە، چونکە منداڵ بچووک و خێران",correct:!1}],explanation:"هەرگیز مەگەڕێوە ناو بینایەکی ئاگرگرتوو. ئاگرکوژێنەرەوەکان جلی پاراستن و ئامێری هەناسەدانیان هەیە؛ گوتنی یەکسەری شوێنی ئەو کەسە بۆیان خێراترین یارمەتییە."},{question:"دووکەڵ و ئاگر هەردوو ڕێگای دەرچوونی ژوورەکەتیان گرتووە. سەرەتا چی دەکەیت؟",options:[{text:"دەرگا و پەنجەرەکە بە تەواوی دەکەمەوە بۆ ئەوەی دووکەڵ لە ژوورەکە دەرچێت",correct:!1},{text:"یەکسەر خۆم لە پەنجەرەکەوە فڕێ دەدەم، تەنانەت لە نهۆمێکی بەرزیشەوە",correct:!1},{text:"دەرگاکە دادەخەم، کونەکان دەگرم و بە شوێنی خۆمەوە پەیوەندی بە ١١٥ دەکەم",correct:!0},{text:"خۆم لە کەنتۆری جلەکاندا دەشارمەوە، لەوێ دووکەڵ ناگاتە من",correct:!1}],explanation:"دەرگای داخراو و گیراو دووکەڵ ماوەیەکی درێژتر لە دەرەوە ڕادەگرێت. ناونیشان، نهۆم و ژوورەکە بە ١١٥ بڵێ، پاشان لە بەر پەنجەرە ئاماژە بدە بۆ ئەوەی ئاگرکوژێنەرەوەکان بتبینن."},{question:"جلەکانت ئاگر دەگرن. دەبێت چی بکەیت؟",options:[{text:"بە خێرایی ڕادەکەمە دەرەوە بۆ ئەوەی با گڕەکە بکوژێنێتەوە",correct:!1},{text:"دەوەستم، خۆم دەدەم بە زەویدا، دەموچاوم دادەپۆشم و خۆم دەگلێنمەوە تا گڕەکە دەکوژێتەوە",correct:!0},{text:"بێجووڵە دەوەستم و چاوەڕێ دەکەم تا کەسێک ئاو لە چێشتخانەوە دەهێنێت",correct:!1},{text:"لە کاتی ڕاکردن بەرەو حەمام جلە ئاگرگرتووەکان دادەکەنم",correct:!1}],explanation:"وەستان، خۆدان بە زەویدا و خۆگلاندنەوە گڕەکە دەکوژێننەوە؛ ڕامەکە. دواتر سووتانەکە ٢٠ خولەک لە ژێر ئاوی فێنکی ڕەواندا سارد بکەرەوە و بۆ سووتانێکی گەورە پەیوەندی بە ١٢٢ بکە."}],media:[{kind:"image",src:"media/images/w7_home_escape_plan.webp",title:"خێزانێک ڕاهێنان بە پلانی دەرچوونی ماڵ دەکات",description:"دایک و باوک و منداڵان بە نزمی لە ژێر دووکەڵەوە لە ماڵ دەردەچن، دەرگا لە دوای خۆیانەوە دادەخەن و لە خاڵی کۆبوونەوەی دەرەوە کۆ دەبنەوە."}]},{id:17,icon:"Fuel",accent:"#b45309",title:"سۆبە، سلیندەری گاز، مۆنۆکسیدی کاربۆن و مۆلیدە",subtitle:"گەرمکردنەوەی سەلامەت، سلیندەری گاز (LPG)، گازی نادیاری CO و مۆلیدە لە ماڵ و لە گەڕەک",summary:"لە زستاندا و لە کاتی بڕانی کارەبادا، زۆرێک لە ماڵەکان سۆبەی گاز و نەوت، سلیندەری گاز (LPG) و مۆلیدە بەکاردەهێنن. ئەگەر بە هەڵە بەکاربهێنرێن، دەتوانن ببنە هۆی ئاگر، تەقینەوە و ژەهراویبوون بە مۆنۆکسیدی کاربۆن (CO)؛ CO گازێکە کە نە دەتوانیت بیبینیت و نە بۆنی بکەیت. ئەم وانەیە یاساکانی سەلامەتی بۆ هەر یەکێکیان دیاری دەکات و ڕوونی دەکاتەوە چی بکەیت ئەگەر بۆنی گازت کرد یان نیشانەکانی ژەهراویبوون بە CO لە کەسێکدا دەرکەوت.",blocks:[{heading:"سۆبەی گاز و نەوت",body:`• سۆبەیەکی ساغ بەکاربهێنە و ڕێنماییەکانی کۆمپانیای بەرهەمهێنەر جێبەجێ بکە. تەنها ئەو سووتەمەنییە بەکاربهێنە کە کۆمپانیای بەرهەمهێنەر دیاری کردووە: هەرگیز بەنزین مەکە ناو سۆبەی نەوتەوە.
• هەر شتێک کە دەسووتێت (پەردە، جێگای نووستن، جل، کەلوپەلی ماڵ) لانیکەم ١ مەتر (٣ پێ) لە سۆبەکە دوور ڕابگرە، و منداڵان لێی دوور بخەرەوە.
• سۆبەکە لەسەر زەوییەکی ڕێک و پتەو دابنێ، دوور لە دەرگاکان و لەو شوێنانەی خەڵکی پێیدا تێدەپەڕن.
• سۆبەی بێ بۆری دووکەڵ (بۆرییەک کە دووکەڵەکە دەباتە دەرەوە) دووکەڵەکەی بەردەداتە ناو ژوورەکە: دەرگای ژوورەکە بەرەو ماڵەکە کراوە بهێڵەوە و پەنجەرەیەک کەمێک بکەرەوە بۆ هەوای پاک.
• سۆبەی گاز و نەوتی گواستراوە پێش خەوتن و کاتێک لە ژوورەکە دەردەچیت بکوژێنەرەوە.
• سۆبەی نەوت لە دەرەوە پڕ بکەرەوە، و تەنها دوای ئەوەی کوژێنرایەوە و سارد بووەوە.
• ئەگەر سۆبەکە گڕی دا یان ئاگری گرت، هەڵیمەگرە: ئەگەر سەلامەت بوو بە سویچی وەستاندنەکەی بیکوژێنەرەوە؛ ئەگەر نا، هەمووان دەربهێنە، دەرگاکە دابخە و پەیوەندی بە ١١٥ بکە.`},{heading:"سلیندەری گاز (LPG)",body:`• سلیندەر، ڕێگولەیتەر و لوولەی ساغ بەکاربهێنە؛ هیچ پارچەیەکی تێکچوو، درزبردوو یان دزەکەر بەکارمەهێنە.
• سلیندەرەکە بە ڕاوەستاوی لە شوێنێکی هەوادار دابنێ، دوور لە سۆبە، تەباخ، تیشکی ڕاستەوخۆی خۆر و هەر گەرمییەکی تر.
• گازی LPG لە هەوا قورسترە: گازی دزەکردوو لە نزیک زەوی و لە شوێنە نزمەکان کۆ دەبێتەوە. سلیندەر لە نهۆمی ژێرزەوی دامەنێ، و سلیندەری زیادە لە ژووری نووستن یان لە نزیک ڕێگای دەرچوون مەهێڵەوە.
• با تەکنیکارێکی شارەزا ڕێگولەیتەر، لوولە و پەیوەندییەکان دابنێت و بیانپشکنێت، و لوولەی درزبردوو، ڕەقبوو یان کۆن بگۆڕە.
• هەرگیز بە ئاگر، شقارتە یان چەرخ بەدوای دزەی گازدا مەگەڕێ. تەکنیکار پەیوەندییەکان بە ئاوی سابوون دەپشکنێت: بڵق نیشانەی دزەکردنی گازە.
• کاتێک گاز بەکارناهێنیت، سەمامەی سلیندەرەکە دابخە.`},{heading:"ئەگەر بۆنی گازت کرد",body:`١. هیچ ئاگرێک دامەگیرسێنە و هیچ گڵۆپ یان ئامێرێک هەڵمەکە و مەکوژێنەرەوە. لە ناو شوێنەکەدا تەلەفۆن بەکارمەهێنە، و مۆلیدە یان ئۆتۆمبێل لە نزیکەوە هەڵمەکە.
٢. ئەگەر بە خێرایی دەتوانیت، لە ڕێگای دەرچووندا دەرگا و پەنجەرەکان بکەرەوە.
٣. سەمامەی گاز تەنها دابخە ئەگەر لە نزیکت بوو و توانیت پێی بگەیت بەبێ ئەوەی بچیتە ئەو شوێنەی گازی تێدا کۆبووەتەوە و بەبێ هیچ پریشکێک؛ ئەگەر نا، لێی نزیک مەبەوە.
٤. هەمووان دەربهێنە و دراوسێکان ئاگادار بکەرەوە.
٥. لە دەرەوە پەیوەندی بە ١١٥ بکە، و مەگەڕێوە ژوورەوە تا پسپۆڕان نەڵێن سەلامەتە.`},{heading:"مۆنۆکسیدی کاربۆن (CO): ژەهری نادیار",body:`مۆنۆکسیدی کاربۆن (CO) کاتێک سووتەمەنی دەسووتێت دروست دەبێت: لە سۆبە، تەباخ، ئاوگەرمکەر، مۆلیدە، بزوێنەری ئۆتۆمبێل و خەڵووزدا. بێ ڕەنگ و بێ بۆنە.
• نیشانەکانی ژەهراویبوون بە CO: سەرئێشە، سەرگێژخواردن، لاوازی، دڵتێکهەڵاتن یان ڕشانەوە، ئازاری سنگ و شێواوی. ئەگەر چەند کەس لە یەک شوێن و لە یەک کاتدا نەخۆش کەوتن، بیر لە CO بکەرەوە.
• ئەو کەسانەی خەوتوون دەتوانن بە CO بمرن پێش ئەوەی هەست بە هیچ نیشانەیەک بکەن.
• ئاگادارکەرەوەی CO لە نزیک شوێنەکانی نووستن دابمەزرێنە، مانگی جارێک تاقی بکەرەوە و ڕێنماییەکانی کۆمپانیای بەرهەمهێنەر جێبەجێ بکە.
• هەموو ساڵێک با تەکنیکارێکی شارەزا سۆبە، ئاوگەرمکەر و بۆری دووکەڵەکان بپشکنێت.
• هەرگیز ماڵ بە فڕنی گاز گەرم مەکەرەوە، و هەرگیز مەنقەڵی خەڵووز یان کەباب مەهێنە ژوورەوە.`},{heading:"ئەگەر ئاگادارکەرەوەی CO لێیدا یان خەڵک نەخۆش کەوتن",body:`• یەکسەر هەمووان بۆ هەوای پاک دەربهێنە؛ تەنها ئەگەر خێرا و سەلامەت بوو، لە ڕێگادا سۆبەکە بکوژێنەرەوە.
• لە دەرەوە بۆ هەر کەسێک نیشانەی هەبێت پەیوەندی بە ١٢٢ بکە، تەنانەت ئەگەر باشتریش بوو، و پەیوەندی بە ١١٥ بکە.
• بۆ ڕزگارکردنی کەس مەگەڕێوە ژوورەوە: چاوەڕێی تیمە ڕاهێنراوەکان بکە.
• کەس ناچێتەوە ژوورەوە تا پسپۆڕان نەڵێن سەلامەتە و ئامێرەکە نەپشکنرێت.`},{heading:"مۆلیدە لە ماڵ و لە گەڕەک",body:`• مۆلیدەی گواستراوە تەنها لە دەرەوە بەکاربهێنە، لانیکەم ٦ مەتر (٢٠ پێ) دوور لە پەنجەرە، دەرگا و کونی هەوا، و دووکەڵەکەی بەرەو دوور لە بیناکان ئاراستە بکرێت. هەرگیز لە ناو ماڵ، گەراج، نهۆمی ژێرزەوی، دووکان یان کۆگا، یان لەسەر باڵکۆنێکی داخراو کاری پێ مەکە، تەنانەت ئەگەر دەرگا و پەنجەرەکان کراوە بن.
• پێش پڕکردنەوەی سووتەمەنی، مۆلیدەکە بکوژێنەرەوە و با سارد ببێتەوە: سووتەمەنی ڕژاو لەسەر پارچە گەرمەکان دەتوانێت ئاگر بگرێت. سووتەمەنی لە دەرەوەی شوێنەکانی ژیان لە دەفرێکی گونجاو و داخراودا هەڵبگرە.
• هەرگیز مۆلیدە بە پلاکی دیوار یان بە وایەرەکانی کارەبای ماڵەوە مەبەستەوە (Backfeeding): دەتوانێت دراوسێکان و کارمەندانی کارەبا بکوژێت. تەنها کارەباچییەکی شارەزا دەتوانێت مۆلیدە ببەستێتەوە، لە ڕێگەی سویچی گواستنەوە (Transfer Switch).
• مۆلیدەی گەڕەک: خۆت دەست لە وایەر و سویچەکانیان مەدە. وایەری شل یان تێکچوو، پریشک یان بۆنی سووتان بە خاوەنی مۆلیدەکە ڕابگەیەنە، و لە باری نائاساییدا پەیوەندی بە ١١٥ بکە. تەنها کارەباچییەکی شارەزا دەبێت ئەو سویچە دابنێت کە ماڵەکەت لە نێوان مۆلیدەی گەڕەک و کارەبای نیشتمانیدا دەگۆڕێت.`}],tips:["ئاگادارکەرەوەی دووکەڵ و ئاگادارکەرەوەی CO لە ماڵەوە دابمەزرێنە و مانگی جارێک تاقییان بکەرەوە.","هەموو ساڵێک با تەکنیکارێکی شارەزا سۆبە و ئامێرەکانی گاز بپشکنێت.","لانیکەم ١ مەتر (٣ پێ) لە دەوری سۆبە وەک ناوچەیەکی سەلامەت بهێڵەوە، بەتایبەتی بۆ منداڵان.","کاتێک گاز بەکارناهێنیت، سەمامەی سلیندەرەکە دابخە.","سووتەمەنی سۆبە و مۆلیدە لە دەرەوەی شوێنەکانی ژیان، لە دەفری گونجاو و داخراو و دوور لە گەرمی هەڵبگرە."],warnings:["هەرگیز مۆلیدە، مەنقەڵی خەڵووز یان کەباب لە ناو ماڵدا بەکارمەهێنە، تەنانەت ئەگەر دەرگا و پەنجەرەکان کراوە بن.","هەرگیز بە ئاگر بەدوای دزەی گازدا مەگەڕێ.","هەرگیز مۆلیدە بە پلاکی دیوار یان بە وایەرەکانی کارەبای ماڵەوە مەبەستەوە."],activity:{prompt:"لە شەوێکی سارددا، سۆبەی نەوت چەند کاتژمێرێک لە ژووری دانیشتنی داخراودا داگیرساو بوو. دایکت و کوڕەکەت هەردووکیان سەریان دێشێت و سەریان گێژ دەخوات و دڵیان تێکهەڵدێت. چی دەکەیت؟",options:[{text:"حەبی سەرئێشەیان دەدەمێ، پەنجەرەکە کەمێک دەکەمەوە و لە ژوورە گەرمەکەدا دەمێنینەوە.",correct:!1,feedback:"حەب CO لە لەش دەرناکات، و کاتێک نیشانەکان دەرکەوتن کردنەوەیەکی بچووک بەس نییە. دەبێت هەمووان بۆ هەوای پاک دەربچن و پەیوەندی بە ١٢٢ بکەیت."},{text:"یەکسەر هەمووان بۆ هەوای پاک دەردەهێنم، تەنها ئەگەر خێرا و سەلامەت بوو سۆبەکە دەکوژێنمەوە، و لە دەرەوە پەیوەندی بە ١٢٢ و ١١٥ دەکەم؛ کەس ناچێتەوە ژوورەوە تا نەپشکنرێت.",correct:!0,feedback:"دوو کەس بە هەمان نیشانە لە نزیک سۆبەیەکی داگیرساو نیشانەی ژەهراویبوون بە CO یە: هەوای پاک و پەیوەندیکردن بە ١٢٢ یەکەم شتن، و دەبێت سۆبەکە بپشکنرێت پێش ئەوەی دووبارە بەکاربهێنرێتەوە."},{text:"سۆبەکە دەکوژێنمەوە و دەهێڵم بخەون، چونکە پشوو بۆ سەرئێشە باشە.",correct:!1,feedback:"ئەو کەسانەی خەوتوون دەتوانن بە CO بمرن بەبێ ئەوەی بەخەبەر بێن. هەمووان بۆ هەوای پاک دەربهێنە و پەیوەندی بە ١٢٢ بکە."},{text:"نەوتی زیاتر دەکەمە ناو سۆبەکەوە بۆ ئەوەی باشتر بسووتێت و دووکەڵی کەمتر بێت.",correct:!1,feedback:"سووتەمەنی زیاتر CO ناوەستێنێت. ئەم کەسانە ئێستا پێویستیان بە هەوای پاک و یارمەتی پزیشکییە: دەریان بهێنە و پەیوەندی بە ١٢٢ بکە."}]},quiz:[{question:"پەردە، جێگای نووستن و شتە سووتاوەکانی تر دەبێت چەند لە سۆبە دوور بن؟",options:[{text:"نزیکەی ١٠ سانتیمەتر بەسە",correct:!1},{text:"لانیکەم ١ مەتر (٣ پێ)",correct:!0},{text:"هەر دوورییەک، ئەگەر سۆبەکە نوێ بێت",correct:!1},{text:"پێویست بە دووری نییە، ئەگەر سۆبەکە نزم بێت",correct:!1}],explanation:"هەر شتێک کە دەسووتێت لانیکەم ١ مەتر (٣ پێ) لە سۆبە دوور ڕابگرە، و منداڵانیش لێی دوور بخەرەوە."},{question:"ڕێگای سەلامەت بۆ پشکنینی لوولەی گاز (LPG) و پەیوەندییەکانی بۆ دزەکردن کامەیە؟",options:[{text:"شقارتەیەکی داگیرساو لە نزیک پەیوەندییەکە دەگرم و سەیر دەکەم گڕ دروست دەبێت",correct:!1},{text:"تەباخەکە هەڵدەکەم و گوێ لە دەنگی گڕەکە دەگرم",correct:!1},{text:"تەکنیکارێکی شارەزا بە ئاوی سابوون دەیپشکنێت",correct:!0},{text:"کاتێک سەمامەی سلیندەرەکە بە تەواوی کراوەیە، لە نزیکەوە بۆنی لوولەکە دەکەم",correct:!1}],explanation:"ئاگر دەتوانێت گازی دزەکردوو داگیرسێنێت و ببێتە هۆی ئاگر یان تەقینەوە. تەکنیکارێکی شارەزا پەیوەندییەکان بە ئاوی سابوون دەپشکنێت: بڵق نیشانەی دزەکردنی گازە."},{question:"کام لەمانە دەتوانێت نیشانەی ژەهراویبوون بە مۆنۆکسیدی کاربۆن (CO) بێت؟",options:[{text:"بۆنێکی بەهێزی گاز کە لە سۆبەکەوە دێت",correct:!1},{text:"سەرئێشە و سەرگێژخواردن لە چەند کەسێکدا پێکەوە",correct:!0},{text:"دووکەڵێکی شین کە بە ڕوونی لە نزیک زەوی دەیبینیت",correct:!1},{text:"خورانێکی پێست کە هەفتەیەک دواتر دەردەکەوێت",correct:!1}],explanation:"CO بێ ڕەنگ و بێ بۆنە. سەرئێشە، سەرگێژخواردن، لاوازی و دڵتێکهەڵاتن، بەتایبەتی لە چەند کەسێکدا پێکەوە لە نزیک ئامێری سووتەمەنی، نیشانەی مەترسین. بۆنی گاز واتە دزەکردنی گاز، نەک CO."},{question:"مۆلیدەی گواستراوە لە کوێ بە سەلامەتی بەکاردەهێنرێت؟",options:[{text:"لە دەرەوە، لانیکەم ٦ مەتر (٢٠ پێ) دوور لە پەنجەرە، دەرگا و کونی هەوا",correct:!0},{text:"لە ناو گەراجدا، بەو مەرجەی دەرگا گەورەکەی گەراجەکە بە تەواوی کراوە بمێنێتەوە",correct:!1},{text:"لەسەر باڵکۆنێکی داخراو، کاتێک پەنجەرەکەی تەنیشتی بۆ هەوای پاک کراوەیە",correct:!1},{text:"لە ناو ماڵدا، لە نزیک پەنجەرەیەکی کراوە، لەگەڵ پانکەیەک کە دووکەڵەکە دەردەکات",correct:!1}],explanation:"دووکەڵی مۆلیدە CO ی تێدایە، کە لە ناو ماڵدا دەتوانێت لە چەند خولەکێکدا بکوژێت. مۆلیدە تەنها لە دەرەوە بەکاربهێنە، لانیکەم ٦ مەتر (٢٠ پێ) دوور لە پەنجەرە، دەرگا و کونی هەوا، و دووکەڵەکەی بەرەو دوور لە بیناکان ئاراستە بکرێت."},{question:"مۆلیدە چۆن دەتوانرێت بە وایەرەکانی کارەبای ماڵەوە ببەسترێتەوە؟",options:[{text:"بە پلاکی دیوارەوە بە وایەرێک کە دوو سەری پلاکی هەیە",correct:!1},{text:"تەنها لەلایەن کارەباچییەکی شارەزاوە، لە ڕێگەی سویچی گواستنەوە",correct:!0},{text:"لەلایەن خاوەنی ماڵەوە، ڕاستەوخۆ بە سندووقی فیوزەوە، لە کاتی بڕانی کارەبادا",correct:!1},{text:"لەلایەن هەر دراوسێیەکەوە کە پێشتر مۆلیدەی بەستبێتەوە",correct:!1}],explanation:"بەستنەوەی مۆلیدە بە پلاکی دیوار یان وایەرەکانی کارەبای ماڵەوە (Backfeeding) دەتوانێت دراوسێکان و کارمەندانی کارەبا بە کارەبا بکوژێت. تەنها کارەباچییەکی شارەزا دەتوانێت بیبەستێتەوە، لە ڕێگەی سویچی گواستنەوە."}],media:[{kind:"image",src:"media/images/w7_heaters_gas_generators.webp",title:"گەرمکردنەوەی سەلامەت و مۆلیدە لە دەرەوە",description:"سۆبەیەک بە ناوچەیەکی بەتاڵ و سەلامەت لە دەوری، سلیندەرێکی گازی ڕاوەستاو بە لوولەیەکی پشکنراو، ئاگادارکەرەوەیەکی CO لەسەر دیوار و مۆلیدەیەک لە دەرەوە، دوور لە پەنجەرەکان."}]},{id:18,icon:"Building",accent:"#4f46e5",title:"ژیان لە شوقە و باڵەخانە بەرزەکاندا",subtitle:"دەرچەکان، پلیکانە، دەرگای دژە-ئاگر و چی بکەیت کاتێک ئاگر لە باڵەخانەکەتدا دەکەوێتەوە",summary:"لە باڵەخانەیەکی شوقەدا، ئاگرێک لە شوقەیەکدا دەتوانێت هەمووان بخاتە مەترسییەوە: دووکەڵ بە ناو ڕاڕەو و پلیکانەکاندا بڵاو دەبێتەوە، و ڕێگای دەرچوون درێژترە. ناسینی دەرچەکان، پاراستنی کارایی پلیکانە و دەرگا دژە-ئاگرەکان و زانینی ئەوەی کەی دەرچیت و کەی لە شوقەکەتدا بمێنیتەوە دەتوانێت خێزانەکەت ڕزگار بکات. هەمیشە پلانی باڵەخانەکەت و ڕێنماییەکانی بەرگریی شارستانی جێبەجێ بکە.",blocks:[{heading:"پێش ئاگر باڵەخانەکەت بناسە",body:`• فێر بە هەموو پلیکانەکانی دەرچوون لە نهۆمەکەتدا لە کوێن، بۆ ئەوەی ئەگەر نزیکترینیان بە ئاگر یان دووکەڵ گیرا، ئەوی تر بەکاربهێنیت. ئەو دەرگایانەی لە نێوان شوقەکەت و هەر پلیکانەیەکدان بژمێرە، بۆ ئەوەی لە تاریکی یان لە ناو دووکەڵدا بیدۆزیتەوە.
• لە بەڕێوەبەرایەتی باڵەخانەکە بپرسە باڵەخانەکە چ سیستەمێکی سەلامەتی لە ئاگری هەیە (زەنگی ئاگر، ئاگرکوژێنەرەوە، ڕووناکی باری نائاسایی، پلانی چۆڵکردن) و دانیشتووان دەبێت چۆن وەڵامی زەنگەکە بدەنەوە.
• پلانێکی دەرچوون بۆ شوقەکەت دابنێ و لەسەر خاڵێکی کۆبوونەوە لە دەرەوەی باڵەخانەکە ڕێک بکەون.
• بزانە کام دراوسێی نهۆمەکەت پێویستی بە یارمەتی دەبێت بۆ دابەزین بە پلیکانەدا، وەک بەساڵاچووان و کەسانی خاوەن پێداویستی تایبەت، و لەگەڵ بەڕێوەبەرایەتی و دراوسێکان ڕێک بکەون کێ یارمەتییان دەدات.`},{heading:"پلیکانە، ڕاڕەو و دەرگای دژە-ئاگر",body:`• هەرگیز هیچ شتێک لە ڕاڕەوەکان، لەسەر پلیکانە یان لە بەردەم دەرگاکانی دەرچووندا دامەنێ: نە کەلوپەلی ماڵ، نە پێڵاو، نە پاسکیل، نە سلیندەری گاز و نە سووتەمەنی.
• دەرگا دژە-ئاگرەکان و دەرگاکانی پلیکانە دەبێت خۆیان دابخرێن و داخراو بمێننەوە. هەرگیز بە شتێک کراوەیان مەهێڵەوە و مەیانبەستەوە، و زیانی دەرگا، داخەر یان لاستیکی دەوریان بە بەڕێوەبەرایەتی ڕابگەیەنە.
• دەرگاکانی دەرچوون و پلیکانە نابێت قفڵ بن یان ڕێگایان لێ بگیرێت، و دەبێت لە ناوەوە بەبێ کلیل بکرێنەوە.
• وایەری مۆلیدە، وایەری درێژکەرەوە یان لوولە بە ناو دەرگاکانی پلیکانە یان دەرگا دژە-ئاگرەکاندا مەبە: ڕێگری لە داخستنی دەرگاکان دەکەن.`},{heading:"پلیکانە بەکاربهێنە، هەرگیز ئاسانسۆر نا",body:`لە کاتی ئاگردا، بۆ دەرچوون پلیکانە بەکاربهێنە. ئاسانسۆر بەکارمەهێنە مەگەر ئاگرکوژێنەرەوەکان پێت بڵێن: دەتوانێت بوەستێت و لە نێوان نهۆمەکاندا لە ناو دووکەڵدا گیرت بخات.

ئەگەر کەسێک نەتوانێت پلیکانە بەکاربهێنێت، مەیبە ناو ئاسانسۆرەوە. یەکسەر بە وردی بە ١١٥ و ئاگرکوژێنەرەوەکان بڵێ ئەو کەسە لە کوێیە: نهۆم و ژمارەی شوقەکە.`},{heading:"ئەگەر ئاگرەکە لە شوقەکەتدا بوو",body:`١. هەموو ئەوانەی لە شوقەکەدان ئاگادار بکەرەوە و یەکسەر دەرچۆ.
٢. دەرگای شوقەکە لە دوای خۆتەوە دابخە: دەرگای داخراو دووکەڵ و ئاگر لە ناوەوە ڕادەگرێت.
٣. دراوسێکان ئاگادار بکەرەوە: لە دەرگاکانیان بدە و هاوار بکە «ئاگر!»، و ئەگەر باڵەخانەکە زەنگی ئاگری هەبوو، لێی بدە.
٤. بە پلیکانەدا دابەزە، نەک بە ئاسانسۆر.
٥. لە دەرەوە پەیوەندی بە ١١٥ بکە: ناونیشان، نهۆم و ژمارەی شوقەکە بڵێ، و بڕۆ بۆ خاڵی کۆبوونەوە.`},{heading:"ئەگەر ئاگرەکە لە شوێنێکی تری باڵەخانەکەدا بوو",body:`• کاتێک زەنگەکە لێدەدات یان بۆنی دووکەڵ دەکەیت، پێش کردنەوە بە پشتی دەستت دەرگای شوقەکەت تاقی بکەرەوە.
• ئەگەر دەرگاکە سارد بوو و ڕاڕەو و پلیکانەکان بەتاڵ بوون، لە نزیکترین پلیکانەوە دەرچۆ، دەرگاکان لە دوای خۆتەوە دابخە و بڕۆ بۆ خاڵی کۆبوونەوە.
• ئەگەر دەرگاکە گەرم بوو، یان ڕاڕەو یان پلیکانەکان پڕ بوون لە دووکەڵ، لە شوقەکەتدا بمێنەوە: دەرگاکە داخراو بهێڵەوە، خاولی یان چەرچەفی تەڕ لە دەوری و لەسەر کونەکانی هەوا دابنێ، و بە ناونیشان، نهۆم و ژمارەی شوقەکەوە پەیوەندی بە ١١٥ بکە.
• بڕۆ بەر پەنجەرەیەک یان باڵکۆنێکی دوور لە دووکەڵ و بە پارچە قوماشێکی ڕەنگ کاڵ یان چرایەکی دەستی ئاماژە بدە. پەنجەرەیەک کەمێک بۆ هەوای پاک بکەرەوە، بەڵام ئەگەر دووکەڵ هات دایبخەرەوە.
• گوێ لە ڕاگەیاندنەکان بگرە و پلانی باڵەخانەکەت و ڕێنماییەکانی بەرگریی شارستانی و ئاگرکوژێنەرەوەکان جێبەجێ بکە: ڕزگارکردن لە باڵەخانەیەکی بەرز دەتوانێت کاتێکی درێژ بخایەنێت.`},{heading:"باڵکۆن، سلیندەری گاز، مۆلیدە و وایەر",body:`• سلیندەری گازی زیادە، سووتەمەنی، کەلوپەلی کۆن یان خاشاک لەسەر باڵکۆن مەهێڵەوە. ئەگەر سلیندەرێکی گاز بۆ چێشتلێنان لەوێیە، بە ڕاوەستاوی، دوور لە گەرمی و تیشکی ڕاستەوخۆی خۆر ڕایبگرە، و کاتێک بەکاری ناهێنیت سەمامەکەی دابخە.
• هەرگیز مۆلیدە لەسەر باڵکۆن کار پێ مەکە: دووکەڵەکەی CO لە ڕێگەی پەنجەرە و دەرگاکانەوە دەباتە ناو ماڵی تۆ و ماڵی دراوسێکان.
• وایەری مۆلیدە و کارەبای گەڕەک دەبێت کارەباچییەکی شارەزا دایبنێت. وایەری شل، تێکچوو یان گەرم لە باڵەخانەکەدا بە بەڕێوەبەرایەتی ڕابگەیەنە.
• جگەرە بە تەواوی لە تەپڵەکێکی قووڵدا بکوژێنەرەوە؛ هەرگیز لە باڵکۆن یان پەنجەرەوە فڕێی مەدە.`}],tips:["لانیکەم دوو پلیکانەی دەرچوون لە نهۆمەکەتەوە بناسە.","کلیل، تەلەفۆن و چرایەکی دەستی لە نزیک جێگای نووستنت دابنێ، و کاتێک دەردەچیت لەگەڵ خۆت بیانبە.","لە ڕاهێنانەکانی ئاگری باڵەخانەکەدا وەک ئەوەی ڕاستی بن بەشداری بکە.","داوا لە بەڕێوەبەرایەتی بکە زەنگی ئاگر، ڕووناکی باری نائاسایی، ئاگرکوژێنەرەوە و دەرگا دژە-ئاگرەکان بە ڕێکی بپشکنێت.","ئاگادارکەرەوەی دووکەڵ لە ناو شوقەکەتدا دابمەزرێنە و مانگی جارێک تاقییان بکەرەوە."],warnings:["لە کاتی ئاگردا هەرگیز ئاسانسۆر بەکارمەهێنە، مەگەر ئاگرکوژێنەرەوەکان پێت بڵێن.","هەرگیز دەرگایەکی دژە-ئاگر یان دەرگای پلیکانە بە شتێک کراوە مەهێڵەوە.","مەچۆ ناو ڕاڕەو یان پلیکانەیەکی پڕ لە دووکەڵ: لە شوقەکەتدا بمێنەوە، کونەکانی دەرگاکە بگرە و پەیوەندی بە ١١٥ بکە."],activity:{prompt:"لە نهۆمی حەوتەم دەژیت. زەنگی ئاگر لێدەدات. دەرگای شوقەکەت ساردە، بەڵام کاتێک کەمێک دەیکەیتەوە، ڕاڕەوەکە پڕە لە دووکەڵی چڕ. چی دەکەیت؟",options:[{text:"بە خێرایی بە ئاسانسۆر دادەبەزم، چونکە لە حەوت نهۆم پلیکانە خێراترە.",correct:!1,feedback:"لە کاتی ئاگردا هەرگیز ئاسانسۆر بەکارمەهێنە: دەتوانێت بوەستێت و لە ناو دووکەڵدا گیرت بخات. لە شوقەکەتدا بمێنەوە و پەیوەندی بە ١١٥ بکە."},{text:"هەناسەم ڕادەگرم و بە ناو دووکەڵەکەدا بەرەو پلیکانەکان ڕادەکەم.",correct:!1,feedback:"دووکەڵ ژەهراوییە و دەتوانیت تێیدا ڕێگا ون بکەیت. دەرگاکە دابخە، کونەکان بگرە و لە شوقەکەتەوە پەیوەندی بە ١١٥ بکە."},{text:"دەرگاکە دووبارە دادەخەم، کونەکانی دەوری بە خاولی تەڕ دەگرم، بە ناونیشان، نهۆم و ژمارەی شوقەکەوە پەیوەندی بە ١١٥ دەکەم و لە پەنجەرەیەکی دوور لە دووکەڵەوە ئاماژە دەدەم.",correct:!0,feedback:"دووکەڵی چڕ لە ڕاڕەوەکەدا ڕێگای دەرچوون دەگرێت. دەرگای داخراوی شوقەکەت دەتپارێزێت تا ١١٥ یارمەتی دەنێرێتە نهۆمەکەت."},{text:"دەرگای شوقەکە کراوە دەهێڵمەوە بۆ ئەوەی گوێم لە هاتنی ئاگرکوژێنەرەوەکان بێت.",correct:!1,feedback:"دەرگای کراوە ڕێگە دەدات دووکەڵ بێتە ناو شوقەکە. داخراو و گیراو بیهێڵەوە، و بە ١١٥ بڵێ لە کوێیت."}]},quiz:[{question:"بۆچی دەبێت دەرگا دژە-ئاگرەکان و دەرگاکانی پلیکانە لە باڵەخانەدا داخراو بمێننەوە؟",options:[{text:"بۆ ئەوەی ڕاڕەوەکان لە زستاندا گەرم ڕابگرن و کارەبا بۆ هەمووان پاشەکەوت بکەن",correct:!1},{text:"بڵاوبوونەوەی دووکەڵ و ئاگر خاو دەکەنەوە و پلیکانەکانی دەرچوون دەپارێزن",correct:!0},{text:"ڕێگری لە بێگانە و منداڵان دەکەن کە بە شەو لە نێوان نهۆمەکاندا هاتوچۆ بکەن",correct:!1},{text:"زیاتر بۆ جوانین، بۆیە گرنگ نییە ئەگەر کراوە بمێننەوە",correct:!1}],explanation:"دەرگای دژە-ئاگری داخراو دووکەڵ، گەرما و ئاگر خاو دەکاتەوە و پلیکانەکە بۆ دەرچوون بە کارایی دەهێڵێتەوە. هەرگیز بە شتێک کراوەی مەهێڵەوە، و دەرگایەک کە خۆی دانەخرێت ڕابگەیەنە."},{question:"ئاگرەکە لە ناو شوقەکەتدایە. کاری دروست کامەیە؟",options:[{text:"دەرچۆ، دەرگاکە لە دوای خۆتەوە دابخە، دراوسێکان ئاگادار بکەرەوە و پەیوەندی بە ١١٥ بکە",correct:!0},{text:"دەرگای شوقەکە کراوە بهێڵەوە بۆ ئەوەی دووکەڵ بچێتە ناو ڕاڕەوەکە",correct:!1},{text:"لە ناوەوە بمێنەوە و هەوڵ بدە بە سەتڵی ئاو ئاگرێکی گەورە بکوژێنیتەوە",correct:!1},{text:"بە ئاسانسۆر دابەزە، پاشان داوا لە پاسەوانی باڵەخانەکە بکە چارەسەری بکات",correct:!1}],explanation:"داخستنی دەرگای شوقە ئاگرگرتووەکە دووکەڵ و ئاگر لەو ڕاڕەو و پلیکانانە دوور دەخاتەوە کە دراوسێکانت پێویستیان پێیەتی. ئاگاداریان بکەرەوە، پلیکانە بەکاربهێنە و لە دەرەوە پەیوەندی بە ١١٥ بکە."},{question:"دەبێت چی لە پێڵاو، پاسکیل یان سلیندەری گاز بکرێت کە لە ڕاڕەو یان لەسەر پلیکانە بەجێهێڵراون؟",options:[{text:"بە ڕێکی لە تەنیشت دیوارێک دایانبنێ بۆ ئەوەی خەڵک هێشتا بتوانن تێپەڕن",correct:!1},{text:"لە هاویندا لەوێ بیانهێڵەوە و تەنها لە زستاندا لایانبە",correct:!1},{text:"بە پارچە قوماشێک دایانپۆشە بۆ ئەوەی ئاگر نەگرن",correct:!1},{text:"لایانبە: ڕاڕەو و پلیکانە دەبێت بۆ دەرچوون بەتاڵ بمێننەوە",correct:!0}],explanation:"لە کاتی ئاگردا، خەڵک بە ناو دووکەڵ و تاریکیدا دەردەچن، و هەر شتێک لە ڕاڕەو یان لەسەر پلیکانە دەتوانێت ڕێگایان بگرێت یان بسووتێت. هیچ شتێک لە ڕاڕەو، لەسەر پلیکانە یان لە بەردەم دەرچەکاندا دانانرێت."},{question:"کەی دەتوانیت لە کاتی ئاگردا لە باڵەخانەکەتدا ئاسانسۆر بەکاربهێنیت؟",options:[{text:"کاتێک لە سەرووی نهۆمی پێنجەم دەژیت",correct:!1},{text:"تەنها کاتێک ئاگرکوژێنەرەوەکان پێت دەڵێن بەکاری بهێنە",correct:!0},{text:"کاتێک دووکەڵەکە تەنها لە نهۆمە خوارەوەکاندایە",correct:!1},{text:"کاتێک منداڵ یان کەلوپەلی قورست هەڵگرتووە",correct:!1}],explanation:"پلیکانە بەکاربهێنە. ئاسانسۆر دەتوانێت بوەستێت و خەڵک لە ناو دووکەڵدا گیر بخات؛ ئاگرکوژێنەرەوەکان بڕیار دەدەن کە ئاسانسۆر بەکاربهێنرێت یان نا."},{question:"دووکەڵی ڕاڕەوەکە لە شوقەکەتدا گیرت دەخات. چی بە ١١٥ دەڵێیت؟",options:[{text:"تەنها ناوی خۆت، چونکە خۆیان باڵەخانەکە دەدۆزنەوە",correct:!1},{text:"ناونیشان، نهۆم، ژمارەی شوقەکە و چەند کەس لەگەڵتن",correct:!0},{text:"تەنها ئەوەی دووکەڵ هەیە؛ دواتر پەیوەندیت پێوە دەکەن بۆ پرسینی وردەکارییەکان",correct:!1},{text:"هێشتا هیچ: بە بێدەنگی چاوەڕێ دەکەیت تا کەسێک لە دەرگا دەدات",correct:!1}],explanation:"ئاگرکوژێنەرەوەکان پێویستە بە وردی بزانن لە کوێیت: ناونیشان، نهۆم و شوقە، و چەند کەس لەوێن. تەلەفۆنەکە دامەخە تا پێت نەڵێن."}],media:[{kind:"image",src:"media/images/w7_apartment_fire_safety.webp",title:"دەرچوونی سەلامەت لە باڵەخانەیەکی شوقە",description:"دانیشتووان بە پلیکانەدا دادەبەزن و بە لای دەرگایەکی دژە-ئاگری داخراودا تێدەپەڕن، لە کاتێکدا خێزانێک لە شوقەیەکی تر لە بەر پەنجەرە چاوەڕێ دەکات و بە قوماشێکی ڕەنگ کاڵ ئاماژە دەدات."}]},{id:19,icon:"Leaf",accent:"#c2410c",title:"ئاگری کێڵگە، قەسەڵ و ڕووەکی وشک",subtitle:"ڕێگرتن لە ئاگر لە کاتی دروێنەدا و سەلامەتی کاتێک ئاگری کێڵگە نزیک دەبێتەوە",summary:"لە هاویندا، کێڵگەی گەنم و جۆی وشک، قەسەڵ (پاشماوەی دروێنە) و گیای وشک بە ئاسانی ئاگر دەگرن، و با دەتوانێت ئاگری کێڵگە زۆر بە خێرایی بڵاو بکاتەوە. ئەم ئاگرانە زۆرجار بە هۆی مرۆڤەوە هەڵدەگیرسێن: جگەرەیەک، پریشکێک یان دووکەڵکێشێکی گەرمی ئامێر، یان ئاگرێک کە بۆ سووتاندنی قەسەڵ کراوەتەوە. ئەم وانەیە ڕوونی دەکاتەوە چۆن ڕێگرییان لێ بکەین و چی بکەین کاتێک ئاگر لە کێڵگە، گوند یان ماڵەکەمان نزیک دەبێتەوە.",blocks:[{heading:"بۆچی ئاگری کێڵگە مەترسیدارە",body:`• دانەوێڵەی وشک، قەسەڵ و گیای وشک بە ئاسانی ئاگر دەگرن، بەتایبەتی لە ڕۆژانی گەرم، وشک و بادا.
• با ئاگر بەرەو پێش دەبات و پشکۆی ئاگر لە پێش گڕەکەوە دەگوازێتەوە، لەوێ دەتوانن ئاگری نوێ هەڵبگیرسێنن.
• ئاگر بەرەو سەرەوەی لێژایی و بەرەو ئەو لایەی با هەڵیدەکات لە هەمووی خێراتر بڵاو دەبێتەوە.
• دووکەڵ ڕێگا دەشارێتەوە، و ئاگرێکی خێرا دەتوانێت مرۆڤ، ئاژەڵ و ئۆتۆمبێل لە ناو کێڵگەدا گەمارۆ بدات.`},{heading:"ڕێگرتن لە کاتی دروێنەدا",body:`• پێش دروێنە و لە ماوەی دروێنەدا، هەموو ڕۆژێک کا، پووش و تۆز لە مەکینەی دروێنە (حاسیدە) و تراکتۆرەکان پاک بکەرەوە، بەتایبەتی لە دەوری بزوێنەر، دووکەڵکێش و توربۆ: ئەو تۆز و پووشەی دەگاتە ئەم پارچە گەرمانە دەتوانێت ئاگر بگرێت.
• ئامێرەکان بۆ ڕۆلمانی سواو، قایشی خلیسکاو و دزەی سووتەمەنی یان ڕۆن بپشکنە، و پێش دەستپێکردنی کار کەموکورتییەکان چاک بکەرەوە.
• ئاو و ئاگرکوژێنەرەوەیەکی گونجاو لەسەر مەکینەی دروێنە و لەگەڵ تیمەکەدا هەبێت.
• هێڵێکی ئاگربڕ (هێڵێکی خاکی ڕووت کە هیچ شتێکی سووتاوی تێدا نەبێت) لە دەوری کێڵگە و لە نێوان کێڵگەکان و گونددا بکێڵە یان پاک بکەرەوە.
• کاتێک هەوا زۆر گەرم، وشک و بادار بوو، کار بە ئامێرەکان ڕابگرە.
• ئۆتۆمبێل و تراکتۆر لەسەر گیای وشک یان قەسەڵ لێمەخوڕە و ڕامەگرە: دووکەڵکێشی گەرم دەتوانێت ئاگری تێبەربدات.`},{heading:"لە نزیک کێڵگە ئاگر مەکەرەوە",body:`• سووتاندنی قەسەڵ یان خاشاک لە شوێنی کراوەدا دەتوانێت لەگەڵ با بچێتە ناو کێڵگە، باخ و گوندەکانی دراوسێ. پێش ئەوەی هیچ شتێک بسووتێنیت، لە بەرگریی شارستانی و لایەنە ناوخۆییەکان بپرسە ئایا سووتاندن ڕێگەپێدراوە و کەی؛ هەرگیز لە ڕۆژێکی وشک یان بادا مەیسووتێنە، و هەرگیز ئاگر بە تەنها بەجێمەهێڵە.
• هەرگیز جگەرە لە ئۆتۆمبێلەوە فڕێ مەدە و مەیخە ناو کێڵگە و گیاوە، و لە کاتی کاری دروێنەدا جگەرە مەکێشە.
• لە نزیک دانەوێڵە یان گیای وشک ئاگری چێشتلێنان یان کەباب مەکەرەوە، و پێش ڕۆیشتن هەر ئاگرێک بە ئاو بە تەواوی بکوژێنەرەوە.
• بوتڵی شووشە و خاشاک بگەڕێنەوە ماڵ: شووشەی بەجێماو لە کێڵگەدا دەتوانێت تیشکی خۆر لەسەر گیای وشک کۆ بکاتەوە.`},{heading:"کاتێک ئاگر نزیک دەبێتەوە",body:`• زوو دەرچۆ. چاوەڕێ مەکە تا ئاگرەکە نزیک دەبێتەوە: دووکەڵ و گڕ دەتوانن ڕێگا بگرن. ئەگەر لایەنی پەیوەندیدار پێیان گوتیت دەرچۆ، یەکسەر بڕۆ.
• تەنها هەوڵ بدە ئاگرێکی زۆر بچووکی تازە دەستپێکردوو بە ئاو یان خۆڵ بکوژێنیتەوە، ئەگەر ڕێگای دەرچوونت لە پشتتەوە بێت و با ئاگرەکە بەرەو تۆ نەبات. ئەگەر یەکسەر نەکوژایەوە، دەرچۆ.
• لە ڕێگای ئاگرەکە دوور بکەوەوە: هەرگیز بەرەو ئەو لایەی با ئاگرەکەی بۆ دەبات مەڕۆ و هەرگیز بە لێژاییدا بۆ سەرووی ئاگرەکە سەرمەکەوە. شەقام و ڕێگاکان بەکاربهێنە، و بەرەو زەوییەک بڕۆ کە هیچ یان کەم شتی سووتاوی تێدایە، وەک زەوی کێڵراو.
• لە شوێنێکی سەلامەتەوە پەیوەندی بە ١١٥ بکە و شوێنی ورد بڵێ (گوند، شەقام، کێڵگە یان نیشانەیەکی دیار) و بڵێ ئایا ئاگرەکە بەرەو ماڵ یان خەڵک دەچێت.
• جووتیارانی تر و گوندەکە بە تەلەفۆن ئاگادار بکەرەوە، نەک بە ڕاکردن لە پێش ئاگرەکەوە.`},{heading:"پاراستنی گوند و ماڵەکان",body:`• دەوروبەری ماڵ، کادین و تەویلەی ئاژەڵ لانیکەم ٩ مەتر (٣٠ پێ) لە گیای وشک، پووش، داری سووتاندن و خاشاک پاک ڕابگرە.
• کۆگای کا و پووش لە ماڵ و شەقامەکان دوور ڕابگرە، و سووتەمەنی لە نزیکیان هەڵمەگرە.
• لە گوندەکەدا ڕێک بکەون کێ پەیوەندی بە ١١٥ دەکات، خەڵک لە کوێ کۆ دەبنەوە و بەساڵاچووان، منداڵان و ئاژەڵەکان چۆن دەگوازرێنەوە.
• شەقام و دەروازەکان بەتاڵ ڕابگرە بۆ ئەوەی ئۆتۆمبێلی ئاگرکوژێنەوە بگەنە گوند و کێڵگەکان.
• کاتێک ئاگر نزیکە، ڕێنماییەکانی بەرگریی شارستانی جێبەجێ بکە و مەگەڕێوە تا پێت نەڵێن سەلامەتە.`}],tips:["هەموو ڕۆژێکی دروێنە مەکینەی دروێنە و تراکتۆرەکان پاک بکەرەوە، بەتایبەتی لە دەوری بزوێنەر و دووکەڵکێش.","لەسەر هەموو مەکینەیەکی دروێنە ئاو و ئاگرکوژێنەرەوەیەک هەبێت.","چاودێری کەشوهەوا بکە: ڕۆژانی گەرم، وشک و بادار لە هەمووی مەترسیدارترن.","١١٥ لە تەلەفۆنەکەتدا پاشەکەوت بکە و بۆ هەر کێڵگەیەکت نیشانەیەکی دیار بزانە.","هەر کاتێک دووکەڵت بینی، یەکسەر جووتیارانی دەوروبەرت ئاگادار بکەرەوە."],warnings:["هەرگیز جگەرە فڕێ مەدە ناو گیای وشک یان قەسەڵ، و نە لە پەنجەرەی ئۆتۆمبێلەوە.","هەرگیز بە تەنها هەوڵ مەدە ئاگرێکی گەورەی کێڵگە بوەستێنیت: دەرچۆ و پەیوەندی بە ١١٥ بکە.","بۆ ڕزگاربوون لە ئاگر هەرگیز بە لێژاییدا سەرمەکەوە یان بەرەو ئەو لایەی با هەڵیدەکات ڕامەکە."],activity:{prompt:"لە نیوەڕۆیەکی گەرم و بادا بە مەکینەی دروێنە گەنم دەدروێنیت. لە پشت مەکینەکە لە ناو قەسەڵەکەدا دووکەڵ و گڕی بچووک دەبینیت، و با بەرەو کێڵگەی دراوسێیان دەبات. چی دەکەیت؟",options:[{text:"دەوەستم، مەکینەکە و خەڵک لە ڕێگای ئاگرەکە دوور دەخەمەوە، بە شوێنی وردەوە پەیوەندی بە ١١٥ دەکەم و جووتیارانی نزیک ئاگادار دەکەمەوە؛ ئاو یان ئاگرکوژێنەرەوە تەنها کاتێک بەکاردەهێنم کە ئاگرەکە هێشتا زۆر بچووکە و ڕێگای دەرچوونم کراوەیە.",correct:!0,feedback:"ئاگری کێڵگە لە بادا بە خێرایی گەورە دەبێت. دەرهێنانی خەڵک لە ڕێگای ئاگرەکە و پەیوەندیکردنی زوو بە ١١٥ یەکەم شتن؛ تەنها ئاگرێکی زۆر بچووک دەکرێت بکوژێنرێتەوە، و تەنها لەگەڵ ڕێگایەکی دەرچوونی سەلامەت."},{text:"مەکینەی دروێنەکە بە ناو گڕەکەدا لێدەخوڕم بۆ ئەوەی بگەمە ئەولای کێڵگەکە.",correct:!1,feedback:"لێخوڕین بە ناو ئاگردا دەتوانێت گیرت بخات و ئاگر بەربداتە مەکینەکە. لە ڕێگای ئاگرەکە دوور بکەوەوە و پەیوەندی بە ١١٥ بکە."},{text:"بەردەوام دەدروێنم، چونکە ئاگری قەسەڵەکە خۆی دەکوژێتەوە.",correct:!1,feedback:"با دەتوانێت ئاگرەکە بباتە ناو دانەوێڵە، باخ و گوندەکان. بوەستە، خەڵک لە ڕێگای دەربهێنە و یەکسەر پەیوەندی بە ١١٥ بکە."},{text:"لە پێش ئاگرەکەوە، بەرەو ئەو لایەی با هەڵیدەکات، ڕادەکەم بۆ ئەوەی کێڵگەی دراوسێ ئاگادار بکەمەوە.",correct:!1,feedback:"ڕاکردن بەرەو ئەو لایەی با ئاگرەکەی بۆ دەبات دەتخاتە ناو ڕێگاکەیەوە. خەڵکی تر بە تەلەفۆن ئاگادار بکەرەوە و لە ڕێگای ئاگرەکە دوور بکەوەوە."}]},quiz:[{question:"کام بەشی مەکینەی دروێنە لە هەمووی گرنگترە لە کا و تۆز پاک بێت؟",options:[{text:"کورسی شۆفێر، پەنجەرەکانی کابینە و ئاوێنەکان",correct:!1},{text:"ناوچەی بزوێنەر، لە دەوری دووکەڵکێشی گەرم و توربۆ",correct:!0},{text:"تایەکان و ئەو پەیژانەی بەرەو دەرگای کابینە دەچن",correct:!1},{text:"تانکی دانەوێڵە، دوای ئەوەی لە کۆتایی ڕۆژدا بەتاڵ دەکرێتەوە",correct:!1}],explanation:"کا و تۆز کە با دەیخاتە سەر دووکەڵکێشی گەرم یان توربۆ دەتوانێت ئاگر بگرێت. هەموو ڕۆژێکی دروێنە ناوچەی بزوێنەر پاک بکەرەوە، و لە ڕۆژە گەرمەکاندا زیاتر."},{question:"ئاگرێکی کێڵگە بە هێزی با بەرەو تۆ دێت. بەرەو کوێ ڕادەکەیت؟",options:[{text:"ڕاستەوخۆ بەرەو ئەو لایەی با هەڵیدەکات، بە خێراترین شێوە",correct:!1},{text:"بە نزیکترین گردەکەدا سەردەکەویت، بۆ ئەوەی ببینیت ئاگرەکە بەرەو کوێ دەچێت",correct:!1},{text:"دوور لە ڕێگای ئاگرەکە بە شەقامێکدا، نە بۆ سەرەوەی لێژایی و نە لەگەڵ با",correct:!0},{text:"بۆ ناو گەنمی ڕاوەستاو، کە دانەوێڵەی بەرز لە دووکەڵ دەتشارێتەوە",correct:!1}],explanation:"ئاگر لەگەڵ با و بە لێژاییدا بۆ سەرەوە لە هەمووی خێراتر دەڕوات. بە شەقام یان ڕێگاکاندا لە ڕێگای دوور بکەوەوە بەرەو زەوییەک کە شتی کەمی سووتاوی تێدایە، و پەیوەندی بە ١١٥ بکە."},{question:"کاتێک ئاگری کێڵگە ڕادەگەیەنیت، دەبێت چی بە ١١٥ بڵێیت؟",options:[{text:"تەنها ئەوەی لە شوێنێک دووکەڵ هەیە، پاشان بە خێرایی تەلەفۆنەکە دادەخەیت بۆ ئەوەی کات بەفیڕۆ نەچێت",correct:!1},{text:"شوێنی ورد (گوند، شەقام یان نیشانەیەکی دیار) و ئاگرەکە بەرەو کوێ دەچێت",correct:!0},{text:"ناوی خاوەنی کێڵگەکە، جۆری دانەوێڵەکە و نرخەکەی چەندە",correct:!1},{text:"هیچی تر نا، چونکە بەرگریی شارستانی لە دوورەوە هەموو ئاگرێکی کێڵگە دەبینێت",correct:!1}],explanation:"بەرگریی شارستانی پێویستی بەوەیە ئاگرەکە بە خێرایی بدۆزێتەوە: گوند، شەقام و نیشانەیەکی دیار بڵێ، بڵێ ئایا ماڵ یان خەڵک لە مەترسیدان، و تەلەفۆنەکە دامەخە تا پێت نەڵێن."},{question:"بۆچی سووتاندنی قەسەڵ مەترسیدارە؟",options:[{text:"قەسەڵ باش ناسووتێت، بۆیە ئاگرەکە هەمیشە خۆی یەکسەر دەکوژێتەوە",correct:!1},{text:"تەنها بە شەو مەترسیدارە، کاتێک خەڵک دووکەڵەکە نابینن",correct:!1},{text:"ئاگرەکە دەتوانێت لەگەڵ با بچێتە ناو کێڵگە و گوندە نزیکەکان",correct:!0},{text:"تەنها بۆ ئەو کەسە مەترسیدارە کە ئاگرەکە دەکاتەوە، نەک بۆ خەڵکی تر",correct:!1}],explanation:"ئەو ئاگرانەی بۆ کاری کشتوکاڵ دەکرێنەوە دەتوانن لە کۆنترۆڵ دەربچن، بەتایبەتی لە ڕۆژانی وشک و بادا. پێش هەر سووتاندنێک لە بەرگریی شارستانی و لایەنە ناوخۆییەکان بپرسە، و هەرگیز ئاگر بە تەنها بەجێمەهێڵە."},{question:"کام لەمانە دەتوانێت ئاگری کێڵگە هەڵبگیرسێنێت؟",options:[{text:"جگەرەیەک کە لە پەنجەرەی ئۆتۆمبێلەوە فڕێدراوەتە ناو گیای وشک",correct:!0},{text:"دارێکی سەوز کە لە سێبەردا لە لێواری کێڵگەکەدا ڕاوەستاوە",correct:!1},{text:"بارانێک کە دوای دروێنە بەسەر قەسەڵدا دەبارێت",correct:!1},{text:"تانکێکی ئاوی داخراو کە لە تەنیشت کێڵگەکە وەستاوە",correct:!1}],explanation:"جگەرە، پریشک و دووکەڵکێشی گەرمی ئۆتۆمبێل و ئامێرەکان، و ئەو ئاگرانەی لە شوێنی کراوەدا دەکرێنەوە، زۆرێک لە ئاگرەکانی کێڵگە هەڵدەگیرسێنن. هەرگیز جگەرە فڕێ مەدە، و لەسەر گیای وشک ڕامەگرە."}],media:[{kind:"image",src:"media/images/w7_crop_fire_prevention.webp",title:"ڕێگرتن لە ئاگر لە کێڵگەیەکی گەنمدا",description:"جووتیارێک ناوچەی بزوێنەری مەکینەیەکی دروێنە لە تەنیشت هێڵێکی ئاگربڕی کێڵراو پاک دەکاتەوە، و تانکێکی ئاو و ئاگرکوژێنەرەوەیەک لە لێواری کێڵگەیەکی گەنمی وشکدا ئامادەن."}]},{id:20,icon:"Bomb",accent:"#b45309",title:"مین و تەقەمەنیی نەتەقیو: سەلامەت بمێنەرەوە",subtitle:"مەترسییەکە بناسە، دوور بکەوەرەوە، ڕایبگەیەنە",summary:"مین، بۆمبە هێشووییەکان و تەقەمەنیی نەتەقیوی تر دەتوانن دەیان ساڵ مەترسیدار بمێننەوە، تەنانەت ئەگەر کۆن، ژەنگاوی یان بێزیان دیار بن. هەموو کەسێک دەتوانێت بە چەند ڕێسایەک سەلامەت بمێنێتەوە: دەستی لێ مەدە، دوور بکەوەرەوە، خەڵکی تر دوور بخەرەوە و ڕایبگەیەنە.",blocks:[{heading:"چ شتێک دەتوانێت مەترسیدار بێت",body:"تەقەمەنی بە زۆر قەبارە، شێوە و ڕەنگی جیاواز هەیە. دەکرێت لەسەر زەوی بێت، لە ناو خاکدا شاردرابێتەوە، لە ناو گژوگیا، کاولگە یان بینا کۆنەکاندا بێت، یان بە دارەکانەوە هەڵواسرابێت. ئەمانە وەک مەترسیدار سەیر بکە:",points:["مین: زۆربەی جار لە ناو خاکدا شاردراوەتەوە و زۆر بە زەحمەت دەبینرێت.","بۆمبە بچووکەکانی بۆمبی هێشوویی: هەندێکیان ڕەنگاوڕەنگن و وەک یاری دەردەکەون.","گوللە تۆپ، مووشەک، هاوەن و نارنجۆکی نەتەقیو.","هەر شتێکی ئاسنی یان پلاستیکی بە شێوەیەکی نەناسراو لە شوێنێک کە شەڕی تێدا کراوە.","شتی کۆن، ژەنگاوی یان شکاو: هێشتا دەتوانن بتەقنەوە."]},{heading:"ئەگەر شتێکی گومانلێکراوت بینی",points:["بوەستە و لێی نزیک مەبەرەوە.","دەستی لێ مەدە، مەیجووڵێنە، پێی لێ مەدە و هەڵیمەگرە؛ هیچ شتێکی بەرەو مەهاوێ و هەرگیز هەوڵی سووتاندنی مەدە.","خەڵکی دەوروبەر ئاگادار بکەرەوە و هەمووان لێی دوور بخەرەوە، بەتایبەتی منداڵان.","شوێنەکەی و نیشانە نزیکەکان لە بیر مەکە.","پێش ئەوەی مۆبایل بەکاربهێنیت باش دوور بکەوەرەوە، پاشان پەیوەندی بە ١١٥ بکە و ڕێنماییەکانی بەرگریی شارستانی جێبەجێ بکە.","هەرگیز شتەکە مەبە بۆ ماڵەوە، بنکەی پۆلیس یان بنکەی بەرگریی شارستانی."]},{heading:"نیشانەکانی ئاگاداری و شوێنە پەرژینکراوەکان",body:"نیشانەکانی ئاگاداری لە مەترسیی تەقەمەنی زۆربەی جار سوور یان پرتەقاڵین، زۆر جار وێنەی کاسەی سەر و وشەی «مەترسی» یان «مین»یان لەسەرە. ناوچەیەکی مەترسیدار دەکرێت بە بەردی سوورڕەنگکراو، پەرژین، تەل، پەت یان شریتیش نیشانە بکرێت. لەوانەیە نیشانەکانی ناوچەکەی تۆ جیاواز بن.",points:["ڕێز لە هەموو نیشانە و پەرژینێک بگرە و هەرگیز لێیان مەپەڕەرەوە.","هەرگیز نیشانەیەک لامەبە، مەیجووڵێنە و مەیبە، تەنانەت ئەگەر کۆن یان شکاو بێت.","نەبوونی نیشانە بە مانای سەلامەتی نییە: زۆربەی ناوچە مەترسیدارەکان نیشانە نەکراون.","لە نزیک کێڵگەی پڕ لە گژوگیا، ڕێگای بەکارنەهاتوو، کاولگە و شوێنە سەربازییە بەجێهێڵراوەکان وریا بە؛ ڕێگا سەرەکییەکان و ئەو ڕێگایانەی خەڵک زۆر پێیاندا دەڕۆن بەکاربهێنە."]},{heading:"ئەگەر پێت وابێت لە ناوچەیەکی میندایت",body:`مینێک، نیشانەیەکی ئاگاداری یان شتێکی نەناسراوت لە نزیک پێیەکانت بینی، یان تەقینەوەیەک ڕوویدا:
١. یەکسەر بوەستە. بێجووڵە بمێنەوە و پێیەکانت مەجووڵێنە.
٢. داوای یارمەتی بکە و خەڵکی تر ئاگادار بکەرەوە کە نەیەنە لات.
٣. چاوەڕێی تیمێکی ڕاهێنراو بکە، تەنانەت ئەگەر کاتێکی زۆری پێ بچێت.

هەرگیز هەوڵ مەدە بە سەر شوێنپێی خۆتدا بگەڕێیتەوە، بە دار زەوی تاقی بکەیتەوە یان نیشانە دابنێیت: ئەمانە ڕێگای سەلامەت نین بۆ دەرچوون. ئەگەر کەسێک بریندار بوو، بەرەو لای ڕامەکە: داوای یارمەتی بکە و چاوەڕێی ڕزگارکەری ڕاهێنراو بکە.`},{heading:"ئامۆژگاری بۆ ئەو کەسانەی زیاتر لە مەترسیدان",points:["جووتیاران: ئەگەر لە کاتی کێڵان یان هەڵکەندندا شتێکی نەناسراوتان بینی، کارەکە ڕابگرن، هەمووان دوور بخەنەوە و ڕایبگەیەنن؛ ئەو زەوییە مەچێنن کە نیشانە کراوە یان خەڵک خۆیانی لێ دوور دەگرن.","شوانەکان: مەڕوماڵات مەبەنە ناو شوێنی نیشانەکراو یان گومانلێکراو، و هەرگیز بەدوای ئاژەڵێکدا مەچن کە چووەتە ناوی.","بیناسازان و بیرلێدەران: ئەگەر لە کاتی هەڵکەندندا شتێکی نەناسراو دەرکەوت، یەکسەر بوەستن، هەمووان دوور بخەنەوە و ڕایبگەیەنن.","ئەو خێزانانەی دوای شەڕ دەگەڕێنەوە: پێش بەکارهێنانی خانوو، کێڵگە یان ڕێگا، لە لایەنی پەیوەندیدار بپرسن کە ئایا پشکنینی بۆ کراوە یان نا.","کۆکەرەوانی ئاسنی کۆن (سکراپ): هەرگیز ئاسنی کۆنی سەربازی کۆ مەکەنەوە، مەیبڕن، مەیکەنەوە و مەیفرۆشن؛ دەتوانێت بتەقێتەوە و ژیانی خۆتان، کڕیار و دراوسێکان بخاتە مەترسییەوە."]},{heading:"قسەکردن لەگەڵ منداڵان",body:"منداڵان کونجکاون و هەندێک شت وەک یاری دەردەکەون. بە ئارامی و زۆر جار قسەیان لەگەڵ بکە، بێ ئەوەی بیانترسێنیت، و کاتێک باسی شتێکت بۆ دەکەن کە بینیویانە دەستخۆشییان لێ بکە. فێریان بکە:",points:["شتێک کە لە تۆ نەکەوتووە، هەڵیمەگرە.","هەرگیز دەست لە شتی نەناسراو مەدە، پێی لێ مەدە و بەردی تێ مەگرە، و لێی نزیک مەبەرەوە.","لە نیشانە، پەرژین، کاولگە و شوێنە سەربازییە کۆنەکان دوور بە.","یەکسەر بە گەورەیەک بڵێ.","ئەگەر پێت وابوو لە شوێنێکی مەترسیداردایت: بوەستە، بێجووڵە بمێنەوە، هاوار بکە بۆ یارمەتی و چاوەڕێ بکە."]}],tips:["ژمارەی ١١٥ لە مۆبایلەکەتدا تۆمار بکە و فێری خێزانەکەتی بکە.","بزانە کام شوێنی نزیک ماڵ، کێڵگە و لەوەڕگاکەت مەترسیدارن؛ ئەگەر دڵنیا نەبوویت، لە لایەنی پەیوەندیدار بپرسە.","کاتێک ڕایدەگەیەنیت، شوێنەکە، نیشانە نزیکەکان و ئەوەی کە ئایا خەڵک لە نزیک شتەکەن یان نا بڵێ.","بڕوا بەو دەنگۆیانە مەکە کە دەڵێن ناوچەیەک پاک کراوەتەوە؛ لە لایەنی پەیوەندیدار بپرسە.","ڕێگا سەرەکییەکان و ئەو ڕێگایانەی خەڵک زۆر پێیاندا دەڕۆن بەکاربهێنە، بەتایبەتی لەو ناوچانەی شەڕیان تێدا کراوە."],warnings:["هەرگیز دەست لە تەقەمەنی یان ئاسنی کۆنی سەربازی مەدە، مەیجووڵێنە، کۆی مەکەرەوە و مەیفرۆشە، تەنانەت ئەگەر کۆن، ژەنگاوی یان بەکارهاتوو دیار بێت.","لە ناوچەی میندا هەرگیز بە سەر شوێنپێی خۆتدا مەگەڕێرەوە، زەوی تاقی مەکەرەوە و نیشانە دامەنێ: بوەستە، بێجووڵە بمێنەوە، داوای یارمەتی بکە و چاوەڕێ بکە.","لە ناوچەی میندا بەرەو لای کەسێکی بریندار ڕامەکە: داوای یارمەتی بکە و چاوەڕێی ڕزگارکەری ڕاهێنراو بکە."],media:[{kind:"image",src:"media/images/w7_uxo_keep_away.webp",title:"دوور بکەوەرەوە و ڕایبگەیەنە",description:"جووتیارێک خێزانەکەی لە شتێکی گومانلێکراو لە کێڵگەکەدا باش دوور دەخاتەوە پێش ئەوەی پەیوەندی بە ١١٥ بکات."}],activity:{prompt:"لە کاتی کێڵانی کێڵگەیەکدا، جووتیارێک شتێکی ئاسنی ژەنگاوی لە ناو خاکدا دەبینێت. کوڕەکەی دەیەوێت هەڵیبگرێت و وەک ئاسنی کۆن بیفرۆشێت. پێویستە چی بکەن؟",options:[{text:"کارەکە ڕادەگرن، هەمووان دوور دەخەنەوە، شوێنەکە لە بیر ناکەن و کاتێک باش دوور کەوتنەوە پەیوەندی بە ١١٥ دەکەن",correct:!0,feedback:"تەقەمەنیی کۆن یان ژەنگاوی هێشتا دەتوانێت بتەقێتەوە. ڕاگرتنی کار، دوورخستنەوەی هەمووان و ڕاگەیاندن لە شوێنێکی سەلامەتەوە خێزانەکە دەپارێزێت و ڕێگە دەدات تیمە ڕاهێنراوەکان مامەڵەی لەگەڵ بکەن."},{text:"بە هێواشی هەڵیدەگرن، دەیخەنە سەر تراکتۆرەکە و دەیبەن بۆ بنکەی بەرگریی شارستانی",correct:!1,feedback:"جووڵاندن یان هەڵگرتنی دەتوانێت ببێتە هۆی تەقینەوە، لە ڕێگادا یان لە بنکەکەدا. لە شوێنی خۆی جێی بهێڵە و لە شوێنێکی سەلامەتەوە ڕایبگەیەنە."},{text:"دەوروبەری دەکێڵن و بەردەوام دەبن، چونکە کۆن و ژەنگاوییە",correct:!1,feedback:"کۆنی و ژەنگ تەقەمەنی سەلامەت ناکەن و کێڵان لە نزیکییەوە دەتوانێت بیتەقێنێتەوە. کارەکە ڕابگرە، دوور بکەوەرەوە و ڕایبگەیەنە."},{text:"بە خۆڵ دایدەپۆشن و بەردێک لە تەنیشتی دادەنێن وەک نیشانە",correct:!1,feedback:"داپۆشین یان نیشانەکردن واتە مانەوە لە تەنیشت مەترسییەکە. دوور بکەوەرەوە، شوێنەکە لە بیر مەکە و بە ١١٥ ڕایبگەیەنە."}]},quiz:[{question:"لە نزیک کێڵگەیەکی پڕ لە گژوگیا کە شەڕی تێدا کراوە، هیچ نیشانەیەکی ئاگاداری نییە. ئایا چوونە ناوی سەلامەتە؟",options:[{text:"نەخێر: زۆربەی ناوچە مەترسیدارەکان نیشانە نەکراون؛ لەسەر ڕێگا بەکارهاتووەکان بمێنەوە و لە لایەنی پەیوەندیدار بپرسە",correct:!0},{text:"بەڵێ: هەموو ناوچە مەترسیدارەکانی هەرێمەکە نیشانەی سووری ئاشکرایان هەیە، بۆیە کێڵگەی بێ نیشانە بە تەواوی سەلامەتە",correct:!1},{text:"بەڵێ، دوای سووتاندنی گژوگیاکە، چونکە ئاگرەکە هەموو مینە شاردراوەکانی ناو خاک لەناو دەبات",correct:!1},{text:"بەڵێ، ئەگەر بەتەمەنەکانی گوندەکە بڵێن کێڵگەکە چەندین ساڵ لەمەوبەر لە مین پاک کراوەتەوە",correct:!1}],explanation:"نەبوونی نیشانە بە مانای سەلامەتی نییە: زۆربەی ناوچە مەترسیدارەکان نیشانە نەکراون. سووتاندن ناوچەیەک سەلامەت ناکات و دەنگۆ پشکنین نییە. ڕێگا سەرەکی و بەکارهاتووەکان بەکاربهێنە و لە لایەنی پەیوەندیدار بپرسە."},{question:"تێدەگەیت کە لەوانەیە چووبیتە ناو ناوچەیەکی مینەوە. کاری دروست چییە؟",options:[{text:"بوەستە، پێیەکانت مەجووڵێنە، داوای یارمەتی بکە و چاوەڕێی تیمێکی ڕاهێنراو بکە",correct:!0},{text:"بە هێواشی و وریاییەوە بە سەر شوێنپێی خۆتدا بگەڕێرەوە بۆ ئەو ڕێگایەی لێیەوە هاتوویت",correct:!1},{text:"دارێک بخەرە ناو زەوی لە بەردەمتدا بۆ دۆزینەوەی ڕێگایەکی سەلامەت بۆ دەرچوون",correct:!1},{text:"بە خێرایی تا دەتوانیت ڕابکە بۆ نزیکترین ڕێگا تا کاتی کەمتر لەوێ بمێنیتەوە",correct:!1}],explanation:"وەستان و چاوەڕێکردن ڕێگری دەکات لەوەی پێ بخەیتە سەر مینێکی تر. شوێنپێ بە زەحمەت دەبینرێت و گەڕانەوە بە سەریدا سەلامەت نییە، تاقیکردنەوەی زەوی کاری پسپۆڕانە، و ناتوانیت لە تەقینەوە ڕابکەیت."},{question:"دراوسێکەت گوللە تۆپی کۆن کۆ دەکاتەوە و دەیانفرۆشێت بە بازرگانی ئاسنی کۆن. سەلامەتترین ئامۆژگاری چییە؟",options:[{text:"یەکسەر کۆکردنەوە ڕابگرێت، خۆی شتەکان نەجووڵێنێت و بە ١١٥ ڕایانبگەیەنێت",correct:!0},{text:"بەردەوام بێت لە کۆکردنەوە، بەڵام تەنها ئەوانە هەڵبگرێت کە بەتاڵ، کۆن یان ژەنگاوی دیارن و ئەوانی تر جێبهێڵێت",correct:!1},{text:"پێش فرۆشتن بیانکاتەوە تا هەر شتێکی مەترسیداریان لێ دەربهێنێت، پاشان ئاسنەکە بفرۆشێت",correct:!1},{text:"لە ژوورێکی فێنک و داخراو لە ماڵەوە دایانبنێت تا بازرگانەکە دێت و دەیانبات",correct:!1}],explanation:"ئاسنی کۆنی سەربازی دەتوانێت هەر کاتێک بتەقێتەوە، تەنانەت ئەگەر بەتاڵ یان ژەنگاوی دیار بێت، و کۆکەرەوە، کڕیار و دراوسێکان دەخاتە مەترسییەوە. مەیجووڵێنە: ڕایبگەیەنە تا تیمە ڕاهێنراوەکان مامەڵەی لەگەڵ بکەن."},{question:"منداڵان لە نزیک قوتابخانە شتێکی نەناسراو و ڕەنگاوڕەنگ دەبینن. گەورەکان پێویستە فێری چییان بکەن؟",options:[{text:"دەستی لێ مەدەن و لێی نزیک مەبنەوە، هاوڕێکانتان دوور بخەنەوە و یەکسەر بە گەورەیەک بڵێن",correct:!0},{text:"بە هێواشی و وریاییەوە هەڵیبگرن و بیبەن بۆ مامۆستا تا مامۆستاکە بیپشکنێت کە ئەوە چ شتێکە",correct:!1},{text:"لە دوورەوە بەردی بچووکی تێ بگرن تا بزانن ئایا مەترسیدارە",correct:!1},{text:"لە نزیکەوە وێنەیەکی ڕوونی بگرن و بە مۆبایل بۆ گرووپی خێزانەکەی بنێرن",correct:!1}],explanation:"هەندێک تەقەمەنی وەک یاری دەردەکەون. دەستلێدان، هەڵگرتن، تێگرتنی شت یان نزیکبوونەوە بۆ وێنەگرتن دەتوانێت ببێتە هۆی تەقینەوە؛ دوورکەوتنەوە و وتن بە گەورەیەک هەمووان سەلامەت دەهێڵێتەوە."},{question:"کاتێک دەربارەی شتێکی گومانلێکراو پەیوەندی بە ١١٥ دەکەیت، پێویستە لە کوێ بیت؟",options:[{text:"لە شوێنێکی سەلامەت و دوور، دوای ئاگادارکردنەوەی خەڵک",correct:!0},{text:"ڕێک لە تەنیشتی، تا بتوانیت شێوە، قەبارە و ڕەنگەکەی بە وردی باس بکەیت",correct:!1},{text:"لە نزیکییەوە لەگەڵ کامێرای مۆبایلەکەت، تا وێنەیەکی ڕوون بنێریت",correct:!1},{text:"بە دەستتەوە بیگریت، تا بتوانیت ئەو نووسین و ژمارانەی لەسەر لاکەیەتی بخوێنیتەوە",correct:!1}],explanation:"هەرگیز بۆ سەیرکردن یان وێنەگرتن لێی نزیک مەبەرەوە. نابێت مۆبایل و بێتەل لە نزیک تەقەمەنی بەکاربهێنرێن، بۆیە باش دوور بکەوەرەوە، پاشان شوێنەکە و نیشانە نزیکەکان ڕابگەیەنە."}]},{id:21,icon:"CloudFog",accent:"#6d28d9",title:"بڵاوبوونەوەی ماددەیەکی مەترسیدار لە نزیکت: لە ژوورەوە بمێنەوە یان شوێنەکە چۆڵ بکە",subtitle:"بچۆ ژوورەوە، لە ژوورەوە بمێنەوە، گوێ لە ڕاگەیاندنەکان بگرە",summary:"ئاگرێک، ڕووداوێکی کارگە یان تانکەرێکی زیانلێکەوتوو دەتوانێت گاز، دووکەڵ یان تۆزی ژەهراوی بڵاو بکاتەوە. زۆر جار سەلامەتترین شوێن ناو بینایەکە. ئەم وانەیە ڕوونی دەکاتەوە چۆن لە ناو بینادا پەنا بگریت، کەی شوێنەکە چۆڵ بکەیت و چی بکەیت ئەگەر ماددەیەک بەر لەشت کەوت.",blocks:[{heading:"بچۆ ژوورەوە، لە ژوورەوە بمێنەوە، گوێ لە ڕاگەیاندنەکان بگرە",body:"ئەگەر لایەنی پەیوەندیدار بڵاوبوونەوەی ماددەیەکی مەترسیداری ڕاگەیاند، یان هەورێکی نەناسراو یان دووکەڵت بینی، بۆنێکی کیمیایی بەهێزت کرد یان گوێت لە دەنگی ئاگادارکردنەوە (سەفارە) بوو لە نزیکت:",points:["بچۆ ژوورەوە: یەکسەر بچۆ ناو نزیکترین بینای بەهێز و منداڵان و ئاژەڵە ماڵییەکانیش بهێنە ژوورەوە.","لە ژوورەوە بمێنەوە: لە ژوورەوە بمێنەوە تا لایەنی پەیوەندیدار دەڵێت دەرچوون سەلامەتە، تەنانەت بۆ یارمەتیدانی خەڵکی تریش.","گوێ لە ڕاگەیاندنەکان بگرە: ڕاگەیاندنە فەرمییەکان لە ڕادیۆ، تەلەفزیۆن یان مۆبایل بەدوادا بچۆ و ئەوە بکە کە دەیڵێن.","هەندێک گازی مەترسیدار بۆنیان نییە: ڕێنماییەکان جێبەجێ بکە تەنانەت ئەگەر هیچ شتێکیش هەست پێ نەکەیت."]},{heading:"چۆن لە ناو بینادا پەنا بگریت",points:["هەموو دەرگا و پەنجەرە دەرەکییەکان دابخە و قفڵیان بکە.","ئامێرەکانی فێنککەرەوە (سپلیت و کوولەر)، پانکە و هەواگۆڕین بکوژێنەرەوە و کونەکانی هەوا دابخە.","بچۆ ژوورێکی ناوەوەی کەم پەنجەرە، ئەگەر بتوانیت لەسەر ئاستی زەوی یان بەرزتر (نەک لە ژێرزەمین)، و دەرگا ناوەکییەکان دابخە.","ئەگەر هەتبوو، کەلێنەکانی دەوروبەری دەرگا، پەنجەرە و کونەکانی هەوا بە شریتی لکێنەر و نایلۆن دابخە.","هیچ خواردن یان خواردنەوەیەک مەخۆ کە لەوانەیە ماددەکە گەیشتبێتێ.","لە ئۆتۆمبێلدا: پەنجەرە و کونەکانی هەوا دابخە، فێنککەرەوە و گەرمکەرەوە بکوژێنەرەوە و بچۆ ناو نزیکترین بینا."]},{heading:"کەی شوێنەکە چۆڵ بکەیت",body:"کاتێک لایەنی پەیوەندیدار پێت دەڵێت دەربچۆ، یان کاتێک ماددەکە گەیشتووەتە ناو بیناکەت و دەتوانیت دەربچیت بێ ئەوەی بە ناویدا تێپەڕیت، شوێنەکە چۆڵ بکە.",points:["ئەگەر پێت وترا شوێنەکە چۆڵ بکە، یەکسەر دەربچۆ و ئەو ڕێنماییانەی پێت دەدرێن جێبەجێ بکە.","بڕۆ بۆ ئەو لایەی کە باکە لێیەوە دێت (upwind) و ئەگەر بتوانیت بەرەو شوێنی بەرز: هەندێک گاز لە هەوا قورسترن و لە شوێنە نزمەکاندا کۆ دەبنەوە.","هەرگیز بە ناو هەور، دووکەڵ یان ماددە ڕژاوەکەدا تێمەپەڕە.","ئەگەر ناتوانیت بگەیتە هەوای پاک بێ ئەوەی بە ناویدا تێپەڕیت، تا دەتوانیت لێی دوور بمێنەوە و لە ناو بینادا پەنا بگرە."]},{heading:"ئەگەر ماددەیەک بەر لەشت کەوت: سێ هەنگاوی لابردن (Remove, Remove, Remove)",body:`١. خۆت دوور بخەرەوە: لە ماددەکە دوور بکەوەرەوە و بچۆ بۆ هەوای پاک.
٢. جلە دەرەکییەکان دابکەنە: ئەو جلانەی ماددەکە بەریان کەوتووە دابکەنە؛ هەوڵ بدە بە سەرتدا دایان نەکەنیت، ئەو جلانەی بە پێستەوە نووساون مەیانکێشە، و بیانخەرە ناو کیسەیەکی نایلۆنی داخراو.
٣. ماددەکە لە پێست لابە: بە دەسماڵی کاغەز یان پەڕۆیەکی وشک ماددەکە لەسەر پێست هەڵبمژە یان بیماڵە؛ ئەگەر پێست خوری یان سووتا، بە ئاوێکی زۆر بیشۆ. ئەگەر چووە ناو چاوەکانت، بە ئاوی پاک بیانشۆ.

هیچ شتێک مەخۆ، مەخۆرەوە، جگەرە مەکێشە و دەست لە دەموچاوت مەدە. بە تیمەکانی فریاکەوتن بڵێ کە ماددەکە بەرت کەوتووە و ڕێنماییەکانیان بۆ پشکنینی پزیشکی جێبەجێ بکە. ئەگەر کەسێک بە زەحمەت هەناسەی دا یان بە سەختی بریندار بوو، پەیوەندی بە ١١٥ و ١٢٢ بکە.`},{heading:"هەرگیز بۆ سەیرکردن مەچۆ",points:["بەرەو شوێنی ڕووداوەکە مەچۆ بۆ سەیرکردن، ڤیدیۆ یان وێنەگرتن: ماددەکە دەتوانێت بێ ئاگادارکردنەوە بگاتە لات.","تا لایەنی پەیوەندیدار نەڵێت سەلامەتە، بۆ یارمەتیدانی خەڵکی تر مەچۆ دەرەوە؛ لە جیاتی ئەوە پەیوەندی بە ١١٥ و ١٢٢ بکە.","بڵاوبوونەوەیەک، هەورێکی نەناسراو یان ڕژانی ماددەیەک لە شوێنێکی سەلامەتەوە بە ١١٥ ڕابگەیەنە.","تەنها ڕاگەیاندنە فەرمییەکان بڵاو بکەرەوە؛ دەنگۆ ترس و ئامۆژگاریی هەڵە بڵاو دەکاتەوە."]}],tips:["ئێستا ژووری پەناگرتنەکەت هەڵبژێرە: ژوورێکی ناوەوەی کەم پەنجەرە، لەسەر ئاستی زەوی یان بەرزتر.","شریتی لکێنەر، مقەست، نایلۆن و ڕادیۆیەکی پاتریدار لە جانتای تەنگانەدا دابنێ.","فێر ببە چۆن ئامێری فێنککەرەوە، کوولەر و هەواگۆڕین بە خێرایی بکوژێنیتەوە.","لەگەڵ خێزانەکەت ڕێک بکەون لە کوێ پەنا دەگرن و چۆن پەیوەندی بە یەکترەوە دەکەن.","تەلەفۆن بۆ ئەو دراوسێیانە بکە کە لەوانەیە ڕاگەیاندنەکەیان نەبیستبێت؛ بۆ پێوتنیان مەچۆ دەرەوە."],warnings:["هەرگیز بەرەو هەور، دووکەڵ یان ماددەی ڕژاو مەچۆ بۆ سەیرکردن یان وێنەگرتن!","تا لایەنی پەیوەندیدار نەڵێت سەلامەتە، شوێنی پەناگرتنەکەت جێمەهێڵە، تەنانەت بۆ یارمەتیدانی خەڵکی تریش.","کاتێک شوێنەکە چۆڵ دەکەیت، هەرگیز بە پێ یان بە ئۆتۆمبێل بە ناو هەور یان ماددە ڕژاوەکەدا تێمەپەڕە."],media:[{kind:"image",src:"media/images/w7_shelter_in_place.webp",title:"پەناگرتن لە ناو بینادا",description:"خێزانێک لە ژوورێکی ناوەوەدا پەنا دەگرێت، دەرگا و پەنجەرەکان داخراون و گوێ لە ڕاگەیاندنە فەرمییەکان دەگرن."}],activity:{prompt:"ئاگرێک لە کۆگایەکی نزیک دووکەڵێکی چڕ و بۆنێکی نامۆ بەرەو گەڕەکەکەت دەنێرێت، و ڕاگەیاندنێکی فەرمی بە خەڵک دەڵێت لە ژوورەوە بمێننەوە. منداڵەکانت لە حەوشە یاری دەکەن. چی دەکەیت؟",options:[{text:"منداڵەکان دەهێنمە ژوورەوە، دەرگا و پەنجەرەکان دادەخەم، کوولەر و هەواگۆڕین دەکوژێنمەوە، دەچینە ژوورێکی ناوەوە و ڕاگەیاندنەکان بەدوادا دەچم",correct:!0,feedback:"ئەمە پەناگرتنە لە ناو بینادا: لە ژوورەوە، کاتێک هەوای دەرەوە ناهێڵدرێت بێتە ژوورەوە، خێزانەکە دووکەڵێکی زۆر کەمتر هەڵدەمژێت، و ڕاگەیاندنەکان دەڵێن کەی سەلامەتە یان ئەگەر پێویستە دەربچیت."},{text:"خێزانەکە بە ئۆتۆمبێل دەبەم بەرەو ڕێگای کۆگاکە تا ببینم ئاگرەکە چەند گەورەیە و پاشان بڕیار بدەم",correct:!1,feedback:"چوون بەرەو شوێنی ڕووداوەکە دەتباتە ناو دووکەڵەکە. لە ژوورەوە بمێنەوە و ڕاگەیاندنە فەرمییەکان بەدوادا بچۆ."},{text:"هەموو پەنجەرەکان دەکەمەوە و پانکەکان هەڵدەکەم تا دووکەڵەکە بە خێرایی بە ماڵەکەدا تێپەڕێت",correct:!1,feedback:"پەنجەرەی کراوە و پانکە دووکەڵ دەهێننە ژوورەوە. هەموویان دابخە و پانکە، کوولەر و هەواگۆڕین بکوژێنەرەوە."},{text:"لەگەڵ منداڵەکان بە پێ بە ناو دووکەڵەکەدا دەچین بۆ ماڵی خزمێک لە گەڕەکێکی تر",correct:!1,feedback:"بە پێ ڕۆیشتن بە ناو دووکەڵدا هەموو خێزانەکە دەخاتە بەر ماددەکە. تەنها کاتێک پێت دەوترێت شوێنەکە چۆڵ بکە، و هەرگیز بە ناو هەوردا."}]},quiz:[{question:"مانای «بچۆ ژوورەوە، لە ژوورەوە بمێنەوە، گوێ لە ڕاگەیاندنەکان بگرە» چییە؟",options:[{text:"بچۆ ژوورەوە، لەوێ بمێنەوە تا لایەنی پەیوەندیدار دەڵێت سەلامەتە و ڕاگەیاندنەکان بەدوادا بچۆ",correct:!0},{text:"بچۆ ناو ناوچەی ڕووداوەکە، لەوێ بمێنەوە بۆ یارمەتیدانی بریندارەکان و بەردەوام تەلەفۆن بۆ خزمەکانت بکە بۆ هەواڵ",correct:!1},{text:"سەرکەوە سەر بان، لەوێ بمێنەوە تا هەورەکە ببینیت و هەموو پانکەکان هەڵبکە تا هەوا پاک بێتەوە",correct:!1},{text:"بچۆ ناو ئۆتۆمبێلەکەت، تێیدا بمێنەوە لە کاتێکدا بزوێنەر و فێنککەرەوە کار دەکەن و گوێ لە مۆسیقا بگرە",correct:!1}],explanation:"لە ژوورەوە زۆر کەمتر لە ماددەکە هەڵدەمژیت. لە ژوورەوە بمێنەوە تا لایەنی پەیوەندیدار دەڵێت سەلامەتە، و ڕاگەیاندنە فەرمییەکان لە ڕادیۆ، تەلەفزیۆن یان مۆبایل بەدوادا بچۆ."},{question:"کاتێک لە ماڵەوە پەنا دەگریت، دەبێت چی لە ئامێری فێنککەرەوە یان کوولەر بکەیت؟",options:[{text:"بیکوژێنەرەوە، لەگەڵ پانکە و هەواگۆڕین، و کونەکانی هەوا دابخە",correct:!0},{text:"بە بەرزترین خێرایی کاری پێ بکە تا گازەکە لە ڕێگەی پەنجەرە و دەرگاکانەوە لە ماڵەکە دەربکات",correct:!1},{text:"با کار بکات، چونکە فلتەرەکەی ماددە کیمیاییەکان لە هەوای ناوەوە پاک دەکاتەوە",correct:!1},{text:"تەنها لەو ژوورەدا هەڵیبکە کە خێزانەکە پێکەوە تێیدا پەنایان گرتووە",correct:!1}],explanation:"ئامێری فێنککەرەوە، کوولەر، پانکە و هەواگۆڕین دەتوانن هەوای دەرەوە و ماددەکە لەگەڵیدا ڕابکێشنە ناو ماڵ. بیانکوژێنەرەوە و کونەکانی هەوا دابخە."},{question:"لە کاتی بڵاوبوونەوەی ماددەیەکی مەترسیداردا، کەی دەبێت شوێنەکە چۆڵ بکەیت؟",options:[{text:"کاتێک پێت دەوترێت، یان کاتێک ماددەکە گەیشتووەتە ناو بیناکەت و دەتوانیت بە سەلامەتی دەربچیت",correct:!0},{text:"هەر کە زانیت ماددەکە بڵاو بووەتەوە، تەنانەت ئەگەر تاکە ڕێگای دەرچوون لە ناوچەکە بە ناو هەورەکەدا بێت",correct:!1},{text:"تەنها دوای ئەوەی دەچیتە دەرەوە تا بە چاوی خۆت ببینیت هەورەکە بەرەو کام لا دەڕوات",correct:!1},{text:"هەر کاتێک دراوسێکانت ڕۆیشتن، گرنگ نییە ڕاگەیاندنە فەرمییەکان چی دەڵێن",correct:!1}],explanation:"زۆر جار مانەوە لە ژوورەوە لە دەرچوون سەلامەتترە. کاتێک پێت دەوترێت دەربچۆ، یان کاتێک ماددەکە لە ژوورەوە گەیشتووەتە لات و دەتوانیت دەربچیت بێ ئەوەی بە ناویدا تێپەڕیت."},{question:"ئەگەر پێویست بوو شوێنەکە چۆڵ بکەیت، کام لا سەلامەتترە؟",options:[{text:"بەرەو ئەو لایەی با لێیەوە دێت و ئەگەر بتوانیت بۆ شوێنی بەرز، بێ تێپەڕین بە ناو هەورەکەدا",correct:!0},{text:"لەگەڵ ئاراستەی با، تا با یارمەتی تۆ و خێزانەکەت بدات بە خێرایی لە هەورەکە دوور بکەونەوە",correct:!1},{text:"بەرەو خوارەوە بۆ دۆڵێک یان ژێرپردێک، کە هەوای ئارام و بێجووڵەی تێدایە",correct:!1},{text:"بەرەو سەرچاوەی ماددەکە، چونکە ئاگری ئەوێ گازە مەترسیدارەکە دەسووتێنێت",correct:!1}],explanation:"لەو لایەی کە باکە لێیەوە دێت، با ماددەکە لە تۆ دوور دەخاتەوە، و هەندێک گاز لە هەوا قورسترن و لە شوێنە نزمەکاندا کۆ دەبنەوە. هەرگیز بە ناو هەوردا مەڕۆ."},{question:"ماددەیەکی کیمیایی شل دەپژێتە سەر باسک و قۆڵی جلەکەت. یەکەم دەبێت چی بکەیت؟",options:[{text:"بچۆ بۆ هەوای پاک، جلە دەرەکییە پیسبووەکان دابکەنە و ماددەکە هەڵبمژە",correct:!0},{text:"بە دەستی ڕووتت بیسڕەوە و بەردەوام بە، چونکە بڕێکی کەم ناتوانێت زیان بگەیەنێت",correct:!1},{text:"بە ڕۆن یان مەعجوونی ددان دایبپۆشە تا نەچێتە ناو پێستەوە",correct:!1},{text:"جلەکان لەبەرتدا بهێڵەوە تا پێستت بپارێزن تا دەگەیتە نەخۆشخانە بۆ چارەسەر",correct:!1}],explanation:"خۆت دوور بخەرەوە، جلە دەرەکییەکان دابکەنە، ماددەکە لە پێست لابە. داکەندنی جلە پیسبووەکان زۆربەی پیسییەکە لادەبات؛ ئەگەر پێست خوری یان سووتا بە ئاوێکی زۆر بیشۆ، و هەرگیز چارەسەری ماڵەوە لەسەر پێست دامەنێ."}]},{id:22,icon:"FlaskConical",accent:"#7e22ce",title:"ژەهراویبوون لە ماڵەوە",subtitle:"هەڵگرتنی سەلامەت، ژەهری قووتدراو، پڕژانی مادەی کیمیایی و مۆنۆکسیدی کاربۆن",summary:"دەرمان، مادەی پاککەرەوە، نەوت، بەنزین و دەرمانی مێروو لە زۆربەی ماڵەکاندا هەن، و هەر یەکێکیان دەتوانێت مرۆڤ ژەهراوی بکات. منداڵانی بچووک زیاتر لە مەترسیدان، چونکە شت دەخەنە دەمیانەوە و ناتوانن لەیبڵەکان بخوێننەوە. ئەم وانەیە ڕوون دەکاتەوە چۆن ئەم مادانە بە سەلامەتی هەڵبگرین، ئەگەر کەسێک شتێکی زیانبەخشی قووتدا چی بکەین، چۆن مادەی کیمیایی لە چاو و پێست بشۆین، و کاتێک گومانی مۆنۆکسیدی کاربۆن (CO) هەبوو چی بکەین.",blocks:[{heading:"مادە مەترسیدارەکان بە سەلامەتی هەڵبگرە",body:"باشترین پاراستن ئەوەیە کە مادەکان بە دروستی هەڵبگیرێن:",points:["دەرمان، مادەی پاککەرەوە و دەرمانی مێروو لە شوێنێکی قفڵدراو یان بەرز دابنێ، دوور لە چاو و دەستی منداڵان.","هەر مادەیەک لە قاپە ڕەسەنەکەی خۆیدا و لەگەڵ لەیبڵەکەیدا بهێڵەرەوە، بۆ ئەوەی هەرگیز بە خواردنەوە دانەنرێت.","هەرگیز نەوت، بەنزین، مادەی کیمیایی یان دەرمان مەخە ناو بوتڵی خواردنەوە، پەرداخ یان قاپی خواردن.","دوای هەر بەکارهێنانێک قاپەکە باش دابخە و یەکسەر بیگەڕێنەرەوە شوێنی خۆی؛ لەسەر زەوی یان مێز جێی مەهێڵە، تەنانەت بۆ ساتێکیش.","هەرگیز مادە پاککەرەوەکان تێکەڵ مەکە (بۆ نموونە کلۆر لەگەڵ پاککەرەوەیەکی تر): تێکەڵەکە دەتوانێت گاز و هەڵمی مەترسیدار دەربکات."]},{heading:"ئەگەر کەسێک شتێکی زیانبەخشی قووتدا",body:`١. مادەکە لە کەسەکە و لە منداڵان دوور بخەرەوە.
٢. یەکسەر پەیوەندی بە ١٢٢ بکە، تەنانەت ئەگەر کەسەکە باش دیار بێت: هەندێک ژەهر دواتر زیان دەگەیەنن. قاپ یان لەیبڵی مادەکە بپارێزە بۆ ئەوەی نیشانی تیمی ئەمبولانس و پزیشکەکانی بدەیت.
٣. هەوڵ مەدە بیڕشێنیتەوە.
٤. شیر، ڕۆن، ئاوی خوێ یان هیچ چارەسەرێکی ماڵەوەی تری مەدەرێ، و هیچ خواردن و خواردنەوەیەکی مەدەرێ مەگەر پزیشک پێت بڵێت.
٥. ئەگەر کەسەکە خەواڵوو یان بێهۆش بوو بەڵام هەناسەی ئاسایی دەدات، لەسەر لا (دۆخی چاکبوونەوە) دایبنێ و بەردەوام هەناسەی بپشکنە. ئەگەر هەناسەی ئاسایی وەستا، دەست بە CPR بکە (سەیری وانەی «فریاکەوتنی سەرەتایی و پەستانی سنگ (CPR)» بکە).`},{heading:"نەوت، بەنزین و ڕۆنی چرا",body:`ئەم شلانە ئەگەر قووت بدرێن زۆر مەترسیدارن. تەنک و خلیسکن و بە ئاسانی دەچنە ناو سییەکانەوە، تەنانەت بڕێکی کەمیش، و دەتوانن گرفتی قورسی هەناسەدان و هەوکردنی سییەکان (pneumonia) دروست بکەن. بۆیە ڕشانەوە لێرەدا زۆر مەترسیدارە. کۆکە، خنکان یان هەناسەتەنگی دوای قووتدانیان دەتوانێت نیشانەی ئەوە بێت کە شلەکە گەیشتووەتە سییەکان: یەکسەر پەیوەندی بە ١٢٢ بکە.

• سووتەمەنی تەنها لە قاپی تایبەتی سووتەمەنیدا بکڕە و هەڵبگرە، و بە قفڵدراوی دوور لە منداڵان دایبنێ.`},{heading:"مادەی کیمیایی لە چاو یان لەسەر پێست",points:["سەرەتا خۆت بپارێزە: بە دەستی ڕووت دەست لە مادە کیمیاییەکە مەدە، و ئەگەر دەستکێشت هەیە بەکاری بهێنە.","چاو: یەکسەر بە ئاوی پاک و ڕەوانی زۆر، لانیکەم ١٥ خولەک بیشۆ و پێڵووەکانی کراوە ڕابگرە. مەهێڵە ئاوەکە بچێتە ناو چاوەکەی تر.","پێست: سەرەتا تۆزی وشک لاببە، جلی پیسبوو، کاتژمێر و خشڵ دابکەنە، پاشان پێست بە ئاوی ڕەوانی زۆر لانیکەم ١٥ خولەک بشۆ.","بۆ ڕێنمایی پەیوەندی بە ١٢٢ بکە و لەیبڵی مادەکە بپارێزە. ئەگەر کەسەکە هەناسەتەنگی هەبوو، هەستی بە نەخۆشی کرد یان بەشێکی گەورەی لەشی پێی گەیشتبوو، یەکسەر پەیوەندی بکە."]},{heading:"مۆنۆکسیدی کاربۆن (CO)",body:`CO گازێکی ژەهراوی بێ ڕەنگ و بێ بۆنە. لە سۆبە، تەباخ، مۆلیدە و بزوێنەرەکان کە سووتەمەنی دەسووتێنن دروست دەبێت. سەرئێشە، سەرگێژخواردن، دڵتێکچوون، لاوازی یان شێواوی لە نزیک ئەم ئامێرانە دەتوانن نیشانەی مەترسی بن.

• یەکسەر هەمووان بۆ هەوای پاک دەربهێنە و لە دەرەوە پەیوەندی بە ١١٥ و ١٢٢ بکە.
• مەگەڕێوە ژوورەوە تا پێت دەوترێت شوێنەکە سەلامەتە.
• هەرگیز مۆلیدە یان بزوێنەری ئۆتۆمبێل لە ناو ماڵ یان گەراجدا کار پێ مەکە، تەنانەت ئەگەر دەرگاکان کراوە بن، و ئاگادارکەرەوەی CO لە نزیک ژوورەکانی نووستن دابنێ.`}],tips:["ژمارەکانی ١٢٢ (ئەمبولانس) و ١١٥ (بەرگریی شارستانی) لە تەنیشت تەلەفۆنەکە بنووسە و فێری هەموو ئەندامانی خێزانی بکە.","بە بەرزیی چاوی منداڵێکی بچووک بە ناو ماڵدا بگەڕێ و هەر شتێکی ژەهراوی کە منداڵ دەستی پێی دەگات لاببە.","کاتێک بەهۆی ژەهراویبوونەوە پەیوەندی بە ١٢٢ دەکەیت، قاپەکە بە دەستتەوە بێت بۆ ئەوەی ناوی مادەکە بخوێنیتەوە.","پێش بەکارهێنانی هەر مادەیەکی پاککەرەوە لەیبڵەکەی بخوێنەوە و ڕێنماییەکانی جێبەجێ بکە.","کاتێک مادەی پاککەرەوە، دەرمانی مێروو یان سووتەمەنی بەکاردەهێنیت، منداڵان دوور بخەرەوە."],warnings:["هەرگیز کەسێک کە ژەهری قووتداوە مەیڕشێنەرەوە، و هەرگیز شیر، ڕۆن یان ئاوی خوێی مەدەرێ.","هەرگیز نەوت، بەنزین یان مادەی کیمیایی لە بوتڵی خواردنەوەدا هەڵمەگرە: لەوانەیە منداڵێک بیخواتەوە.","بۆ ڕزگارکردنی کەسێک مەچۆ ناو ژوورێکی پڕ لە گاز یان گومانی مۆنۆکسیدی کاربۆنی تێدا هەبێت؛ دەرچۆ و پەیوەندی بە ١١٥ بکە."],activity:{prompt:"برازا سێ ساڵانەکەت کۆکە دەکات و دەگری. لە تەنیشتییەوە بوتڵێکی خواردنەوەی کراوە هەیە کە خێزانەکە نەوتی سۆبەی تێدا هەڵدەگرت. چی دەکەیت؟",options:[{text:"بوتڵەکە لێی دوور دەخەمەوە، یەکسەر پەیوەندی بە ١٢٢ دەکەم و بوتڵەکە دەپارێزم بۆ ئەوەی نیشانی تیمی ئەمبولانسی بدەم. نایڕشێنمەوە و هیچ خواردنەوەیەکی پێ نادەم.",correct:!0,feedback:"کۆکە دوای قووتدانی نەوت دەتوانێت نیشانەی ئەوە بێت کە گەیشتووەتە سییەکان. پەیوەندیکردنی خێرا بە ١٢٢، پاراستنی بوتڵەکە و نەڕشاندنەوە منداڵەکە دەپارێزن."},{text:"پەنجەم دەخەمە قوڕگییەوە بۆ ئەوەی نەوتەکە بڕشێتەوە.",correct:!1,feedback:"ڕشانەوە لەگەڵ نەوت زۆر مەترسیدارە، چونکە شلەکە دەتوانێت بچێتە ناو سییەکان. لە جیاتی ئەوە پەیوەندی بە ١٢٢ بکە."},{text:"پەرداخێک شیری پێ دەدەم بۆ ئەوەی ژەهرەکە لاواز بکات.",correct:!1,feedback:"شیر نەوت بێزیان ناکات و لەوانەیە بیڕشێنێتەوە. مەگەر پزیشک بڵێت، هیچ شتێک بە دەمیدا مەدە؛ پەیوەندی بە ١٢٢ بکە."},{text:"چاوەڕێ دەکەم بزانم کۆکەکە دەوەستێت، پاشان پەیوەندی بە کەسێک دەکەم.",correct:!1,feedback:"کۆکە نیشانەی مەترسییە کە لەوانەیە نەوت گەیشتبێتە سییەکان، و چاوەڕوانی کات بەفیڕۆ دەدات. ئێستا پەیوەندی بە ١٢٢ بکە."}]},quiz:[{question:"دەرمان و مادەی پاککەرەوە دەبێت لە کوێ هەڵبگیرێن؟",options:[{text:"لە شوێنێکی قفڵدراو یان بەرز، لە قاپە ڕەسەنەکانی خۆیاندا",correct:!0},{text:"لە ژێر دەستشۆری چێشتخانە، بۆ ئەوەی هەموو خێزان بە خێرایی بیاندۆزنەوە",correct:!1},{text:"لە بوتڵی خواردنەوەی پاکدا، بۆ ئەوەی شوێنی کەمتر بگرن",correct:!1},{text:"لەسەر ڕەفەیەکی نزم لە حەمامدا، و سەرەکانیان کراوە بن",correct:!1}],explanation:"شوێنی قفڵدراو یان بەرز و قاپی ڕەسەنی لەیبڵدار منداڵان لەم مادانە دوور دەخەنەوە و ناهێڵن کەس بە خواردنەوەیان دابنێت."},{question:"کەسێک مادەیەکی پاککەرەوەی قووتداوە. کام کار دروستە؟",options:[{text:"پەیوەندی بە ١٢٢ بکە، قاپەکە بپارێزە و هیچ بە دەمیدا مەدە",correct:!0},{text:"یەکسەر بیڕشێنەرەوە بۆ ئەوەی مادەکە بە خێرایی لە گەدەی دەربچێت",correct:!1},{text:"پەرداخێک شیر یان ڕۆنی پێ بدە بۆ ئەوەی گەدەی لە مادەکە بپارێزێت",correct:!1},{text:"ئاوی خوێی پێ بدە، پاشان چاوەڕێ بکە بزانە باشتر دەبێت یان نا",correct:!1}],explanation:"ڕشانەوە و چارەسەری ماڵەوە دەتوانن زیانەکە زیاتر بکەن. پەیوەندی بە ١٢٢ بکە، قاپەکە بپارێزە و مەگەر پزیشک پێت بڵێت هیچ خواردن و خواردنەوەیەکی مەدەرێ."},{question:"بۆچی قووتدانی نەوت یان بەنزین زۆر مەترسیدارە؟",options:[{text:"دەتوانێت بچێتە ناو سییەکان و گرفتی قورسی هەناسەدان دروست بکات",correct:!0},{text:"تەنها زیان بە گەدە دەگەیەنێت، بۆیە دوای ڕشانەوە کەسەکە بە تەواوی سەلامەتە",correct:!1},{text:"تەنها ئەگەر پەرداخێکی پڕ بخورێتەوە مەترسیدارە، نەک قومێکی بچووک",correct:!1},{text:"دوای چەند خولەکێک لەگەڵ ئاودا تێکەڵ دەبێت و بێزیان دەبێت",correct:!1}],explanation:"نەوت و بەنزین دەتوانن بچنە ناو سییەکان، تەنانەت بڕێکی کەمیش، و ڕشانەوە ئەم مەترسییە زیاتر دەکات. یەکسەر پەیوەندی بە ١٢٢ بکە."},{question:"مادەیەکی کیمیایی پڕژاوەتە ناو چاوی کەسێک. چەند کات دەبێت بە ئاوی ڕەوان بشۆردرێت؟",options:[{text:"لانیکەم ١٥ خولەک",correct:!0},{text:"نزیکەی ٣٠ چرکە",correct:!1},{text:"یەک جار ئاو پێدادان بەسە",correct:!1},{text:"تەنها تا سووتانەوەکە دەوەستێت",correct:!1}],explanation:"یەکسەر بە ئاوی ڕەوانی زۆر، لانیکەم ١٥ خولەک بیشۆ و پێڵووەکان کراوە ڕابگرە، پاشان بۆ ڕێنمایی پەیوەندی بە ١٢٢ بکە."},{question:"کاتێک سۆبەیەک لە ژوورەوە داگیرساوە، چەند ئەندامێکی خێزان سەرئێشە و سەرگێژخواردنیان هەیە. سەرەتا چی دەکەیت؟",options:[{text:"هەمووان دەربهێنە، پاشان لە دەرەوە پەیوەندی بە ١١٥ و ١٢٢ بکە",correct:!0},{text:"دەرمانی سەرئێشە بە هەمووان بدە و با لە هەمان ژووری گەرمدا پشوو بدەن",correct:!1},{text:"پەنجەرەیەک کەمێک بکەرەوە و سۆبەکە هەموو شەو داگیرساو بهێڵەرەوە",correct:!1},{text:"سۆبەکە بەرزتر بکەرەوە تا ژوورەکە زوو گەرم بێت و سەرگێژەکە نەمێنێت",correct:!1}],explanation:"ئەمانە دەتوانن نیشانەی ژەهراویبوون بە مۆنۆکسیدی کاربۆن بن. CO نە ڕەنگی هەیە و نە بۆن: سەرەتا هەمووان دەربهێنە، لە دەرەوە پەیوەندی بکە و مەگەڕێوە ژوورەوە تا پێت دەوترێت شوێنەکە سەلامەتە."}],media:[{kind:"image",src:"media/images/w7_poisoning_home.webp",title:"هەڵگرتنی سەلامەت لە ماڵەوە",description:"دەرمان و مادەی پاککەرەوە لە قاپە ڕەسەنەکانیاندا، قفڵدراو و دوور لە دەستی منداڵان"}]},{id:23,icon:"Ambulance",accent:"#be123c",title:"باری نائاسایی پزیشکی: بیناسەوە و پەیوەندی بکە",subtitle:"جەڵتەی مێشک، جەڵتەی دڵ، گرژبوون، دابەزینی شەکر، هەستیاریی توند، شۆک و بێهۆشی",summary:"لە نەخۆشییەکی لەناکاودا، گرنگترین کارەکان کە هاووڵاتییەک دەتوانێت بیکات ئەمانەن: نیشانەکانی مەترسی بناسێتەوە، یەکسەر پەیوەندی بە ١٢٢ بکات و لەگەڵ کەسەکەدا بمێنێتەوە. ئەم وانەیە نیشانەکانی جەڵتەی مێشک (FAST)، جەڵتەی دڵ، گرژبوون، دابەزینی شەکری خوێن، هەستیاریی توند و شۆک فێر دەکات، و ڕوون دەکاتەوە بۆ کەسێکی بێهۆش چی بکەیت و کاتێک پەیوەندی بە ١٢٢ دەکەیت چی بڵێیت. ئەم وانەیە جێگەی خولی فریاکەوتنی سەرەتایی ناگرێتەوە.",blocks:[{heading:"جەڵتەی مێشک: FAST بیر بێنەوە",body:`جەڵتەی مێشک ئەو کاتە ڕوودەدات کە لەناکاو خوێنی پێویست ناگاتە بەشێک لە مێشک. چارەسەر کاتێک زوو دەست پێبکات باشتر کار دەکات، بۆیە یەکسەر کار بکە:
• F = دەموچاو (Face): داوای لێ بکە پێبکەنێت. ئایا لایەکی دەموچاوی شۆڕ دەبێتەوە؟
• A = باسک (Arms): داوای لێ بکە هەردوو باسکی بەرز بکاتەوە. ئایا باسکێک دادەبەزێت یان لاوازە؟
• S = قسەکردن (Speech): ئایا قسەکردنی قورس یان سەیرە، یان لە قسەکانت تێناگات؟
• T = کات (Time): ئەگەر یەکێک لەم نیشانانەت بینی، یەکسەر پەیوەندی بە ١٢٢ بکە.

کاتی دەستپێکردنی نیشانەکان، یان دوایین کات کە کەسەکە ئاسایی بینراوە، بنووسە و بە تیمی ئەمبولانسی بڵێ. تەنانەت ئەگەر نیشانەکان نەمان، پەیوەندی بکە. خواردن و خواردنەوەی مەدەرێ، چونکە جەڵتەی مێشک دەتوانێت قووتدان قورس بکات.`},{heading:"جەڵتەی دڵ",body:`نیشانەکانی مەترسی دەتوانن ئەمانە بن: ئازار، قورسایی یان گوشار لە سنگدا؛ ئازارێک کە بۆ باسک، مل، چەناگە یان پشت بڵاو دەبێتەوە؛ هەناسەتەنگی؛ ئارەقکردنەوە؛ و دڵتێکچوون.
• یەکسەر پەیوەندی بە ١٢٢ بکە. با ئەمبولانس بیگەیەنێتە نەخۆشخانە؛ مەهێڵە خۆی ئۆتۆمبێل لێبخوڕێت.
• هەموو چالاکییەک ڕابگرە: یارمەتی بدە دابنیشێت یان لەو دۆخەدا پشوو بدات کە بۆی ئاسوودەترە، و لەگەڵیدا بمێنەوە.
• ئەگەر وەڵامی نەدایەوە و هەناسەی ئاسایی وەستا، دەست بە CPR بکە و کەسێک بنێرە بۆ هێنانی ئامێری شۆکی دڵ (AED).`},{heading:"گرژبوون (فێ)",body:`لە کاتی گرژبووندا لەوانەیە کەسەکە بکەوێت، لەشی ڕەق ببێت و بلەرزێت، یان چاوی بڕێتە شوێنێک و وەڵام نەداتەوە. زۆربەی گرژبوونەکان لە ماوەی چەند خولەکێکدا خۆیان دەوەستن.
• لەگەڵیدا بمێنەوە و کاتی دەستپێکردنی گرژبوونەکە تۆمار بکە.
• شتە ڕەق یان تیژەکان دوور بخەرەوە و شتێکی نەرم و پان، وەک چاکەتێکی پێچراو، بخەرە ژێر سەری.
• بە زۆر مەیگرە و هیچ شتێک مەخە ناو دەمییەوە. هیچ خواردن، خواردنەوە یان دەرمانێکی مەدەرێ تا بە تەواوی بەئاگا دێتەوە.
• کاتێک لەرزینەکە وەستا، ئەگەر گومانی برینداربوونی مل یان پشت نەبوو، لەسەر لا (دۆخی چاکبوونەوە) دایبنێ و هەناسەی بپشکنە.

پەیوەندی بە ١٢٢ بکە ئەگەر:`,points:["یەکەم گرژبوونی ئەو کەسە بێت.","زیاتر لە ٥ خولەک بخایەنێت، یان گرژبوونێکی تر دەست پێبکات پێش ئەوەی کەسەکە بێتەوە سەر خۆی.","لە ناو ئاودا ڕووبدات، یان کەسەکە بریندار بێت یان هەناسەتەنگی هەبێت.","کەسەکە ئافرەتێکی دووگیان بێت، یان کۆرپەیەکی خوار تەمەنی ٦ مانگ بێت.","کەسەکە لە ماوەی ٥–١٠ خولەکدا دوای وەستانی گرژبوونەکە بە دروستی بەئاگا نەیەتەوە."]},{heading:"دابەزینی شەکر، هەستیاریی توند و شۆک",points:["دابەزینی شەکری خوێن (زۆرجار لە کەسێکی نەخۆشی شەکرەدا): شێواویی لەناکاو، لەرزین، ئارەقکردنەوە یان ڕەفتاری سەیر. ئەگەر کەسەکە بەئاگا بوو و دەتوانێت قووت بدات، شەکر، شیرینی یان خواردنەوەیەکی شیرینی پێبدە. ئەگەر نەیتوانی قووت بدات، گرژبوونی بۆ دروست بوو یان لە ماوەی ١٠ خولەکدا باشتر نەبوو، پەیوەندی بە ١٢٢ بکە.","هەستیاریی توند (Anaphylaxis): ئاوسانی لێو، دەموچاو یان گەروو، هەناسەتەنگی، فیکەی هەناسە، پەڵەی سوور لەسەر پێست، سەرگێژخواردن یان لەهۆشچوون، زۆرجار چەند خولەکێک دوای خواردنێک، دەرمانێک یان پێوەدانی مێرووێک. یەکسەر پەیوەندی بە ١٢٢ بکە. ئەگەر دەرزیی ئەدرینالینی خۆکار (auto-injector)ی تایبەت بە خۆی پێ بوو، یارمەتی بدە بەپێی ڕێنماییەکانی بەکاری بهێنێت.","لە هەستیاریی تونددا، ئەگەر هەناسەدان قورس بوو با کەسەکە دابنیشێت؛ ئەگەرنا با ڕابکشێت. مەهێڵە هەستێتە سەر پێ یان بڕوات، تەنانەت ئەگەر هەست بە باشتربوونیش بکات.","شۆک (دوای خوێنبەربوونێکی زۆر، سووتان یان نەخۆشییەکی قورس): پێستی زەرد، سارد و تەڕ، لێدانی خێرای دڵ، سەرگێژخواردن یان شێواوی. پەیوەندی بە ١٢٢ بکە، کەسەکە لەسەر پشت ڕابکشێنە، گەرمی ڕابگرە و هیچ خواردن و خواردنەوەیەکی مەدەرێ. ئەگەر ڕشایەوە یان خەواڵوو بوو، لەسەر لا دایبنێ ئەگەر گومانی برینداربوونی مل یان پشت نەبوو."]},{heading:"بێهۆش: ئایا هەناسەی ئاسایی دەدات؟",body:"دەست لە شانەکانی بدە و بە دەنگی بەرز بپرسە: «باشیت؟» ئەگەر وەڵامی نەدایەوە، پەیوەندی بە ١٢٢ بکە (یان با کەسێکی تر پەیوەندی بکات) و زیاتر لە ١٠ چرکە سەیری سنگی بکە.",points:["هەناسەی ئاسایی دەدات و نە کەوتووە، نە ڕووداوی هاتووچۆی بەسەردا هاتووە و نە زەبر بەر سەر، مل یان پشتی کەوتووە: لەسەر لا لە دۆخی چاکبوونەوەدا دایبنێ، هیچ شتێک بە دەمیدا مەدە و بەردەوام هەناسەی بپشکنە.","هەناسەی ئاسایی دەدات، بەڵام لەوانەیە مل، پشت، سمت یان ئێسکی حەوزی (pelvis) بریندار بێت: مەیجووڵێنە مەگەر شوێنەکە مەترسیدار بێت؛ بێجووڵە ڕایبگرە و بەردەوام چاودێری هەناسەی بکە.","هەناسە نادات، یان تەنها هەناسەی نائاسایی و پچڕپچڕ دەدات: یەکسەر دەست بە CPR بکە و کەسێک بنێرە بۆ هێنانی AED (سەیری وانەی «فریاکەوتنی سەرەتایی و پەستانی سنگ (CPR)» بکە)."]},{heading:"پەیوەندیکردن بە ١٢٢: چی بڵێیت؟",body:`هێمن بە و وەڵامی پرسیارەکانی کارمەندی پەیوەندی بدەرەوە:
١. لە کوێیت: ناوچە، شەقام، نیشانەیەکی نزیک، بینا و نهۆم.
٢. چی ڕوویداوە و چی دەبینیت، بۆ نموونە: «پیاوێکی نزیکەی ٦٠ ساڵ؛ لایەکی دەموچاوی شۆڕ بووەتەوە.»
٣. چەند کەس نەخۆش یان بریندارن، و ئایا هیچ مەترسییەک هەیە.
٤. ناو و ژمارەی تەلەفۆنەکەت.

پەیوەندییەکە مەپچڕێنە تا پێت دەوترێت. لەگەڵ کەسەکەدا بمێنەوە، و دەرمان و بەڵگەنامە پزیشکییەکانی بۆ تیمی ئەمبولانس ئامادە بکە.`}],tips:["FAST فێر ببە و فێری خێزانەکەتی بکە: دەموچاو، باسک، قسەکردن، کات.","بەشداری خولی فریاکەوتنی سەرەتایی و CPR بکە، و هەر چەند ساڵ جارێک نوێی بکەرەوە.","ئەگەر یەکێک لە خێزانەکەت نەخۆشی شەکرە، فێ، نەخۆشی دڵ یان هەستیاریی توندی هەیە، پلانی باری نائاسایی و شوێنی دەرمان و ئامێرەکانی بزانە.","لیستێکی نووسراو لە نەخۆشی، دەرمان و هەستیارییەکانی هەر ئەندامێکی خێزان ڕابگرە و بیدە بە تیمی ئەمبولانس.","لەگەڵ کەسەکەدا بمێنەوە تا تیمی ئەمبولانس کارەکە وەردەگرێت."],warnings:["هەرگیز هیچ شتێک مەخە ناو دەمی کەسێک کە گرژبووە یان بە تەواوی بەئاگا نییە.","بە ئارەزووی خۆت دەرمان مەدە؛ تەنها یارمەتی کەسەکە بدە دەرزیی ئەدرینالینی خۆکار یان هەڵمژی (inhaler) تایبەت بە خۆی کە پزیشک بۆی نووسیوە بەکاربهێنێت.","چاوەڕێ مەکە بزانیت نیشانەکانی جەڵتەی مێشک یان دڵ نامێنن یان نا: یەکسەر پەیوەندی بە ١٢٢ بکە."],activity:{prompt:"لە کۆبوونەوەیەکی خێزانیدا، مامە ٦٢ ساڵانەکەت لەناکاو ناتوانێت باسکی ڕاستی بەرز بکاتەوە و قسەکردنی قورس بووە. دەڵێت تەنها پێویستی بەوەیە بۆ ماوەیەک ڕابکشێت. چی دەکەیت؟",options:[{text:"یەکسەر پەیوەندی بە ١٢٢ دەکەم، پێیان دەڵێم چی دەبینم و نیشانەکان کەی دەستیان پێکرد، و لەگەڵیدا دەمێنمەوە تا ئەمبولانس دەگات.",correct:!0,feedback:"لاوازی باسک و قورسی قسەکردن نیشانەی جەڵتەی مێشکن (FAST). چارەسەر کاتێک زوو دەست پێبکات باشتر کار دەکات، و کاتی دەستپێکردنی نیشانەکان یارمەتی پزیشکەکان دەدات."},{text:"دەهێڵم ڕابکشێت و پشوو بدات، و ئەگەر باشتر نەبوو سبەی پەیوەندی بە پزیشکەوە دەکەین.",correct:!1,feedback:"چاوەڕوانی کات بەفیڕۆ دەدات: جەڵتەی مێشک پێویستی بە زووترین چارەسەر هەیە. ئێستا پەیوەندی بە ١٢٢ بکە، تەنانەت ئەگەر هەست بە باشتربوونیش بکات."},{text:"بە ئۆتۆمبێل دەیبەمە دەرمانخانە بۆ ئەوەی دەرمانی پەستانی خوێن بکڕێت.",correct:!1,feedback:"دەرمانخانە ناتوانێت جەڵتەی مێشک چارەسەر بکات، و دەرمانی بێ پزیشک دەتوانێت زیانی پێبگەیەنێت. پەیوەندی بە ١٢٢ بکە بۆ ئەوەی ئەمبولانس بیبات بۆ نەخۆشخانە."},{text:"چایەکی شیرینی پێ دەدەم و نیو کاتژمێر چاوەڕێ دەکەم بزانم قسەکردنی باشتر دەبێت.",correct:!1,feedback:"چای شیرین جەڵتەی مێشک چارەسەر ناکات، و چاوەڕوانی کاتێکی گرنگ بەفیڕۆ دەدات. یەکسەر پەیوەندی بە ١٢٢ بکە."}]},quiz:[{question:"پیتی T لە FAST دا مانای چییە؟",options:[{text:"کات (Time): یەکسەر پەیوەندی بە ١٢٢ بکە و کاتی نیشانەکان بنووسە",correct:!0},{text:"پلەی گەرمی (Temperature): سەرەتا بە گەرماپێو بپشکنە بزانە تای هەیە یان نا",correct:!1},{text:"حەب (Tablets): سەرەتا دەرمانە ڕۆژانەکەی پێبدە",correct:!1},{text:"چا (Tea): خواردنەوەیەکی گەرمی پێبدە بۆ ئەوەی هێمن ببێتەوە",correct:!1}],explanation:"FAST واتە دەموچاو، باسک، قسەکردن و کات. کات واتە یەکسەر پەیوەندیکردن بە ١٢٢؛ کاتی دەستپێکردنی نیشانەکان یارمەتی پزیشکەکان دەدات چارەسەر هەڵبژێرن."},{question:"کەسێک لەسەر زەوی گرژ بووە. کام کار دروستە؟",options:[{text:"شتە ڕەقەکان دوور بخەرەوە، کات بزانە و هیچ مەخە ناو دەمی",correct:!0},{text:"دەست و قاچەکانی بە توندی بگرە بۆ ئەوەی لەرزینەکە زووتر بوەستێت",correct:!1},{text:"کەوچکێک بخەرە نێوان ددانەکانییەوە بۆ ئەوەی زمانی خۆی نەگەزێت",correct:!1},{text:"ئاوی سارد بکە بە دەموچاویدا بۆ ئەوەی بەئاگا بێتەوە و گرژبوونەکە بوەستێت",correct:!1}],explanation:"بە زۆر مەیگرە و هیچ شتێک مەخە ناو دەمییەوە. لە برینداربوون بیپارێزە، کاتی گرژبوونەکە بزانە و کاتێک لەرزینەکە وەستا لەسەر لا دایبنێ."},{question:"کەی دەبێت بەهۆی گرژبوونەوە پەیوەندی بە ١٢٢ بکەیت؟",options:[{text:"ئەگەر زیاتر لە ٥ خولەک بخایەنێت یان یەکەم گرژبوونی ئەو کەسە بێت",correct:!0},{text:"تەنها ئەگەر کەسەکە دوای کۆتاییهاتنی گرژبوونەکە داوای بکات",correct:!1},{text:"هەرگیز، چونکە گرژبوون هەمیشە خۆی بەبێ یارمەتی دەوەستێت",correct:!1},{text:"تەنها ئەگەر گرژبوونەکە زیاتر لە نیو کاتژمێر بخایەنێت بێ ئەوەی بوەستێت",correct:!1}],explanation:"بۆ یەکەم گرژبوون، گرژبوونی درێژتر لە ٥ خولەک، گرژبوونی دووبارە، گرژبوون لە ناو ئاودا، برینداربوون، هەناسەتەنگی، دووگیانی، کۆرپەی خوار ٦ مانگ، یان ئەگەر کەسەکە بە دروستی بەئاگا نەهاتەوە، پەیوەندی بە ١٢٢ بکە."},{question:"کەسێکی نەخۆشی شەکرە شێواوە و ئارەق دەکاتەوە، بەڵام بەئاگایە و دەتوانێت قووت بدات. چی یارمەتی دەدات؟",options:[{text:"شەکر یان خواردنەوەیەکی شیرینی پێبدە؛ ئەگەر باشتر نەبوو پەیوەندی بە ١٢٢ بکە",correct:!0},{text:"دۆزێکی زیادەی ئینسولینەکەی پێبدە بۆ ئەوەی شەکری خوێنی بە خێرایی ئاسایی ببێتەوە",correct:!1},{text:"با لە ژوورێکی بێدەنگدا بخەوێت بێ ئەوەی هیچ شتێک بخوات",correct:!1},{text:"خواردنەوەیەکی شیرین بکە بە دەمیدا تەنانەت ئەگەر خەواڵووش بێت",correct:!1}],explanation:"دابەزینی شەکری خوێن بە شەکر لە ڕێگای دەمەوە چارەسەر دەکرێت تەنها ئەگەر کەسەکە بەئاگا بێت و بتوانێت قووت بدات. ئەگەر نەیتوانی قووت بدات، گرژبوونی بۆ دروست بوو یان لە ماوەی ١٠ خولەکدا باشتر نەبوو، پەیوەندی بە ١٢٢ بکە."},{question:"کەسێکی بێهۆش هەناسەی ئاسایی دەدات، و هیچ نیشانەیەکی کەوتن یان زەبر لە مل یان پشتی نییە. چی دەکەیت؟",options:[{text:"پەیوەندی بە ١٢٢ بکە، لەسەر لا دایبنێ و هەناسەی بپشکنە",correct:!0},{text:"دایبنیشێنە و ئاوی پێبدە بۆ ئەوەی زووتر بەئاگا بێتەوە",correct:!1},{text:"یەکسەر دەست بە پەستانی سنگ بکە، تەنانەت ئەگەر هەناسەش بدات",correct:!1},{text:"بە تەنها لەسەر پشت جێی بهێڵە و بڕۆ بەدوای خێزانەکەیدا بگەڕێ",correct:!1}],explanation:"دۆخی چاکبوونەوە ڕێڕەوی هەوا کراوە دەهێڵێتەوە بۆ کەسێکی بێهۆش کە هەناسەی ئاسایی دەدات و گومانی برینداربوونی مل، پشت، سمت یان ئێسکی حەوزی (pelvis) نییە. هیچ شتێک بە دەمیدا مەدە؛ ئەگەر هەناسەی وەستا، دەست بە CPR بکە."}],media:[{kind:"image",src:"media/images/w7_medical_emergencies.webp",title:"نیشانەکانی جەڵتەی مێشک: FAST",description:"دەموچاو، باسک، قسەکردن، کات: نیشانەکان بناسەوە و پەیوەندی بە ١٢٢ بکە"}]},{id:24,icon:"Handshake",accent:"#0369a1",title:"چۆڵکردنی ئەو کەسانەی پێویستیان بە یارمەتییە",subtitle:"منداڵان، بەساڵاچووان، کەسانی خاوەن پێداویستیی تایبەت، ئافرەتانی دووگیان و نەخۆشان",summary:"لە ئاگرکەوتنەوە، بوومەلەرزە یان لافاودا، هەندێک کەس ناتوانن بە خێرایی یان بە تەنها دەربچن: منداڵانی بچووک، بەساڵاچووان، کەسانی خاوەن پێداویستیی تایبەت، ئافرەتانی دووگیان و نەخۆشان. سەلامەتییان بەندە بە پلانێک کە پێش باری نائاسایی دانرابێت. ئەم وانەیە ڕوون دەکاتەوە چۆن پلانێکی تایبەتی چۆڵکردن بۆ کەسێک دابنێیت، چۆن لەگەڵ کەسانی کەڕ یان نابینادا قسە بکەیت، بۆچی ئاسانسۆری ئاسایی لە کاتی ئاگردا بەکارناهێنرێت، و چۆن یارمەتی بدەیت بێ ئەوەی خۆت یان ئەو کەسە بخەیتە مەترسییەوە.",blocks:[{heading:"کێ لەوانەیە پێویستی بە یارمەتی بێت؟",body:"بیر لە هەموو ئەو کەسانە بکەرەوە کە لە ماڵەکەت، بیناکەت و شەقامەکەتدا لەوانەیە نەتوانن بە خێرایی یان بە تەنها دەربچن:",points:["کۆرپە و منداڵانی بچووک، کە دەبێت کەسێکی گەورەساڵ بەئاگایان بهێنێتەوە و دەریانبهێنێت.","بەساڵاچووانێک کە هێواش دەڕۆن، ڕۆیشتنیار (walker) بەکاردەهێنن یان دەنگی ئاگادارکەرەوە باش نابیستن.","ئەوانەی کورسیی چەرخدار، گۆچان یان دار بەکاردەهێنن، و کەسانی خاوەن پێداویستیی تایبەتی بینین، بیستن، هزری یان دەروونی.","ئافرەتانی دووگیان، نەخۆشان یان ئەوانەی لە نەشتەرگەری چاک دەبنەوە، و هەر کەسێک کە پشت بە دەرمان یان ئامێری پزیشکی دەبەستێت."]},{heading:"پلانی تایبەتی چۆڵکردن",body:"پێش باری نائاسایی، پلانەکە لەگەڵ خودی ئەو کەسە دابنێ:",points:["خودی کەسەکە باشتر لە هەمووان توانا و پێداویستییەکانی خۆی دەزانێت: پرسیاری لێ بکە، و لەگەڵ خێزانەکەی و بەرپرسی بیناکە پلانەکە دابنێ.","بۆ هەر کەسێک یارمەتیدەرێک (هاوڕێ، buddy) و یارمەتیدەرێکی جێگرەوە هەڵبژێرە، و دڵنیابە کە هەردووکیان ئەم ئەرکە قبووڵ دەکەن.","پێداویستییەکانی ئەو کەسە بنووسە: دەرمان، ئامێری پزیشکی، ئامرازی جووڵە، چۆن پەیوەندی دەکات و پەیوەندی بە کێوە بکرێت.","بە شەو، چاویلکە، ئامێری بیستن، ئامرازی ڕۆیشتن، تەلەفۆن و چرای دەستی لە تەنیشت جێگاکەی دابنێ.","ئەگەر بکرێت، با ئەو کەسە لە نهۆمی سەر زەوی و نزیک دەرچەیەک بخەوێت.","بە بەردەوامی پێکەوە ڕاهێنان لەسەر پلانەکە بکەن."]},{heading:"قسەکردن لەگەڵ کەسانی کەڕ یان نابینا",points:["کەڕ یان بیستن لاواز: لەوانەیە دەنگی ئاگادارکەرەوە یان هاوار نەبیستێت. تا لای بڕۆ و بە ڕاوەشاندنی دەست یان چرایەکی تروسکەدار سەرنجی ڕابکێشە، پاشان ڕووبەڕووی بوەستە و بە ڕوونی و بێ هاوار قسە بکە.","بە ئاماژەی سادە ڕوونی بکەرەوە، دەرچەکە نیشان بدە یان تێبینییەکی کورت بنووسە. لە تاریکیدا، ڕووناکی بخەرە سەر دەموچاو و دەستەکانت بۆ ئەوەی بتبینێت.","نابینا یان بینین لاواز: بڵێ تۆ کێیت و چی ڕوودەدات، و بپرسە چۆن دەتوانیت یارمەتی بدەیت. بە توندی مەیگرە و پاڵی پێوە مەنێ.","باسکت پێشکەش بکە و با لە سەرووی ئانیشکەوە بیگرێت. پێش پلیکانە، لێواری ڕێگا و دەرگا کەمێک بوەستە و بڵێ چی لە پێشەوەیە.","لە شوێنی کۆبوونەوە، پێی بڵێ لە کوێیە و کێ لەگەڵیدایە."]},{heading:"ئاسانسۆر و شوێنەکانی پەنا",points:["هەرگیز لە کاتی ئاگردا ئاسانسۆری ئاسایی بەکارمەهێنە. کاتێک ئاگادارکەرەوەی ئاگر لێدەدات، ئاسانسۆرەکان بە گشتی دەچنە نهۆمێکی دیاریکراو و پاشان تەنها ئاگرکوژەکان دەتوانن بەکاریان بهێنن.","کەسێک کە ناتوانێت پلیکانە بەکاربهێنێت، لەگەڵ یارمەتیدەرەکەیدا لەو شوێنە سەلامەتەدا چاوەڕێ دەکات کە لە پلانی باری نائاسایی بیناکەدا دیاری کراوە، وەک شوێنی پەنا (Area of Refuge)، دوور لە ئاگر و دووکەڵ.","ئەگەر نەتوانیت بگەیتە کەسێک کە پێویستی بە یارمەتییە، دەرچۆ و پەیوەندی بە ١١٥ بکە. یەکسەر بە ئاگرکوژەکان بڵێ ئەو کەسە لە کوێ چاوەڕێ دەکات: نهۆم، ژوور و چەند کەسن.","ئەم ڕێکارانە پێشوەختە لەگەڵ بەرپرسی بیناکە ڕێک بخە، و ڕێنماییەکانی بەرگریی شارستانی جێبەجێ بکە."]},{heading:"یارمەتیدان بێ مەترسی",points:["پێش یارمەتیدان بپرسە، و ڕێنماییەکانی خودی ئەو کەسە جێبەجێ بکە کە چۆن یارمەتی بدەیت.","ئەگەر ڕاهێنانت نەکردووە کەس بەرز مەکەرەوە و هەڵمەگرە، مەگەر مەترسییەکی یەکسەر لەسەر ژیان هەبێت: دەتوانیت ئەو و خۆت بریندار بکەیت.","کورسیی چەرخدار، ڕۆیشتنیار یان گۆچان لە کەسەکە دوور مەخەرەوە؛ ئەگەر توانیت ئامرازی جووڵەکە لەگەڵ خۆت ببە.","دەرمان و ئامێرەکانی تەنها ئەگەر لەبەردەستدا بوون لەگەڵ خۆت ببە؛ هەرگیز بۆیان مەگەڕێوە ژوورەوە.","لە شوێنی کۆبوونەوە لەگەڵ ئەو کەسەدا بمێنەوە و بەو کەسە بڵێ کە خەڵک دەژمێرێت کە ئەو سەلامەتە."]}],tips:["لیستێک لەو دراوسێیانەی بیناکەت دروست بکە کە لەوانەیە پێویستیان بە یارمەتی بێت، و لەگەڵیان ڕێک بکەون کێ یارمەتی کێ دەدات.","کۆپییەکی لیستی پێداویستییەکانی هەر کەسێک لە جانتای باری نائاساییدا دابنێ.","ئاگادارکەرەوەی دووکەڵی خاوەن چرای تروسکەدار یان بالیفی لەرزۆک یارمەتی ئەو کەسانە دەدات کە کەڕن یان بیستنیان لاوازە.","ئەگەر کەسێک ڕۆیشتنیار یان کورسیی چەرخدار بەکاردەهێنێت، دڵنیابە کە دەتوانێت بە هەموو دەرگاکانی دەرچوونی ماڵەکەتدا تێپەڕێت.","ئەو کەسەی پێویستی بە یارمەتییە لە ڕاهێنانەکانتاندا بەشدار بکە، بۆ ئەوەی پلانەکە بە ڕاستی بۆی گونجاو بێت."],warnings:["هەرگیز لە کاتی ئاگردا ئاسانسۆری ئاسایی بەکارمەهێنە.","هەرگیز بۆ ڕزگارکردنی کەسێک مەگەڕێوە ناو بینایەکی ئاگرگرتوو: بە وردی بە ئاگرکوژەکان بڵێ ئەو کەسە لە کوێیە."],activity:{prompt:"ئاگادارکەرەوەی ئاگر لە بینای شوقەکانتاندا لێدەدات. دراوسێکەت لە نهۆمی چوارەم ئافرەتێکی بەساڵاچووە کە ڕۆیشتنیار بەکاردەهێنێت و ناتوانێت بە خێرایی بە پلیکانەدا دابەزێت. چی دەکەیت؟",options:[{text:"پێی دەڵێم چی ڕوودەدات، بە خێرایی خۆی یارمەتی دەدەم بە پلیکانەدا دابەزێت یان بچێتە شوێنی چاوەڕوانیی سەلامەتی ڕێککەوتوو، و بە وردی بە ئاگرکوژەکان دەڵێم لە کوێیە.",correct:!0,feedback:"یارمەتیدانی بۆ جێبەجێکردنی پلانەکە و پێدانی شوێنی وردی بە ئاگرکوژەکان، ڕزگارکەری ڕاهێنراو بە خێرایی دەگەیەنێتە لای، بێ ئەوەی هیچ کامتان بخاتە مەترسیی زیاترەوە."},{text:"بە ئاسانسۆر دایدەبەزێنم، چونکە لە پلیکانە خێراترە.",correct:!1,feedback:"ئاسانسۆری ئاسایی نابێت لە کاتی ئاگردا بەکاربهێنرێت: دەچێتە نهۆمێکی دیاریکراو و پاشان ئاگرکوژەکان کۆنتڕۆڵی دەکەن. پلیکانە یان شوێنی چاوەڕوانیی ڕێککەوتوو بەکاربهێنە."},{text:"بەبێ ئەو دەردەچم، چونکە ڕزگارکردنی خەڵک تەنها کاری ئاگرکوژانە.",correct:!1,feedback:"جێهێشتنی بێ ئەوەی بە کەس بڵێیت ڕزگارکردنی دوادەخات. ئاگاداری بکەرەوە، بەپێی پلانەکەت یارمەتی بدە، و بە ئاگرکوژەکان بڵێ لە کوێیە."},{text:"بە تەنها دەیخەمە سەر پشتم و بە خێرایی بە پلیکانەدا دادەبەزم.",correct:!1,feedback:"هەڵگرتنی بێ ڕاهێنان دەتوانێت هەردووکتان بریندار بکات، و کەوتن لەسەر پلیکانە ڕێگا لە کەسانی تر دەگرێت. تەنها ئەگەر ڕاهێنانت کردبێت یان مەترسییەکی یەکسەر لەسەر ژیان هەبێت کەس هەڵبگرە."}]},quiz:[{question:"کێ دەبێت پلانی تایبەتی چۆڵکردن بۆ کەسێک دابنێت؟",options:[{text:"خودی ئەو کەسە، لەگەڵ خێزان، یارمەتیدەران و بەرپرسی بیناکە",correct:!0},{text:"تەنها بەرپرسی بیناکە، بێ ئەوەی پرسیار لە پێداویستییەکانی بکات",correct:!1},{text:"تەنها ئاگرکوژەکان، لەو ڕۆژەدا کە باری نائاسایی بە ڕاستی ڕوودەدات",correct:!1},{text:"هیچ کەس: باشترە کاتێک ئاگادارکەرەوە لێدەدات بڕیار بدرێت",correct:!1}],explanation:"خودی کەسەکە باشتر لە هەمووان پێداویستییەکانی خۆی دەزانێت، بۆیە پلانەکە لەگەڵ ئەو، خێزانەکەی، یارمەتیدەرەکانی و بەرپرسی بیناکە دادەنرێت، و پێش باری نائاسایی ڕاهێنانی لەسەر دەکرێت."},{question:"ئاگادارکەرەوەی ئاگر لێدەدات. چۆن سەرنجی دراوسێیەکی کەڕ ڕادەکێشیت؟",options:[{text:"بڕۆ بۆ لای، دەست ڕاوەشێنە یان ڕووناکی بەکاربهێنە و ڕووبەڕووی بوەستە",correct:!0},{text:"لە سەری ڕاڕەوەکەوە بە دەنگی بەرز هاوار بکە تا ئەو کاتەی گوێی لە دەنگت دەبێت",correct:!1},{text:"لە پشتەوە باسکی بگرە و بە خێرایی بەرەو دەرچەکە ڕایبکێشە",correct:!1},{text:"نامەیەک بۆ تەلەفۆنەکەی بنێرە و بە تەنها بەرەو دەرچەکە بڕۆ",correct:!1}],explanation:"کەسی کەڕ لەوانەیە دەنگی ئاگادارکەرەوە یان هاوار نەبیستێت. تا لای بڕۆ، سەرنجی ڕابکێشە، ڕووبەڕووی بوەستە و بە ئاماژە یان تێبینییەکی نووسراو ڕوونی بکەرەوە."},{question:"چۆن کەسێکی نابینا لە بینایەک دەردەهێنیت؟",options:[{text:"بڵێ تۆ کێیت، باسکت پێشکەش بکە و پلیکانە و ڕێگرەکانی بۆ باس بکە",correct:!0},{text:"هەردوو شانی بگرە و لە پشتەوە بەرەو دەرچەکە ئاڕاستەی بکە",correct:!1},{text:"دەستی بگرە و بێ ئەوەی هیچ بڵێیت بە خێرایی بەدوای خۆتدا ڕایبکێشە",correct:!1},{text:"بە پەنجە دەرچەکە نیشان بدە و پێی بڵێ بە تەنها ڕێگای خۆی بدۆزێتەوە",correct:!1}],explanation:"بڵێ تۆ کێیت و بپرسە چۆن یارمەتی بدەیت. با ئەو کەسە لە سەرووی ئانیشکەوە باسکت بگرێت، و بڵێ چی لە پێشەوەیە، وەک پلیکانە، لێواری ڕێگا و دەرگا."},{question:"بۆچی نابێت ئاسانسۆری ئاسایی لە کاتی ئاگردا بەکاربهێنرێت؟",options:[{text:"لە ئاگردا دەچێتە نهۆمێکی دیاریکراو و ئاگرکوژەکان کۆنتڕۆڵی دەکەن",correct:!0},{text:"تا ئەو کاتەی ئاگرەکە لە نهۆمێکی ترە بەکارهێنانی هیچ کێشەیەکی نییە",correct:!1},{text:"بۆ بەکارهێنەرانی کورسیی چەرخدار سەلامەتە بەڵام بۆ کەسانی تر نا",correct:!1},{text:"دەتوانیت بەکاری بهێنیت ئەگەر کەسێک دەرگاکان بە کورسییەک کراوە بهێڵێتەوە",correct:!1}],explanation:"ئاسانسۆری ئاسایی لە باری نائاساییدا بەکارناهێنرێت مەگەر بۆ ئەم کارە دیزاین کرابێت. کاتێک ئاگادارکەرەوەی ئاگر لێدەدات بە گشتی دەچێتە نهۆمێکی دیاریکراو و تەنها ئاگرکوژەکان دەتوانن بەکاری بهێنن. کەسێک کە ناتوانێت پلیکانە بەکاربهێنێت لە شوێنی ڕێککەوتوو چاوەڕێ دەکات، و بە ئاگرکوژەکان دەوترێت لە کوێیە."},{question:"ڕاهێنانت لەسەر هەڵگرتنی خەڵک نەکردووە و مەترسییەکی یەکسەر نییە. پیاوێک لەسەر کورسیی چەرخدار ناتوانێت پلیکانە بەکاربهێنێت. باشترین کار چییە؟",options:[{text:"یارمەتی بدە بچێتە شوێنی ڕێککەوتوو و بە ئاگرکوژەکان بڵێ لە کوێیە",correct:!0},{text:"لە کورسییەکە بەرزی بکەرەوە و بە تەنها و بە خێرایی بە پلیکانەدا دایبەزێنە",correct:!1},{text:"لە ڕاڕەوەکەدا جێی بهێڵە و بێ ئەوەی بە کەس بڵێیت بچۆ دەرەوە",correct:!1},{text:"بە ئاسانسۆر دایبەزێنە، چونکە پلیکانەکان زۆر تەسکن",correct:!1}],explanation:"هەڵگرتن بێ ڕاهێنان دەتوانێت هەردووکتان بریندار بکات. ئەگەر مەترسییەکی یەکسەر نەبوو، یارمەتی بدە بچێتە شوێنی سەلامەتی ڕێککەوتوو و دڵنیابە کە ئاگرکوژەکان بە وردی دەزانن لە کوێیە."}],media:[{kind:"image",src:"media/images/w7_assisted_evacuation.webp",title:"یارمەتیدانی دراوسێیەک بۆ چۆڵکردن",description:"یارمەتیدەرێک پیاوێکی نابینا بە باسک ڕێنمایی دەکات، و بەکارهێنەرێکی کورسیی چەرخدار لەگەڵ هاوڕێکەیدا لە شوێنی پەنا چاوەڕێ دەکات"}]},{id:25,icon:"TrafficCone",accent:"#ea580c",title:"لە شوێنی ڕووداوی ئۆتۆمبێل یان ئاگرگرتنی ئۆتۆمبێل",subtitle:"سەرەتا خۆت بپارێزە، پاشان پەیوەندی بکە و بە سەلامەتی یارمەتی بدە",summary:"زۆربەی ڕووداوەکانی ئۆتۆمبێل بە ئاگرگرتن کۆتایی نایەن، بەڵام شوێنی ڕووداو هەر مەترسیدارە: هاتوچۆی ئۆتۆمبێلەکان، سووتەمەنیی دزەکردوو و دووکەڵ دەتوانن زیان بەو کەسانە بگەیەنن کە بۆ یارمەتی دەوەستن. ئەم وانەیە نیشان دەدات چۆن سەرەتا خۆت بپارێزیت، چۆن پەیوەندی بە ١١٥ و ١٢٢ بکەیت و شوێنێک بڵێیت کە تیمەکان بتوانن بیدۆزنەوە، چۆن یارمەتی بریندارەکان بدەیت بێ ئەوەی برینەکانیان خراپتر بن، و ئەگەر ئۆتۆمبێلێک ئاگری گرت چی بکەیت.",blocks:[{heading:"سەرەتا خۆت بپارێزە",points:["تەنها لە شوێنێکی سەلامەتدا بوەستە، ئەگەر توانیت لە دەرەوەی شەقام، و ڕێگا لە ئەمبوڵانس و ئۆتۆمبێلەکانی ئاگرکوژێنەوە مەگرە.","گڵۆپەکانی ئاگادارکردنەوە (Hazard lights) هەڵبکە، بزوێنەری ئۆتۆمبێلەکەت بکوژێنەرەوە و داوا لە شۆفێرەکانی تر بکە بزوێنەرەکانیان بکوژێننەوە.","کەس لە نزیک ئۆتۆمبێلەکان جگەرە نەکێشێت و ئاگر هەڵنەکات: سووتەمەنی و زۆربەی شلەمەنییەکانی تری ئۆتۆمبێل بە ئاسانی ئاگر دەگرن.","ئەگەر جلیتکەی ڕووناکیدەرەوە (High-visibility vest)ت هەیە، لەبەری بکە، و هەرگیز لە نێوان ئۆتۆمبێلەکانی ڕووداوەکە و ئەو ئۆتۆمبێلانەی بە ڕێوەن مەوەستە.","ئەگەر سێگۆشەی ئاگادارکردنەوە (Warning triangle)ت لە ئۆتۆمبێلەکەدا هەیە، تەنها لە شوێنێک دایبنێ کە بتوانیت بێ چوونە ناو هاتوچۆوە دایبنێیت. یاسا ناوخۆییەکانی بەکارهێنان و دووریی ئەو لەلایەن دەزگاکانی هاتوچۆوە دیاری دەکرێن.","ئەو کەسانەی بریندار نەبوون، بەتایبەتی منداڵان، لە ئۆتۆمبێلەکان و شەقامەکە دوور بخەرەوە بۆ شوێنێکی سەلامەتتر."]},{heading:"پەیوەندی بە ١١٥ و ١٢٢ بکە",points:["یەکسەر پەیوەندی بکە: دوای ڕووداو، چەند خولەکێک دەتوانن جیاوازی لە نێوان ژیان و مردندا بکەن. بۆ ئاگر، کەسانی گیرخواردوو یان سووتەمەنیی دزەکردوو ١١٥، بۆ بریندارەکان ١٢٢، و ئەگەر هەردووکیان پێویست بوون، پەیوەندی بە هەردووکیانەوە بکە.","لە کوێ: ناوی ڕێگاکە یان ناوی ئەو دوو شارەی ڕێگاکە پێکیانەوە دەبەستێت، ئاراستەی ڕۆیشتنت و نیشانەیەکی دیاری نزیک، وەک پردێک، بەنزینخانەیەک، چوارڕیانێک یان تابلۆیەکی ڕێگا.","ئەگەر دڵنیا نیت لە کوێیت، نزیکترین تابلۆکانی ڕێگا بخوێنەرەوە یان ئەو شوێنە بەکاربهێنە کە نەخشەی مۆبایلەکەت نیشانی دەدات.","چی ڕوویداوە: چەند ئۆتۆمبێل، چەند کەس بریندار بوون یان گیریان خواردووە، و هەر مەترسییەک وەک ئاگر، دووکەڵ، سووتەمەنیی دزەکردوو یان بارهەڵگرێک بە تابلۆی مەترسییەوە.","ناو و ژمارەی تەلەفۆنەکەت بڵێ و تا پێت نەڵێن تەلەفۆنەکە دامەخە. ئەگەر کەس بریندار نەبوو و ئاگر، دزەی سووتەمەنی یان مەترسییەکی تر نەبوو، ڕووداوەکە لە ڕێگەی ١٠٤ بە پۆلیسی هاتوچۆ ڕابگەیەنە."]},{heading:"یارمەتی بریندارەکان بدە بێ ئەوەی بارودۆخەکە خراپتر بکەیت",points:["بریندار مەجووڵێنە مەگەر لە مەترسییەکی ڕاستەوخۆدا بێت، وەک ئاگر، دووکەڵی زۆر یان هاتوچۆیەک کە ناتوانرێت ڕابگیرێت: دوای ڕووداو، لەوانەیە مل یان پشت بریندار بێت.","ئەگەر بریندارەکە بەئاگا بوو، بە ئارامی قسەی لەگەڵ بکە، داوای لێ بکە سەر و ملی نەجووڵێنێت و پێی بڵێ کە یارمەتی لە ڕێگادایە.","کڵاوی پاراستن (Helmet) لە سەری ماتۆڕسوار دامەکەنە. تەنها ئەگەر هەناسە نەدات یان ڕێڕەوی هەوای گیرابێت لادەبرێت، ئەویش تەنها لەلایەن کەسانی ڕاهێنراوەوە، باشتر دوو کەس، کە سەر و مل نەجووڵێنن.","بە پارچە قوماشێکی پاک بە توندی پەستان بخە سەر خوێنبەربوونی زۆر و ڕێنماییەکانی کارمەندی پەیوەندیی ١٢٢ جێبەجێ بکە.","لەگەڵ بریندارەکان بمێنەوە تا تیمەکان دەگەن، پاشان ڕێنماییەکانیان جێبەجێ بکە."]},{heading:"ئەگەر ئۆتۆمبێلێک ئاگری گرت",points:["نیشانەکانی مەترسی: دووکەڵ یان گڕ، یان بۆنی سووتانی لاستیک یان پلاستیک. یەکسەر کار بکە.","ئەگەر لێدەخوڕیت، بە زووترین کات کە سەلامەت بێت لە قەراغ ڕێگا بوەستە و بزوێنەرەکە بکوژێنەرەوە.","هەمووان دەربهێنە و لانیکەم ٣٠ مەتر (١٠٠ پێ) لە ئۆتۆمبێلە ئاگرگرتووەکە دوور بکەونەوە، زۆر دوور لە هاتوچۆ و دەرەوەی دووکەڵەکە، و ئەگەر توانیت لەو لایەوە کە باکە لێیەوە دێت (Upwind).","هەرگیز بۆ ئۆتۆمبێلی ئاگرگرتوو مەگەڕێوە، نە بۆ مۆبایل، نە بۆ جانتا و نە بۆ بەڵگەنامە.","ئەگەر پێت وابوو ئاگرەکە لە ناوەوەیە، کاپۆت (سەرپۆشی بزوێنەر) یان سندووقی دواوە مەکەرەوە: هەوای تازە دەتوانێت ئاگرەکە گەورەتر بکات.","هەوڵ مەدە خۆت ئاگرەکە بکوژێنیتەوە. لە دوورییەکی سەلامەتەوە پەیوەندی بە ١١٥ بکە."]},{heading:"سووتەمەنیی دزەکردوو و بارە مەترسیدارەکان",points:["هەڵمی سووتەمەنی دەتوانێت لە پریشکێک، جگەرەیەک یان بزوێنەرێکی گەرمەوە ئاگر بگرێت: نە جگەرە، نە ئاگر، و بزوێنەرەکان کوژاوە بن.","خەڵک لە سووتەمەنیی دزەکردوو دوور بخەرەوە و بە ناویدا مەڕۆ.","بارهەڵگر یان تانکەرێک بە تابلۆی پرتەقاڵی یان نیشانەی مەترسییەوە: زۆر دوور بمێنەوە، هەوڵ مەدە خۆت کەس لێی ڕزگار بکەیت، بە ١١٥ بڵێ نیشانەکان چی دەردەخەن و لە نزیکیدا مۆبایل بەکارمەهێنە.","لە دەوری شوێنی ڕووداوەکە قەرەباڵغی دروست مەکە و ڤیدیۆی بریندارەکان مەگرە، و ئەگەر تەنها تێدەپەڕیت، چاوت لەسەر ڕێگا بێت."]}],tips:["جلیتکەی ڕووناکیدەرەوە، چرایەکی دەستی و جانتایەکی فریاکەوتنی سەرەتایی لە ئۆتۆمبێلەکەتدا دابنێ.","هەمیشە ئاگاداری ناوی ڕێگا، ئاراستەی خۆت و نیشانەکانی سەر ڕێگا بە.","ئۆتۆمبێلەکەت بەردەوام لای وەستایەکی شارەزا چاک بکە و هەر دزەیەکی شلەمەنی بدە بە پشکنین.","هەرگیز دەبەی سووتەمەنی یان بۆتڵی گاز لە بەشی سەرنشیناندا مەگوازەرەوە.","خولێکی فریاکەوتنی سەرەتایی ببینە بۆ ئەوەی بزانیت تا یارمەتی دەگات چی بکەیت."],warnings:["ئۆتۆمبێلی ئاگرگرتوو دەتوانێت بە خێرایی خەڵک تێیدا گیر بکات: یەکسەر دەرچۆ و هەرگیز مەگەڕێوە.","بریندارەکان مەجووڵێنە مەگەر لە مەترسییەکی ڕاستەوخۆدا بن، و کڵاوی پاراستن لە سەری ماتۆڕسوار دامەکەنە.","جگەرە، ئاگر و بزوێنەری کارا لە نزیک سووتەمەنیی دزەکردوو دەتوانن ئاگر هەڵبگیرسێنن."],media:[{kind:"image",src:"media/images/w7_crash_scene_safety.webp",title:"یارمەتیی سەلامەت لە شوێنی ڕووداو",description:"شۆفێرێک لە دەرەوەی شەقام بە گڵۆپی ئاگادارکردنەوەوە وەستاوە و پەیوەندی دەکات، و هەمووان زۆر دوور لە ئۆتۆمبێلێکی دووکەڵاوی چاوەڕێ دەکەن."}],activity:{prompt:"شەو لەسەر ڕێگایەک لە نێوان دوو شاردا، ئەو ئۆتۆمبێلەی لە پێشتەوەیە بەر پەرژینی قەراغ ڕێگا دەکەوێت. دووکەڵ لە ژێر کاپۆتەکەیەوە دەردەچێت. شۆفێرەکە بەئاگایە و هەوڵ دەدات دەرگاکە بکاتەوە. چی دەکەیت؟",options:[{text:"لە دواوەی، لە دەرەوەی شەقام بە سەلامەتی دەوەستم، گڵۆپەکانی ئاگادارکردنەوە هەڵدەکەم و بزوێنەرەکەم دەکوژێنمەوە، بەهۆی دووکەڵەکەوە یارمەتی شۆفێرەکە دەدەم دەربچێت و دوور بکەوێتەوە، پەیوەندی بە ١١٥ و ١٢٢ دەکەم و لانیکەم ٣٠ مەتر دوور لە ئۆتۆمبێلەکە چاوەڕێ دەکەین.",correct:!0,feedback:"دروستە: دووکەڵ واتە مەترسیی ڕاستەوخۆ، بۆیە یارمەتیدانی شۆفێرە بەئاگاکە بۆ دەرچوون ڕەوایە. سەرەتا خۆت دەپارێزیت، پەیوەندی بە هەردوو ژمارەکە دەکەیت و هەمووان لانیکەم ٣٠ مەتر دوور ڕادەگریت."},{text:"کاپۆتەکە دەکەمەوە بۆ ئەوەی ببینم دووکەڵەکە لە کوێوە دێت، تا بە وردی بە ١١٥ بڵێم چی ئاگری گرتووە.",correct:!1,feedback:"کردنەوەی کاپۆت هەوای تازە دەهێڵێتە ژوورەوە و ئاگرەکە دەتوانێت گەورە ببێت و بگاتە ڕووت. داخراوی بهێڵەوە، هەمووان دوور بخەرەوە و پەیوەندی بە ١١٥ بکە."},{text:"ڕاست لە تەنیشت ئۆتۆمبێلەکە لە هەمان هێڵی ڕێگادا دەوەستم و بزوێنەرەکەم بە کارکردوویی دەهێڵمەوە، تا بتوانین بە خێرایی بڕۆین.",correct:!1,feedback:"وەستان لە هێڵی ڕێگادا دەتخاتە بەردەم ئۆتۆمبێلەکانی تر، و بزوێنەری کارا لە نزیک ئۆتۆمبێلێکی دووکەڵاوی دەبێتە سەرچاوەیەکی تری ئاگرگرتن. لە دەرەوەی شەقام بوەستە و بزوێنەرەکە بکوژێنەرەوە."},{text:"چەند خولەکێک چاوەڕێ دەکەم بزانم دووکەڵەکە دەوەستێت پێش ئەوەی پەیوەندی بکەم، تا پەیوەندییەکی درۆ نەکەم.",correct:!1,feedback:"ڕووداوێکی ڕاستەقینە لەگەڵ دووکەڵ هەرگیز پەیوەندیی درۆ نییە. دوای ڕووداو خولەکەکان گرنگن، بۆیە یەکسەر پەیوەندی بە ١١٥ و ١٢٢ بکە."}]},quiz:[{question:"ئۆتۆمبێلێک ئاگری گرتووە. پێویستە هەمووان چەند دوور بکەونەوە؟",options:[{text:"لانیکەم ٣٠ مەتر (١٠٠ پێ)، دوور لە هاتوچۆ",correct:!0},{text:"نزیکەی ٥ مەتر، ئەوەندە نزیک کە ئاگرەکە ببینیت",correct:!1},{text:"ڕاست لە تەنیشت ئۆتۆمبێلەکە، تا سەرەتا جانتاکان دەربهێنیت",correct:!1},{text:"لە ناوەڕاستی شەقام، لە شوێنێک کە شۆفێرەکان بتبینن",correct:!1}],explanation:"ڕێنماییەکانی سەلامەتیی ئاگر (USFA و NFPA) دەڵێن هەمووان لانیکەم ٣٠ مەتر (١٠٠ پێ) لە ئۆتۆمبێلی ئاگرگرتوو و زۆر لە هاتوچۆ دوور بکەونەوە. هەرگیز بۆ کەلوپەل مەگەڕێوە."},{question:"دووکەڵ لە ژێر کاپۆتی ئۆتۆمبێلێکەوە دەردەچێت. پێویستە چی لە کاپۆتەکە بکەیت؟",options:[{text:"داخراوی بهێڵەوە: هەوا ئاگرەکە گەورەتر دەکات",correct:!0},{text:"بە تەواوی بیکەرەوە تا دووکەڵەکە خێراتر دەربچێت",correct:!1},{text:"کەمێک بەرزی بکەرەوە و ئاو بکە بە سەر بزوێنەرەکەدا",correct:!1},{text:"بیکەرەوە بۆ پشکنینی بزوێنەرەکە پێش ئەوەی پەیوەندی بە کەسەوە بکەیت",correct:!1}],explanation:"USFA دەڵێت: ئەگەر پێت وابوو ئاگر لە ژێر کاپۆت یان لە سندووقی دواوەدایە، مەیکەرەوە، چونکە هەوای تازە دەتوانێت ئاگرەکە گەورەتر بکات. دوور بکەوەرەوە و پەیوەندی بە ١١٥ بکە."},{question:"کەی دەتوانیت بریندار لە ئۆتۆمبێلی ڕووداوەکە دەربهێنیت؟",options:[{text:"تەنها ئەگەر لە مەترسییەکی ڕاستەوخۆدا بێت، وەک ئاگر یان هاتوچۆ",correct:!0},{text:"هەمیشە یەکسەر، تا بتوانێت لەسەر زەوی لە تەنیشت ئۆتۆمبێلەکە ڕاکشێت",correct:!1},{text:"هەر کاتێک دوو کەسی بەهێز هەبن بۆ هەڵگرتنی",correct:!1},{text:"کاتێک ئەمبوڵانس دوای دە خولەک نەگەیشتبێت",correct:!1}],explanation:"دوای ڕووداو لەوانەیە مل یان پشت بریندار بن. ڕێنماییەکانی فریاکەوتنی سەرەتایی دەڵێن تەنها ئەگەر شوێنەکە سەلامەت نەبوو بریندار بجووڵێنە، بۆ نموونە بەهۆی ئاگر، دووکەڵ یان هاتوچۆوە."},{question:"ماتۆڕسوارێک دوای ڕووداو لەسەر شەقامەکە کەوتووە. بەئاگایە و هەناسە دەدات. چی لە کڵاوەکەی دەکەیت؟",options:[{text:"لەسەر سەری بهێڵەوە و داوای لێ بکە سەری نەجووڵێنێت",correct:!0},{text:"یەکسەر دایبکەنە تا باشتر هەناسە بدات",correct:!1},{text:"شلی بکەرەوە و سەری بسووڕێنە بۆ پشکنینی ملی",correct:!1},{text:"بە خێرایی دایبکێشە پێش ئەوەی ئەمبوڵانس بگات",correct:!1}],explanation:"تا ماتۆڕسوارەکە هەناسە بدات، کڵاوەکە لەسەر سەری دەمێنێتەوە. تەنها ئەگەر هەناسە نەدات یان ڕێڕەوی هەوای گیرابێت لادەبرێت، ئەویش لەلایەن کەسانی ڕاهێنراوەوە، باشتر دوو کەس، کە سەر و مل نەجووڵێنن."},{question:"تیمی ١١٥ یان ١٢٢ پێویستە سەرەتا چی لە تۆ ببیستێت؟",options:[{text:"ڕێگاکە، ئاراستەکەت و نیشانەیەکی نزیک",correct:!0},{text:"جۆر، مۆدێل و ڕەنگی هەموو ئۆتۆمبێلەکانی ناو ڕووداوەکە",correct:!1},{text:"بۆچوونی خۆت لەسەر ئەوەی کێ و بۆچی هۆکاری ڕووداوەکە بوو",correct:!1},{text:"ئەو نەخۆشخانەیەی دەتەوێت بریندارەکانی بۆ ببەن",correct:!1}],explanation:"تیمەکان تەنها دەتوانن یارمەتی بدەن ئەگەر بتدۆزنەوە. سەرەتا شوێن بڵێ، پاشان چی ڕوویداوە، چەند کەس بریندارن، هەر مەترسییەک و ژمارەی تەلەفۆنەکەت، و تا پێت نەڵێن تەلەفۆنەکە دامەخە."}]},{id:26,icon:"Waves",accent:"#0e7490",title:"لافاو: ڕێنمایی بۆ خێزانەکان",subtitle:"ئاگادارکردنەوە، لافاوی لەناکاو، دەرچوون لە کاتی خۆیدا و گەڕانەوەی سەلامەت بۆ ماڵ",summary:"لافاو و لافاوی لەناکاو دەتوانن بە خێرایی بێن، هەندێک جار بە ئاگادارکردنەوەیەکی کەم یان بێ ئاگادارکردنەوە، و زۆربەی ئەو کەسانەی لە لافاودا دەمرن بە خنکان دەمرن. ئەم وانەیە یارمەتی خێزانەکەت دەدات ئامادە بێت، بەپێی ئاگادارکردنەوەکان کار بکات، لە ئاوی لافاو دوور بمێنێتەوە، لە کاتی خۆیدا دەربچێت و بە سەلامەتی بگەڕێتەوە ماڵ.",blocks:[{heading:"ئاگادارکردنەوە و ئامادەباشی",points:["ڕاگەیاندنە فەرمییەکانی بەرگریی شارستانی و دەسەڵاتداران لە ڕادیۆ، تەلەفزیۆن و پەڕە فەرمییەکانیان پەیڕەو بکە، و بەپێی دەنگۆ کار مەکە.","لە بەرگریی شارستانی و دەسەڵاتە ناوخۆییەکان بپرسە ئاگادارکردنەوەکانی لافاو و فەرمانەکانی چۆڵکردن لە شوێنی نیشتەجێبوونت چۆن ڕادەگەیەنرێن.","پلانێکی خێزانی دابنێ: بۆ کام شوێنی بەرز دەچن، بە کام ڕێگادا دەڕۆن و چۆن پەیوەندی بە یەکترەوە دەکەن.","جانتای باری نائاسایی ئامادە بکە: ئاوی خواردنەوە، خواردنی خراپنەبوو، دەرمان، چرای دەستی، ڕادیۆ، باتری، کەرەستەی فریاکەوتنی سەرەتایی و کۆپی بەڵگەنامە گرنگەکان لە کیسەیەکی دژە ئاودا.","پلان بۆ منداڵان، بەساڵاچووان، کەسانی خاوەن پێداویستی تایبەت و هەر کەسێک کە بۆ جووڵە پێویستی بە یارمەتییە دابنێ."]},{heading:"لافاوی لەناکاو لە دۆڵ و ڕووبارە وشکەکاندا",points:["لافاوی لەناکاو زۆربەی جار لە ماوەی ٦ کاتژمێردا دوای بارانی بەخوڕ دێت، هەندێک جار لە چەند خولەکێکدا، و لەوانەیە بارانەکە زۆر دوور لە تۆ باریبێت.","ڕووبارێکی وشک یان دۆڵێک دەتوانێت لە چەند خولەکێکدا پڕ ببێت لە ئاوی خێرا، تەنانەت ئەگەر لە شوێنی تۆ باران نەبارێت.","کاتێک پێشبینیی باران هەیە یان زریان نزیکە، لە شوێنی نزمی تەنیشت ئاو یان لە ناو ڕووبارێکی وشکدا چادر هەڵمەدە، سەیران مەکە و ئۆتۆمبێل ڕامەگرە.","ئەگەر ئاو دەستی بە بەرزبوونەوە کرد، یەکسەر بڕۆ بۆ شوێنێکی بەرزتر: بە پێ سەرکەوە، هەوڵ مەدە بە ئۆتۆمبێل دەربچیت.","بە شەو بینینی هاتنی لافاو قورسە، بۆیە پێش تاریکبوون ئاگادارکردنەوەکان بە جددی وەربگرە."]},{heading:"بگەڕێوە، خۆت مەخنکێنە",points:["هەرگیز بە پێ، بە مەلەکردن یان بە ئۆتۆمبێل مەچۆ ناو ئاوی لافاوەوە: ١٥ سم ئاوی جووڵاو دەتوانێت مرۆڤێکی گەورە بخاتە سەر زەوی و ٣٠ سم دەتوانێت زۆربەی ئۆتۆمبێلەکان ڕابماڵێت.","بگەڕێوە و ڕێگایەکی تر بدۆزەرەوە. لەوانەیە ڕێگای ژێر ئاوەکە ڕووخابێت، و هەرگیز بە دەوری ئەو بەربەستانەدا لێمەخوڕە کە ڕێگایەکی لافاوگرتوو دادەخەن.","لەسەر پردەکانی سەر ئاوی خێرا مەمێنەوە.","ئاوی لافاو دەتوانێت چاڵ، پاشماوەی مەترسیدار و مەترسیی کارەبا بشارێتەوە، و زۆربەی جار پیسە.","ئەگەر کەسێک لە ناو ئاودا بوو، بە دوایدا مەچۆ ناو ئاو: پەیوەندی بە ١١٥ و ١٢٢ بکە، پاشان لە شوێنێکی سەلامەتەوە دار یان پەتێکی بۆ درێژ بکە یان شتێکی سەرئاوکەوتووی بۆ فڕێ بدە."]},{heading:"کەی و چۆن دەربچیت",points:["ئەگەر دەسەڵاتداران پێیان وتیت، یەکسەر دەرچۆ، و ئەوەندە زوو دەرچۆ کە ئاو گیرت نەخات.","جانتای باری نائاسایی لەگەڵ خۆت ببە، ئەو ڕێگایانە بگرە کە پێشنیار کراون و ڕێگای کورت بەکارمەهێنە: لەوانەیە داخراو یان لافاوگرتوو بن.","کارەبا پێش دەرچوون تەنها بکوژێنەرەوە ئەگەر پێت وترا و بتوانیت بە سەلامەتی بیکەیت. هەرگیز دەست لە سویچ و ئامێری کارەبایی مەدە کاتێک تەڕیت یان لە ناو ئاودا وەستاویت.","گاز: ئەگەر بۆنی گازت کرد، دەست لە هیچ سویچێک مەدە؛ دەرچۆ، خەڵک ئاگادار بکەرەوە و لە دەرەوە پەیوەندی بە ١١٥ بکە. ڤاڵڤی گاز تەنها دابخە ئەگەر نزیک بوو و بتوانیت بێ چوونە ناو ئەو شوێنەی گازی تێدا کۆبووەتەوە پێی بگەیت.","ئەگەر ئاو لە ناو بینایەکدا گیری کردیت، بڕۆ بۆ بەرزترین ئاستی سەلامەت و پەیوەندی بە ١١٥ بکە و شوێنەکەت بە وردی بڵێ. مەچۆ ناو ژوورێکی داخراوی ژێر سەربان کە ئاو دەتوانێت لەوێدا گیرت بخات؛ تەنها لە کاتی پێویستدا بڕۆ سەر سەربان."]},{heading:"گەڕانەوەی سەلامەت بۆ ماڵ",points:["تەنها کاتێک بگەڕێوە کە دەسەڵاتداران دەڵێن سەلامەتە. ئەگەر خانووەکە زیانی بەرکەوتبێت، مەچۆ ژوورەوە تا شارەزایەکی بیناسازی نەیپشکنێت.","کارەبا کوژاوە بهێڵەوە تا کارەباچییەکی شارەزا خانووەکە دەپشکنێت. ئەگەر بۆ گەیشتن بە سویچی سەرەکی پێویست بوو بچیتە ناو ئاو، لە جیاتی ئەوە پەیوەندی بە کارەباچییەکەوە بکە.","دەست لە ئامێری کارەبایی مەدە ئەگەر تەڕ بوو یان تۆ لە ناو ئاودا وەستابوویت.","بەپێی ڕێنمایی ناوخۆیی کار بکە دەربارەی ئەوەی ئاوی بۆری بۆ خواردنەوە سەلامەتە یان نا، و هەر خواردنێک کە لەوانەیە بەر ئاوی لافاو کەوتبێت فڕێ بدە: ئەگەر گومانت هەبوو، فڕێی بدە.","هەوای خانووەکە بگۆڕە و وشکی بکەرەوە. ئەگەر بۆ چەند ڕۆژێک داخراو و تەڕ مابێتەوە، چاوەڕێی کەڕوو (Mold) بکە، و لە کاتی پاککردنەوەدا پۆتینی لاستیکی و دەستکێش لەبەر بکە.","مۆلیدە تەنها لە دەرەوە بەکاربهێنە، لانیکەم ٦ مەتر (٢٠ پێ) دوور لە دەرگا، پەنجەرە و کونی هەوا، و هەرگیز لە ناو خانوودا، تەنانەت ئەگەر دەرگاکان کراوە بن."]}],tips:["بزانە ئایا ماڵ، شوێنی کار یان قوتابخانەکەت لە شوێنێکی نزم یان نزیک دۆڵێکە کە لافاوی تێدا دەبێت.","لەسەر خاڵێکی کۆبوونەوە لە شوێنێکی بەرز و خزمێک لە دەرەوەی ناوچەکە کە هەمووان بتوانن پەیوەندیی پێوە بکەن ڕێک بکەون.","کاتێک پێشبینیی بارانی بەخوڕ هەیە، مۆبایلەکەت پڕ بکە و ڕادیۆیەکی باتریدار ئامادە بکە.","پێش و دوای لافاو سەردانی دراوسێ بەساڵاچووەکان و کەسانی خاوەن پێداویستی تایبەت بکە.","پێکەوە ڕاهێنان لەسەر پلانی خێزانی بکەن."],warnings:["هەرگیز بە پێ، بە مەلەکردن یان بە ئۆتۆمبێل مەچۆ ناو ئاوی لافاوەوە: بگەڕێوە و ڕێگایەکی تر بدۆزەرەوە.","کارەبا و ئاو پێکەوە دەتوانن بکوژن: هەرگیز کاتێک تەڕیت یان لە ناو ئاودایت دەست لە سویچ و ئامێری کارەبایی مەدە.","منداڵان هەرگیز نابێت دوای باران لە ئاوی لافاو، جۆگە یان کەناڵەکانی ئاودا یاری بکەن."],media:[{kind:"image",src:"media/images/w7_flood_family_higher_ground.webp",title:"خێزانەکان بەرەو شوێنی بەرز دەڕۆن",description:"خێزانێک بە جانتای باری نائاساییەوە بە پێ بەرەو گردێک سەردەکەوێت، دوور لە ئاوی دۆڵێک کە دوای باران بەرز دەبێتەوە."}],activity:{prompt:"هەموو شەو لە چیاکان بارانی بەخوڕ باری. خێزانەکەت لە دۆڵێک لە تەنیشت ڕووبارێکی وشک سەیران دەکەن، و لە شوێنی ئێوە باران نابارێت. لەناکاو ڕووبارەکە دەست دەکات بە پڕبوون لە ئاوی لیخن. چی دەکەن؟",options:[{text:"شتەکانمان جێدەهێڵین و یەکسەر بە پێ دەچینە شوێنێکی بەرزتر دوور لە ڕووبارەکە، پاشان ئەگەر کەسێک لە مەترسیدا بوو پەیوەندی بە ١١٥ دەکەین.",correct:!0,feedback:"لافاوی لەناکاو دەتوانێت لە چەند خولەکێکدا بەرز ببێتەوە. جێهێشتنی هەموو شتێک و یەکسەر بە پێ چوون بۆ شوێنی بەرزتر سەلامەتترین هەڵبژاردنە؛ کەلوپەل دەگۆڕدرێن، ژیان نا."},{text:"بە خێرایی هەموو شتێک دەخەینە ناو ئۆتۆمبێلەکە و بە ڕێگای بنی دۆڵەکەدا دەردەچین.",correct:!1,feedback:"کۆکردنەوەی شتەکان خولەکەکان بەفیڕۆ دەدات، و لەوانەیە ڕێگای بنی دۆڵەکە یەکەم جار ئاو بیگرێت: ٣٠ سم ئاوی جووڵاو دەتوانێت ئۆتۆمبێلێک ڕابماڵێت. بە پێ سەرکەوە، بە ئۆتۆمبێل دەرمەچۆ."},{text:"چاوەڕێ دەکەین و سەیر دەکەین، چونکە لێرە باران نابارێت و ئاوەکە زۆر بەرز نابێتەوە.",correct:!1,feedback:"لافاوی لەناکاو زۆربەی جار لە بارانێکی زۆر دوورەوە دێت. ڕووبارێکی وشک دەتوانێت لە چەند خولەکێکدا ببێتە لافاوێکی بەهێز، بۆیە ئێستا بڕۆ بۆ شوێنی بەرز."},{text:"بە خێرایی ڕووبارەکە دەپەڕینەوە بۆ ئەو دیو پێش ئەوەی ئاوەکە قووڵ ببێت.",correct:!1,feedback:"هەرگیز مەچۆ ناو ئاوی جووڵاوەوە: تەنها ١٥ سم دەتوانێت مرۆڤێکی گەورە بخاتە سەر زەوی. لە هەمان لای خۆتەوە بڕۆ بۆ شوێنێکی بەرزتر."}]},quiz:[{question:"ئاوی لافاوی جووڵاو پێویستە چەند قووڵ بێت بۆ ئەوەی مرۆڤێکی گەورە بخاتە سەر زەوی؟",options:[{text:"نزیکەی ١٥ سم",correct:!0},{text:"نزیکەی ١ مەتر",correct:!1},{text:"نزیکەی ٥٠ سم",correct:!1},{text:"تەنها لە کەمەر بەرزتر",correct:!1}],explanation:"خزمەتگوزاریی نیشتمانیی کەشوهەوای ئەمریکا (NWS) ئاگادار دەکاتەوە کە نزیکەی ١٥ سم (٦ ئینچ) ئاوی خێرا دەتوانێت مرۆڤێکی گەورە بخات و نزیکەی ٣٠ سم (١٢ ئینچ) دەتوانێت زۆربەی ئۆتۆمبێلەکان ڕابماڵێت."},{question:"ڕێگای پێشتەوە بە ئاوی جووڵاو داپۆشراوە. چی دەکەیت؟",options:[{text:"بگەڕێوە و ڕێگایەکی تر بگرە",correct:!0},{text:"بە هێواشی و بە گێرێکی نزم پێیدا تێپەڕە",correct:!1},{text:"سەرەتا بە پێ بپەڕەوە بۆ تاقیکردنەوەی قووڵی",correct:!1},{text:"بە دوای ئۆتۆمبێلی پێشەوەدا پێیدا تێپەڕە",correct:!1}],explanation:"بگەڕێوە، خۆت مەخنکێنە: ناتوانیت ببینیت ئاوەکە چەند قووڵ یان چەند خێرایە، یان ئایا ڕێگای ژێری ڕووخاوە. هەرگیز بە پێ یان بە ئۆتۆمبێل مەچۆ ناو ئاوی لافاوەوە."},{question:"پێش دەرچوون لە ماڵ لە کاتی لافاودا، کەی پێویستە کارەبا بکوژێنیتەوە؟",options:[{text:"تەنها ئەگەر پێت وترا و لە کاتی کردنیدا وشک بمێنیتەوە",correct:!0},{text:"هەمیشە، تەنانەت ئەگەر پێویست بێت لە ناو ئاودا بوەستیت بۆ گەیشتن پێی",correct:!1},{text:"هەرگیز: هەموو ئامێرەکان هەڵکراو بهێڵەوە تا خانووەکە ڕووناک بمێنێت",correct:!1},{text:"تەنها دوای ئەوەی ئاو زەوی خانووەکەی داپۆشی",correct:!1}],explanation:"کارەبا پێش دەرچوون تەنها بکوژێنەرەوە ئەگەر پێت وترا و بتوانیت بە سەلامەتی بیکەیت. هەرگیز کاتێک تەڕیت یان لە ناو ئاودا وەستاویت دەست لە سویچ و ئامێری کارەبایی مەدە."},{question:"دوای لافاو، خێزانەکەت کەی دەتوانێت بگەڕێتەوە ماڵ؟",options:[{text:"کاتێک دەسەڵاتداران دەڵێن سەلامەتە",correct:!0},{text:"هەر کە باران وەستا",correct:!1},{text:"کاتێک ئاوی دەرەوە لە ئەژنۆت نزمتر بێت",correct:!1},{text:"بەیانیی دواتر، هەر زیانێک هەبێت",correct:!1}],explanation:"تەنها کاتێک بگەڕێوە کە دەسەڵاتداران دەڵێن سەلامەتە. پێویستە شارەزایەکی بیناسازی خانووی زیانلێکەوتوو و کارەباچییەک کارەباکە بپشکنن، پێش ئەوەی بەکاری بهێنیت."},{question:"دوای لافاو، مۆلیدە لە کوێ دەتوانرێت بەکاربهێنرێت؟",options:[{text:"لە دەرەوە، لانیکەم ٦ مەتر دوور لە دەرگا و پەنجەرەکان",correct:!0},{text:"لە گەراجدا، ئەگەر دەرگای گەراجەکە کراوە بێت",correct:!1},{text:"لە ناو خانوودا، ڕاست لە تەنیشت پەنجەرەیەکی کراوە",correct:!1},{text:"لە ڕاڕەودا، بەو مەرجەی هەموو دەرگاکان کراوە بن",correct:!1}],explanation:"مۆلیدە گازی ژەهراویی مۆنۆکسیدی کاربۆن (CO) دەردەدات کە بێ ڕەنگ و بێ بۆنە. تەنها لە دەرەوە بەکاری بهێنە، لانیکەم ٦ مەتر (٢٠ پێ) دوور لە دەرگا، پەنجەرە و کونی هەوا، و هەرگیز لە ژوورەوە، تەنانەت ئەگەر دەرگاکان کراوە بن."}]},{id:27,icon:"CloudLightning",accent:"#7c3aed",title:"کەشوهەوای توند بۆ هەموو خەڵک",subtitle:"گەرما، هەورەتریشقە، تەپوتۆز، بای توند، بەفر و سەهۆڵ",summary:"کەشوهەوای توند دەتوانێت لە ماوەیەکی کورتدا زیان بە خەڵک بگەیەنێت. لە ناوچەکەی ئێمەدا شەپۆلی گەرما، زریانی هەورەتریشقەدار، تەپوتۆز، بای توند، بەفر و سەهۆڵ هەن. ئەم وانەیە کارە سەرەکییە سەلامەتەکان بۆ هەر یەکێکیان دەخاتە ڕوو. هەمیشە ئاگادارکردنەوەکانی کەشوهەوای دەسەڵاتداران و ڕێنماییەکانی بەرگریی شارستانی پەیڕەو بکە.",blocks:[{heading:"شەپۆلی گەرما",points:["بەساڵاچووان، منداڵە بچووکەکان و کەسانی خاوەن نەخۆشیی درێژخایەن لە مەترسییەکی گەورەتردان. لە کاتی شەپۆلی گەرمادا زۆر جار سەردانیان بکە.","بە درێژایی ڕۆژ بەردەوام ئاو بخۆرەوە، تەنانەت پێش ئەوەی تینووت بێت، و لە گەرمترین کاتژمێرەکاندا خۆت لە کاری قورس و وەرزش بپارێزە.","ماندووبوون بە گەرما (Heat exhaustion): ئارەقکردنەوەی زۆر، لاوازی، سەرگێژخواردن، سەرئێشە، دڵتێکهەڵاتن و تینوێتی. کەسەکە بگوازەرەوە بۆ شوێنێکی فێنک، بە ئاو ساردی بکەرەوە و ئەگەر بە تەواوی بەئاگا بوو قومە ئاوی بدەرێ. داوای یارمەتیی پزیشکی بکە ئەگەر ڕشایەوە، ئەگەر نیشانەکان خراپتر بوون یان لە کاتژمێرێک زیاتر بەردەوام بوون.","گەرمالێدان (Heatstroke): شێواوی، ڕەفتاری نائاسایی، قسەکردنی قورس، گرژبوون یان کەوتن لە گەرمادا؛ پێست دەکرێت گەرم و وشک بێت یان هێشتا ئارەقەی هەبێت. پەیوەندی بە ١٢٢ بکە و یەکسەر کەسەکە سارد بکەرەوە: باشترین ڕێگا ئەوەیە لەشی تا مل لە ناو ئاوی سارددا بێت بۆ ١٥ خولەک یان تا هۆشی دیسان ڕوون دەبێتەوە، کامیان زووتر بێت؛ ئەگەر نەکرا، دووشی سارد، خاولیی تەڕی سارد، کیسەی سەهۆڵ و باوەشێن بەکاربهێنە. هیچ خواردنەوەیەک مەدە بە کەسێکی شێواو.","هەرگیز منداڵێک، یان هەر کەسێک، لە ئۆتۆمبێلێکی وەستاودا بەجێ مەهێڵە، تەنانەت بۆ یەک خولەکیش: ناوی ئۆتۆمبێلەکە دەتوانێت بە خێرایی بە شێوەیەکی مەترسیدار گەرم ببێت."]},{heading:"هەورەتریشقە",points:["کاتێک هەورە دەگرمێت، بچۆ ژوورەوە: ئەگەر گوێت لە هەورەگرمە بێت، هەورەتریشقە دەتوانێت بگاتە تۆ. لە کاتی زریانی هەورەتریشقەدا هیچ شوێنێکی سەلامەت لە دەرەوە نییە.","پەنا ببە بۆ بینایەکی بەهێز یان ئۆتۆمبێلێکی خاوەن سەقفی کانزایی و پەنجەرەی داخراو، و تا ٣٠ خولەک دوای دوایین هەورەگرمە لە ژوورەوە بمێنەوە.","ئەگەر نەتتوانی بگەیتە پەناگەیەک، لە سەری گرد، دەشتی کراوە، دارە بەرزە تاکەکان، ئاو و پەرژینی کانزایی دوور بکەوەرەوە. چادر هیچ پاراستنێک نادات.","لە ژوورەوە، لە پەنجەرە و دەرگاکان دوور بکەوەرەوە، تەلەفۆنی وایەردار بەکارمەهێنە و تا زریانەکە تێدەپەڕێت دووش مەکە و قاپ مەشۆ."]},{heading:"تەپوتۆز",points:["لە ماڵەوە، لە ژوورەوە بمێنەوە و پەنجەرە و دەرگاکان دابخە.","ساوا، بەساڵاچووان و کەسانی تووشی ڕەبۆ (Asthma) یان کێشەی تری هەناسە پێویستیان بە چاودێریی زیاترە: لە ژوورەوە دەمێننەوە، و نەخۆشانی ڕەبۆ پلانی ڕەبۆی خۆیان جێبەجێ دەکەن و ئەو هەناسەپێدەرە (Inhaler)ی پزیشک بۆی نووسیون لەگەڵ خۆیان هەڵدەگرن.","لێخوڕین: مەچۆ ناو تەپوتۆزەوە. ئەگەر بینین کەم بووەوە، هەتا دەتوانیت لە شەقامەکە دوور دەربچۆ، بوەستە، هەموو گڵۆپەکانی ئۆتۆمبێلەکە بکوژێنەرەوە، بریکی دەستی ڕابکێشە و پێت لەسەر بریک هەڵبگرە. هەرگیز لەسەر خودی شەقامەکە مەوەستە.","کاتێک وەستاویت دەبێت گڵۆپەکانت کوژاوە بن: شۆفێرەکانی دواوە لەوانەیە بە دوای ڕووناکییەکانتدا بێن و لێت بدەن."]},{heading:"بای توند",points:["پێش با، شتە شلەکانی سەر سەربان، باڵکۆن و حەوشە ببەستەوە یان ببە ژوورەوە، تا با فڕێیان نەدات بۆ سەر خەڵک یان پەنجەرەکان.","لە کاتی بادا، بچۆ ناو بینایەکی بەهێز و بڕۆ بۆ ژوورێکی ناوەوە دوور لە پەنجەرەکان.","لەوانەیە وایەرە کەوتووەکانی کارەبا کارەبایان تێدا بێت: لە خۆیان و هەر شتێک کە بەریان کەوتووە نزیک مەبەرەوە، خەڵکیش دوور بخەرەوە و پەیوەندی بە ١١٥ بکە.","ئەگەر لێدەخوڕیت، سووکانەکە بە هەردوو دەست بگرە، خێرایی کەم بکەرەوە و لە بارهەڵگر و پاسەکان دوور بمێنەوە."]},{heading:"بەفر، سەهۆڵ و گەرمکردنەوە",points:["سۆبە: ڕێگایەک بۆ هەوای پاک بۆ ژوورەکە کراوە بهێڵەوە، ئاگادارکەرەوەی CO دابنێ، هەرگیز خانوو بە فڕنی گاز گەرم مەکەرەوە و هەرگیز مۆلیدە یان ئاگری خەڵوز لە ژوورەوە بەکارمەهێنە.","سەرئێشە، سەرگێژخواردن، دڵتێکهەڵاتن یان شێواوی لە نزیک سۆبە دەتوانێت نیشانەی ژەهراویبوون بە مۆنۆکسیدی کاربۆن (CO) بێت: یەکسەر هەمووان بۆ هەوای پاک دەربهێنە و لە دەرەوە پەیوەندی بە ١١٥ و ١٢٢ بکە.","لەسەر سەهۆڵ، پێڵاوی نەخلیسک لەبەر بکە، هەنگاوی کورت بنێ و هێواش بڕۆ.","لە کاتی بەفر و سەهۆڵدا، ئەگەر توانیت لێمەخوڕە. ئەگەر پێویست بوو، هێواش لێبخوڕە، تەنانەت ئەگەر ڕێگاکە تەنها تەڕ دیار بێت، و بەتانی، ئاو، چرای دەستی و مۆبایلێکی پڕکراو لە ئۆتۆمبێلەکەدا دابنێ."]}],tips:["پێشبینیی کەشوهەوا و ئاگادارکردنەوەکانی دەسەڵاتداران و بەرگریی شارستانی پەیڕەو بکە.","لە کاتەکانی گەرما و سەرمای توند، زۆر جار سەردانی دراوسێ و خزمە بەساڵاچووەکان بکە.","هەر کە پێشبینیی بای توند کرا، شتە شلەکانی سەر سەربان و باڵکۆن ببەستەوە.","چرایەکی دەستی، ڕادیۆیەکی باتریدار و مۆبایلێکی پڕکراو بۆ زریانەکان ئامادە بکە.","با سۆبە و ئۆجاغەکان بپشکنرێن و هەر شتێک کە ئاگر دەگرێت لێیان دوور بخەرەوە."],warnings:["هەرگیز منداڵ لە ئۆتۆمبێلێکی وەستاودا بەجێ مەهێڵە، تەنانەت بۆ یەک خولەکیش.","کاتێک هەورە دەگرمێت، بچۆ ژوورەوە: هیچ شوێنێک لە دەرەوە سەلامەت نییە.","هەرگیز مۆلیدە یان ئاگری خەڵوز لە ژوورەوە بەکارمەهێنە، و هەرگیز خانوو بە فڕنی گاز گەرم مەکەرەوە."],media:[{kind:"image",src:"media/images/w7_severe_weather_actions.webp",title:"کارە سەلامەتەکان لە کەشوهەوای توندا",description:"چوار وێنە: ساردکردنەوەی کەسێک لە سێبەردا لە کاتی شەپۆلی گەرما، خێزانێک کاتێک زریانی هەورەتریشقە نزیک دەبێتەوە دەچێتە ژوورەوە، ئۆتۆمبێلێک لە دەرەوەی شەقام بە گڵۆپی کوژاوەوە لە کاتی تەپوتۆزدا وەستاوە، و کەسێک لە وایەرێکی کارەبای کەوتوو دوور دەمێنێتەوە."}],activity:{prompt:"لە دوانیوەڕۆیەکی زۆر گەرمدا، دراوسێ بەساڵاچووەکەت لە باخچەکەیدا کاری دەکرد. ئێستا شێواوە، بە شێوەیەکی نائاسایی قسە دەکات و پێستی زۆر گەرمە. چی دەکەیت؟",options:[{text:"پەیوەندی بە ١٢٢ دەکەم، دەیبەمە سێبەر یان ژوورێکی فێنک و یەکسەر بە ئاوی سارد، خاولیی تەڕ و باوەشێن دەست بە ساردکردنەوەی دەکەم، و هیچ خواردنەوەیەکی نادەمێ.",correct:!0,feedback:"شێواوی لە گەرمادا واتە گەرمالێدان، کە باری نائاساییە. پەیوەندیکردن بە ١٢٢ و ساردکردنەوەی یەکسەری دەتوانێت ژیانی ڕزگار بکات؛ نابێت خواردنەوە بدرێت بە کەسێکی شێواو."},{text:"پەرداخێکی گەورە ئاوی ساردی دەدەمێ بیخواتەوە و دەیهێڵم لەسەر کورسییەک لە باخچەکەدا پشوو بدات.",correct:!1,feedback:"نابێت خواردنەوە بدرێت بە کەسێکی شێواو، و باخچەکە لە گەرمادا دەیهێڵێتەوە. پەیوەندی بە ١٢٢ بکە، بیبە بۆ شوێنێکی فێنک و یەکسەر ساردی بکەرەوە."},{text:"یارمەتی دەدەم لە ژوورەوە بخەوێت تا باش دەبێتەوە، و ئێوارە دیسان سەردانی دەکەمەوە.",correct:!1,feedback:"گەرمالێدان دەتوانێت بکوژێت ئەگەر ساردکردنەوە دوا بکەوێت. مەیهێڵە بخەوێت: پەیوەندی بە ١٢٢ بکە و ئێستا دەست بە ساردکردنەوە بکە."},{text:"یەکسەر خۆم بە ئۆتۆمبێل دەیبەمە نەخۆشخانە، بێ ئەوەی سەرەتا بوەستم و ساردی بکەمەوە.",correct:!1,feedback:"لە گەرمالێدانیدا، ساردکردنەوە یەکەمە و گواستنەوە دواتر. پەیوەندی بە ١٢٢ بکە و یەکسەر دەست بە ساردکردنەوە بکە؛ کارمەندی پەیوەندییەکە ڕێنماییت دەکات."}]},quiz:[{question:"لە کاتی زریانی هەورەتریشقەدا، کەی پێویستە بچیتە ژوورەوە؟",options:[{text:"هەر کە گوێت لە هەورەگرمە بوو",correct:!0},{text:"تەنها کاتێک باران توند دەبێت",correct:!1},{text:"تەنها کاتێک هەورەتریشقە ڕاست لە سەرتەوە بێت",correct:!1},{text:"کاتێک با دەست بە توندی دەکات",correct:!1}],explanation:"ئەگەر گوێت لە هەورەگرمە بێت، ئەوەندە نزیکیت کە هەورەتریشقە دەتوانێت لێت بدات. کاتێک هەورە دەگرمێت، بچۆ ژوورەوە: لە کاتی زریانی هەورەتریشقەدا هیچ شوێنێکی سەلامەت لە دەرەوە نییە."},{question:"دوای دوایین هەورەگرمە، پێویستە چەند چاوەڕێ بکەیت پێش ئەوەی بگەڕێیتەوە دەرەوە؟",options:[{text:"٣٠ خولەک",correct:!0},{text:"٥ خولەک",correct:!1},{text:"تا باران دەوەستێت",correct:!1},{text:"پێویست بە چاوەڕێکردن ناکات",correct:!1}],explanation:"هەورەتریشقە دەتوانێت دوای کەمبوونەوەی بارانیش لێ بدات. خزمەتگوزاریی نیشتمانیی کەشوهەوای ئەمریکا (NWS) دەڵێت دوای دوایین هەورەتریشقە یان هەورەگرمە ٣٠ خولەک چاوەڕێ بکە پێش ئەوەی بگەڕێیتەوە دەرەوە."},{question:"کاتێک لێدەخوڕیت، تەپوتۆزێک لەناکاو بینین کەم دەکاتەوە. سەلامەتترین کار چییە؟",options:[{text:"زۆر لە شەقامەکە دوور دەربچۆ، بوەستە و هەموو گڵۆپەکان بکوژێنەرەوە",correct:!0},{text:"لە هێڵی خۆتدا بوەستە و گڵۆپەکانی ئاگادارکردنەوە هەڵبکە",correct:!1},{text:"خێراییەکەت زیاد بکە تا بە زووترین کات لە تەپوتۆزەکە دەربچیت",correct:!1},{text:"بە دوای گڵۆپەکانی دواوەی ئۆتۆمبێلی پێشەوەتدا بڕۆ",correct:!1}],explanation:"هەرگیز لەسەر خودی شەقامەکە مەوەستە. هەتا دەتوانیت دەربچۆ، هەموو گڵۆپەکان بکوژێنەرەوە، بریکی دەستی ڕابکێشە و پێت لەسەر بریک هەڵبگرە، تا شۆفێرەکانی دواوە بە دوای ڕووناکییەکانتدا نەیەن و لێت نەدەن (NWS، Pull aside, stay alive)."},{question:"کامیان نیشانەی گەرمالێدانە، نەک ماندووبوون بە گەرما؟",options:[{text:"شێواوی یان ڕەفتاری نائاسایی لە گەرمادا",correct:!0},{text:"تینوێتی دوای ڕۆژێکی درێژی کارکردن لەبەر خۆر",correct:!1},{text:"ئارەقکردنەوەی زۆر و ماندووبوون دوای کار",correct:!1},{text:"سەرئێشەیەکی سووک لە کاتی دانیشتن لە ژوورێکی گەرمدا",correct:!1}],explanation:"شێواوی، ڕەفتاری نائاسایی، گرژبوون یان کەوتن لە گەرمادا واتە گەرمالێدان، کە باری نائاسایی و مەترسیدارە بۆ ژیان: پەیوەندی بە ١٢٢ بکە و یەکسەر کەسەکە سارد بکەرەوە. تینوێتی، ئارەقکردنەوەی زۆر و سەرئێشەی سووک لەگەڵ ماندووبوون بە گەرما دەگونجێن."},{question:"دوای زریان وایەرێکی کارەبا دەبینیت لەسەر زەوی کەوتووە. چی دەکەیت؟",options:[{text:"دوور بمێنەوە، خەڵک دوور بخەرەوە و پەیوەندی بە ١١٥ بکە",correct:!0},{text:"بە دارێکی وشک لای بدە",correct:!1},{text:"ئەگەر پریشکی لێ دەرنەچوو، بە وریاییەوە بەسەریدا بپەڕەوە",correct:!1},{text:"بە هێواشی بە ئۆتۆمبێل بەسەریدا تێپەڕە",correct:!1}],explanation:"وایەری کارەبای کەوتوو، و هەر شت یان ئاوێک کە بەری کەوتووە، لەوانەیە کارەبای تێدا بێت تەنانەت ئەگەر پریشکیشی لێ دەرنەچێت. هەرگیز دەستی لێ مەدە، مەیجووڵێنە و بە ئۆتۆمبێل بەسەریدا مەڕۆ: هەمووان دوور بخەرەوە و پەیوەندی بە ١١٥ بکە."}]},{id:28,icon:"Truck",accent:"#4d7c0f",title:"سەلامەتی لە کشتوکاڵ و ژیانی گوندەکاندا",subtitle:"دەرمانی مێروو، تراکتۆر و ئامێرەکان، دانەوێڵە و کا، و مەترسییە شاراوەکانی ناو خاک",summary:"کاری کشتوکاڵ مەترسیی تایبەت بە خۆی هەیە: ئەو ژەهرانەی بۆ پاراستنی بەرهەم بەکاردەهێنرێن، ئامێری قورس کە دەتوانن وەربگەڕێن یان جلوبەرگ بگرن، کۆگای دانەوێڵە و کا کە دەتوانن کەسێک لە ناو خۆیاندا بگرن و بیخنکێنن یان ئاگر بگرن، و تەقەمەنیی کۆن لە ناو خاکدا. ئەو منداڵانەی لە نزیک کارەکە یاری دەکەن یان سوار دەبن لە مەترسییەکی تایبەتدان. ئەم وانەیە ڕوون دەکاتەوە کە خێزانی جووتیاران و کرێکارانی کشتوکاڵ چۆن خۆیان بپارێزن و کاتێک شتێک بە هەڵەدا دەچێت چی بکەن.",blocks:[{heading:"دەرمانی مێروو: بە سەلامەتی هەڵیبگرە",body:"زۆرێک لە ژەهراویبوونەکان لەبەر ئەوە ڕوودەدەن کە دەرمانێکی مێروو لە بەردەستدا بووە یان وەک خواردنەوە دەرکەوتووە:",points:["دەرمانی مێروو لە شوێنێکی قفڵدراودا، دوور لە دەستی منداڵان هەڵبگرە، و هەرگیز لەگەڵ خواردن، ئالیکی ئاژەڵ یان دەرماندا یان لە نزیکیاندا دایمەنێ.","هەر دەرمانێکی مێروو لە قاپە ڕەسەنەکەی خۆیدا و لەگەڵ لەیبڵەکەیدا بهێڵەرەوە. هەرگیز مەیخە ناو بوتڵی خواردنەوە، پەرداخ یان قاپی خواردن: لەوانەیە کەسێک بیخواتەوە.","دەرمانی مێرووی زۆر ژەهراوی یان چڕکراوە لە ماڵدا دامەنێ؛ لە کۆگایەکی جیا و قفڵدراودا هەڵیانبگرە.","هەرگیز قاپی بەتاڵی دەرمانی مێروو بۆ ئاو، خواردن یان ئالیکی ئاژەڵ بەکارمەهێنە. بەو شێوەیەی لەیبڵەکە و لایەنە ناوخۆییەکان دەڵێن لەناویان ببە.","تۆوی دەرمانکراو و ژەهری مشک دەتوانن وەک دانەوێڵەی ئاسایی دەربکەون: لە شوێنێکی قفڵدراودا، دوور لە منداڵان و ئاژەڵان هەڵیانبگرە."]},{heading:"بەکارهێنانی دەرمانی مێروو بە سەلامەتی",points:["پێش کردنەوەی قاپەکە هەموو لەیبڵەکە بخوێنەرەوە و وەک خۆی جێبەجێی بکە: بڕەکە، تێکەڵکردن، کەرەستەی پاراستن و ئەو ماوەیەی خەڵک دەبێت لە شوێنی دەرمانکراو دوور بن.","ئەو جلوبەرگی پاراستنەی لەیبڵەکە داوای دەکات لەبەر بکە، وەک دەستکێشی ئاونەچوو، پانتۆڵی درێژ و قۆڵی درێژ.","لە کاتی تێکەڵکردن و پرژاندندا، و تا ئەو کاتەی لەسەر لەیبڵەکە نووسراوە تێدەپەڕێت، منداڵان، خەڵکی تر و ئاژەڵان دوور بخەرەوە.","دوای پرژاندن، یەکسەر جلەکانت بگۆڕە و دەستەکانت بشۆ. جلی کار و ئامێری پرژاندن لەو شوێنەدا جێمەهێڵە کە منداڵان یاری تێدا دەکەن."]},{heading:"ئەگەر کەسێک بە دەرمانی مێروو ژەهراوی بوو",body:`سەرگێژخواردن، ماندوێتی، تەڵخبوونی بینین، دڵتێکهەڵاتن، وشکبوونی قوڕگ، هەناسەتەنگی، سووتانەوەی چاو، خوورانی پێست یان لاوازیی ماسولکەکان لە کاتی کارکردن بە دەرمانی مێروو یان دوای ئەوە دەتوانن نیشانەی ژەهراویبوون بن.

١. سەرەتا خۆت بپارێزە: دەستکێش لەبەر بکە و بە دەستی ڕووت دەست لە دەرمانەکە مەدە. کەسەکە لە دەرمانەکە دوور بخەرەوە بۆ هەوای پاک.
٢. یەکسەر پەیوەندی بە ١٢٢ بکە، تەنانەت ئەگەر کەسەکە باش دیار بێت، و قاپەکە یان لەیبڵەکەی بپارێزە تا نیشانی تیمی ئەمبولانس و پزیشکەکانی بدەیت.
٣. ئەگەر قووت درابێت: مەیهێنەرەوە سەر ڕشانەوە، و هیچ خواردن و خواردنەوەیەکی مەدەرێ مەگەر پزیشک بڵێت.
٤. لەسەر پێست یان لە چاودا: جلە پیسبووەکان دابکەنە و پێستەکە، یان چاوە کراوەکە، بە ئاوی ڕەوان و زۆر بۆ لانیکەم ١٥ خولەک بشۆ.
٥. ئەگەر کەسەکە بێهۆش بوو بەڵام هەناسەی ئاسایی دەدات و هیچ برینێکی لە مل، پشت، سمت یان ئێسکی حەوز نییە، لەسەر لا دایبنێ و بەردەوام هەناسەی بپشکنە. ئەگەر هەناسەی ئاسایی وەستا، دەست بە CPR بکە (وانەی «ژەهراویبوون لە ماڵەوە» ببینە).`},{heading:"تراکتۆر و ئامێرەکان",body:"وەرگەڕان، کەوتنی خەڵک لە ژێر تایەکاندا و گیرخواردنی جلوبەرگ لە میلی سووڕاوەی گواستنەوەی هێز (PTO) زۆربەی برینە قورسەکانی تراکتۆر دروست دەکەن.",points:["تراکتۆرێک بەکاربهێنە کە چوارچێوەی پاراستنی لە وەرگەڕان هەبێت (ROPS: شیشێکی پاراستن یان کابینەیەکی سەلامەت) و هەمیشە پشتێنی سەلامەتی ببەستە: پێکەوە باشترین دەرفەت دەدەنە شۆفێر کە لە وەرگەڕان ڕزگاری بێت. فرۆشیارێکی شارەزا دەتوانێت چوارچێوەیەک بۆ زۆرێک لە تراکتۆرە کۆنەکان دابنێت.","لە جۆگە، لێوار و چاڵ دوور بکەوەرەوە، لەسەر لێژایی زۆر تیژ مەڕۆ، و لە کاتی سووڕانەوەدا و لەسەر زەویی ناڕێک، خلیسک یان قوڕاوی هێواش لێبخوڕە.","هەموو پارێزەرەکانی میلی PTO و ئامێرەکان لە شوێنی خۆیاندا بهێڵەرەوە. قژی درێژ ببەستەوە و لە نزیک پارچە جووڵاوەکان جلی فشەڵ لەبەر مەکە.","پێش پاککردنەوە، ڕێکخستن یان کردنەوەی گیرانی ئامێرێک، بزوێنەرەکە بکوژێنەوە و چاوەڕێ بکە تا میلەکە و هەموو پارچە جووڵاوەکان دەوەستن.","هیچ کەسێک سواری تراکتۆر نابێت مەگەر کورسی و پشتێنی سەلامەتیی بۆ ئەو کەسە تێدا بێت. منداڵان هەرگیز سواری تراکتۆر و ئامێر نابن و لە نزیکیان یاری ناکەن.","پێش هەڵکردنی بزوێنەر یان PTO، دڵنیا بە کە هەموو کەسێک، بەتایبەتی منداڵان، زۆر لە ئامێرەکە دوورن."]},{heading:"دانەوێڵە، کا و گیای وشک",points:["هەرگیز مەچۆ ناو کۆگا، سایلۆ یان تریلەیەکی دانەوێڵە کاتێک دانەوێڵەکە دەجووڵێت یان بەتاڵ دەکرێت: دانەوێڵەی ڕەوان وەک لمی نوقمکەر کار دەکات و دەتوانێت لە چەند چرکەیەکدا کەسێک بشارێتەوە. هەرگیز لەسەر دانەوێڵە مەڕۆ بۆ ئەوەی بڕوات.","ئەو دانەوێڵەیەی چینێکی ڕەقی لەسەر دروست بووە یان بووەتە کۆمەڵەیەکی بەرز و لێژ دەتوانێت لەناکاو بەسەر هەر کەسێکدا بڕووخێت کە لەسەری یان لە تەنیشتی وەستاوە.","منداڵان هەرگیز لە کۆگای دانەوێڵە، تریلەی دانەوێڵە یان کۆمەڵەی کا و گیادا یاری ناکەن.","تەنها کاتێک گیا بە تەواوی وشک بوو بیکە بە بەستە و هەڵیبگرە: گیای تەڕ یان سەوز دەتوانێت لە ناوەوە گەرم ببێت و خۆی ئاگر بگرێت، لە دوو هەفتە تا سێ مانگ یان زیاتر دوای بەستەکردن.","نیشانەکانی ئاگادارکردنەوە: هەڵم لە کۆمەڵەکەوە بەرز دەبێتەوە، کەڕوو، یان بۆنی سووتان، بۆنی شێداری یان بۆنێکی شیرینی وەک کەرامێل. ئەگەر دووکەڵت بینی یان بۆنت کرد، یان بەشێک لە کۆمەڵەکە زۆر گەرم بوو، لێکی مەکەرەوە: خەڵک دوور بخەرەوە و پەیوەندی بە ١١٥ بکە.","کۆمەڵەی گیا و کا لە ماڵ، ئامێر، سووتەمەنی، مادەی کیمیایی و تەلی کارەبا دوور بهێڵەرەوە."]},{heading:"تەقەمەنی و ئاگری کێڵگە",points:["ئەگەر کێڵان یان هەڵکەندن شتێکی نەناسراوی دەرخست، یەکسەر کارەکە ڕابگرە. دەستی لێ مەدە و مەیجووڵێنە، هەمووان دوور بخەرەوە، پێش بەکارهێنانی تەلەفۆن زۆر دوور بکەوەرەوە، و بە ١١٥ ڕایبگەیەنە (وانەی «مین و تەقەمەنیی نەتەقیو: سەلامەت بمێنەرەوە» ببینە).","ئەو زەوییە مەکێڵە و ئاژەڵی تێدا مەلەوەڕێنە کە وەک مەترسیدار نیشانە کراوە یان خەڵک خۆیانی لێ دوور دەگرن. شوێنێک کە نیشانەی ئاگادارکردنەوەی نییە بە پێویستی سەلامەت نییە: کێڵگەیەکی بەکارنەهاتوو و گژوگیا لێ ڕواو لە تەنیشت کێڵگە چێنراوەکان لەوانەیە مینی تێدا شاردرابێتەوە.","ئەگەر پێت وایە لە ناوچەیەکی مینڕێژکراودایت: بوەستە، مەجووڵێ، بانگی یارمەتی بکە و چاوەڕێی تیمێکی ڕاهێنراو بکە.","تراکتۆر و ئۆتۆمبێل لەسەر گیای وشک یان قەسەڵ ڕامەگرە: بۆری دووکەڵی گەرم دەتوانێت ئاگری تێبەردات. ئاگرەکانی کاتی دروێنە لە وانەی «ئاگری کێڵگە، قەسەڵ و ڕووەکی وشک» ڕوون کراونەتەوە."]}],tips:["دەرمانی مێروو لە قاپە ڕەسەنە لەیبڵدارەکانیاندا، لە شوێنێکی قفڵدراودا هەڵبگرە.","پێش هەر بەکارهێنانێک لەیبڵەکە بخوێنەرەوە و ئەو جلوبەرگی پاراستنەی داوای دەکات لەبەر بکە.","لەسەر تراکتۆرێکی خاوەن شیشی پاراستن پشتێنی سەلامەتی ببەستە، و هەموو پارێزەرەکان لە شوێنی خۆیان بهێڵەرەوە.","پێش پاککردنەوە یان کردنەوەی گیرانی ئامێرێک، بزوێنەرەکە بکوژێنەوە و چاوەڕێ بکە تا هەموو شتێک دەوەستێت.","وەک خێزان ڕێک بکەون منداڵان لە کوێ یاری بکەن: دوور لە ئامێر، کۆگای دانەوێڵە، کۆمەڵەی گیا و کێڵگەی دەرمانکراو."],warnings:["هەرگیز دەرمانی مێروو یان سووتەمەنی مەخە ناو بوتڵی خواردنەوە یان قاپی خواردن.","هەرگیز مەهێڵە منداڵ سواری تراکتۆر ببێت یان لە نزیک ئامێرێکی کارکردوو یاری بکات.","هەرگیز مەچۆ ناو کۆگا یان سایلۆی دانەوێڵە کاتێک دانەوێڵەکە دەجووڵێت، و هەرگیز لەسەر دانەوێڵە مەڕۆ بۆ ئەوەی بڕوات."],activity:{prompt:"دراوسێکەت خەریکە کێڵگەیەک لەسەر لێژاییەک دەکێڵێت. کوڕە ٨ ساڵانەکەی داوا دەکات لەسەر تایەی تراکتۆرەکە دابنیشێت و لەگەڵی سوار ببێت، و باوکەکە دەڵێت تەنها بۆ چەند خولەکێکە. چ ئامۆژگارییەکی دەکەیت؟",options:[{text:"کوڕەکە سواری تراکتۆر نابێت و لە کێڵگەکە دوور دەمێنێتەوە؛ باوکەکە پشتێنی سەلامەتی دەبەستێت و لە هەر لێژاییەکی زۆر تیژ دوور دەکەوێتەوە.",correct:!0,feedback:"منداڵ دەتوانێت بکەوێتە ژێر تایەکان یان گاسنەکە، و تراکتۆر دەتوانێت لەسەر لێژایی لە چەند چرکەیەکدا وەربگەڕێت. منداڵان زۆر لە ئامێری کارکردوو دوور دەمێننەوە، و شۆفێر پشتێنی سەلامەتی دەبەستێت."},{text:"کوڕەکە دەتوانێت سوار ببێت ئەگەر لەسەر تایەکە دابنیشێت و بە هەردوو دەست توند خۆی بگرێت.",correct:!1,feedback:"منداڵان لەسەر تایەکان دەکەون و دەکەونە ژێر تایەکان یان گاسنەکە. کەس بێ کورسی و پشتێنی سەلامەتیی خۆی سوار نابێت، و منداڵان هەرگیز سوار نابن."},{text:"کوڕەکە دەتوانێت سوار ببێت بە مەرجێک باوکی لەسەر لێژاییەکە زۆر هێواش لێبخوڕێت.",correct:!1,feedback:"وەرگەڕان دەتوانێت لە چەند چرکەیەکدا ڕووبدات، تەنانەت بە خێرایی کەمیش، و لێژایی مەترسییەکە زیاتر دەکات. کوڕەکە سواری تراکتۆر نابێت."},{text:"کوڕەکە دەتوانێت بە دوای گاسنەکەدا بڕوات بۆ ئەوەی ببینێت چۆن خاک هەڵدەگێڕێتەوە.",correct:!1,feedback:"منداڵێک کە لە نزیک گاسنێکی جووڵاو دەڕوات دەتوانێت بکەوێتە ژێری یان تێیدا گیر بخوات. منداڵان زۆر لە ئامێری کارکردوو دوور دەمێننەوە."}]},quiz:[{question:"دەرمانی مێروو دەبێت لە کوێ هەڵبگیرێت؟",options:[{text:"لە شوێنێکی قفڵدراو، لە قاپی ڕەسەنی لەیبڵداردا، دوور لە خواردن",correct:!0},{text:"لە بوتڵێکی پاکی خواردنەوەدا، و ناوەکەی بە قەڵەم لەسەری بنووسە",correct:!1},{text:"لەسەر ڕەفێکی بەرزی چێشتخانە، کە خێزانەکە هەمیشە بتوانێت بیبینێت",correct:!1},{text:"لە سندوقێکی کراوەدا لە حەوشە، کە هەوا بۆنەکەی دوور ببات",correct:!1}],explanation:"لە بوتڵی خواردنەوە یان چێشتخانەدا، دەرمانی مێروو دەتوانێت بە خواردنەوە دابنرێت یان دەستی منداڵان پێی بگات. لە قاپە ڕەسەنەکەی و لەگەڵ لەیبڵەکەیدا، لە شوێنێکی قفڵدراو، دوور لە خواردن و ئالیکی ئاژەڵ هەڵیبگرە."},{question:"کرێکارێکی کشتوکاڵ دوای پرژاندنی دەرمان سەری دەگێژێت، باش نابینێت و دڵی تێکدێت. سەرەتا چی دەکەیت؟",options:[{text:"دەیبەم بۆ هەوای پاک و پەیوەندی بە ١٢٢ دەکەم، و لەیبڵەکە دەپارێزم",correct:!0},{text:"پەرداخێک شیری دەدەمێ بۆ ئەوەی ژەهرەکە لە گەدەیدا بشوات",correct:!1},{text:"یەکسەر دەیهێنمەوە سەر ڕشانەوە، پاشان دەهێڵم لە سێبەردا پشوو بدات",correct:!1},{text:"دەهێڵم پرژاندنەکە تەواو بکات، پاشان لە ماڵەوە خۆی بشوات",correct:!1}],explanation:"ئەمانە دەتوانن نیشانەی ژەهراویبوون بە دەرمانی مێروو بن. کەسەکە لە دەرمانەکە دوور بخەرەوە، پەیوەندی بە ١٢٢ بکە و قاپەکە یان لەیبڵەکە بۆ پزیشکەکان بپارێزە؛ هەرگیز مەیهێنەرەوە سەر ڕشانەوە و شیر یان چارەسەری ماڵەوەی مەدەرێ."},{question:"بۆچی شۆفێری تراکتۆرێکی خاوەن شیشی پاراستن (ROPS) دەبێت پشتێنی سەلامەتی ببەستێت؟",options:[{text:"بۆ ئەوەی لە ناو ناوچە پارێزراوەکەدا بمێنێتەوە ئەگەر تراکتۆرەکە وەرگەڕا",correct:!0},{text:"بۆ ئەوەی کاتێک لەسەر ڕێگای سەرەکی لێدەخوڕێت سزا نەدرێت",correct:!1},{text:"چونکە پشتێنی سەلامەتی سووتەمەنیی بزوێنەر کەم دەکاتەوە",correct:!1},{text:"پێویست نییە، چونکە شیشی پاراستن بە تەنها بەسە",correct:!1}],explanation:"شیشی پاراستن تەنها شوێنی دەوروبەری کورسییەکە دەپارێزێت. بەبێ پشتێنی سەلامەتی، شۆفێرەکە دەتوانێت فڕێ بدرێتە دەرەوە و تراکتۆرەکە لە ژێر خۆیدا بیپلیشێنێتەوە."},{question:"پێش ئەوەی گیرانی ئامێرێک بکەیتەوە کە بە میلی PTO کار دەکات، دەبێت چی بکەیت؟",options:[{text:"بزوێنەرەکە بکوژێنەوە و چاوەڕێ بکە تا هەموو پارچەکان دەوەستن",correct:!0},{text:"خێرایی بزوێنەرەکە کەم بکەرەوە و دەستەکانت لە نزیک پارێزەرەکە بهێڵەرەوە",correct:!1},{text:"پارێزەرەکە لاببە بۆ ئەوەی بە ئاسانی بگەیتە شوێنی گیرانەکە",correct:!1},{text:"داوا لە منداڵێک بکە چاودێریی میلەکە بکات و ئەگەر خێرا بوو هاوار بکات",correct:!1}],explanation:"میلێکی سووڕاو دەتوانێت لە ساتێکدا جل یان قژ بگرێت. بزوێنەرەکە بکوژێنەوە، چاوەڕێ بکە تا هەموو شتێک دەوەستێت و هەموو پارێزەرەکان لە شوێنی خۆیان بهێڵەرەوە."},{question:"لە کاتی کێڵاندا، شتێکی ئاسنی ژەنگاوی دەبینیت کە وەک گولەتۆپێکی کۆن دیارە. چی دەکەیت؟",options:[{text:"کارەکە ڕادەگرم، هەمووان دوور دەخەمەوە و بە ١١٥ ڕایدەگەیەنم",correct:!0},{text:"دەیبەمە لێواری کێڵگەکە بۆ ئەوەی کار بەردەوام بێت",correct:!1},{text:"لە دەوری دەیکێڵم، چونکە گولەیەکی کۆن و ژەنگاوی ناتەقێتەوە",correct:!1},{text:"بە خاکەناز لێی دەدەم بۆ ئەوەی بزانم ناوەکەی بەتاڵە یان نا",correct:!1}],explanation:"تەقەمەنیی کۆن و ژەنگاوی هێشتا دەتوانێت بتەقێتەوە ئەگەر بجووڵێنرێت یان لێی بدرێت. دەستی لێ مەدە: کارەکە ڕابگرە، هەمووان دوور بخەرەوە، پێش تەلەفۆنکردن زۆر دوور بکەوەرەوە و ڕایبگەیەنە."}],media:[{kind:"image",src:"media/images/w8_farm_safety.webp",title:"کاری سەلامەت لە کێڵگە",description:"جووتیارێک بە پشتێنی سەلامەتی تراکتۆرێکی خاوەن شیشی پاراستن لێدەخوڕێت و منداڵەکانی لە پشت پەرژینی حەوشەوە سەیر دەکەن؛ دەرمانی مێروو لە قاپە لەیبڵدارەکانیاندا لە کۆگایەکی قفڵدراودان."}]},{id:29,icon:"Mountain",accent:"#15803d",title:"سەیران و گەشتی شاخاوی",subtitle:"سەیران، کەباب، پیاسە و چادرهەڵدان بەبێ ئاگر، کەوتن یان ونبوون",summary:"زۆرێک لە خێزانەکان لە بەهار و هاویندا حەز لە سەیران، پیاسە و چادرهەڵدان لە شاخ و دۆڵەکان دەکەن. زۆربەی ڕووداوەکانی دەرەوە بە کەمێک پلاندانان ڕێگرییان لێ دەکرێت: ئاگرێک لە شوێنی هەڵە هەڵکرابێت، کەوتن لەسەر بەرد، کەسێک ون ببێت، پێوەدانی مار یان دووپشک، لافاوێکی لەناکاو یان زریانێک. ئەم وانەیە ڕوون دەکاتەوە چۆن گەشتێکی سەلامەت پلان بکەیت و ئەگەر لە شوێنێکی دوور لە یارمەتی شتێک بە هەڵەدا چوو چی بکەیت.",blocks:[{heading:"پێش ئەوەی بڕۆیت",points:["بە کەسێک کە لەگەڵت نایەت بڵێ بۆ کوێ دەچیت، بە چ ڕێگایەکدا دەڕۆیت و کەی دەگەڕێیتەوە. داوای لێ بکە ئەگەر لە کاتی خۆیدا نەگەڕایتەوە، بانگی یارمەتی بکات.","پێشبینیی کەشوهەوا بۆ ئەو شوێنەی دەچیتە ئەوێ بپشکنە، نەک تەنها بۆ شارەکەی خۆت، و ئەگەر زریان یان بارانی بەخوڕ پێشبینی کرا پلانەکەت بگۆڕە.","ئاوی خواردنەوەی پێویست، خواردن، مۆبایلێکی بارگاویکراو، چرایەکی دەستی، جانتای فریاکەوتنی سەرەتایی، جلی گەرم و فیکەیەک بۆ هەر کەسێک، بەتایبەتی بۆ منداڵان، لەگەڵ خۆت ببە.","لەسەر ئەو ڕێگا و جادانە بمێنەرەوە کە خەڵک زۆر پێیاندا دەڕۆن. لەو ناوچانەی شەڕیان تێدا بووە، ڕێگای بەکارنەهاتوو و زەویی گژوگیا لێ ڕواو لەوانەیە مین یان تەقەمەنییان تێدا شاردرابێتەوە: ڕێز لە هەموو نیشانەیەکی ئاگادارکردنەوە بگرە (وانەی «مین و تەقەمەنیی نەتەقیو: سەلامەت بمێنەرەوە» ببینە).","هەمیشە وەک گرووپ پێکەوە بن، و منداڵان لە شوێنێکدا بهێڵەرەوە کە بیانبینیت."]},{heading:"ئاگری سەیران و کەباب",points:["ئاگر یان کەباب تەنها لەو شوێنە هەڵبکە کە ڕێگەپێدراوە. پێش ڕۆیشتن پرسیار لە یاسا ناوخۆییەکان بکە.","هەرگیز ئاگر لەسەر گیای وشک یان لە ڕۆژێکی وشک و باداردا هەڵمەکە. لە دەوریدا بۆ لانیکەم ٣ مەتر (١٠ پێ) گیا و گەڵای وشک پاک بکەرەوە، و لانیکەم ٨ مەتر (٢٥ پێ) لە دار، چادر، ئۆتۆمبێل و هەر شتێکی تری سووتاو دووری بخەرەوە.","ئاگرەکە بچووک بهێڵەرەوە و هەرگیز بە تەنها جێی مەهێڵە، تەنانەت بۆ چەند خولەکێکیش. منداڵان لانیکەم ١ مەتر (٣ پێ) لێی دوور بخەرەوە، و هەرگیز بەنزین یان سووتەمەنیی تر بۆ هەڵکردن یان گەشکردنەوەی بەکارمەهێنە.","ئاو، یان خاکەناز و خاک، لە نزیک خۆت دابنێ. پێش ڕۆیشتن، ئاو بکە بەسەر هەموو پشکۆکاندا، تێکیبدە و دووبارە ئاو بکە، تا هیچ گەرمی، سووری، گڕ یان دووکەڵێک نەمێنێت.","هەرگیز مەنقەڵی کەباب، ئاگری خەڵووز یان پشکۆی گەرم مەبە ناو چادر، ئۆتۆمبێل یان ماڵ، تەنانەت بۆ گەرمبوونەوەش: دەتوانن ببنە هۆی ئاگر یان ژەهراویبوون بە مۆنۆکسیدی کاربۆن (CO)، کە دەکوژێت."]},{heading:"ئەگەر ون بوویت",body:`ڕزگارکردن دەتوانێت چەند کاتژمێرێک بخایەنێت، بۆیە وا بکە بە ئاسانی بدۆزرێیتەوە:

١. بوەستە و هێمن بە. لە شوێنی خۆت بمێنەرەوە: جووڵە دۆزینەوەت بۆ ڕزگارکەران قورستر دەکات. تەنها ئەگەر لە مەترسییەکی ڕاستەوخۆدا بوویت بجووڵێ، بۆ نموونە لە ئاوێکی بەرزبووەوە یان لە ئاگر.
٢. پێکەوە بن؛ کەس بە تەنها ناڕوات بۆ دۆزینەوەی ڕێگاکە.
٣. ئەگەر هێڵ هەبوو، پەیوەندی بە ١١٥ بکە و بڵێ لە کوێوە دەستت پێکرد، دواجار کە زانیت لە کوێیت لە کوێ بوویت، چی لە دەوروبەرت دەبینیت، چەند کەسن و ئایا کەسێک بریندار یان نەخۆش هەیە. ئەگەر توانیت، شوێنەکەت لە مۆبایلەکەوە بنێرە.
٤. سێ جار فیکە لێبدە، پشوو بدە و دووبارەی بکەرەوە: دەنگی فیکە لە دەنگی تۆ دوورتر دەڕوات و وزەت دەپارێزێت. جلی ڕەنگ گەش لەبەر بکە یان ڕایخە بۆ ئەوەی ببینرێیت.
٥. پەناگەیەک لە خۆر، باران یان سەرما بدۆزەرەوە و چاوەڕێی یارمەتی بکە. ئەگەر هەر مەترسییەکی ئاگری دارستان هەبوو، ئاگر هەڵمەکە.

فێری منداڵانی بکە: ئەگەر ون بوویت، لە شوێنی خۆت بمێنەرەوە، «دارێک لە باوەش بگرە» (یان بەردێکی گەورە) و فیکەکەت لێبدە.`},{heading:"کەوتن و بەرد",points:["لەسەر ڕێگاکە بمێنەرەوە و ئاگات لە شوێنی پێی خۆت بێت، بەتایبەتی لە نزیک لێواری هەڵدێر و لەسەر زەویی خلیسک.","لە نزیک تاڤگە و جۆگەکان سەر بەردەکان مەکەوە: پرژەی ئاو و قەوزە خلیسکیان دەکەن، و خەڵک لەوێ کەوتوون و گیانیان لەدەست داوە.","منداڵان لە نزیک خۆت بهێڵەرەوە و لە نزیک لێوارە بەرزەکان و ئاو هەمیشە چاودێرییان بکە.","ئەگەر کەسێک کەوت و لەوانەیە سەر، مل یان پشتی بریندار بووبێت، مەیجووڵێنە مەگەر شوێنەکە مەترسیدار بێت. پەیوەندی بە ١٢٢ بکە، بێجووڵە و گەرم ڕایبگرە و چاوەڕێی یارمەتی بکە."]},{heading:"مار و دووپشک",points:["پێڵاوی داخراو یان پۆتین و پانتۆڵی درێژ لەبەر بکە. دەستت مەخە ژێر بەرد، کۆمەڵەی دار یان کونەوە، و تا دەتوانیت لە گیای بەرز و کۆمەڵەی گەڵا دوور بکەوەرەوە.","پێش بەکارهێنان، پێڵاو، جل و جێگای نووستنەکەت ڕابتەکێنە.","هەرگیز دەست لە مار مەدە، مەیگرە و هەوڵی کوشتنی مەدە.","پێوەدانی مار: کەسەکە هێمن و بێجووڵە ڕابگرە، پێش ئاوسان ئەنگوستیلە، کاتژمێر و هەر شتێکی تەنگ لابەرە، و بە خێرایی بیگەیەنە نەخۆشخانە: پەیوەندی بە ١٢٢ بکە، و مەهێڵە خۆی لێبخوڕێت. برینەکە مەبڕە و مەیمژە، بەندێکی توند مەبەستە، سەهۆڵی لەسەر دامەنێ و چارەسەری میللی بەکارمەهێنە.","پێوەدانی دووپشک: کەسەکە هێمن ڕابگرە. دەتوانیت کیسێکی سارد کە لە پارچە قوماشێکدا پێچراوە لەسەر شوێنی پێوەدانەکە دابنێیت، بەڵام ئەندامەکە مەخە ناو ئاوی سەهۆڵەوە، و هیچ دەرمانێکی مەدەرێ. بۆ هەر پێوەدانێک یارمەتیی پزیشکی وەربگرە، و ئەگەر کەسەکە هەناسەتەنگی، لەرزینی ماسولکە، هاتنی لیک، قسەکردنی قورس یان نائارامییەکی سەیری هەبوو، یەکسەر پەیوەندی بە ١٢٢ بکە."]},{heading:"لافاو، هەورەتریشقە و گەرما",points:["هەرگیز لە ناو ڕووبارێکی وشک یان لە شوێنی نزمی تەنیشت جۆگە چادر هەڵمەدە، سەیران مەکە و ئۆتۆمبێل ڕامەگرە: لافاوی لەناکاو دەتوانێت لە چەند خولەکێکدا بێت، تەنانەت ئەگەر باران زۆر دوور لە تۆ ببارێت. ئەگەر ئاو دەستی بە بەرزبوونەوە کرد، یەکسەر بڕۆ بۆ شوێنێکی بەرزتر.","هەرگیز بە پێ یان بە ئۆتۆمبێل مەچۆ ناو ئاوی ڕەوانەوە (وانەی «لافاو: ڕێنمایی بۆ خێزانەکان» ببینە).","کاتێک هەورە دەگرمێت، بچۆ ژوورەوە: هیچ شوێنێکی سەلامەت لە دەرەوە نییە. پەنا ببە بۆ بینایەکی بەهێز یان ئۆتۆمبێلێکی خاوەن سەقفی کانزایی؛ چادر یان سێبەری سەیران هیچ پاراستنێک نادەن. ٣٠ خولەک دوای دوایین هەورەگرمە چاوەڕێ بکە.","ئەگەر نەتتوانی بگەیتە پەناگەیەک، لە سەری گرد، سەری زنجیرە شاخ، دەشتی کراوە، دارە بەرزە تاکەکان، ئاو و پەرژینی کانزایی دوور بکەوەرەوە، و ئەگەر گرووپن، لە یەک بڵاو ببنەوە.","ئاوی زۆر لەگەڵ خۆت ببە، لە سێبەردا پشوو بدە و لە گەرمترین کاتژمێرەکاندا پیاسەی قورس مەکە. تێکچوونی هۆش یان کەوتن لە گەرمادا دەتوانێت گەرمالێدان بێت: پەیوەندی بە ١٢٢ بکە و یەکسەر کەسەکە سارد بکەرەوە (وانەی «سەلامەتی لە هاویندا» ببینە)."]}],tips:["بە کەسێک بڵێ بۆ کوێ دەچیت و کەی دەگەڕێیتەوە.","فیکەیەک بدە بە هەر منداڵێک و فێری بکە ئەگەر ون بوو لە شوێنی خۆی بمێنێتەوە.","ئاگر تەنها لەو شوێنە هەڵبکە کە ڕێگەپێدراوە، و پێش ڕۆیشتن بە ئاو بە تەواوی بیکوژێنەوە.","پێش لەبەرکردنی پێڵاو و جلەکانت، ڕایانبتەکێنە.","پێشبینیی کەشوهەوا بۆ ئەو شوێنەی دەچیتە ئەوێ بپشکنە، و کاتێک زریان دێت بگەڕێوە."],warnings:["هەرگیز ئاگر یان کەبابی هەڵکراو بە تەنها جێمەهێڵە، و هەرگیز لەسەر گیای وشک یان لە ڕۆژێکی باداردا هەڵیمەکە.","هەرگیز مەنقەڵی کەباب یان پشکۆی گەرم مەبە ناو چادر، ئۆتۆمبێل یان ماڵ.","کاتێک ئەگەری باران هەیە، هەرگیز لە ناو ڕووبارێکی وشک یان لە تەنیشت جۆگە چادر هەڵمەدە و ئۆتۆمبێل ڕامەگرە."],activity:{prompt:"لەگەڵ دوو هاوڕێ لە شاخ پیاسە دەکەیت و تێدەگەیت کە ڕێگاکەتان ون کردووە. خۆر دوای دوو کاتژمێر ئاوا دەبێت و هێڵی مۆبایلەکەت لاوازە. چی دەکەیت؟",options:[{text:"دەوەستین، پێکەوە لە شوێنی خۆمان دەمێنینەوە، بە دوایین شوێنی زانراومان و ئەوەی دەیبینین پەیوەندی بە ١١٥ دەکەین، و جار جار فیکە لێدەدەین.",correct:!0,feedback:"مانەوە لە یەک شوێن دۆزینەوەتان بۆ ڕزگارکەران ئاسانتر دەکات، و پەیوەندییەک بە زانیاریی ڕوون دەربارەی شوێن و فیکەیەک کە دەنگی دوور دەڕوات یارمەتییان دەدەن بگەنە لاتان."},{text:"لە یەک جیا دەبینەوە بۆ ئەوەی بە ئاراستەی جیاواز بە دوای ڕێگاکەدا بگەڕێین و پاشان دووبارە یەک بگرینەوە.",correct:!1,feedback:"جیابوونەوە دەتوانێت یەک گرووپی ونبوو بکات بە چەند کەسێکی ونبوو. پێکەوە بن و لە شوێنی خۆتان بمێننەوە."},{text:"بە خێراترین شێوە بەرەو خوارەوە دەڕۆین، تەنانەت دوای تاریکبوونیش، تا جادەیەک دەدۆزینەوە.",correct:!1,feedback:"ڕۆیشتنی خێرا لەسەر زەوییەکی نەناسراو لە تاریکیدا دەتوانێت ببێتە هۆی کەوتن، و جووڵە دۆزینەوەتان قورستر دەکات. بوەستن، بانگی یارمەتی بکەن و چاوەڕێ بکەن."},{text:"ئاگرێکی گەورە لە ناو گیای وشکدا هەڵدەکەین بۆ ئەوەی خەڵک دووکەڵەکە ببینن.",correct:!1,feedback:"ئاگر لە گیای وشکدا دەتوانێت بڵاو ببێتەوە و گەمارۆتان بدات. بە فیکە، ڕووناکی یان جلی ڕەنگ گەش ئاماژە بدەن، و پەیوەندی بە ١١٥ بکەن."}]},quiz:[{question:"کەی دەتوانیت ئاگری سەیران جێبهێڵیت؟",options:[{text:"کاتێک بە ئاو تەڕ کراوە و تێکدراوە و هیچ گەرمی و دووکەڵێک نەماوە",correct:!0},{text:"کاتێک گڕەکە کەم بووەتەوە و تەنها پشکۆی سوور ماونەتەوە",correct:!1},{text:"کاتێک دارە سووتاوەکە بە چینێک گەڵای وشک داپۆشراوە",correct:!1},{text:"کاتێک با گۆڕاوە و دووکەڵەکە لە تۆ دوور دەبات",correct:!1}],explanation:"پشکۆ دەتوانێت بۆ چەند کاتژمێرێک گەرم بمێنێتەوە، و با دەتوانێت بیبات بۆ ناو گیای وشک. ئاو بکە بەسەر هەموو پشکۆکاندا، تێکیبدە، دووبارە ئاو بکە و دڵنیا بە کە هیچ گەرمی، سووری، گڕ یان دووکەڵێک نەماوە."},{question:"خێزانەکەت لە شاخێکدا ون بووە. باشترین کار چییە؟",options:[{text:"پێکەوە لە شوێنی خۆتان بمێننەوە، پەیوەندی بە ١١٥ بکەن و فیکە لێبدەن",correct:!0},{text:"بە خێرایی بەرەو یەک ئاراستە بڕۆن تا دەگەنە جادەیەک یان گوندێک",correct:!1},{text:"منداڵە گەورەکان بە تەنها بنێرنە پێشەوە بۆ دۆزینەوەی ڕێگاکە",correct:!1},{text:"بەردەوام بەرەو بەرزترین شوێن سەربکەون بۆ دەست ڕاوەشاندن، تەنانەت دوای تاریکیش",correct:!1}],explanation:"جووڵە دۆزینەوەتان بۆ ڕزگارکەران قورستر دەکات و دەتوانێت ببێتە هۆی کەوتن. پێکەوە لە شوێنی خۆتان بمێننەوە، بە دوایین شوێنی زانراوتان پەیوەندی بە ١١٥ بکەن و بە فیکە ئاماژە بدەن."},{question:"مارێک قاچی کەسێکی پێوەداوە. دەبێت چی بکەیت؟",options:[{text:"بێجووڵەی ڕابگرە، شتە تەنگەکان لابەرە و بە خێرایی بیگەیەنە نەخۆشخانە",correct:!0},{text:"شوێنی پێوەدانەکە ببڕە و ژەهرەکە بمژە پێش ئەوەی بچیتە نەخۆشخانە",correct:!1},{text:"بەندێکی توند لە سەرووی پێوەدانەکە ببەستە و سەهۆڵ لەسەر برینەکە دابنێ",correct:!1},{text:"بهێڵە بە خێرایی بە پێ بچێتەوە ماڵەوە و بە چارەسەرێکی ماڵەوە چارەسەری بکە",correct:!1}],explanation:"بێجووڵە مانەوە بڵاوبوونەوەی ژەهرەکە هێواش دەکاتەوە، و چارەسەری نەخۆشخانە ئەوەیە کە یارمەتی دەدات. بڕین، مژین، بەندی توند، سەهۆڵ و چارەسەری میللی تەنها زیان زیاتر دەکەن."},{question:"پێشبینیی باران لە شاخەکان هەیە. کام شوێن بۆ چادرەکەت لە هەمووان مەترسیدارترە؟",options:[{text:"لە ناو ڕووبارێکی وشک یان لە شوێنی نزمی تەنیشت جۆگە",correct:!0},{text:"لەسەر شوێنێکی تەخت و بەرز، زۆر دوور لە ئاو",correct:!1},{text:"لە تەنیشت ئۆتۆمبێلەکەت لە پارکینگێکی چەوداری لەسەر شوێنێکی بەرز",correct:!1},{text:"لە کەمپێک لەسەر لێژایی گردێک، زۆر بەرزتر لە بنی دۆڵەکە",correct:!1}],explanation:"لافاوی لەناکاو دەتوانێت لە چەند خولەکێکدا ڕووبارێکی وشک پڕ بکات، تەنانەت کاتێک باران زۆر دوور دەبارێت. لە شوێنی بەرزتر چادر هەڵبدە و سەیران بکە، و ئەگەر ئاو دەستی بە بەرزبوونەوە کرد یەکسەر سەربکەوە."},{question:"کاتێک لە چادرەکەتدایت هەورەگرمە دەست پێدەکات. سەلامەتترین شوێن کامەیە؟",options:[{text:"لە ناو بینایەکی بەهێز یان ئۆتۆمبێلێکی خاوەن سەقفی کانزایی",correct:!0},{text:"لە ناو چادرەکەتدا، و دەرگاکەی بە تەواوی داخراو",correct:!1},{text:"لە ژێر بەرزترین داری تاکی ناو دەشتەکە",correct:!1},{text:"لەسەر لووتکەی گردەکە، کە بتوانیت زریانەکە ببینیت",correct:!1}],explanation:"لە کاتی زریانی هەورەتریشقەدا هیچ شوێنێکی سەلامەت لە دەرەوە نییە، و چادر هیچ پاراستنێک نادات. بچۆ بۆ بینایەکی بەهێز یان ئۆتۆمبێلێکی سەقف ڕەق و تا ٣٠ خولەک دوای دوایین هەورەگرمە لەوێ بمێنەرەوە."}],media:[{kind:"image",src:"media/images/w8_outdoor_safety.webp",title:"سەیرانێکی سەلامەتی خێزانی لە شاخ",description:"خێزانێک لەسەر شوێنێکی بەرز، زۆر دوور لە ڕووبارێکی وشک، سەیران دەکات؛ باوکەکە ئاو دەکات بەسەر پشکۆی کەبابەکەدا و منداڵێک کە فیکەیەکی لە ملدایە لە نزیکیان دەمێنێتەوە."}]},{id:30,icon:"Construction",accent:"#a16207",title:"دوای ڕووخانی بینایەک: هاووڵاتیان دەتوانن چی بکەن",subtitle:"یارمەتیدانی سەلامەت لە دەرەوە، ڕاگەیاندنی کەسە گیرخواردووەکان و پاراستنی خۆت ئەگەر گیرت خوارد",summary:"بینایەک دەتوانێت دوای بوومەلەرزە یان تەقینەوەیەک، لە ئاگرێکدا، یان لەبەر ئەوەی کۆنە یان خراپ دروستکراوە بڕووخێت. زۆربەی جار یەکەم کەسانێک کە یارمەتی دەدەن ئەوانەن کە لە نزیکن، پێش گەیشتنی تیمەکانی ڕزگارکردن. بەڵام ئەو کەسانەی ڕاهێنانیان نەکردووە و بە پەلە دەچنە ناو بینای زیانپێگەیشتوو یان سەر داڕماوەکان، زۆرجار بە سەختی بریندار دەبن، و هەندێکیان گیانیان لەدەست داوە. ئەم وانەیە ڕوون دەکاتەوە کە دەتوانیت بە سەلامەتی لە دەرەوە چی بکەیت، چی بە ١١٥ بڵێیت و ئەگەر گیرت خوارد چۆن خۆت بپارێزیت.",blocks:[{heading:"سەلامەتیی تۆ لە پێشەوەیە",points:["هەرگیز مەچۆ ناو بینایەکی زیانپێگەیشتوو و هەرگیز سەر داڕماوەکان مەکەوە، تەنانەت بۆ ڕزگارکردنی کەسێکیش: داڕماوەکان دەتوانن بجووڵێن و بڕووخێن، و لەرزەیەکی دوای بوومەلەرزە دەتوانێت زیاتر بهێنێتە خوارەوە.","ئەگەر دوای وەستانی لەرزینەکە لە بینایەکی زیانپێگەیشتوودا بوویت، بچۆ دەرەوە و بە خێرایی لێی دوور بکەوەرەوە، بۆ شوێنێکی کراوە دوور لە بینا، دار، ستوونی چرای شەقام و تەلی کارەبا.","نیشانەکانی ئەوەی بینایەک لەوانەیە بکەوێت: لار بووەتەوە یان لەسەر بناغەکەی جووڵاوە، بەشێکی ڕووخاوە، درزی گەورە لە بناغەکەیدا هەیە، یان گوێت لە دەنگی قرچە یان ناڵە دەبێت. هەمووان لێی دوور بخەرەوە.","چاوەڕێی لەرزەکانی دوای بوومەلەرزە (Aftershock) بە، هەندێک جار بۆ چەند هەفتەیەک. ئەگەر هەستت بە یەکێکیان کرد: ئەگەر لە ژوورەوە بوویت، خۆت نزم بکەرەوە، خۆت دابپۆشە و بیگرە (Drop, Cover, Hold On)، و ئەگەر لە دەرەوە بوویت، لە شوێنی کراوە بمێنەرەوە.","ئەگەر بۆنی گاز هات، لە نزیک بیناکە سویچ، چەقماخ یان تەلەفۆن بەکارمەهێنە: دوور بکەوەرەوە، خەڵکی تر ئاگادار بکەرەوە و لە شوێنێکی سەلامەتەوە پەیوەندی بە ١١٥ بکە. هەرگیز دەست لە تەلی کارەبای کەوتوو یان هەر شتێک کە بەری کەوتووە مەدە."]},{heading:"یارمەتیدان لە دەرەوە",points:["یارمەتیی ئەو کەسانە بدە کە دەتوانن بڕۆن تا لە بیناکە دوور بکەونەوە بۆ شوێنێکی کراوە و سەلامەت، و تەماشاکەران دوور بخەرەوە.","فریاکەوتنی سەرەتایی بگەیەنە بەو بریندارانەی دەتوانیت بەبێ چوونە ناو بیناکە یان سەر داڕماوەکان پێیان بگەیت، و پەیوەندی بە ١٢٢ بکە. کەسێک کە لەوانەیە مل یان پشتی بریندار بێت مەجووڵێنە، مەگەر شوێنەکە مەترسیدار بێت.","کەسی گیرخواردوو بە زۆر مەکێشە دەرەوە و پارچە قورسەکانی داڕماوەکان بەرز مەکەرەوە: پارچەکانی تر دەتوانن بەسەر ئەو و تۆدا بکەون. ئەم کارە بۆ تیمی ڕاهێنراوی ڕزگارکردن جێبهێڵە.","لە ناو داڕماوەکاندا هەڵمەکەنە و مەچۆ ناو کەلێنەکانەوە: دەتوانن هەر ساتێک دابخرێن.","لە شوێنێکی سەلامەتەوە بانگ بکە و گوێ بگرە: «کەس گوێی لە دەنگم دەبێت؟ لێبدە یان بانگ بکە.» بە وردی بزانە دەنگ یان لێدان لە کوێوە دێت.","کاتێک تیمی ڕزگارکردن گەیشت، ئەوەی دەیزانیت پێیان بڵێ و ڕێنماییەکانیان جێبەجێ بکە. تەنها ئەگەر داوایان لێکردیت یارمەتی بدە."]},{heading:"پەیوەندیکردن بە ١١٥: چی بڵێیت",body:`لە شوێنێکی سەلامەتەوە پەیوەندی بە ١١٥ بکە (و بە ١٢٢ بۆ برینداران) و بڵێ:

١. لە کوێ: ناوچە، شەقام، بینا و نیشانەیەکی دیار؛ کام لای بیناکە و کام نهۆم.
٢. چی ڕوویدا: ڕووخان، و هەر ئاگرێک، بۆنی گاز یان تەلی کارەبای کەوتوو.
٣. خەڵک: چەند کەس لەوانەیە گیریان خواردبێت، لە کوێ گوێت لە دەنگ یان لێدان بوو، و چەند کەس بریندارن.
٤. ناو و ژمارەی تەلەفۆنەکەت. تەلەفۆنەکە دامەخە تا پێت دەڵێن.

کاتێک تیمی ڕزگارکردن گەیشت، پێیان بڵێ کێ لە بیناکەدا دەژیا، کێ بە سەلامەتی بینراوە و کێ هێشتا ونە.`},{heading:"ئەگەر گیرت خوارد",body:`١. تا دەتوانیت کەم بجووڵێ، بۆ ئەوەی تۆز بەرز نەکەیتەوە و داڕماوی زیاتر نەهێنیتە خوارەوە.
٢. دەم و لووتت بە پارچە قوماشێک یان جلەکانت داپۆشە.
٣. شقارتە یان چەقماخ هەڵمەکە: لەوانەیە گاز دزە بکات.
٤. لە بۆرییەک یان دیوارێک بدە، یان فیکە لێبدە، بۆ ئەوەی ڕزگارکەران بتدۆزنەوە. ئەگەر مۆبایلەکەت کار دەکات، پەیوەندی بە ١١٥ بکە یان نامەیەک بە شوێنەکەتەوە بنێرە.
٥. تەنها وەک دوایین چارە هاوار بکە: هاوارکردن وات لێدەکات بڕێکی مەترسیدار لە تۆز هەڵمژیت.

فیکەیەک و چرایەکی دەستی لە نزیک جێگای نووستنەکەت و لە جانتای فریاکەوتندا دابنێ.`},{heading:"لە کاتژمێر و ڕۆژەکانی دواتردا",points:["کاتێک دەتوانیت، لە جیاتی پەیوەندی نامە بنێرە، بۆ ئەوەی تۆڕی تەلەفۆن بۆ فریاکەوتنەکان بەتاڵ بمێنێتەوە.","شەقامەکان بۆ ئەمبولانس و ئۆتۆمبێلەکانی ڕزگارکردن بەتاڵ بهێڵەرەوە: بە ئۆتۆمبێل مەچۆ ئەوێ بۆ تەماشاکردن.","منداڵان بەشداری لە لابردنی داڕماوەکان یان پاککردنەوەدا ناکەن.","مەگەڕێوە ناو بینایەکی زیانپێگەیشتوو تا ئەندازیاران یان لایەنە پەیوەندیدارەکان نەڵێن سەلامەتە.","ڕاگەیاندنە فەرمییەکانی بەرگریی شارستانی و لایەنە پەیوەندیدارەکان جێبەجێ بکە، و دەنگۆ بڵاو مەکەرەوە."]}],tips:["فیکەیەک و چرایەکی دەستی لە نزیک جێگای نووستنەکەت و لە جانتای فریاکەوتندا دابنێ.","لەگەڵ خێزانەکەت لەسەر خاڵی کۆبوونەوە لە دەرەوە، دوور لە بیناکان، ڕێک بکەون.","١١٥ و ١٢٢ لە مۆبایلەکەتدا تۆمار بکە، و ناوی شەقامەکەت و نیشانە دیارەکانی نزیک بزانە.","دوای ڕووخانێک، لە شوێنێکی سەلامەتەوە بانگ بکە و گوێ بگرە، و بە وردی بە تیمی ڕزگارکردن بڵێ لە کوێ گوێت لە دەنگی کەسێک بوو.","دوای کارەسات نامە بنێرە بۆ ئەوەی هێڵەکانی تەلەفۆن بەتاڵ بمێننەوە."],warnings:["هەرگیز مەچۆ ناو بینایەکی زیانپێگەیشتوو و سەر داڕماوەکان مەکەوە، تەنانەت بۆ ڕزگارکردنی کەسێکیش.","ئەگەر بۆنی گاز هات، لەوێ سویچ، چەقماخ یان تەلەفۆن بەکارمەهێنە: دوور بکەوەرەوە و لە شوێنێکی سەلامەتەوە پەیوەندی بە ١١٥ بکە.","هەرگیز دەست لە تەلی کارەبای کەوتوو یان هەر شتێک کە بەری کەوتووە مەدە."],activity:{prompt:"دوای بوومەلەرزەیەک، بەشێک لە ماڵی دراوسێیەک ڕووخاوە. گوێت لە دەنگێکی لاواز دەبێت لە ژێر داڕماوەکانەوە، و چەند گەنجێک دەست دەکەن بە سەرکەوتن بۆ سەر داڕماوەکان بۆ هەڵکەندن. چی دەکەیت؟",options:[{text:"بە شوێنی ورد و شوێنی دەنگەکە پەیوەندی بە ١١٥ دەکەم، داوا لە گەنجەکان دەکەم دابەزن و خەڵک دوور دەخەمەوە، و لە شوێنێکی سەلامەتەوە بەردەوام قسە لەگەڵ ئەو کەسە دەکەم.",correct:!0,feedback:"داڕماوەکان دەتوانن بجووڵێن و لەرزەکانی دوای بوومەلەرزە دەتوانن زیاتر بهێننە خوارەوە. زانیاریی ورد یارمەتیی تیمی ڕزگارکردن دەدات، و قسەکردن لەگەڵ کەسی گیرخواردوو لە شوێنێکی سەلامەتەوە هێمنی دەکاتەوە بەبێ ئەوەی خەڵکی زیاتر بخاتە مەترسییەوە."},{text:"لەگەڵیان سەردەکەوم، چونکە هەر خولەکێک گرنگە و دەستی زیاتر خێراتر هەڵدەکەنێت.",correct:!1,feedback:"قورسایی زیاتر لەسەر داڕماوەکان دەتوانێت بیانڕووخێنێت بەسەر کەسی گیرخواردوو و ئەوانەی هەڵدەکەنن. سەر داڕماوەکان مەکەوە و پەیوەندی بە ١١٥ بکە."},{text:"پارچە گەورەکانی کۆنکرێت لە لێوارەکەوە دەردەهێنم بۆ کردنەوەی ڕێگایەک.",correct:!1,feedback:"دەرهێنانی پارچەکان دەتوانێت ئەو داڕماوانە بهێنێتە خوارەوە کە بۆشاییەکەیان ڕاگرتووە کە کەسەکە تێیدا هەناسە دەدات. داڕماوی قورس بۆ تیمی ڕاهێنراو جێبهێڵە."},{text:"تا بەیانی چاوەڕێ دەکەم بۆ ڕاگەیاندن، چونکە تیمەکانی ڕزگارکردن ئێستا سەرقاڵن.",correct:!1,feedback:"کەسانی گیرخواردوو پێویستیان بە یارمەتییە هەرچی زووتر بێت. یەکسەر پەیوەندی بە ١١٥ بکە و شوێنی ورد بڵێ."}]},quiz:[{question:"دوای بوومەلەرزەیەک لە ژێر داڕماوەکاندا گیرت خواردووە. دەبێت چی بکەیت؟",options:[{text:"دەمت داپۆشە، و لە بۆرییەک یان دیوارێک بدە یان فیکە لێبدە",correct:!0},{text:"شقارتەیەک هەڵبکە بۆ ئەوەی شوێنی دەوروبەرت ببینیت",correct:!1},{text:"تا دەتوانیت بە دەنگی بەرز و بێوەستان هاوار بکە تا یارمەتی دێت",correct:!1},{text:"بە هێز پاڵ بە داڕماوەکانی سەرتەوە بنێ بۆ ئەوەی بە خێرایی ڕێگایەک بکەیتەوە",correct:!1}],explanation:"گڕ دەتوانێت گازی دزەکردوو هەڵبکات، هاواری بەردەوام وات لێدەکات تۆز هەڵمژیت، و پاڵنان دەتوانێت داڕماوی زیاتر بهێنێتە خوارەوە. لێدان و فیکە یارمەتیی ڕزگارکەران دەدەن بتدۆزنەوە؛ تەنها وەک دوایین چارە هاوار بکە."},{question:"سەلامەتترین ڕێگا بۆ هاووڵاتییەک کە دوای ڕووخانی بینایەک یارمەتی بدات چییە؟",options:[{text:"یارمەتیی خەڵک لە دەرەوەی بیناکە بدە و کەسە گیرخواردووەکان بە ١١٥ ڕابگەیەنە",correct:!0},{text:"بچۆ ناو بینا زیانپێگەیشتووەکە و هەموو ژوورەکانی بۆ ڕزگاربووان بپشکنە",correct:!1},{text:"سەر داڕماوەکان بکەوە و پارچە قورسەکان یەک بە یەک بەرز بکەرەوە",correct:!1},{text:"بە ئۆتۆمبێلەکەت بچۆ ناو شەقامەکە بۆ ئەوەی ببینیت چی ڕوودەدات",correct:!1}],explanation:"ئەو کەسانەی ڕاهێنانیان نەکردووە و دەچنە ناو بینای زیانپێگەیشتوو یان سەر داڕماوەکان زۆرجار بریندار دەبن یان دەمرن. لە دەرەوە یارمەتی بدە، شەقامەکان بۆ ئۆتۆمبێلەکانی ڕزگارکردن بەتاڵ بهێڵەرەوە و کەسە گیرخواردووەکان بە ١١٥ ڕابگەیەنە."},{question:"کاتێک کەسانی گیرخواردوو لە ڕووخانێکدا ڕادەگەیەنیت، سەرەتا دەبێت چی بە ١١٥ بڵێیت؟",options:[{text:"شوێنی ورد: ناوچە، شەقام، بینا و نیشانەیەکی دیار",correct:!0},{text:"بۆچوونی خۆت دەربارەی ئەوەی کێ بیناکەی دروست کردووە و بۆچی ڕووخاوە",correct:!1},{text:"تەنها ئەوەی کە لە شوێنێکی گەڕەکەکەتدا شتێک ڕوویداوە",correct:!1},{text:"ناوی تەواوی هەموو ئەو کەسانەی تا ئێستا لە بیناکەدا ژیاون",correct:!1}],explanation:"تیمەکانی ڕزگارکردن دەبێت بە خێرایی شوێنەکە بدۆزنەوە. سەرەتا شوێنەکە بڵێ، پاشان چی ڕوویداوە، چەند کەس لەوانەیە گیریان خواردبێت، لە کوێ گوێت لێیان بوو و هەر مەترسییەک، و تەلەفۆنەکە دامەخە تا پێت دەڵێن."},{question:"بۆچی کەسی گیرخواردوو دەبێت تەنها وەک دوایین چارە هاوار بکات؟",options:[{text:"هاوارکردن وات لێدەکات بڕێکی مەترسیدار لە تۆز هەڵمژیت",correct:!0},{text:"تیمەکانی ڕزگارکردن ڕاهێنراون تەنها گوێ لە دەنگی لێدان بگرن",correct:!1},{text:"دەنگی هاوار دەتوانێت داڕماوەکانی سەرت بڕووخێنێت",correct:!1},{text:"هاوارکردن بە خێرایی پاتریی مۆبایلەکەت تەواو دەکات",correct:!1}],explanation:"تۆزی ناو بینایەکی ڕووخاو دەتوانێت زیان بە سییەکانت بگەیەنێت، و هاوارکردن وات لێدەکات زیاتری هەڵمژیت. دەنگی لێدان لە بۆری یان دیوار و دەنگی فیکە باش دەڕۆن و هەناسەت دەپارێزن."},{question:"لە نزیک بینایەکی ڕووخاو بۆنی گاز دەکەیت. چی دەکەیت؟",options:[{text:"لەوێ سویچ و ئاگر بەکارناهێنم، دوور دەکەومەوە و پەیوەندی بە ١١٥ دەکەم",correct:!0},{text:"بە خێرایی دەچمە ژوورەوە و سەمامەی گاز لە چێشتخانە دادەخەم",correct:!1},{text:"چراکانی ڕاڕەوەکە هەڵدەکەم بۆ ئەوەی شوێنی دزەی گازەکە ببینم",correct:!1},{text:"چەقماخێک لە نزیک بۆرییەکان هەڵدەکەم بۆ ئەوەی بزانم گاز لە کوێوە دزە دەکات",correct:!1}],explanation:"پریشکێک یان گڕێک دەتوانێت گازەکە هەڵبکات و ببێتە هۆی تەقینەوە. هەرگیز بۆ گەیشتن بە سەمامەی گاز مەچۆ ناو بیناکە: دوور بکەوەرەوە، خەڵکی تر ئاگادار بکەرەوە و لە شوێنێکی سەلامەتەوە پەیوەندی بە ١١٥ بکە."}],media:[{kind:"image",src:"media/images/w8_collapse_citizen_help.webp",title:"یارمەتیدانی سەلامەت دوای ڕووخان",description:"دراوسێکان لە ماڵێکی نیوە ڕووخاو دوور دەمێننەوە؛ ئافرەتێک پەیوەندی بە ١١٥ دەکات و ئاماژە بەو شوێنە دەکات کە دەنگی لێ بیستراوە، و هەندێکی تر یارمەتیی پیاوێکی بریندار دەدەن بچێتە شوێنێکی کراوە دوور لە بینا و تەلی کارەبا."}]},{id:31,icon:"Users",accent:"#0f766e",title:"سەلامەتی لە کۆبوونەوە قەرەباڵغەکاندا",subtitle:"زەماوەند، فێستیڤاڵ، بۆنە ئایینییەکان، یاریگا و بازاڕ",summary:"زەماوەند، فێستیڤاڵ، بۆنە ئایینییەکان، یاری و بازاڕە قەرەباڵغەکان خەڵکێکی زۆر لە یەک شوێن کۆدەکەنەوە. کاتێک خەڵکێکی زۆر لە شوێنێکی تەنگدا کۆدەبنەوە، یان هەمووان بەرەو یەک خاڵ ڕادەکەن، خەڵک دەتوانن بپلیشێنرێنەوە یان لە ژێر پێدا بمێننەوە. لە کارەساتەکانی قەرەباڵغیدا، زۆربەی خەڵک دەمرن چونکە ئەوەندە دەگوشرێن کە ناتوانن هەناسە بدەن. ئەم وانەیە ڕوون دەکاتەوە چۆن قەرەباڵغییەکی مەترسیدار زوو بناسیتەوە، ئەگەر تێیدا گیرت خوارد چی بکەیت، چۆن منداڵان بپارێزیت و ڕێکخەرانی بۆنەکە دەبێت چی بکەن.",blocks:[{heading:"کاتێک دەگەیت",points:["هەر کە گەیشتیت بە دوای هەموو دەرچەکاندا بگەڕێ، و لانیکەم دوو ڕێگای دەرچوون بدۆزەرەوە: لە کاتی فریاکەوتندا لەوانەیە ئەو دەرگایەی لێیەوە هاتوویتە ژوورەوە داخرابێت.","دڵنیا بە کە دەرچەکان قفڵ نەکراون، بە زنجیر نەبەستراون و داخراو نین. ئەگەر لانیکەم دوو ڕێگای دەرچوون نەبوو، بە ڕێکخەرانی بۆنەکە بڵێ، و ئەگەر یەکسەر چاک نەکرا، بڕۆ دەرەوە.","بزانە خاڵی فریاکەوتنی سەرەتایی لە کوێیە، و خاڵی زانیاری یان خاڵی منداڵانی ونبوو ئەگەر هەبێت.","لەگەڵ خێزان یان هاوڕێکانت لەسەر خاڵێکی کۆبوونەوە ڕێک بکەون ئەگەر لە یەک جیا بوونەوە.","لە لێوارەکانی قەرەباڵغییەکە یان لە شوێنە کەمتر قەرەباڵغەکان، لەسەر زەوییەکی ڕێک و وشک بمێنەرەوە.","ئەگەر هەستت کرد شوێنەکە زۆر قەرەباڵغە یان سەلامەت نییە، زوو بڕۆ دەرەوە."]},{heading:"نیشانەکانی قەرەباڵغییەکی مەترسیدار",body:"زوو بڕۆ دەرەوە، کاتێک هێشتا دەتوانیت بە ئازادی بجووڵێیت، ئەگەر ئەمانەت بینی:",points:["هیچ بۆشاییەک لە نێوان تۆ و خەڵکی دەوروبەرتدا نەماوە، و خەڵکی زیاتر بەردەوام پاڵ دەنێن و دێنە ژوورەوە.","قەرەباڵغییەکە دەست دەکات بە لەنجەکردن یان پاڵنان وەک شەپۆل، و بەرەو شوێنێک دەبرێیت کە ناتەوێت.","خەڵک پاڵ دەنێن یان ڕادەکەن، بۆ نموونە بەرەو دەرگایەک، شانۆیەک یان دابەشکردنێکی بەخۆڕایی.","خەڵک بە دیوار، بەربەست یان پەرژینەوە دەگوشرێن.","هەناسەدان قورس دەبێت."]},{heading:"ئەگەر لە پاڵەپەستۆی قەرەباڵغیدا گیرت خوارد",points:["دەستەکانت لە بەردەم سنگتدا بەرز ڕابگرە، وەک بۆکسێنێک، بۆ ئەوەی بۆشاییی هەناسەدان بپارێزیت.","لەسەر پێیەکانت بمێنەرەوە: بە هێز لەسەر زەوی دایانبنێ و هەوڵ بدە نەکەویت. دانەچەمێوە بۆ هەڵگرتنی هیچ شتێک.","پاڵ بە قەرەباڵغییەکەوە مەنێ. ئەگەر خەڵکی بەردەمت وەستان، پاڵ مەنێ: خۆت بگرە و داوا لەوانەی پشتت بکە ئەوانیش خۆیان بگرن.","کاتێک گوشارەکە بۆ ساتێک کەم دەبێتەوە، بە لاری بە ناو قەرەباڵغییەکەدا بەرەو لێوارەکەی بڕۆ.","لە دیوار، بەربەست و پەرژین دوور بکەوەرەوە، کە خەڵک لەوێ دەپلیشێنرێنەوە.","ئەگەر کەوتیت، خۆت وەک تۆپێک کۆ بکەرەوە، سەرت بپارێزە و هەرچی زووتر هەستەوە. ئەگەر کەسێک لە نزیکت کەوت، داوا لە خەڵکی دەوروبەرت بکە خۆیان بگرن و یارمەتیی بدە هەستێتەوە."]},{heading:"منداڵان، بەساڵاچووان و کەسانی خاوەن پێداویستیی تایبەت",points:["منداڵە بچووکەکان لە نزیک خۆت بهێڵەرەوە، دەستیان بگرە و دڵنیا بە کە شوێنی پێویستیان هەیە.","کارتێک بە ناو و ژمارەی تەلەفۆنەکەت بخە ناو گیرفانی منداڵەکەت.","خاڵی کۆبوونەوە نیشانی منداڵان بدە، و فێریان بکە ئەگەر تۆیان ون کرد بچنە ئەوێ.","لەگەڵ بەساڵاچووان و کەسانی خاوەن پێداویستیی تایبەت لە لێوارەکانی قەرەباڵغییەکە و نزیک دەرچەیەک بمێنەرەوە."]},{heading:"ڕێکخەرانی بۆنەکە دەبێت چی بکەن",points:["ژمارەی سەلامەتی ئەو خەڵکە بزانن کە شوێنەکە دەتوانێت بیگرێت، لەگەڵ ئەو ناوچانەشدا کە خەڵک تێیاندا ڕیز دەبەستن، کۆدەبنەوە و دەردەچن، و هەرگیز لەو ژمارەیە زیاتر خەڵک مەهێڵنە ژوورەوە.","هەموو دەرچەکان بێ قفڵ و هەموو ڕێگاکانی بەرەویان بەتاڵ بهێڵنەوە بە درێژایی کاتی بۆنەکە؛ دەرگاکانی دەرچوون دەبێت لە ناوەوە بەبێ کلیل بکرێنەوە.","ڕێکخەرانی خەڵکی (Stewards) ڕاهێنراو و پێویستیان هەبێت بۆ ئەوەی ڕێنمایی خەڵک بکەن، چاودێریی پاڵنان و زیادبوونی قەرەباڵغی بکەن، و کاتێک ناوچەیەک پڕ بوو هاتنە ژوورەوە ڕابگرن.","فریاکەوتنی سەرەتایی و یارمەتیی پزیشکی بۆ ئەو قەرەباڵغییەی پێشبینی دەکرێت پلان بکەن، و پێشوەختە لەگەڵ بەرگریی شارستانی و خزمەتگوزاریی ئەمبولانس ڕێک بکەون کە چۆن دەگەنە شوێنەکە.","سیستەمێکی بڵندگۆ و ڕێنماییی فریاکەوتنی ڕوونیان هەبێت، و نیشانەکانی زیادبوونێکی مەترسیداری قەرەباڵغی یەکسەر ڕابگەیەنن.","هاتن و دەرچوون بە شێوەیەک پلان بکەن کە خەڵک بەرەو یەک خاڵ ڕانەکەن، وەک یەک دەرگا یان دابەشکردنێکی بەخۆڕایی.","پێداویستییەکانی بەرگریی شارستانی و لایەنە ناوخۆییەکان بۆ مۆڵەت و ڕێکارەکانی سەلامەتی جێبەجێ بکەن."]},{heading:"ئەگەر شتێک بە هەڵەدا چوو",points:["ئەگەر زەنگی ئاگادارکردنەوە لێیدا، یان دووکەڵ، ئاگر یان شڵەژانێکی لەناکاوت بینی، یەکسەر بە هێمنی لە نزیکترین دەرچەوە بڕۆ دەرەوە.","بە خێرایی قەرەباڵغییەکە بجووڵێ؛ ڕامەکە و پاڵ مەنێ.","کاتێک چوویتە دەرەوە، لە دەرەوە بمێنەرەوە. بڕۆ بۆ خاڵی کۆبوونەوەکەت و ئەگەر کەسێک ون بوو بە تیمەکانی ڕزگارکردن بڵێ.","دەنگۆ بڵاو مەکەرەوە؛ ڕێنماییەکانی ڕێکخەرانی خەڵک و بەرگریی شارستانی جێبەجێ بکە."]}],tips:["هەر کە گەیشتیت دوو ڕێگای دەرچوون بدۆزەرەوە.","پێش چوونە ژوورەوە لەگەڵ خێزانەکەت لەسەر خاڵێکی کۆبوونەوە ڕێک بکەون.","لە لێوارەکانی قەرەباڵغییەکە بمێنەرەوە، بەتایبەتی لەگەڵ منداڵان.","ئەگەر قەرەباڵغییەکە بەردەوام گەورەتر دەبێت و ناتوانیت بە ئازادی بجووڵێیت، زوو بڕۆ دەرەوە.","کارتێک بە ژمارەی تەلەفۆنەکەت بخە ناو گیرفانی منداڵەکەت."],warnings:["هەرگیز لە قەرەباڵغیدا پاڵ مەنێ؛ ئەگەر خەڵکی بەردەم وەستان، خۆت بگرە و داوا لەوانەی پشتت بکە بوەستن.","ڕێکخەرانی بۆنەکە: هەرگیز کاتێک خەڵک لە ژوورەوەن دەرچەیەک قفڵ مەکەن و دامەخەن.","هەرگیز لەو ژمارەیە زیاتر خەڵک مەهێڵە ژوورەوە کە شوێنەکە بە سەلامەتی دەتوانێت بیگرێت."],activity:{prompt:"لە فێستیڤاڵێکی قەرەباڵغدا، قەرەباڵغییەکە لەناکاو بەرەو شانۆکە پاڵ دەنێت. بەرەو پێشەوە پاڵت پێوە دەنرێت و بە زەحمەت دەتوانیت دەستەکانت بجووڵێنیت. چی دەکەیت؟",options:[{text:"دەستەکانم لە بەردەم سنگمدا بەرز ڕادەگرم، لەسەر پێیەکانم دەمێنمەوە، پاڵ نانێم، و کاتێک گوشارەکە کەم دەبێتەوە بە لاری بەرەو لێوارەکە دەڕۆم.",correct:!0,feedback:"دەستەکان لە بەردەم سنگدا بۆشاییی هەناسەدان دەپارێزن، مانەوە لەسەر پێ لە کەوتنە ژێر پێ دەتپارێزێت، و ڕۆیشتن بە لاری لە ساتێکی هێمنیدا لە توندترین گوشار دەرتدەهێنێت."},{text:"بە هێز پاڵ بەو کەسانەوە دەنێم کە لە پشتمن بۆ ئەوەی شوێنی زیاتر دروست بکەم.",correct:!1,feedback:"پاڵنان گوشاری سەر هەمووان زیاتر دەکات و دەتوانێت خەڵک بخات. بەرەنگاری هێزی قەرەباڵغییەکە مەبەوە؛ چاوەڕێی ساتێکی هێمنی بکە."},{text:"دادەچەمێمەوە بۆ هەڵگرتنەوەی مۆبایلەکەم کە کەوتووەتە سەر زەوی.",correct:!1,feedback:"داچەمانەوە لە کاتی پاڵەپەستۆدا دەتوانێت بتخات و لە ژێر پێدا بمێنیتەوە. لەسەر پێیەکانت بمێنەرەوە و مۆبایلەکە جێبهێڵە."},{text:"بەرەو بەربەستەکەی پێشەوە دەڕۆم، کە بتوانم دەست بە شتێکەوە بگرم.",correct:!1,feedback:"خەڵک بە بەربەست و دیوارەوە دەپلیشێنرێنەوە. لێیان دوور بکەوەرەوە، بە لاری بەرەو لێواری قەرەباڵغییەکە."}]},quiz:[{question:"بۆچی کاتێک دەگەیتە هۆڵی زەماوەند یان یاریگا دەبێت دوو ڕێگای دەرچوون بدۆزیتەوە؟",options:[{text:"ئەو دەرگایەی لێیەوە هاتوویتە ژوورەوە لەوانەیە لە کاتی فریاکەوتندا داخرابێت",correct:!0},{text:"لەوانەیە ڕێکخەران داوات لێبکەن لە نزیک یەکێک لە دەرچەکان دابنیشیت",correct:!1},{text:"بۆ میوانان ڕێزلێنانە کە بزانن دەرگاکانی هۆڵەکە لە کوێن",correct:!1},{text:"دەرچەی دووەم هەمیشە لە پارکینگی دەرەوە نزیکترە",correct:!1}],explanation:"لە کاتی فریاکەوتندا زۆربەی خەڵک بەرەو ئەو دەرگایە دەچن کە لێیەوە هاتوونەتە ژوورەوە، و دەتوانێت بە خێرایی دابخرێت. ڕێگایەکی دووەمی دەرچوون ڕێگەت پێدەدات لە نزیکترین دەرچەی سەلامەتەوە بڕۆیتە دەرەوە."},{question:"ئەگەر لە پاڵەپەستۆی قەرەباڵغیدا گیرت خوارد، دەستەکانت چی لێ دەکەیت؟",options:[{text:"لە بەردەم سنگمدا بەرزیان ڕادەگرم، وەک بۆکسێنێک",correct:!0},{text:"ڕاست بە تەنیشتەکانمدا شۆڕیان دەکەمەوە بۆ ئەوەی شوێنی کەمتر بگرم",correct:!1},{text:"زۆر بەرزیان دەکەمەوە بۆ سەرووی سەرم بۆ ئەوەی خەڵک بمبینن",correct:!1},{text:"بەکاریان دەهێنم بۆ ئەوەی خەڵکی بەردەمم لە ڕێگا پاڵ بنێم",correct:!1}],explanation:"دەستەکان لە بەردەم سنگدا بۆشاییەکی بچووک بۆ سییەکان دەپارێزن. لە پلیشانەوەی قەرەباڵغیدا، زۆربەی خەڵک دەمرن چونکە ئەوەندە دەگوشرێن کە ناتوانن هەناسە بدەن."},{question:"لە کاتی پاڵەپەستۆی قەرەباڵغیدا، گوشارەکە بۆ ساتێک کەم دەبێتەوە. دەبێت بەرەو کوێ بڕۆیت؟",options:[{text:"بە لاری بە ناو قەرەباڵغییەکەدا بەرەو لێوارەکەی",correct:!0},{text:"ڕاستەوخۆ بۆ دواوە، بە پێچەوانەی ڕەوتی قەرەباڵغییەکە",correct:!1},{text:"بۆ پێشەوە، بەرەو بەربەستەکەی پێشەوە",correct:!1},{text:"بۆ سەر زەوی، بۆ ئەوەی پشوو بدەیت تا تەواو دەبێت",correct:!1}],explanation:"ڕۆیشتن بە لاری بەرەو لێوار لە توندترین گوشار دەرتدەهێنێت بەبێ ئەوەی شەڕ لەگەڵ قەرەباڵغییەکە بکەیت. بەربەست و زەوی ئەو شوێنانەن کە خەڵک تێیاندا دەپلیشێنرێنەوە یان لە ژێر پێدا دەمێننەوە."},{question:"کام لەمانە ئەرکی ڕێکخەری زەماوەندێکی گەورە یان فێستیڤاڵێکە؟",options:[{text:"هەموو دەرچەکان بێ قفڵ و بەتاڵ بهێڵێتەوە کاتێک میوانان لە ژوورەوەن",correct:!0},{text:"دەرگاکانی تەنیشت قفڵ بکات بۆ ئەوەی کەس بەبێ کارتی بانگهێشت نەیەتە ژوورەوە",correct:!1},{text:"هەموو ئەو کەسانەی دێن بهێڵێتە ژوورەوە، تەنانەت دوای پڕبوونی هۆڵەکەش",correct:!1},{text:"دیاریی بەخۆڕایی لە یەک دەرگای تەنگدا دابەش بکات بۆ دڵخۆشکردنی میوانان",correct:!1}],explanation:"دەرگاکانی دەرچوون دەبێت لە ناوەوە بەبێ کلیل بکرێنەوە و ڕێگاکانی بەرەویان بەتاڵ بمێنن. ڕێکخەران هەروەها دەبێت ژمارەی سەلامەت بپارێزن و لە هەر شتێک دوور بکەونەوە کە خەڵک بەرەو یەک خاڵ ڕادەکێشێت."},{question:"ئەگەر منداڵەکەت لە قەرەباڵغیدا لێت جیا بووەوە، چی زیاتر یارمەتی دەدات؟",options:[{text:"خاڵێکی کۆبوونەوەی پێشوەختە ڕێککەوتوو و کارتێک بە ژمارەی تەلەفۆنەکەت",correct:!0},{text:"بەڵێنێک کە بە هەموو گۆشەیەکی شوێنی فێستیڤاڵەکەدا دەگەڕێیت",correct:!1},{text:"یاسایەک کە منداڵەکە هەمیشە بە تەنها لە پێشەوەی خێزانەکە دەڕوات",correct:!1},{text:"پلانێک کە منداڵەکە بە تەنها بە پاس بچێتەوە ماڵەوە ئەگەر تۆی نەدۆزیەوە",correct:!1}],explanation:"خاڵێکی کۆبوونەوە کە منداڵەکە دەیزانێت و کارتێک بە ژمارەی تەلەفۆنەکەت یارمەتیی ڕێکخەرانی خەڵک و گەورەکانی تر دەدەن بە خێرایی بتانگەیەننەوە بە یەک. منداڵ هەرگیز نابێت بە تەنها بڕوات."}],media:[{kind:"image",src:"media/images/w8_crowd_safety.webp",title:"سەلامەت مانەوە لە قەرەباڵغیدا",description:"خێزانەکان لە فێستیڤاڵێکدا لە لێواری قەرەباڵغییەکە لە تەنیشت دەرچەیەکی کراوە و بە ڕوونی نیشانەکراو وەستاون؛ ڕێکخەرێکی خەڵک بە جلێکی ڕەنگ گەش ڕێنمایی خەڵک دەکات، و کارتێک بە ژمارەی تەلەفۆنی دایک یان باوک لە گیرفانی منداڵێکدایە."}]},{id:32,icon:"PlugZap",accent:"#a16207",title:"سەلامەتیی کارەبا و پاتری لە ماڵەوە",subtitle:"پلاک و درێژکەرەوەکانی کارەبا، شەحنکەر، پاسکیل و سکوتەری کارەبایی، پاتریی لیتیۆم-ئایۆن و فریاکەوتنی سەرەتایی بۆ شۆکی کارەبا",summary:"هەموو ماڵێک پڕە لە ئامێری کارەبایی و پاتریی شەحنکراو: پلاک و درێژکەرەوەکانی کارەبا، شەحنکەری مۆبایل، پاوەر بانک، پاسکیل و سکوتەری کارەبایی. پلاکێکی بارقورس، وایەرێکی تێکچوو یان پاترییەکی تێکچوو دەتوانێت ئاگر دروست بکات، و شۆکی کارەبا دەتوانێت بکوژێت. ئەم وانەیە ڕوون دەکاتەوە چۆن بە سەلامەتی بەکاریان بهێنیت، چۆن نیشانەکانی مەترسی بناسیتەوە، چی بکەیت ئەگەر پاترییەک زۆر گەرم بوو یان ئاگری گرت، و چۆن یارمەتیی کەسێک بدەیت کە شۆکی کارەبای لێداوە.",blocks:[{heading:"پلاک، درێژکەرەوەی کارەبا و وایەر",points:["باری زیادە مەخەرە سەر پلاک، درێژکەرەوە یان پلاکی زیادە: ئامێری زۆر لەسەر یەک پلاک دەتوانێت گەرمی بکات و ئاگر دروست بکات.","هەرگیز درێژکەرەوەیەکی کارەبا یان پلاکێکی زیادە بە یەکێکی ترەوە مەبەستە (Daisy chaining).","درێژکەرەوەکانی کارەبا تەنها بۆ ماوەیەکی کورتن. ئەگەر هەمیشە پێویستت پێیانە، با کارەباچییەکی شارەزا بپشکنێت کە ئایا پلاکی زیاتر پێویستە.","سۆبە، سەلاجە، جلشۆر و ئامێرە گەورەکانی تر ڕاستەوخۆ بە پلاکی دیوارەوە ببەستە، هەرگیز بە درێژکەرەوە یان پلاکی زیادەوە نا.","وایەر لە ژێر فەرش و مافوور، بە بەردەم دەرگادا یان لەو شوێنەی کەلوپەل دەتوانێت پانی بکاتەوە ڕامەکێشە.","وایەر و درێژکەرەوەی درزبردوو یان تێکچوو بگۆڕە؛ هەوڵ مەدە خۆت چاکیان بکەیتەوە.","بە دەستی تەڕ دەست لە پلاک، سویچ و ئامێری کارەبایی مەدە."]},{heading:"نیشانەکانی مەترسی لە پلاک و وایەرەکانی کارەبادا",body:"ئەگەر یەکێک لەم نیشانانەت بینی، پلاکەکە یان ئامێرەکە بەکارمەهێنە، ئەگەر سەلامەت بوو بیکوژێنەرەوە و فیشەکەی دەربهێنە، و با کارەباچییەکی شارەزا هۆکارەکەی بدۆزێتەوە و چاکی بکاتەوە. ئەگەر دووکەڵ یان ئاگر هەبوو، هەمووان دەربهێنە، دەرگاکە دابخە و پەیوەندی بە ١١٥ بکە:",points:["پلاک یان سویچی گەرم یان ڕەنگگۆڕاو، یان فیش کە گەرم دەبێت.","بۆنی سووتان یان پلاستیکی گەرم لە نزیک پلاکێک یان ئامێرێک.","پریشک، دەنگی ویزەویز یان چرپەچرپ، یان شوێنەواری ڕەشبوون لە دەوری پلاک یان فیش.","گڵۆپی لەرزۆک، یان فیوز و سویچی ئۆتۆماتیکی (Circuit breaker) کە بەردەوام دەسووتێن یان دەکەون.","هەستکردن بە تەزوویەکی سووک کاتێک دەست لە ئامێرێک یان دەستشۆرێکی کانزایی دەدەیت."]},{heading:"شەحنکەر، پاسکیل و سکوتەری کارەبایی",points:["مۆبایل، لاپتۆپ، پاوەر بانک، پاسکیل و سکوتەری کارەبایی پاتریی لیتیۆم-ئایۆنیان (Li-ion) تێدایە. ئەم پاترییانە وزەیەکی زۆر هەڵدەگرن، و پاترییەکی تێکچوو یان شەحنکەرێکی نەگونجاو دەتوانێت زۆر گەرمیان بکات، ئاگریان تێبەربدات یان بیانتەقێنێتەوە.","ئەو شەحنکەرە بەکاربهێنە کە لەگەڵ ئامێرەکەدا هاتووە، یان ئەوەی کۆمپانیای بەرهەمهێنەر پێشنیاری دەکات. شەحنکەر و پاتری لە فرۆشیاری متمانەپێکراو بکڕە: کۆپیی هەرزان لەوانەیە ستانداردەکانی سەلامەتی پڕ نەکەنەوە.","لەسەر ڕووبەرێکی ڕەق و ڕێک وەک مێز یان زەوی شەحن بکە، هەرگیز لەسەر جێگای نووستن، قەنەفە یان لە ژێر سەرین نا، چونکە لەوێ گەرمی دەرناچێت.","کاتێک دەخەویت یان کەس لە ماڵەوە نییە ئامێر لەسەر شەحن بەجێمەهێڵە، و کاتێک پاترییەکە پڕ بوو فیشی شەحنکەرەکە دەربهێنە.","ئەگەر دەتوانیت، پاسکیل و سکوتەری کارەبایی لە دەرەوەی ماڵ شەحن بکە. هەرگیز لە ڕاڕەو، لە نزیک دەرگای سەرەکی یان لەسەر پلیکانە شەحنیان مەکە و دایانمەنێ، چونکە ئاگرێک لەوێ ڕێگای دەرچوون دەگرێت.","لەو شوێنەی پاسکیل و سکوتەری کارەبایی تێدا شەحن دەکەیت ئاگادارکەرەوەی دووکەڵ دابنێ، و دوای لێخوڕین با پاترییەکە سارد ببێتەوە پێش ئەوەی شەحنی بکەیت.","پاترییەکی تێکچوو بەکارمەهێنە، هەروەها پاترییەک کە کەسێکی ناشارەزا دەستکاریی کردبێت یان چاکی کردبێتەوە."]},{heading:"پاترییەک کە زۆر گەرم دەبێت، دووکەڵ دەدات یان دەسووتێت",body:"نیشانەکانی مەترسی: پاترییەکە زۆر گەرم دەبێت، هەڵدەئاوسێت یان شێوە یان ڕەنگی دەگۆڕێت، شتی لێ دەتکێت، بۆنێکی نائاسایی دەدات، دەنگی فیشەفیش، چرپەچرپ یان تەقەتەقی لێوە دێت، یان دووکەڵ دەدات. ئاگری پاتریی لیتیۆم-ئایۆن خێرا گەورە دەبێت، کوژاندنەوەی قورسە و دووکەڵ و گازی ژەهراوی لێ دەردەچێت.",points:["ئەگەر دووکەڵ یان ئاگر نەبوو، یەکسەر واز لە بەکارهێنانی پاترییەکە بهێنە. ئەگەر سەلامەت بوو، ئامێرەکە بکوژێنەرەوە و فیشی شەحنکەرەکە دەربهێنە، پاشان لە کۆمپانیای بەرهەمهێنەر یان فرۆشیار بپرسە چی بکەیت.","ئەگەر پاترییەکە دووکەڵی دا یان سووتا، یەکسەر هەمووان دەربهێنە، دەرگاکە لە دوای خۆتەوە دابخە و لە دەرەوە پەیوەندی بە ١١٥ بکە. لە دەرەوە بمێنەوە.","ئەگەر ڕاهێنانت نەکردووە، هەوڵ مەدە خۆت پاترییەکی سووتاو بکوژێنیتەوە یان سارد بکەیتەوە: بۆ ئاگرکوژەکانی بەجێبهێڵە.","پاتریی کۆن یان تێکچوو فڕێمەدە ناو زبڵی ماڵەوە؛ بپرسە لە کوێ بە سەلامەتی کۆدەکرێنەوە."]},{heading:"دوای لافاو و بوومەلەرزە، و وایەرەکانی مۆلیدەی گەڕەک",points:["کارەبا و ئاو پێکەوە دەتوانن بکوژن: هەرگیز کاتێک تەڕیت یان لە ناو ئاودا وەستاویت دەست لە سویچ، پلاک و ئامێری کارەبایی مەدە.","دوای لافاو، کارەبا کوژاوە بهێڵەوە تا کارەباچییەکی شارەزا خانووەکە دەپشکنێت. ئەگەر بۆ گەیشتن بە سویچی سەرەکی پێویست بوو بچیتە ناو ئاو، لە جیاتی ئەوە پەیوەندی بە کارەباچییەکەوە بکە.","ئەو ئامێرە کارەبایی، شەحنکەر، پاسکیل و سکوتەرە کارەباییانەی کەوتوونەتە ناو ئاو بەکارمەهێنە تا کەسێکی شارەزا نەیانپشکنێت.","دوای بوومەلەرزە، ئاگاداری وایەری کارەبای کەوتوو و تەلی زیانلێکەوتوو بە و زۆر لێیان دوور بکەوەوە. وایەرێکی کەوتوو و هەر شتێک کە بەری کەوتووە وەک کارەبادار دابنێ، و پەیوەندی بە ١١٥ بکە.","ئەگەر بۆنی گازت کرد، هیچ گڵۆپ یان ئامێرێک هەڵمەکە و مەیکوژێنەرەوە: هەمووان دەربهێنە، دراوسێکان ئاگادار بکەرەوە و لە دەرەوە پەیوەندی بە ١١٥ بکە.","وایەرەکانی مۆلیدەی گەڕەک: خۆت دەستیان لێ مەدە و هیچ شتێکیان پێوە مەبەستە. وایەری شل یان تێکچوو، پریشک یان بۆنی سووتان بە خاوەنی مۆلیدەکە ڕابگەیەنە، و لە باری نائاساییدا پەیوەندی بە ١١٥ بکە. تەنها کارەباچییەکی شارەزا دەبێت ماڵەکەت بە هێڵی گەڕەکەوە ببەستێتەوە."]},{heading:"شۆکی کارەبا: فریاکەوتنی سەرەتایی",body:`١. دەست لە کەسەکە مەدە ئەگەر لەوانەیە هێشتا بە کارەباوە بەسترابێت: لەوانەیە شۆکی کارەبا تۆش بگرێتەوە.
٢. سەرەتا کارەبا ببڕە: فیشەکە دەربهێنە یان سویچی سەرەکی لە سندوقی فیوزەکان بکوژێنەرەوە، ئەگەر بتوانیت بە سەلامەتی بیکەیت.
٣. ئەگەر نەتتوانی کارەبا ببڕیت، یان هێڵی کارەبای بەرز یان وایەرێکی کەوتوو تێوەگلابوو، زۆر دوور بکەوەوە، خەڵکیش دوور بخەرەوە و پەیوەندی بە ١١٥ و ١٢٢ بکە.
٤. کاتێک کارەبا بڕا، پەیوەندی بە ١٢٢ بکە. ئەگەر کەسەکە بە ئاسایی هەناسە نادات، دەست بە CPR بکە (ئەگەر فێر نەبوویت تەنها پەستانی سنگ بدە) و ڕێنماییەکانی کارمەندی پەیوەندی جێبەجێ بکە؛ ئەگەر ئامێری شۆکی دڵ (AED) هەبوو، بەکاری بهێنە.
٥. تەنانەت ئەگەر کەسەکە باش دیار بوو، چاودێری بکە و لە ١٢٢ ئامۆژگاریی پزیشکی وەربگرە: شۆکی کارەبا دەتوانێت سووتانی قووڵ و برینی ناوەکی دروست بکات کە نابینرێن.`}],tips:["بزانە سویچی سەرەکیی ماڵەکەت (سندوقی فیوزەکان) لە کوێیە، بۆ ئەوەی بتوانیت بە خێرایی و بە سەلامەتی کارەبا ببڕیت.","سۆبە و ئامێرە گەورەکانی تر ڕاستەوخۆ بە پلاکی دیوارەوە ببەستە.","کاتێک شەحنکەر و ئامێرە بچووکەکان بەکارناهێنیت، فیشەکانیان دەربهێنە.","لەو شوێنەی پاسکیل یان سکوتەری کارەبایی تێدا شەحن دەکەیت ئاگادارکەرەوەی دووکەڵ دابنێ، و مانگانە ئاگادارکەرەوەکانی دووکەڵی ماڵەکەت تاقی بکەرەوە.","شەحنکەر، پاتری و درێژکەرەوەی کارەبا لە فرۆشیاری متمانەپێکراو بکڕە، و تەنها ئەو شەحنکەرە بەکاربهێنە کە کۆمپانیای بەرهەمهێنەر پێشنیاری دەکات."],warnings:["هەرگیز دەست لە کەسێک مەدە کە لەوانەیە هێشتا بە کارەباوە بەسترابێت: سەرەتا کارەبا ببڕە.","هەرگیز پاسکیل یان سکوتەری کارەبایی لە ڕاڕەو یان لە نزیک دەرگای سەرەکی شەحن مەکە، و هەرگیز کاتێک هەمووان خەوتوون لەسەر شەحن بەجێی مەهێڵە.","ئەگەر پاترییەک دووکەڵی دا یان ئاگری گرت، دەرچۆ، دەرگاکە دابخە و پەیوەندی بە ١١٥ بکە؛ هەوڵ مەدە خۆت بیکوژێنیتەوە."],activity:{prompt:"درەنگانی شەوە. سکوتەری کارەبایی کوڕەکەت لە ڕاڕەو لە نزیک دەرگای سەرەکی لەسەر شەحنە. گوێت لە فیشەفیشی پاترییەکە دەبێت و بۆنێکی کیمیایی بەهێز دەکەیت. چی دەکەیت؟",options:[{text:"هەمووان بەئاگا دەهێنم و یەکسەر دەریاندەهێنم، دەرگاکان لە دوای خۆمانەوە دادەخەین و لە دەرەوە پەیوەندی بە ١١٥ دەکەم؛ کەس نامێنێتەوە بۆ چارەسەرکردنی سکوتەرەکە.",correct:!0,feedback:"فیشەفیش و بۆنی کیمیایی نیشانەی ئەوەن کە پاترییەکە تێکدەچێت و لەوانەیە زۆر بە خێرایی ئاگر بگرێت. لە ڕاڕەودا ئاگر ڕێگای دەرچوون دەگرێت، بۆیە دەرهێنانی هەمووان لە سەرەتادا و پەیوەندیکردن بە ١١٥ کاری دروستە."},{text:"سەتڵێک ئاو دەکەمە سەر پاترییەکە بۆ ئەوەی سارد ببێتەوە و لە تەنیشتی دەمێنمەوە بۆ چاودێری.",correct:!1,feedback:"ئەگەر ڕاهێنانت نەکردووە، هەوڵ مەدە پاترییەکی تێکچوو سارد بکەیتەوە یان بیکوژێنیتەوە: لەوانەیە لەناکاو گڕ بگرێت و دووکەڵی ژەهراوی بدات. هەمووان دەربهێنە و پەیوەندی بە ١١٥ بکە."},{text:"سکوتەرەکە هەڵدەگرم و لە دەرگای سەرەکییەوە دەیبەمە سەر شەقام، بۆ ئەوەی ماڵەکە ئاگر نەگرێت.",correct:!1,feedback:"پاترییەک کە فیشەفیش دەکات دەتوانێت هەر ساتێک ئاگر بگرێت: هەڵگرتنی تۆ دەخاتە مەترسییەوە، و ئاگرێک لە ڕاڕەودا ڕێگای دەرچوون دەگرێت. سەرەتا هەمووان دەربهێنە و پەیوەندی بە ١١٥ بکە."},{text:"فیشی شەحنکەرەکە دەردەهێنم، پەنجەرەیەک دەکەمەوە و دەگەڕێمەوە بۆ خەوتن، و بەیانی پاترییەکە دەپشکنم.",correct:!1,feedback:"ئەمانە نیشانەکانی پاترییەکن کە لەوانەیە ئاگر بگرێت. بەجێهێشتنی لە ڕاڕەودا لە کاتێکدا هەمووان خەوتوون هەموو خێزانەکە دەخاتە مەترسییەوە: دەرچۆ و پەیوەندی بە ١١٥ بکە."}]},quiz:[{question:"ڕێگای سەلامەت بۆ بەکارهێنانی درێژکەرەوە و پلاکی زیادە لە ماڵەوە کامەیە؟",options:[{text:"تەنها بۆ ماوەیەکی کورت، و هەرگیز بە درێژکەرەوە یان پلاکێکی ترەوە نەبەسترێت",correct:!0},{text:"پلاکێکی زیادەی دووەم بە یەکەمەوە ببەستە کاتێک پلاکی زیاترت پێویستە",correct:!1},{text:"وایەرەکە لە ژێر فەرشەوە ڕابکێشە بۆ ئەوەی کەس پێی هەڵنەکەوێت و نەکەوێتە سەر زەوی",correct:!1},{text:"سۆبە و سەلاجە پێکەوە پێوەی ببەستە بۆ ئەوەی پلاکەکانی دیوار بپارێزیت",correct:!1}],explanation:"درێژکەرەوەکانی کارەبا بۆ ماوەی کورتن. بەستنی یەکێکیان بە یەکێکی ترەوە دەتوانێت باری زیادە بخاتە سەر پلاکەکە و ئاگر دروست بکات، وایەری ژێر فەرش دەتوانێت پان ببێتەوە و تێکبچێت، و سۆبە و ئامێرە گەورەکان ڕاستەوخۆ بە پلاکی دیوارەوە دەبەسترێن."},{question:"باشترین شوێن بۆ شەحنکردنی مۆبایل یان پاوەر بانک کامەیە؟",options:[{text:"لەسەر ڕووبەرێکی ڕەق وەک مێز، و کاتێک پڕ بوو فیشەکەی دەردەهێنرێت",correct:!0},{text:"لەسەر جێگای نووستن لە ژێر سەرین، بۆ ئەوەی بە شەو لە ڕێگادا نەبێت",correct:!1},{text:"لەسەر قەنەفە بە درێژایی شەو، بۆ ئەوەی بەیانی پاترییەکە پڕ بێت",correct:!1},{text:"لە نزیک سۆبە، چونکە هەوای گەرم یارمەتیی پاترییەکە دەدات خێراتر شەحن بێت",correct:!1}],explanation:"ڕووبەری نەرم وەک جێگای نووستن، سەرین و قەنەفە گەرمی ڕادەگرن، و پاترییەک کە نەتوانێت سارد ببێتەوە دەتوانێت زۆر گەرم ببێت و ئاگر بگرێت. لەسەر ڕووبەرێکی ڕەق و ڕێک شەحن بکە، نەک لە کاتی خەوتندا، و کاتێک پاترییەکە پڕ بوو فیشی شەحنکەرەکە دەربهێنە."},{question:"کام لەمانە نیشانەی ئەوەیە کە پاترییەکی لیتیۆم-ئایۆن تێکدەچێت؟",options:[{text:"هەڵدەئاوسێت، زۆر گەرم دەبێت یان دەنگی فیشەفیشی لێوە دێت",correct:!0},{text:"ئێستا شەحنکردنی کەمێک لە کاتی نوێبوونی زیاتر کات دەخایەنێت",correct:!1},{text:"ڕەنگی وایەری شەحنکەرەکەی لە ڕەنگی ئامێرەکە جیاوازە",correct:!1},{text:"ڕووناکیی شاشەی مۆبایلەکە ئێواران خۆی کەم دەبێتەوە",correct:!1}],explanation:"گەرمیی زۆر، هەڵئاوسان یان گۆڕانی شێوە یان ڕەنگ، تکان، بۆنێکی نائاسایی، دەنگی فیشەفیش یان تەقەتەق و دووکەڵ نیشانەکانی مەترسین. یەکسەر واز لە بەکارهێنانی پاترییەکە بهێنە؛ ئەگەر دووکەڵی دا یان سووتا، دەرچۆ و پەیوەندی بە ١١٥ بکە."},{question:"پاوەر بانکێک لەسەر مێز دەست بە دووکەڵدان دەکات. کاری دروست چییە؟",options:[{text:"هەمووان دەربهێنە، دەرگاکە دابخە و لە دەرەوە پەیوەندی بە ١١٥ بکە",correct:!0},{text:"پەرداخێک ئاو بکە سەری و لە نزیکی بمێنەوە تا بە چاوی خۆت دەبینیت کوژایەوە",correct:!1},{text:"بیخەرە ناو سەلاجەوە بۆ ئەوەی خێراتر سارد ببێتەوە",correct:!1},{text:"هەڵیبگرە و بە خێرایی بیبە بۆ دەستشۆری چێشتخانە",correct:!1}],explanation:"ئاگری پاتریی لیتیۆم-ئایۆن خێرا گەورە دەبێت و دووکەڵ و گازی ژەهراوی دەدات. ئەگەر ڕاهێنانت نەکردووە، هەوڵ مەدە پاترییەکی سووتاو بکوژێنیتەوە، سارد بکەیتەوە یان هەڵیبگریت: دەرچۆ، لە دەرەوە بمێنەوە و لە دەرەوە پەیوەندی بە ١١٥ بکە."},{question:"دوای شۆکی کارەبا، پیاوێک لەسەر زەوی کەوتووە و هێشتا وایەری ئامێرێکی بە دەستەوەیە. سەرەتا چی دەکەیت؟",options:[{text:"بەبێ ئەوەی دەستی لێ بدەیت، کارەبا لە فیشەکە یان سویچی سەرەکی ببڕە",correct:!0},{text:"قۆڵی بگرە و بە خێراترین شێوە لە وایەرەکە دووری بخەرەوە",correct:!1},{text:"ئاو بکە سەر دەستەکانی بۆ ساردکردنەوەی سووتانەکان پێش هەموو شتێک",correct:!1},{text:"یەکسەر دەست بە CPR بکە، تەنانەت ئەگەر هێشتا وایەرەکەی بە دەستەوە بێت",correct:!1}],explanation:"هەرگیز دەست لە کەسێک مەدە کە لەوانەیە هێشتا بە کارەباوە بەسترابێت: لەوانەیە شۆکی کارەبا تۆش بگرێتەوە. سەرەتا کارەبا ببڕە، پاشان پەیوەندی بە ١٢٢ بکە و ئەگەر بە ئاسایی هەناسە نادات دەست بە CPR بکە."}],media:[{kind:"image",src:"media/images/w8_home_electrical_battery.webp",title:"شەحنکردنی سەلامەت و پلاک لە ماڵەوە",description:"مۆبایلێک لەسەر مێز شەحن دەکرێت، سکوتەرێکی کارەبایی لە دەرەوەی ماڵ و دوور لە دەرگا شەحن دەکرێت، پلاکێکی دیوار کە تەنها یەک ئامێری پێوە بەستراوە و ئاگادارکەرەوەیەکی دووکەڵ لەسەر بنمیچ."}]}],t={lessons:e};export{t as default,e as lessons};
